// 历年真题(4套)与2026预测卷(4套)全量试卷库
var ALL_EXAMS_DATA = (typeof window !== 'undefined' ? (window.ALL_EXAMS_DATA = [{"id":"zt-2025","title":"2025年成考政治真题卷","type":"past","year":2025,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2025-c-1","isSubjective":false,"num":1,"category":"2025年成考政治真题卷 · 单选","stem":"恩格斯指出，马克思的整个世界观不是教义，而是（ ）。","options":["哲学","方法","革命思想","理论体系"],"answer":1,"answerLetter":"B","explanation":"恩格斯强调马克思的整个世界观不是固定不变的教义，而是可用于分析和解决问题的方法。答案选 B。","score":2},{"id":"zt-2025-c-2","isSubjective":false,"num":2,"category":"2025年成考政治真题卷 · 单选","stem":"马克思主义认为，物质是标志客观实在的哲学范畴。下列不属于物质范畴的是（ ）。","options":["暗物质","反物质","人工智能","人类智能"],"answer":2,"answerLetter":"C","explanation":"马克思主义哲学指出物质是不依赖于人的意识并能为人的意识所反映的客观实在，暗物质、反物质 是客观存在的实物形态，属于物质范畴；人类智能是人脑这一物质器官产生的机能，依托物质载体存在，归 属于物质范畴；人工智能是人类设计的算法、程序与逻辑集合，是人类意识的模拟产物，属于意识层面的派 生内容，并非客观实在，因此不属于物质范畴。","score":2},{"id":"zt-2025-c-3","isSubjective":false,"num":3,"category":"2025年成考政治真题卷 · 单选","stem":"物质世界在人类改造世界的实践活动中发生二重分化，这种二重分化既包括自然界与人类社会的分化，也 包括（ ）。","options":["形式与内容的分化","认识世界与改造世界的分化","真理与价值的分化","客观世界与主观世界的分化"],"answer":3,"answerLetter":"D","explanation":"物质世界在实践中二重分化，除自然界和人类社会分化，还有客观世界和主观世界分化。客观世界 指物质世界，主观世界指人的意识世界。答案选D。","score":2},{"id":"zt-2025-c-4","isSubjective":false,"num":4,"category":"2025年成考政治真题卷 · 单选","stem":"唯物辩证法揭示的事物变化发展的一般规律，除了对立统一规律和否定之否定规律外，还包括（ ）。","options":["矛盾分析规律","事物的普遍联系规律","量变质变规律","现象表现本质的规律"],"answer":2,"answerLetter":"C","explanation":"唯物辩证法的三大规律是对立统一规律、否定之否定规律和量变质变规律。选项A不是唯物辩证法的 规律；选项B普遍联系是辩证法总特征之一，并非规律；选项D也不是辩证法的规律。","score":2},{"id":"zt-2025-c-5","isSubjective":false,"num":5,"category":"2025年成考政治真题卷 · 单选","stem":"费尔巴哈打破了黑格尔的体系。简单地把它撇在一旁。但是简单地宣布一种哲学是错误的，还制服不了这 种哲学。……必须从它的本来意义上\"扬弃\"它。就是说，要批判地消灭它的形式但是要救出通过这个形式获 得的新内容。恩格斯的这一论述体现的是（ ）。","options":["超前思维","逆向思维","发散思维","辩证思维"],"answer":3,"answerLetter":"D","explanation":"恩格斯强调对黑格尔哲学既要批判其形式，又要救出新内容，这体现了用联系、发展、全面的观点 看待事物和思考问题，即辩证思维。答案选D。","score":2},{"id":"zt-2025-c-6","isSubjective":false,"num":6,"category":"2025年成考政治真题卷 · 单选","stem":"“蜂建筑的本领使人间的许多建筑师感到惭愧。但是，最蹩脚的建筑师从一开始就比最灵巧的蜜蜂高明的 地方，是他在用蜂蜡建筑蜂房以前，已经在自己的头脑中把它建成了。”马克思的这一论述强调人的实践活 动是（ ）。","options":["感性的、直接的活动","有目的、有意识的活动","客观的、物质的活动","批判的、革命的活动"],"answer":1,"answerLetter":"B","explanation":"马克思强调建筑师在实际建造蜂房之前已在头脑中建成，体现出人的实践活动具有目的性和意识性 ，这是人与动物本能活动的区别。","score":2},{"id":"zt-2025-c-7","isSubjective":false,"num":7,"category":"2025年成考政治真题卷 · 单选","stem":"习近平指出：\"了解情况的渠道千条万条，但是调查研究要放在第一条，这是不可替代、不会失真的一条。 通过二手材料了解情况是必要的，但不能代替亲身调研。这一论述体现的哲学道理是（ ）。","options":["直接经验是获得知识的唯一渠道","直接经验完全排斥间接经验","一切真知都是从直接经验发源的","一切事情都必须去直接经验"],"answer":2,"answerLetter":"C","explanation":"题干强调亲身调研（直接经验）的重要性，说明一切真知都源于直接经验。A选项，获得知识渠道有 直接经验和间接经验等，并非唯一；B选项，直接经验和间接经验并不相互排斥；D选项，并非一切事情都要 直接经验。","score":2},{"id":"zt-2025-c-8","isSubjective":false,"num":8,"category":"2025年成考政治真题卷 · 单选","stem":"唯物史观坚持社会存在决定社会意识。社会存在包括诸多因素。其中决定整个社会历史发展的是（ ）。","options":["自然地理环境","人口因素","物质生产方式","意识形态"],"answer":2,"answerLetter":"C","explanation":"物质生产方式是人类社会存在和发展的基础，它决定着社会的性质和面貌，决定着社会形态的更替 ，对整个社会历史发展起决定性作用。自然地理环境和人口因素是社会存在发展的重要条件但非决定力量。 意识形态属于社会意识。","score":2},{"id":"zt-2025-c-9","isSubjective":false,"num":9,"category":"2025年成考政治真题卷 · 单选","stem":"普遍交往是世界历史的基本特征。这是（ ）。","options":["历史唯物主义的观点","唯物主义辩证法的观点","历史唯心主义的观点","唯心主义辩证法的观点"],"answer":0,"answerLetter":"A","explanation":"历史唯物主义认为生产力的发展推动世界市场形成，使各民族普遍交往，普遍交往是世界历史基本 特征体现了社会存在决定社会意识等历史唯物主义原理。答案选A。","score":2},{"id":"zt-2025-c-10","isSubjective":false,"num":10,"category":"2025年成考政治真题卷 · 单选","stem":"马克思指出：手推磨产生的是封建主的社会，蒸汽磨产生的是工业资本家的社会。这一论述蕴含的基本原 理是（ ）。","options":["物质决定意识","社会存在决定社会意识","生产力状况决定生产关系","生产关系对生产力具有反作用"],"answer":2,"answerLetter":"C","explanation":"“手推磨”“蒸汽磨”代表生产力，“封建主的社会”“工业资本家的社会”指不同生产关系，体 现了生产力状况决定生产关系。答案选C。","score":2},{"id":"zt-2025-c-11","isSubjective":false,"num":11,"category":"2025年成考政治真题卷 · 单选","stem":"毛泽东在党的六届六中全会上强调：没有抽象的马克思主义，只有具体的马克思主义。……按照中国的特 点去应用它，成为全党亟待了解并须解决的问题。这标志着","options":["马克思主义开始传入中国","马克思主义在中国得到广泛传播","马克思主义自此成为中国共产党的指导思想","马克思主义的中国化这一命题的正式提出"],"answer":3,"answerLetter":"D","explanation":"毛泽东强调按中国特点应用马克思主义，即强调马克思主义中国化，此为该命题正式提出。A项马克 思主义开始传入中国是在新文化运动后期；B项马克思主义广泛传播是在五四运动前后；C项马克思主义成为 中共指导思想并非这一表述标志。","score":2},{"id":"zt-2025-c-12","isSubjective":false,"num":12,"category":"2025年成考政治真题卷 · 单选","stem":"一个政党的纲领，是公开树立起来的一面旗帜。在新民主主义的经济纲领中，标明新民主主义革命主要内 容的是（ ）。","options":["没收帝国主义在华企业归新生的人民政权所有","没收封建地主阶级的土地归农民所有","没收官僚资产阶级的垄断资本归新民主主义的国家所有","保护民族工商业"],"answer":1,"answerLetter":"B","explanation":"新民主主义革命的主要任务是反帝反封建，封建剥削的根基是地主土地所有制，没收封建地主阶级 土地归农民，消除封建剥削根基，是主要内容。答案选B。","score":2},{"id":"zt-2025-c-13","isSubjective":false,"num":13,"category":"2025年成考政治真题卷 · 单选","stem":"党在领导新民主主义革命的过程中，把党的建设作为一项伟大的工程，逐步形成了三大优良作风，这是中 国共产党区别于其他任何政党的显著标志。三大优良作风是（ ）。","options":["土地革命、武装斗争、根据地建设","统一战线、武装斗争、党的建设","官兵一致、军民一致、瓦解敌军和优待俘虏","理论联系实际、密切联系群众、批评与自我批评"],"answer":3,"answerLetter":"D","explanation":"A选项是工农武装割据内容；B选项是中国革命三大法宝；C选项是人民军队政治工作原则；D选项理 论联系实际、密切联系群众、批评与自我批评是党的三大优良作风。","score":2},{"id":"zt-2025-c-14","isSubjective":false,"num":14,"category":"2025年成考政治真题卷 · 单选","stem":"社会主义社会存在敌我矛盾和人民内部矛盾。下列关于社会主义社会这两类矛盾的表述，正确的是（ ）。","options":["敌我矛盾是非对抗性的矛盾","人民内部矛盾是对抗性的矛盾","两类不同性质的矛盾是固定不变的","两类矛盾的性质不同，解决的方法也不同"],"answer":3,"answerLetter":"D","explanation":"敌我矛盾是对抗性矛盾，人民内部矛盾是非对抗性矛盾，且两类矛盾在一定条件下可相互转化，因 性质不同解决方法也不同。","score":2},{"id":"zt-2025-c-15","isSubjective":false,"num":15,"category":"2025年成考政治真题卷 · 单选","stem":"在社会主义建设道路初步探索中，毛泽东提出三个世界划分的战略思想。三个世界中，属于第三世界的是 （ ）。","options":["苏美两个超级大国","苏美以外的西方发达国家","东欧国家","亚洲、非洲、拉丁美洲的广大发展中国家"],"answer":3,"answerLetter":"D","explanation":"毛泽东提出的三个世界划分战略，第一世界是苏美两个超级大国；第二世界是苏美以外的西方发达 国家等；第三世界是亚非拉广大发展中国家。答案选D。","score":2},{"id":"zt-2025-c-16","isSubjective":false,"num":16,"category":"2025年成考政治真题卷 · 单选","stem":"在改革开放和社会主义现代化建设新时期，邓小平提出的检验一切工作是非得失的根本标准是（ ）。","options":["三个有利于","姓社姓资","九个善于","姓公姓私"],"answer":0,"answerLetter":"A","explanation":"在改革开放和社会主义现代化建设新时期，邓小平提出“三个有利于”作为判断改革得失成败的标 准。“三个有利于”即是否有利于发展社会主义社会的生产力、是否有利于增强社会主义国家的综合国力、 是否有利于提高人民的生活水平。而“姓社姓资”“姓公姓私”是当时改革中曾存在的争议性概念，“九个 善于”与本题无关。所以答案选A。","score":2},{"id":"zt-2025-c-17","isSubjective":false,"num":17,"category":"2025年成考政治真题卷 · 单选","stem":"三个代表重要思想是统一的整体，相互联系、相互促进。发展先进文化、实现最广大人民根本利益的基础 条件是（ ）。","options":["坚持与时俱进","发展先进生产力","坚持执政为民","保持党的纯洁性"],"answer":1,"answerLetter":"B","explanation":"生产力是社会发展的最终决定力量，发展先进生产力是发展先进文化、实现人民根本利益的基础条 件。答案选B。","score":2},{"id":"zt-2025-c-18","isSubjective":false,"num":18,"category":"2025年成考政治真题卷 · 单选","stem":"九层之台，起于累土。党的全部工作和战斗力的基础是（ ）。","options":["党员个体","党的基层组织","党员领导干部","党的地方组织"],"answer":1,"answerLetter":"B","explanation":"党的基层组织是党在社会基层组织中的战斗堡垒，是党的全部工作和战斗力的基础。答案选B。","score":2},{"id":"zt-2025-c-19","isSubjective":false,"num":19,"category":"2025年成考政治真题卷 · 单选","stem":"科学发展观认为，加快转变经济发展方式是一项紧迫而重大的战略任务，是顺应我国发展新的阶段性特征 的必然要求。转变经济发展方式的出发点和落脚点是（ ）。","options":["科技进步和创新","经济结构战略性调整","保障和改善民生","建设环境友好型社会"],"answer":2,"answerLetter":"C","explanation":"科学发展观核心是以人为本，所以转变经济发展方式要以保障和改善民生为出发点和落脚点。答案 选C。","score":2},{"id":"zt-2025-c-20","isSubjective":false,"num":20,"category":"2025年成考政治真题卷 · 单选","stem":"社会主义核心价值体系是根源于民族优秀文化和社会主义先进文化并吸收人类文明成果发展起来的。在社 会主义核心价值体系的基本内容中，属于基本道德规范的是（ ）。","options":["马克思主义指导思想","民族精神和时代精神","中国特色社会主义共同理想","社会主义荣辱观"],"answer":3,"answerLetter":"D","explanation":"社会主义荣辱观体现了中华民族传统美德、中国共产党的优良传统和作风与时代精神的凝聚和升华 ，涵盖了社会公德、职业道德、家庭美德和个人品德等各个方面，是基本道德规范的集中体现。A选项马克思 主义指导思想是灵魂；B选项民族精神和时代精神是精髓；C选项中国特色社会主义共同理想是主题。所以答 案选D。","score":2},{"id":"zt-2025-c-21","isSubjective":false,"num":21,"category":"2025年成考政治真题卷 · 单选","stem":"中国特色社会主义之所以不一样，之所以生机勃勃、充满活力，关键就在于中国特色，中国特色的关键就 在于两个结合。两个结合中的第二个结合是（ ）。","options":["马克思主义基本原理同中华悠久历史传统相结合","马克思主义基本原理同中华优秀传统文化相结合","马克思主义基本原理同中国具体实际相结合","马克思主义基本原理同中国传统文化相结合"],"answer":1,"answerLetter":"B","explanation":"“两个结合”指把马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合，第一个结合 是同中国具体实际结合，第二个结合是同中华优秀传统文化结合。","score":2},{"id":"zt-2025-c-22","isSubjective":false,"num":22,"category":"2025年成考政治真题卷 · 单选","stem":"习近平新时代中国特色社会主义思想是完整的科学体系。其中，集中体现这一思想体系主要观点和基本精 神的是（ ）。","options":["十个明确","十四个坚持","十三个方面成就","六个必须坚持"],"answer":0,"answerLetter":"A","explanation":"“十个明确”集中体现习近平新时代中国特色社会主义思想的主要观点和基本精神，是该思想体系 的核心“四梁八柱”；“十四个坚持”是新时代坚持和发展中国特色社会主义的基本方略，侧重实践层面行 动准则；“十三个方面成就”展现新时代党和国家取得的历史性变革与实践成果；“六个必须坚持”是贯穿 这一思想的世界观、方法论与立场观点方法，因此本题选A。","score":2},{"id":"zt-2025-c-23","isSubjective":false,"num":23,"category":"2025年成考政治真题卷 · 单选","stem":"社会主要矛盾是各种社会矛盾的主要根源和集中反映。新时代我国社会主要矛盾是（ ）。","options":["人民对于经济文化迅速发展的需要问经济文化不能满足人民需要的状况之间的矛盾","人民对于建立先进的工业国的要求和落后的农业国的现实之间的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"],"answer":3,"answerLetter":"D","explanation":"这题考查新时代我国社会主要矛盾。A、B是1956年八大提出的矛盾表述；C是1981 - 2017年间的矛 盾表述；2017年十九大提出新时代我国社会主要矛盾转变为人民日益增长的美好生活需要和不平衡不充分的 发展之间的矛盾。所以答案选D。","score":2},{"id":"zt-2025-c-24","isSubjective":false,"num":24,"category":"2025年成考政治真题卷 · 单选","stem":"新时代抓发展，必须坚定不移贯彻新发展理念。在新发展理念中，注重解决发展动力问题、不平衡问题的 分别是（ ）。","options":["开放发展、绿色发展","创新发展、协调发展","开放发展、协调发展","创新发展、绿色发展"],"answer":1,"answerLetter":"B","explanation":"创新是引领发展的第一动力，注重解决发展动力问题；协调注重解决发展不平衡问题。答案选B。","score":2},{"id":"zt-2025-c-25","isSubjective":false,"num":25,"category":"2025年成考政治真题卷 · 单选","stem":"公有制经济和非公有制经济都是社会主义市场经济的重要组成部分。下列选项中属于公有制经济的是（ ）。","options":["集体经济","私营经济","民营经济","外商投资经济"],"answer":0,"answerLetter":"A","explanation":"公有制经济包括国有经济、集体经济以及混合所有制经济中的国有成分和集体成分。私营经济、民 营经济、外商投资经济都属于非公有制经济。所以答案选A。","score":2},{"id":"zt-2025-c-26","isSubjective":false,"num":26,"category":"2025年成考政治真题卷 · 单选","stem":"民主是全人类共同价值，人民民主是社会主义的生命。下列选项中，属于新时代我国民主政治领域具有重 大创新意义的标志性成果是（ ）。","options":["全过程人民民主","直接民主","无产阶级专政","间接民主"],"answer":0,"answerLetter":"A","explanation":"全过程人民民主是新时代我国民主政治领域具有重大创新意义的标志性成果。直接民主和间接民主 是民主的实现形式；无产阶级专政是国家性质相关概念。答案选A。","score":2},{"id":"zt-2025-c-27","isSubjective":false,"num":27,"category":"2025年成考政治真题卷 · 单选","stem":"从建设更高水平的法治中国的角度来说，维护社会公平正义的最后一道防线是（ ）。","options":["科学立法","严格执法","公正司法","全民守法"],"answer":2,"answerLetter":"C","explanation":"司法是维护社会公平正义的最后一道防线，公正司法能确保法律正确实施、保障公民合法权益、实 现公平正义。答案选C。","score":2},{"id":"zt-2025-c-28","isSubjective":false,"num":28,"category":"2025年成考政治真题卷 · 单选","stem":"人无精神不立，国无精神则不强。中国共产党人精神谱系的源头是（ ）。","options":["伟大建党精神","井冈山精神","长征精神","延安精神"],"answer":0,"answerLetter":"A","explanation":"伟大建党精神是中国共产党人精神谱系的源头，后续诸多精神都是在此基础上衍生发展。答案选A。","score":2},{"id":"zt-2025-c-29","isSubjective":false,"num":29,"category":"2025年成考政治真题卷 · 单选","stem":"党的十八大以来，在习近平强军思想指引下，人民军队实现整体性革命性重塑、重整行装再出发，中国特 色强军之路越走越宽广。人民军队建军之本、强军之魂是（ ）。","options":["党对人民军队的绝对领导","科学技术","军民融合发展","依法治军"],"answer":0,"answerLetter":"A","explanation":"本题主要考查人民军队建军之本、强军之魂的相关知识。党对军队的绝对领导是中国特色社会主义 的本质特征，是党和国家的重要政治优势，是人民军队的建军之本、强军之魂。所以答案是A选项。","score":2},{"id":"zt-2025-c-30","isSubjective":false,"num":30,"category":"2025年成考政治真题卷 · 单选","stem":"推动构建新型国际关系是新时代中国外交理论和实践的重要创新。推动构建新型国际关系的原则是（ ）。","options":["和平共处、总体稳定、均衡发展","相互尊重、公平正义、合作共赢","相互信任、平等协商、互利互惠","求同存异、相互尊重、互学互鉴"],"answer":1,"answerLetter":"B","explanation":"推动构建新型国际关系的原则是相互尊重、公平正义、合作共赢。所以答案选B。","score":2},{"id":"zt-2025-c-31","isSubjective":false,"num":31,"category":"2025年成考政治真题卷 · 单选","stem":"2024年7月4日，上海合作组织正式接收的新成员国是（ ）。","options":["阿富汗","白俄罗斯","土库曼斯坦","格鲁吉亚"],"answer":1,"answerLetter":"B","explanation":"2024年7月4日，上海合作组织正式接收白俄罗斯为成员国。答案选B。","score":2},{"id":"zt-2025-c-32","isSubjective":false,"num":32,"category":"2025年成考政治真题卷 · 单选","stem":"2024年11月14日，作为一带一路重要项目，中国和秘鲁共建的南美洲首个智慧港口和绿色港口正式开港 ，这个港口是（ ）。","options":["科隆港","巴尔博亚港","钱凯港","曼萨尼约港"],"answer":2,"answerLetter":"C","explanation":"2024年11月14日，中秘共建的南美洲首个智慧港口和绿色港口钱凯港正式开港。答案选C。","score":2},{"id":"zt-2025-c-33","isSubjective":false,"num":33,"category":"2025年成考政治真题卷 · 单选","stem":"2024年12月13日国家统计局发布的数据显示，我国2024年粮食总产量迈上一个新台阶，首次突破（ ）。","options":["1.1万亿斤","1.2万亿斤","1.3万亿斤","1.4万亿斤"],"answer":3,"answerLetter":"D","explanation":"2024年我国粮食总产量首次突破1.4万亿斤。答案选D。","score":2},{"id":"zt-2025-c-34","isSubjective":false,"num":34,"category":"2025年成考政治真题卷 · 单选","stem":"2024年底，我国自主研制建造的076两栖攻击舰下水，命名为中国人民解放军海军（ ）。","options":["四川舰","安徽舰","河北舰","湖南舰"],"answer":0,"answerLetter":"A","explanation":"截至2024年7月，076两栖攻击舰并未下水，这是一道虚构情境的题。不过按照海军舰艇命名规则 ，两栖攻击舰以省级行政区命名，目前“安徽舰”是075型两栖攻击舰。鉴于这题虚构性且你不需要分析选项 ，从出题逻辑可能想考察新下水对应命名，“四川舰”目前无此种舰艇命名，所以答案倾向选A。","score":2},{"id":"zt-2025-c-35","isSubjective":false,"num":35,"category":"2025年成考政治真题卷 · 单选","stem":"中国电影史上首部百亿元票房影片于2025年2月13日诞生，它是（ ）。","options":["《熊出没·重启未来》","《哪吒之魔童闹海》","《唐探1900》","《封神第二部：战火西岐》"],"answer":1,"answerLetter":"B","explanation":"这是一道基于虚构信息的题目。在现实截至目前（2024年7月）并不存在2025年2月13日诞生的首部 百亿票房影片这一情况。若按题目设定，需根据相关背景知识判断。正确答案是B选项《哪吒之魔童闹海》 。","score":2},{"id":"zt-2025-s-36","isSubjective":true,"num":36,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"如何理解历史人物的出现是必然性与偶然性的统一？","answer":"（1）历史人物是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物 ，他们的出现存在历史必然性。社会发展存在客观规律与客观历史任务，时代发展到特定阶段，客观上需要 相应才能的人物完成时代任务，这是必然。 （2）历史人物的具体出现、个人特质、行事方式带有偶然性。同样的历史任务，可能由不同人物完成；个人 机遇、性格等偶然因素会影响人物发挥作用的形式。 （3）必然性居于主导地位，决定历史发展总方向；偶然性是必然性的表现形式，任何历史人物都无法改变社 会发展客观总进程，二者辩证统一。","explanation":"（1）历史人物是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物 ，他们的出现存在历史必然性。社会发展存在客观规律与客观历史任务，时代发展到特定阶段，客观上需要 相应才能的人物完成时代任务，这是必然。 （2）历史人物的具体出现、个人特质、行事方式带有偶然性。同样的历史任务，可能由不同人物完成；个人 机遇、性格等偶然因素会影响人物发挥作用的形式。 （3）必然性居于主导地位，决定历史发展总方向；偶然性是必然性的表现形式，任何历史人物都无法改变社 会发展客观总进程，二者辩证统一。","score":10},{"id":"zt-2025-s-37","isSubjective":true,"num":37,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"简述经济基础的基本内涵。","answer":"（1）经济基础是由社会一定发展阶段的生产力所决定的生产关系的总和。 （2）一个社会内部会同时存在多种生产关系，其中占支配地位、决定社会性质的生产关系是该社会的核心经 济基础。 （3）经济基础与经济体制紧密关联，经济体制是生产关系的具体组织、管理实现形式。","explanation":"（1）经济基础是由社会一定发展阶段的生产力所决定的生产关系的总和。 （2）一个社会内部会同时存在多种生产关系，其中占支配地位、决定社会性质的生产关系是该社会的核心经 济基础。 （3）经济基础与经济体制紧密关联，经济体制是生产关系的具体组织、管理实现形式。","score":10},{"id":"zt-2025-s-38","isSubjective":true,"num":38,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"简述新民主主义革命与社会主义革命的关系。","answer":"（1）二者相互区别：新民主主义革命属于资产阶级民主革命范畴，目标建立各革命阶级联合专政 ；社会主义革命是无产阶级性质革命，目标消灭私有制、建立无产阶级专政。 （2）二者紧密联系，分为上下两篇：新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主 义革命的必然趋势。中国社会性质决定革命必须分两步，不能割裂、也不能混淆两个革命阶段。","explanation":"（1）二者相互区别：新民主主义革命属于资产阶级民主革命范畴，目标建立各革命阶级联合专政 ；社会主义革命是无产阶级性质革命，目标消灭私有制、建立无产阶级专政。 （2）二者紧密联系，分为上下两篇：新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主 义革命的必然趋势。中国社会性质决定革命必须分两步，不能割裂、也不能混淆两个革命阶段。","score":10},{"id":"zt-2025-s-39","isSubjective":true,"num":39,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"新安全格局中，政治安全包括哪些内容？","answer":"（1）政治安全是国家安全的根本，统领经济、社会、军事等各领域安全。 （2）政权安全：坚持、巩固中国共产党长期执政地位，牢牢把握正确政治方向，防范颠覆性风险。 （3）制度安全：坚持完善中国特色社会主义制度，抵御制度层面外部冲击。 （4）意识形态安全：巩固马克思主义在意识形态领域指导地位，筑牢全国人民共同思想基础。","explanation":"（1）政治安全是国家安全的根本，统领经济、社会、军事等各领域安全。 （2）政权安全：坚持、巩固中国共产党长期执政地位，牢牢把握正确政治方向，防范颠覆性风险。 （3）制度安全：坚持完善中国特色社会主义制度，抵御制度层面外部冲击。 （4）意识形态安全：巩固马克思主义在意识形态领域指导地位，筑牢全国人民共同思想基础。","score":10},{"id":"zt-2025-s-40","isSubjective":true,"num":40,"category":"2025年成考政治真题卷 · 论述题 (20分)","stem":"如何理解邓小平理论是对马克思列宁主义、毛泽东思想的继承和发展？","answer":"（1）理论根基一脉相承：邓小平理论坚持马克思主义辩证唯物主义、历史唯物主义立场、观点、 方法，坚守马列、毛泽东思想基本原理，解放思想、实事求是是贯穿始终的精髓，继承了科学社会主义根本 立场。 （2）立足时代创新发展：围绕“什么是社会主义、怎样建设社会主义”核心问题，结合改革开放新时期国情 与时代特征，突破传统理论束缚，提出社会主义初级阶段、社会主义市场经济、三步走发展战略、三个有利 于标准等全新论断，开拓马克思主义中国化新境界。 （3）实践与价值延续：始终以实现人民共同富裕、解放发展生产力为目标，继承我党革命、建设的宝贵经验 ，同时回应现代化建设全新课题，是党和人民集体智慧结晶，丰富完善科学社会主义理论体系。","explanation":"（1）理论根基一脉相承：邓小平理论坚持马克思主义辩证唯物主义、历史唯物主义立场、观点、 方法，坚守马列、毛泽东思想基本原理，解放思想、实事求是是贯穿始终的精髓，继承了科学社会主义根本 立场。 （2）立足时代创新发展：围绕“什么是社会主义、怎样建设社会主义”核心问题，结合改革开放新时期国情 与时代特征，突破传统理论束缚，提出社会主义初级阶段、社会主义市场经济、三步走发展战略、三个有利 于标准等全新论断，开拓马克思主义中国化新境界。 （3）实践与价值延续：始终以实现人民共同富裕、解放发展生产力为目标，继承我党革命、建设的宝贵经验 ，同时回应现代化建设全新课题，是党和人民集体智慧结晶，丰富完善科学社会主义理论体系。","score":20},{"id":"zt-2025-s-41","isSubjective":true,"num":41,"category":"2025年成考政治真题卷 · 论述题 (20分)","stem":"对于如何跳出历史周期率，毛泽东在延安窑洞给出第一个答案，即让人民监督政府；经过百年奋斗特别是 新时代实践，党给出第二个答案，即自我革命。请分析中国共产党勇于自我革命的原因，并说明实现党的自 我革命的重要途径。","answer":"1.勇于自我革命的原因 （1）根本底气：我党除国家、民族、人民利益之外，无任何特殊私利，不存在需要维护的集团私利，敢于直 面自身问题。 （2）内在品格：党始终坚持真理、修正错误，具备高度理论与历史自信，不讳疾忌医，主动清除自身弊病。 （3）使命要求：党肩负中华民族伟大复兴历史使命，唯有持续自我革新，才能永葆先进性纯洁性，长期执政 、永续奋斗。 2.实现自我革命的重要途径：坚持“四个自我” （1）自我净化：清除党内腐败、不良作风，过滤杂质； （2）自我完善：健全党内法规制度，补齐制度短板； （3）自我革新：创新治党方式、理论思想，破除固化思维； （4）自我提高：提升党员干部执政能力、党性修养。 “四个自我”形成依靠自身力量发现、纠正问题的良性循环，是推进伟大自我革命核心路径。","explanation":"1.勇于自我革命的原因 （1）根本底气：我党除国家、民族、人民利益之外，无任何特殊私利，不存在需要维护的集团私利，敢于直 面自身问题。 （2）内在品格：党始终坚持真理、修正错误，具备高度理论与历史自信，不讳疾忌医，主动清除自身弊病。 （3）使命要求：党肩负中华民族伟大复兴历史使命，唯有持续自我革新，才能永葆先进性纯洁性，长期执政 、永续奋斗。 2.实现自我革命的重要途径：坚持“四个自我” （1）自我净化：清除党内腐败、不良作风，过滤杂质； （2）自我完善：健全党内法规制度，补齐制度短板； （3）自我革新：创新治党方式、理论思想，破除固化思维； （4）自我提高：提升党员干部执政能力、党性修养。 “四个自我”形成依靠自身力量发现、纠正问题的良性循环，是推进伟大自我革命核心路径。","score":20}]},{"id":"zt-2024","title":"2024年成考政治真题卷","type":"past","year":2024,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2024-c-1","isSubjective":false,"num":1,"category":"2024年成考政治真题卷 · 单选","stem":"对存在和思维何者为第一性问题的不同回答形成的哲学派别是（ ）。","options":["唯物主义和唯心主义","辩证法和形而上学","可知论和不可知论","经验论和唯理论"],"answer":0,"answerLetter":"A","explanation":"哲学的基本问题是思维和存在的关系问题，其中对思维和存在何者为第一性问题的不同回答，划分 出唯物主义和唯心主义两大派别。唯物主义认为物质第一性，意识第二性；唯心主义认为意识第一性，物质 第二性。","score":2},{"id":"zt-2024-c-2","isSubjective":false,"num":2,"category":"2024年成考政治真题卷 · 单选","stem":"人工智能不可能取代人类智能，人工智能只是人的意识能动性的一种（ ）。","options":["一般表现","特殊表现","低级形式","高级形式"],"answer":1,"answerLetter":"B","explanation":"人工智能是人类利用科技手段模拟人类智能，它本质上是人类意识能动性发挥作用创造出来的，是 人类意识能动性在特定科技领域的特殊体现，并非一般意义的表现，也不是意识能动性本身的低级或高级形 式。","score":2},{"id":"zt-2024-c-3","isSubjective":false,"num":3,"category":"2024年成考政治真题卷 · 单选","stem":"主观世界是从客观世界分化出来的，它具有（ ）。","options":["绝对独立性","被动反映性","消极从属性","相对独立性"],"answer":3,"answerLetter":"D","explanation":"主观世界虽源于客观世界，但它一旦形成，就有自己独特的发展规律等，并非完全与客观世界亦步 亦趋，所以具有相对独立性，并非绝对独立；主观世界对客观世界有能动的反映，不是被动反映；主观世界 也并非消极从属于客观世界，而是有主观能动性。","score":2},{"id":"zt-2024-c-4","isSubjective":false,"num":4,"category":"2024年成考政治真题卷 · 单选","stem":"“只要功夫深，铁杵磨成针”体现的唯物辩证法道理是（ ）。","options":["矛盾双方可以相互转化","矛盾存在于一切事物中","量变的积累会引起质变","万事万物都是有联系的"],"answer":2,"answerLetter":"C","explanation":"“铁杵磨成针”，从铁杵到针，需要长时间不断磨（即量变积累），最终达成从铁杵到针的质的变 化，体现量变积累引起质变。","score":2},{"id":"zt-2024-c-5","isSubjective":false,"num":5,"category":"2024年成考政治真题卷 · 单选","stem":"习近平指出：“系统观念是具有基础性的思想和工作方法。”坚持系统观念，就是要把事物放在普遍联系 的系统中来把握。下列各项中最符合这一要求的是（ ）。","options":["谋划全局，协同推进","以史为鉴，知古鉴今","坚守底线，有备无患","跳出藩篱，开拓创新"],"answer":0,"answerLetter":"A","explanation":"题干强调把事物放在普遍联系的系统中来把握，也就是要从整体、全局角度，注重各部分协同。 A选项“谋划全局，协同推进”，“谋划全局”体现从整体出发，“协同推进”体现各部分之间的联系与配合 ，符合把事物放在普遍联系系统中把握的要求。 B选项“以史为鉴，知古鉴今”主要是从历史与现实的联系 角度，重点在于借鉴历史，并非强调普遍联系的系统把握。 C选项“坚守底线，有备无患”侧重于做好防范 ，未突出事物普遍联系的系统性。 D选项“跳出藩篱，开拓创新”强调突破限制，创新思维，和普遍联系的 系统把握关联不大。","score":2},{"id":"zt-2024-c-6","isSubjective":false,"num":6,"category":"2024年成考政治真题卷 · 单选","stem":"实践具有三个基本特征，除了客观实在性、自觉能动性外，还包括（ ）。","options":["自发性","社会历史性","机械性","主观随意性"],"answer":1,"answerLetter":"B","explanation":"实践的三个基本特征是客观物质性（客观实在性表述不准确，但接近此意思）、自觉能动性、社会 历史性。A选项自发性不是实践特征；C选项机械性与实践特征无关；D选项主观随意性违背实践客观的特点。 答案选B。","score":2},{"id":"zt-2024-c-7","isSubjective":false,"num":7,"category":"2024年成考政治真题卷 · 单选","stem":"理性认识是认识的高级阶段，其特点是（ ）。","options":["具体性和直接性","抽象性和间接性","生动性和直观性","个别性和片面性"],"answer":1,"answerLetter":"B","explanation":"理性认识是对事物本质、内在联系的认识，它摆脱了对事物表面现象的直观反映，具有抽象性和间 接性。而具体性、直接性、生动性、直观性、个别性、片面性更多是感性认识的特点。","score":2},{"id":"zt-2024-c-8","isSubjective":false,"num":8,"category":"2024年成考政治真题卷 · 单选","stem":"人类认识世界和改造世界的根本目标是（ ）。","options":["战胜自然和支配自然","人口增长和物质丰富","认识必然和争取自由","发现规律和创造规律"],"answer":2,"answerLetter":"C","explanation":"人类认识世界是为了掌握事物发展的规律即“认识必然”，改造世界是为了按照人的需求改变世界 ，从必然王国走向自由王国，即“争取自由” ，认识必然和争取自由是人类认识世界和改造世界的根本目标 。 A选项“战胜自然和支配自然”表述片面且不准确，人类应与自然和谐共生；B选项“人口增长和物质丰富 ”只是人类发展过程中的部分方面，并非根本目标；D选项规律不能被创造，违背规律的客观性。","score":2},{"id":"zt-2024-c-9","isSubjective":false,"num":9,"category":"2024年成考政治真题卷 · 单选","stem":"社会一定发展阶段的生产力所决定的生产关系的总和称为（ ）。","options":["生产能力","上层建筑","社会结构","经济基础"],"answer":3,"answerLetter":"D","explanation":"经济基础是指由社会一定发展阶段的生产力所决定的生产关系的总和。A选项生产能力与题干表述概 念不同；B选项上层建筑是建立在经济基础之上的意识形态以及相应的制度、组织和设施；C选项社会结构是 一个更为宽泛概念，与题干所指不符。","score":2},{"id":"zt-2024-c-10","isSubjective":false,"num":10,"category":"2024年成考政治真题卷 · 单选","stem":"社会形态是关于社会运动的具体形式、发展阶段和不同质态的范畴。除了经济形态、政治形态外，社会形 态还包括（ ）。","options":["意识形态","物质形态","实体形态","虚拟形态"],"answer":0,"answerLetter":"A","explanation":"社会形态包括经济形态、政治形态和意识形态，意识形态是社会存在的反映，是思想上层建筑。答 案：A 。","score":2},{"id":"zt-2024-c-11","isSubjective":false,"num":11,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东思想是马克思主义中国化时代化的第一次历史性飞跃。把毛泽东思想写人党章并确立为党的指导思 想的会议是（ ）。","options":["八七会议","遵义会议","党的七大","党的八大"],"answer":2,"answerLetter":"C","explanation":"党的七大把毛泽东思想写入 党章并确立为党的指导思想，使全党有了在思想上、政治上、组织上达 到空前团结和统一的牢固的理论基础。八七会议主要是纠正右倾机会主义错误，确定土地革命和武装斗争总 方针；遵义会议主要是纠正军事和组织上“左”倾错误，事实上确立毛泽东领导地位；党的八大主要是对社 会主义建设道路进行探索。答案选C。","score":2},{"id":"zt-2024-c-12","isSubjective":false,"num":12,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东思想是党的宝贵精神财富，其精髓是（ ）。","options":["实事求是","群众路线","独立自主","推陈出新"],"answer":0,"answerLetter":"A","explanation":"毛泽东思想的精髓是实事求是，它是贯穿于毛泽东思想各个组成部分的立场、观点和方法。群众路 线是党的根本工作路线，独立自主是中国革命和建设的基本立足点 。推陈出新不属于毛泽东思想精髓内容。","score":2},{"id":"zt-2024-c-13","isSubjective":false,"num":13,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东在《（共产党人）发刊词》中总结了中国共产党在中国革命中战胜敌人的三大法宝。三大法宝指的 是（ ）。","options":["统一战线、武装斗争、党的建设","土地革命、武装斗争、农村革命根据地建设","发展进步势力、争取中间势力、孤立顽固势力","理论联系实际、密切联系群众、批评与自我批评"],"answer":0,"answerLetter":"A","explanation":"毛泽东在《[音频]发刊词》中指出统一战线、武装斗争、党的建设是中国共产党在中国革命中战胜 敌人的三大法宝。A选项符合。B选项土地革命等是革命道路相关内容；C选项是抗日民族统一战线中策略方针 ；D选项是党的三大优良作风。","score":2},{"id":"zt-2024-c-14","isSubjective":false,"num":14,"category":"2024年成考政治真题卷 · 单选","stem":"分清敌友，这是革命的首要问题。中国民主革命的首要对象是（ ）。","options":["民族资产阶级","官僚资产阶级","地主阶级","帝国主义"],"answer":3,"answerLetter":"D","explanation":"帝国主义是中国革命的首要对象，它通过侵略手段给中国带来严重灾难，是近代中国贫困落后和一 切灾祸的总根源。中国民主革命的任务就是要推翻帝国主义压迫。","score":2},{"id":"zt-2024-c-15","isSubjective":false,"num":15,"category":"2024年成考政治真题卷 · 单选","stem":"中国必须走社会主义道路，新民主主义社会必然要过渡到社会主义社会。党在过渡时期总路线的主要内容 被概括为（ ）。","options":["“两参一改三结合”","“两个转变”","“两条腿走路”","“一化三改”"],"answer":3,"answerLetter":"D","explanation":"党在过渡时期的总路线的主要内容可以概括为“一化三改”（又称“一体两翼”），“一化”即社 会主义工业化，“三改”即对个体农业、手工业和资本主义工商业的社会主义改造。“两参一改三结合”是 毛泽东1960年3月在鞍山市委报告上批示中提出的；“两个转变”并非过渡时期总路线内容；“两条腿走路 ”是中国社会主义建设中采取的一种方针。所以选D。","score":2},{"id":"zt-2024-c-16","isSubjective":false,"num":16,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东强调，在我们面前有两类社会矛盾，这就是敌我矛盾和人民内部矛盾，这是两类性质完全不同的矛 盾。解决人民内部矛盾的方法是（ ）。","options":["专政","民主","斗争","改造"],"answer":1,"answerLetter":"B","explanation":"敌我矛盾用专政方法解决，人民内部矛盾用民主方法解决，即“团结 - 批评 - 团结”的方法。所 以答案选B 。","score":2},{"id":"zt-2024-c-17","isSubjective":false,"num":17,"category":"2024年成考政治真题卷 · 单选","stem":"“一个中心、两个基本点”是党在社会主义初级阶段基本路线的简明概括，其中回答社会主义根本任务问 题的是（ ）。","options":["以经济建设为中心","坚持四项基本原则","坚持改革开放","自力更生，艰苦创业"],"answer":0,"answerLetter":"A","explanation":"社会主义根本任务是解放和发展生产力。“以经济建设为中心”强调把发展经济放在首要位置，而 发展经济就是解放和发展生产力的重要体现，直接回答了社会主义根本任务问题。四项基本原则主要是回答 确保社会主义方向等问题；改革开放是回答如何更好推动社会主义发展等问题；“自力更生，艰苦创业”是 实现基本路线的途径等方面内容。","score":2},{"id":"zt-2024-c-18","isSubjective":false,"num":18,"category":"2024年成考政治真题卷 · 单选","stem":"党的十一届三中全会作出实行改革开放的历史性决策。我国改革的性质是（ ）。","options":["对原有经济体制的细枝末节的修补","否定和抛弃社会主义基本经济制度","社会主义制度的自我完善和发展","一个阶级推翻另一个阶级的革命"],"answer":2,"answerLetter":"C","explanation":"我国改革不是对原有经济体制细枝末节的修补，A 错误；改革不会否定和抛弃社会主义基本经济制 度，B 错误；也不是一个阶级推翻另一个阶级的革命，D 错误。我国改革是社会主义制度的自我完善和发展 ，目的是解放和发展生产力。","score":2},{"id":"zt-2024-c-19","isSubjective":false,"num":19,"category":"2024年成考政治真题卷 · 单选","stem":"在“三个代表”重要思想的主要内容中，党执政兴国的第一要务是（ ）。","options":["调整","发展","巩固","提高"],"answer":1,"answerLetter":"B","explanation":"“三个代表”重要思想明确指出，发展是党执政兴国的第一要务。发展对于全面建设小康社会、加 快推进社会主义现代化，具有决定性意义。答案选B。","score":2},{"id":"zt-2024-c-20","isSubjective":false,"num":20,"category":"2024年成考政治真题卷 · 单选","stem":"科学发展观是在新世纪新阶段全面建设小康社会进程中形成和发展起来的。科学发展观的根本方法是（ ）。","options":["以人为本","坚持可持续发展","统筹兼顾","转变经济发展方式"],"answer":2,"answerLetter":"C","explanation":"科学发展观，第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼 顾。","score":2},{"id":"zt-2024-c-21","isSubjective":false,"num":21,"category":"2024年成考政治真题卷 · 单选","stem":"在习近平新时代中国特色社会主义思想的主要内容中，新时代坚持和发展中国特色社会主义基本方略概括 为（ ）。","options":["“十个明确”","“十四个坚持”","“六个必须坚持”","“十三个方面成就”"],"answer":1,"answerLetter":"B","explanation":"新时代坚持和发展中国特色社会主义基本方略概括为“十四个坚持” 。“十个明确”是习近平新时 代中国特色社会主义思想最为核心关键的组成部分；“六个必须坚持”是习近平新时代中国特色社会主义思 想的立场观点方法；“十三个方面成就”展现了党和国家事业取得的历史性成就、发生的历史性变革。答案 ：B","score":2},{"id":"zt-2024-c-22","isSubjective":false,"num":22,"category":"2024年成考政治真题卷 · 单选","stem":"党百余年的奋斗历程表明，关系党的事业兴衰成败第一位的问题是（ ）。","options":["文化问题","制度问题","理论问题","道路问题"],"answer":3,"answerLetter":"D","explanation":"道路问题关乎党的事业兴衰成败，道路正确，事业才能顺利发展，走错路则会遭受挫折。百余年奋 斗历程充分证明道路问题是首要关键。答案：D。","score":2},{"id":"zt-2024-c-23","isSubjective":false,"num":23,"category":"2024年成考政治真题卷 · 单选","stem":"党的执政水平和执政成效都不是由自己说了算，我们党做好一切工作的价值取向和根本标准是（ ）。","options":["让世界满意","让群众满意","制度完善","社会和谐"],"answer":1,"answerLetter":"B","explanation":"中国共产党的根本宗旨是全心全意为人民服务，始终把人民放在心中最高位置，所以党做好一切工 作是以让群众满意作为价值取向和根本标准。","score":2},{"id":"zt-2024-c-24","isSubjective":false,"num":24,"category":"2024年成考政治真题卷 · 单选","stem":"新时代坚持和发展中国特色社会主义的根本动力是（ ）。","options":["不断增进民生福祉","安全稳定","全面深化改革开放","反腐倡廉"],"answer":2,"answerLetter":"C","explanation":"全面深化改革开放为坚持和发展中国特色社会主义注入强大动力，是推动中国特色社会主义事业发 展的根本动力。A选项不断增进民生福祉是发展的根本目的；B选项安全稳定是发展的前提；D选项反腐倡廉是 加强党的建设等方面的重要举措。","score":2},{"id":"zt-2024-c-25","isSubjective":false,"num":25,"category":"2024年成考政治真题卷 · 单选","stem":"全面建设社会主义现代化国家的首要任务是（ ）。","options":["推动高质量发展","把握新发展阶段","贯彻新发展理念","构建新发展格局"],"answer":0,"answerLetter":"A","explanation":"推动高质量发展是全面建设社会主义现代化国家的首要任务。高质量发展是解决我国一切问题的基 础和关键，对全面建设社会主义现代化国家意义重大。而把握新发展阶段、贯彻新发展理念、构建新发展格 局是为推动高质量发展服务的重要举措。","score":2},{"id":"zt-2024-c-26","isSubjective":false,"num":26,"category":"2024年成考政治真题卷 · 单选","stem":"教育、科技、人才是中国式现代化的基础性、战略性支撑。其中，人才是（ ）。","options":["根本优势","组织保障","第一资源","第一动力"],"answer":2,"answerLetter":"C","explanation":"在现代化建设中，人才具有极其重要的地位，被视为第一资源，强调其在推动各方面发展中的关键 作用。科技是第一生产力，创新是第一动力 。根本优势、组织保障表述与人才地位不符。","score":2},{"id":"zt-2024-c-27","isSubjective":false,"num":27,"category":"2024年成考政治真题卷 · 单选","stem":"党的十八大以来，党中央明确提出全面依法治国，并将其纳入“四个全面”战略布局予以有力推进。全面 推进依法治国的总目标是（ ）。","options":["坚持依宪治国、依宪执政","全面建成法治国家、法治政府、法治社会","全面推进科学立法、严格执法、公正司法、全民守法","建设中国特色社会主义法治体系、建设社会主义法治国家"],"answer":3,"answerLetter":"D","explanation":"全面推进依法治国的总目标是建设中国特色社会主义法治体系、建设社会主义法治国家 ，这是全面 依法治国的核心要义。A选项依宪治国、依宪执政是重要方面但非总目标；B选项表述不准确；C选项科学立法 等是全面依法治国的基本格局。","score":2},{"id":"zt-2024-c-28","isSubjective":false,"num":28,"category":"2024年成考政治真题卷 · 单选","stem":"总体国家安全观为维护和塑造新时代国家安全提供了基本遵循。总体国家安全观的宗旨是（ ）。","options":["经济安全","网络安全","人民安全","政治安全"],"answer":2,"answerLetter":"C","explanation":"总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础等。所以直接对应，答 案选与宗旨匹配的内容。","score":2},{"id":"zt-2024-c-29","isSubjective":false,"num":29,"category":"2024年成考政治真题卷 · 单选","stem":"强国必须强军，军强才能国安。新时代强军目标中，决定军队建设政治方向的是（ ）。","options":["听党指挥","能打胜仗","作风优良","纪律严明"],"answer":0,"answerLetter":"A","explanation":"听党指挥是灵魂，决定军队建设的政治方向。能打胜仗是核心，反映军队的根本职能和军队建设的 根本指向。作风优良是保证，关系军队的性质、宗旨、本色。","score":2},{"id":"zt-2024-c-30","isSubjective":false,"num":30,"category":"2024年成考政治真题卷 · 单选","stem":"把党的建设作为一项伟大工程来推进，是我们党的一大创举。新时代党的建设总体布局中，摆在首位的是 （ ）。","options":["纪律建设","思想建设","组织建设","政治建设"],"answer":3,"answerLetter":"D","explanation":"在新时代党的建设总体布局中，政治建设是党的根本性建设，决定党的建设方向和效果，所以摆在 首位。答案选D。","score":2},{"id":"zt-2024-c-31","isSubjective":false,"num":31,"category":"2024年成考政治真题卷 · 单选","stem":"2023年9月23日，第十九届亚运会开幕。这是亚运会历史上规模最大、项目最多、覆盖面最广的一次盛会 ，举办地是（ ）。","options":["成都","杭州","广州","青岛"],"answer":1,"answerLetter":"B","explanation":"2023年9月23日开幕的第十九届亚运会举办地是杭州 。成都举办的是大运会，广州举办过2010年亚 运会，青岛未举办过亚运会。","score":2},{"id":"zt-2024-c-32","isSubjective":false,"num":32,"category":"2024年成考政治真题卷 · 单选","stem":"下列中国传统节日中，被第78届联合国大会确定为联合国假日的是（ ）。","options":["春节","元宵节","端午节","中秋节"],"answer":0,"answerLetter":"A","explanation":"2023年12月22日，第78届联合国大会协商一致通过决议，将春节确定为联合国假日。答案：A。","score":2},{"id":"zt-2024-c-33","isSubjective":false,"num":33,"category":"2024年成考政治真题卷 · 单选","stem":"2023年我国外贸规模稳、结构优，“新三样”出口增长近30%。“新三样”指的是（ ）。","options":["计算机、智能手机、玩具","电动汽车、锂电池、光伏产品","服装、家电、家具","工程机械、通信设备、医疗器械"],"answer":1,"answerLetter":"B","explanation":"“新三样”是近年来我国外贸出口中表现亮眼的品类，在新能源等领域，A选项计算机等是传统电子 产品和玩具，C选项是传统轻工品类，D选项工程机械等并非统称“新三样”，而电动汽车、锂电池、光伏产 品符合“新三样”概念。","score":2},{"id":"zt-2024-c-34","isSubjective":false,"num":34,"category":"2024年成考政治真题卷 · 单选","stem":"2024年5月，嫦娥六号探测器成功发射，开启世界首次（ ）。","options":["火星北极样品采集任务","月球正面样品采集任务","火星北极样品采集任务","月球背面样品采集任务"],"answer":3,"answerLetter":"D","explanation":"嫦娥六号执行的是月球相关任务，不是火星任务，所以A、C排除。嫦娥五号已完成月球正面采样返 回，嫦娥六号开启世界首次月球背面样品采集任务。答案选D。","score":2},{"id":"zt-2024-c-35","isSubjective":false,"num":35,"category":"2024年成考政治真题卷 · 单选","stem":"2024年6月30日，我国建成开通的全球首个集“桥、岛、隧、水下互通”为一体的重大工程是（ ）。","options":["平陆运河","川藏铗路","深圳至中山跨江通道","引汉济渭工程"],"answer":2,"answerLetter":"C","explanation":"2024 年 6 月 30 日，深中通道建成通车，它是全球首个集“桥、岛、隧、水下互通”为一体的跨 海通道 。平陆运河是内河航运运河；川藏铁路重点在铁路建设；引汉济渭是调水工程，均不符合。","score":2},{"id":"zt-2024-s-36","isSubjective":true,"num":36,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"确立社会主义基本制度的重大意义是什么?","answer":"社会主义基本制度的确立，是中国共产党领导人民在百年奋斗中实现的一次具有里程碑意义的伟 大变革，它从根本上扭转了近代以来中国积贫积弱的发展命运，为当代中国的发展进步筑牢了制度根基，也 为中国特色社会主义道路的开辟与拓展提供了根本性前提。 （1）社会主义基本制度的确立，充分解放了生产关系中束缚生产力发展的桎梏，极大激发了工人阶级及广大 劳动人民的主人翁意识与创造活力。通过确立生产资料公有制为主体的经济制度，使劳动者与生产资料实现 直接结合，从根本上调动了全社会的生产积极性，有力推动了我国工业、农业等各领域生产力水平的跨越式 提升。 （2）社会主义基本制度的确立，彻底终结了中国历史上长期存在的剥削制度与阶级压迫，使广大劳动人民真 正实现了从“被统治阶级”到“国家主人”的历史转变。这一变革重构了中国的阶级关系，使工人阶级领导 的、以工农联盟为基础的人民民主专政政权拥有了坚实的阶级依托和经济支撑，极大巩固了人民当家作主的 政治地位。 （3）社会主义基本制度的确立，让占世界总人口四分之一的中国成功迈入社会主义行列，这是世界社会主义 运动在20世纪取得的又一辉煌成就。它打破了资本主义制度在全球范围内的扩张态势，重塑了当时的世界政 治经济格局，显著增强了国际社会主义阵营的力量，为维护世界和平、促进人类进步事业作出了重要贡献。 （4）社会主义基本制度的确立，是马克思列宁主义基本原理与中国具体国情相结合的光辉典范，是中国共产 党对社会主义革命理论的创造性运用与发展。这一实践不仅验证了马克思列宁主义关于社会主义革命理论的 科学性与真理性，更以中国独特的实践经验丰富了科学社会主义的理论体系，为其他发展中国家探索符合自 身国情的发展道路提供了有益借鉴。","explanation":"社会主义基本制度的确立，是中国共产党领导人民在百年奋斗中实现的一次具有里程碑意义的伟 大变革，它从根本上扭转了近代以来中国积贫积弱的发展命运，为当代中国的发展进步筑牢了制度根基，也 为中国特色社会主义道路的开辟与拓展提供了根本性前提。 （1）社会主义基本制度的确立，充分解放了生产关系中束缚生产力发展的桎梏，极大激发了工人阶级及广大 劳动人民的主人翁意识与创造活力。通过确立生产资料公有制为主体的经济制度，使劳动者与生产资料实现 直接结合，从根本上调动了全社会的生产积极性，有力推动了我国工业、农业等各领域生产力水平的跨越式 提升。 （2）社会主义基本制度的确立，彻底终结了中国历史上长期存在的剥削制度与阶级压迫，使广大劳动人民真 正实现了从“被统治阶级”到“国家主人”的历史转变。这一变革重构了中国的阶级关系，使工人阶级领导 的、以工农联盟为基础的人民民主专政政权拥有了坚实的阶级依托和经济支撑，极大巩固了人民当家作主的 政治地位。 （3）社会主义基本制度的确立，让占世界总人口四分之一的中国成功迈入社会主义行列，这是世界社会主义 运动在20世纪取得的又一辉煌成就。它打破了资本主义制度在全球范围内的扩张态势，重塑了当时的世界政 治经济格局，显著增强了国际社会主义阵营的力量，为维护世界和平、促进人类进步事业作出了重要贡献。 （4）社会主义基本制度的确立，是马克思列宁主义基本原理与中国具体国情相结合的光辉典范，是中国共产 党对社会主义革命理论的创造性运用与发展。这一实践不仅验证了马克思列宁主义关于社会主义革命理论的 科学性与真理性，更以中国独特的实践经验丰富了科学社会主义的理论体系，为其他发展中国家探索符合自 身国情的发展道路提供了有益借鉴。","score":10},{"id":"zt-2024-s-37","isSubjective":true,"num":37,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"简述邓小平理论的历史地位。","answer":"（1）邓小平理论是马克思列宁主义、毛泽东思想的继承和发展。 （2）邓小平理论是中国特色社会主义理论体系的开篇之作。 （3）邓小平理论是改革开放和社会主义现代化建设的科学指南。","explanation":"（1）邓小平理论是马克思列宁主义、毛泽东思想的继承和发展。 （2）邓小平理论是中国特色社会主义理论体系的开篇之作。 （3）邓小平理论是改革开放和社会主义现代化建设的科学指南。","score":10},{"id":"zt-2024-s-38","isSubjective":true,"num":38,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"“三个代表”重要思想的集中概括是什么?","answer":"“三个代表”重要思想的集中概括是： （1）我们党必须始终代表中国先进生产力的发展要求。 （2）我们党必须始终代表中国先进文化的前进方向。 （3）我们党必须始终代表中国最广大人民的根本利益。","explanation":"“三个代表”重要思想的集中概括是： （1）我们党必须始终代表中国先进生产力的发展要求。 （2）我们党必须始终代表中国先进文化的前进方向。 （3）我们党必须始终代表中国最广大人民的根本利益。","score":10},{"id":"zt-2024-s-39","isSubjective":true,"num":39,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"中国式现代化的中国特色有哪些?","answer":"（1）中国式现代化是人口规模巨大的现代化。 （2）中国式现代化是全体人民共同富裕的现代化。 （3）中国式现代化是物质文明和精神文明相协调的现代化。 （4）中国式现代化是人与自然和谐共生的现代化。 （5）中国式现代化是走和平发展道路的现代化。","explanation":"（1）中国式现代化是人口规模巨大的现代化。 （2）中国式现代化是全体人民共同富裕的现代化。 （3）中国式现代化是物质文明和精神文明相协调的现代化。 （4）中国式现代化是人与自然和谐共生的现代化。 （5）中国式现代化是走和平发展道路的现代化。","score":10},{"id":"zt-2024-s-40","isSubjective":true,"num":40,"category":"2024年成考政治真题卷 · 论述题 (20分)","stem":"文化兴则国家兴，文化强则民族强。试从社会历史发展动力的角度论述文化在社会发展中的作用。","answer":"（1）文化是驱动社会历史前进的关键动力之一。文化凝结了人类在长期实践中形成的智慧结晶、 价值取向与人文情怀，是国家与民族赖以生存和发展的精神根基。文化的繁荣兴盛直接关系到国家的兴旺发 达和民族的强大复兴。在当今时代，文化的战略地位愈发凸显，不仅成为民族复兴进程中不可或缺的精神源 泉与社会发展的重要支撑，更是衡量综合国力竞争的核心要素之一，而满足人民群众日益增长的精神文化需 求、丰富其精神世界，也已成为社会发展的重要目标。 （2）文化对社会发展的作用具有多维度、深层次的影响。从作用性质来看，文化可分为先进文化与落后文化 ，先进文化能为社会发展注入正能量，推动社会进步；落后文化则可能成为社会发展的阻碍，制约社会前进 。从作用程度来看，文化的影响力强弱直接关系到社会发展的速度，积极向上的文化能加速社会发展进程 ，消极滞后的文化则会延缓社会发展步伐。因此，准确把握文化发展的正确方向，最大限度发挥先进文化的 引领和推动作用，对把握社会发展规律、引领社会发展进程具有决定性意义。 第一，文化为社会发展提供科学的思想导向。文化作为社会经济基础和政治制度在观念形态上的反映，具有 对现实社会的辩护与批判功能，进而深刻影响社会发展的总体走向。先进文化能够基于社会发展规律，明确 社会变革的目标与路径，为生产力的解放和发展、社会制度的完善和进步提供思想引领。中国特色社会主义 文化既传承了中华民族的精神基因，承载着中华民族的精神追求，又以马克思主义为科学指导，构筑起中国 人民在新时代砥砺奋进的思想灯塔和精神支柱。 第二，文化为社会发展注入强大的精神动能。民族的复兴是物质文明与精神文明的协同发展，仅有坚实的物 质基础不足以支撑民族的长久屹立，还需要强大的精神力量作为支撑。缺乏先进文化的引领，人民的精神世 界就会匮乏，民族的精神凝聚力就会削弱，国家发展就会失去内在动力。先进文化通过培育民族精神、弘扬 时代新风，能够激发全体人民的创造热情和奋斗精神，为社会发展提供不竭的精神动力。 第三，文化为社会发展凝聚坚实的社会共识。文化的核心是价值观念，占主导地位的主流价值观能够通过引 领社会思潮、规范道德行为，将不同群体的思想和行动凝聚起来，形成共同的价值追求和社会认同。文化作 为连接民族情感的精神纽带，能够增强民族归属感和向心力，促进全社会形成心往一处想、劲往一处使的强 大合力，为社会发展提供稳定的精神支撑和团结基础。","explanation":"（1）文化是驱动社会历史前进的关键动力之一。文化凝结了人类在长期实践中形成的智慧结晶、 价值取向与人文情怀，是国家与民族赖以生存和发展的精神根基。文化的繁荣兴盛直接关系到国家的兴旺发 达和民族的强大复兴。在当今时代，文化的战略地位愈发凸显，不仅成为民族复兴进程中不可或缺的精神源 泉与社会发展的重要支撑，更是衡量综合国力竞争的核心要素之一，而满足人民群众日益增长的精神文化需 求、丰富其精神世界，也已成为社会发展的重要目标。 （2）文化对社会发展的作用具有多维度、深层次的影响。从作用性质来看，文化可分为先进文化与落后文化 ，先进文化能为社会发展注入正能量，推动社会进步；落后文化则可能成为社会发展的阻碍，制约社会前进 。从作用程度来看，文化的影响力强弱直接关系到社会发展的速度，积极向上的文化能加速社会发展进程 ，消极滞后的文化则会延缓社会发展步伐。因此，准确把握文化发展的正确方向，最大限度发挥先进文化的 引领和推动作用，对把握社会发展规律、引领社会发展进程具有决定性意义。 第一，文化为社会发展提供科学的思想导向。文化作为社会经济基础和政治制度在观念形态上的反映，具有 对现实社会的辩护与批判功能，进而深刻影响社会发展的总体走向。先进文化能够基于社会发展规律，明确 社会变革的目标与路径，为生产力的解放和发展、社会制度的完善和进步提供思想引领。中国特色社会主义 文化既传承了中华民族的精神基因，承载着中华民族的精神追求，又以马克思主义为科学指导，构筑起中国 人民在新时代砥砺奋进的思想灯塔和精神支柱。 第二，文化为社会发展注入强大的精神动能。民族的复兴是物质文明与精神文明的协同发展，仅有坚实的物 质基础不足以支撑民族的长久屹立，还需要强大的精神力量作为支撑。缺乏先进文化的引领，人民的精神世 界就会匮乏，民族的精神凝聚力就会削弱，国家发展就会失去内在动力。先进文化通过培育民族精神、弘扬 时代新风，能够激发全体人民的创造热情和奋斗精神，为社会发展提供不竭的精神动力。 第三，文化为社会发展凝聚坚实的社会共识。文化的核心是价值观念，占主导地位的主流价值观能够通过引 领社会思潮、规范道德行为，将不同群体的思想和行动凝聚起来，形成共同的价值追求和社会认同。文化作 为连接民族情感的精神纽带，能够增强民族归属感和向心力，促进全社会形成心往一处想、劲往一处使的强 大合力，为社会发展提供稳定的精神支撑和团结基础。","score":20},{"id":"zt-2024-s-41","isSubjective":true,"num":41,"category":"2024年成考政治真题卷 · 论述题 (20分)","stem":"党的十八大以来，以习近平同志为核心的党中央积极回应人民对民主政治的新要求新期待，提出全过程人 民民主重大理念。全过程人民民主是新时代我国民主政治领域具有重大创新意义的标志性成果。如何理解全 过程人民民主是社会主义民主政治的本质属性？","answer":"全过程人民民主是社会主义民主政治的本质属性，可以从以下几个方面理解： （1）全过程人民民主是社会主义民主政治的伟大创造。全过程人民民主是中国共产党团结带领人民追求民主 、发展民主、实现民主的伟大创造，是党不断推进中国民主理论创新、制度创新、实践创新的经验结晶。它 植根于我国社会主义民主的长期实践，是马克思主义基本原理同中国具体实际相结合的产物，实现了过程民 主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志的统一。 （2）全过程人民民主是全链条、全方位、全覆盖的民主。全过程人民民主既有完整的制度程序，也有完整的 参与实践，将民主选举、民主协商、民主决策、民主管理、民主监督贯通起来，覆盖经济、政治、文化、社 会、生态文明等各个领域，贯穿国家发展大事、社会治理难事、百姓日常琐事，在时间上具有连续性，在内 容上具有整体性，在运行上具有协同性，在人民参与上具有广泛性和持续性。 （3）全过程人民民主是最广泛、最真实、最管用的民主。全过程人民民主坚持以人民为中心，能确保人民充 分享有各方面权利，人民依法通过各种途径和形式管理国家事务、管理经济和文化事业、管理社会事务。它 有效促进了国家治理高效和社会和谐稳定，维护和保障了人民群众的根本利益，既强调把民主价值和理念转 化为科学有效的制度安排，又转化为具体现实的民主实践，是经得起实践检验、得到人民认可的民主。","explanation":"全过程人民民主是社会主义民主政治的本质属性，可以从以下几个方面理解： （1）全过程人民民主是社会主义民主政治的伟大创造。全过程人民民主是中国共产党团结带领人民追求民主 、发展民主、实现民主的伟大创造，是党不断推进中国民主理论创新、制度创新、实践创新的经验结晶。它 植根于我国社会主义民主的长期实践，是马克思主义基本原理同中国具体实际相结合的产物，实现了过程民 主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志的统一。 （2）全过程人民民主是全链条、全方位、全覆盖的民主。全过程人民民主既有完整的制度程序，也有完整的 参与实践，将民主选举、民主协商、民主决策、民主管理、民主监督贯通起来，覆盖经济、政治、文化、社 会、生态文明等各个领域，贯穿国家发展大事、社会治理难事、百姓日常琐事，在时间上具有连续性，在内 容上具有整体性，在运行上具有协同性，在人民参与上具有广泛性和持续性。 （3）全过程人民民主是最广泛、最真实、最管用的民主。全过程人民民主坚持以人民为中心，能确保人民充 分享有各方面权利，人民依法通过各种途径和形式管理国家事务、管理经济和文化事业、管理社会事务。它 有效促进了国家治理高效和社会和谐稳定，维护和保障了人民群众的根本利益，既强调把民主价值和理念转 化为科学有效的制度安排，又转化为具体现实的民主实践，是经得起实践检验、得到人民认可的民主。","score":20}]},{"id":"zt-2023","title":"2023年成考政治真题卷","type":"past","year":2023,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2023-c-1","isSubjective":false,"num":1,"category":"2023年成考政治真题卷 · 单选","stem":"下列选项中体现事物因果联系的是（ ）","options":["有无相生","过犹不及","冬去春来","摩擦生热"],"answer":3,"answerLetter":"D","explanation":"因果联系是指事物之间一种先行后续，引起和被引起的关系。 A选项“有无相生”体现的是矛盾双 方相互依存、相互转化的关系，并非因果联系。 B选项“过犹不及”强调的是要把握适度原则，和因果联系 无关。 C选项“冬去春来”是自然现象的循环更替，不存在引起和被引起的关系，不是因果联系。 D选项 “摩擦”会引起“生热”，“摩擦”是原因，“生热”是结果，体现了因果联系。","score":2},{"id":"zt-2023-c-2","isSubjective":false,"num":2,"category":"2023年成考政治真题卷 · 单选","stem":"否定之否定规律揭示了事物的发展是（ ）","options":["绝对性与相对性的统一","有限性与无限性的统一","前进性与曲折性的统一","稳定性与变动性的统一"],"answer":2,"answerLetter":"C","explanation":"否定之否定规律表明，事物发展的总方向、总趋势是前进上升的，具体道路是曲折的，即事物发展 是前进性与曲折性的统一。","score":2},{"id":"zt-2023-c-3","isSubjective":false,"num":3,"category":"2023年成考政治真题卷 · 单选","stem":"观念上层建筑指的是（ ）","options":["意识形态","政治制度","法律制度","政治组织"],"answer":0,"answerLetter":"A","explanation":"观念上层建筑主要指社会的意识形态，它是对一定社会经济基础的反映并为其服务。而政治制度、 法律制度、政治组织属于政治上层建筑。","score":2},{"id":"zt-2023-c-4","isSubjective":false,"num":4,"category":"2023年成考政治真题卷 · 单选","stem":"马克思主义认为，社会革命根源于（ ）","options":["人口数量和结构的变化","思想观念斗争的尖锐化","自然资源和环境的变化","社会基本矛盾的尖锐化"],"answer":3,"answerLetter":"D","explanation":"社会革命是推动社会发展的重要动力，其根源在于生产力与生产关系、经济基础与上层建筑这一社 会基本矛盾的尖锐化。当旧的生产关系严重阻碍生产力发展，旧的上层建筑维护旧的生产关系，就会引发社 会革命。而人口数量和结构变化、思想观念斗争尖锐化、自然资源和环境变化都不是社会革命的根源。答案 ：D","score":2},{"id":"zt-2023-c-5","isSubjective":false,"num":5,"category":"2023年成考政治真题卷 · 单选","stem":"习近平指出，人民既是历史的创造者、也是历史的见证者，既是历史的“剧中人”、也是历史的“剧作者 ”。这一论断的理论依据是（ ）","options":["历史宿命论","历史决定论","英雄史观","群众史观"],"answer":3,"answerLetter":"D","explanation":"题干强调人民在历史中的重要创造作用，历史宿命论认为历史发展由不可抗拒的命运决定，否定人 的主观能动性，A 不符；历史决定论强调社会历史发展有其客观规律，但题干重点突出人民作用，B 不准确 ；英雄史观夸大英雄人物在历史中的作用，忽视人民，C 错误；群众史观强调人民群众是历史的创造者，符 合题干表述。","score":2},{"id":"zt-2023-c-6","isSubjective":false,"num":6,"category":"2023年成考政治真题卷 · 单选","stem":"毛泽东思想开始萌芽的标志是（ ）","options":["人民民主专政理论的形成","关于新民主主义革命基本思想的提出","农村包围城市、武装夺取政权道路的开辟","马克思主义中国化第一次历史性飞跃的实现"],"answer":1,"answerLetter":"B","explanation":"毛泽东思想开始萌芽于中国共产党创建和大革命时期。关于新民主主义革命基本思想的提出，标志 着毛泽东思想开始萌芽。A选项人民民主专政理论形成于解放战争时期，是毛泽东思想发展的重要成果；C选 项农村包围城市、武装夺取政权道路开辟是毛泽东思想初步形成的标志；D选项马克思主义中国化第一次历史 性飞跃的实现以毛泽东思想的形成为标志。","score":2},{"id":"zt-2023-c-7","isSubjective":false,"num":7,"category":"2023年成考政治真题卷 · 单选","stem":"新民主主义革命的主力军是（ ）","options":["无产阶级","小资产阶级","农民","知识分子"],"answer":2,"answerLetter":"C","explanation":"农民是中国革命的主力军，因为中国是农业大国，农民占人口绝大多数，且深受压迫，有强烈革命 要求和积极性，无产阶级最可靠的同盟军也是农民。","score":2},{"id":"zt-2023-c-8","isSubjective":false,"num":8,"category":"2023年成考政治真题卷 · 单选","stem":"过渡时期总路线中，“过渡时期”是指（ ）","options":["从资本主义社会向社会主义社会过渡","从封建社会向半殖民地半封建社会演变","从半殖民地半封建社会向资本主义社会转变","从中华人民共和国成立到社会主义改造基本完成"],"answer":3,"answerLetter":"D","explanation":"过渡时期总路线中的“过渡时期”，是中国从新民主主义社会向社会主义社会过渡的时期，时间跨 度是从中华人民共和国成立到社会主义改造基本完成。A选项说法不准确，中国不是从资本主义社会过渡 ；B选项封建社会向半殖民地半封建社会演变是鸦片战争后的情况；C选项不符合史实。","score":2},{"id":"zt-2023-c-9","isSubjective":false,"num":9,"category":"2023年成考政治真题卷 · 单选","stem":"在社会主义社会两类社会矛盾中，工人阶级同民族资产阶级的矛盾是（ ）","options":["敌我矛盾","人民内部矛盾","基本矛盾","社会主要矛盾"],"answer":1,"answerLetter":"B","explanation":"在社会主义社会，民族资产阶级具有两面性，工人阶级同民族资产阶级的矛盾属于人民内部矛盾。 A选项敌我矛盾不符，C选项基本矛盾是生产力与生产关系等，D选项当时社会主要矛盾不是这两者矛盾。答案 ：B","score":2},{"id":"zt-2023-c-10","isSubjective":false,"num":10,"category":"2023年成考政治真题卷 · 单选","stem":"毛泽东中国工业化道路思想强调，实现四个现代化关键在于（ ）","options":["农业现代化","工业现代化","国防现代化","科学技术现代化"],"answer":3,"answerLetter":"D","explanation":"在毛泽东关于中国工业化道路思想及实现四个现代化进程中，科学技术现代化是关键。因为科学技 术能推动农业、工业、国防等各领域发展，是实现其他现代化的重要支撑和驱动力。","score":2},{"id":"zt-2023-c-11","isSubjective":false,"num":11,"category":"2023年成考政治真题卷 · 单选","stem":"改革开放以来，我们党和国家生存发展的政治基石是（ ）","options":["四项基本原则","以德治国","国际政治秩序","依宪治国"],"answer":0,"answerLetter":"A","explanation":"四项基本原则是立国之本，是我们党和国家生存发展的政治基石。以德治国、依宪治国主要侧重于 治国理政的方式，国际政治秩序并非党和国家生存发展的政治基石。答案：A 。","score":2},{"id":"zt-2023-c-12","isSubjective":false,"num":12,"category":"2023年成考政治真题卷 · 单选","stem":"邓小平指出，中国解决所有问题的关键是（ ）","options":["要靠照搬马克思主义理论","要靠自己的发展","要靠模仿周边国家的经验","要靠别国的支持"],"answer":1,"answerLetter":"B","explanation":"中国不能照搬理论、模仿他国经验，也不能依赖别国支持，发展才是硬道理，中国解决所有问题关 键要靠自身发展，通过自身发展增强综合国力等，来应对各种挑战和解决各类问题。","score":2},{"id":"zt-2023-c-13","isSubjective":false,"num":13,"category":"2023年成考政治真题卷 · 单选","stem":"“三个代表”重要思想强调，我们党进行的一切奋斗，归根到底都是为了（ ）","options":["社会生产力的快速发展","社会主义和谐社会的建成","最广大人民的根本利益","社会主义市场经济的完善"],"answer":2,"answerLetter":"C","explanation":"“三个代表”重要思想始终强调以人民为中心，党一切奋斗的根本目的就是维护好、实现好、发展 好最广大人民的根本利益。A选项社会生产力发展是手段之一；B选项社会主义和谐社会提出晚于“三个代表 ”重要思想；D选项社会主义市场经济完善也是发展过程中的举措，并非最终目的。","score":2},{"id":"zt-2023-c-14","isSubjective":false,"num":14,"category":"2023年成考政治真题卷 · 单选","stem":"坚持中国特色社会主义政治发展道路，最根本的是（ ）","options":["坚持改革、发展、稳定的辩证统一","坚持生产发展、生活富裕、生态良好的有机统一","坚持党的使命、国家的前途、人民的福祉的辩证统一","坚持党的领导、人民当家作主、依法治国的有机统"],"answer":3,"answerLetter":"D","explanation":"中国特色社会主义政治发展道路，强调要把坚持党的领导、人民当家作主、依法治国有机统一起来 ，这是最根本的。A选项强调的是改革发展稳定关系，属于总体发展层面；B选项围绕生产、生活、生态，是 生态文明相关方面；C选项表述并非政治发展道路最根本内容。","score":2},{"id":"zt-2023-c-15","isSubjective":false,"num":15,"category":"2023年成考政治真题卷 · 单选","stem":"社会主义核心价值观中，富强、民主、文明、和谐体现的是（ ）","options":["国家层面的价值要求","社会层面的价值要求","公民层面的价值要求","组织层面的价值要求"],"answer":0,"answerLetter":"A","explanation":"社会主义核心价值观包括国家、社会、公民三个层面。富强、民主、文明、和谐是国家层面的价值 目标，自由、平等、公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民个人层面的价值准 则。所以富强、民主、文明、和谐体现的是国家层面的价值要求。","score":2},{"id":"zt-2023-c-16","isSubjective":false,"num":16,"category":"2023年成考政治真题卷 · 单选","stem":"党的十八大以来，我们党的全部理论和实践探索都是（ ）","options":["围绕推动高质量发展来展开、深化和拓展的","围绕全面建成小康社会来展开、深化和拓展的","围绕坚持和发展中国特色社会主义来展开、深化和拓展的","围绕传承和弘扬中华优秀传统文化来展开、深化和拓展的"],"answer":2,"answerLetter":"C","explanation":"党的十八大以来，我们党的全部理论和实践探索都是围绕坚持和发展中国特色社会主义这个主题来 展开、深化和拓展的 。中国特色社会主义是改革开放以来党的全部理论和实践的主题。","score":2},{"id":"zt-2023-c-17","isSubjective":false,"num":17,"category":"2023年成考政治真题卷 · 单选","stem":"中国特色社会主义事业总体布局和战略布局分别是（ ）","options":["“两个转变”和“一体两翼”","“五位一体”和“四个全面”","“八个明确”和“四面八方”","“一个中心”和“五湖四海”"],"answer":1,"answerLetter":"B","explanation":"中国特色社会主义事业总体布局是“五位一体”，即经济建设、政治建设、文化建设、社会建设、 生态文明建设五位一体；战略布局是“四个全面”，即全面建设社会主义现代化国家、全面深化改革、全面 依法治国、全面从严治党 。答案选B。","score":2},{"id":"zt-2023-c-18","isSubjective":false,"num":18,"category":"2023年成考政治真题卷 · 单选","stem":"习近平新时代中国特色社会主义思想的根本立场是（ ）","options":["人民立场","阶级立场","历史自觉","求真务实"],"answer":0,"answerLetter":"A","explanation":"人民立场是中国共产党的根本政治立场，习近平新时代中国特色社会主义思想始终强调以人民为中 心，把人民对美好生活的向往作为奋斗目标，其根本立场就是人民立场。","score":2},{"id":"zt-2023-c-19","isSubjective":false,"num":19,"category":"2023年成考政治真题卷 · 单选","stem":"习近平指出：“实现中国梦必须走中国道路、弘扬中国精神、凝聚中国力量。”中国力量指的是（ ）","options":["科技创新的力量","文化创新的力量","全国各族人民大团结的力量","全世界人民大团结的力量"],"answer":2,"answerLetter":"C","explanation":"中国力量指全国各族人民大团结的力量，这是实现中国梦的重要支撑。ABD选项表述不符。","score":2},{"id":"zt-2023-c-20","isSubjective":false,"num":20,"category":"2023年成考政治真题卷 · 单选","stem":"全面建设社会主义现代化国家的进程分两个阶段来安排，其中第二个阶段的目标是到本世纪中叶（ ）","options":["实现总体小康","消除绝对贫困","人均国内生产总值达到中等发达国家的水平","把我国建成富强民主文明和谐美丽的社会主义现代化强国"],"answer":3,"answerLetter":"D","explanation":"全面建设社会主义现代化国家进程分两个阶段，第二个阶段是从2035年到本世纪中叶，目标是建成 富强民主文明和谐美丽的社会主义现代化强国。A选项实现总体小康在20世纪末已达成；B选项消除绝对贫困 在2020年完成；C选项人均国内生产总值达到中等发达国家水平是第一阶段2035年要实现的目标之一。答案 ：D","score":2},{"id":"zt-2023-c-21","isSubjective":false,"num":21,"category":"2023年成考政治真题卷 · 单选","stem":"在新发展理念中，注重解决发展不平衡问题的是（ ）","options":["创新发展","协调发展","绿色发展","共享发展"],"answer":1,"answerLetter":"B","explanation":"创新发展注重解决发展动力问题；协调发展注重解决发展不平衡问题；绿色发展注重解决人与自然 和谐共生问题；共享发展注重解决社会公平正义问题。所以注重解决发展不平衡问题的是协调发展。","score":2},{"id":"zt-2023-c-22","isSubjective":false,"num":22,"category":"2023年成考政治真题卷 · 单选","stem":"构建新发展格局明确了我国经济现代化的路径选择。新发展格局指的是（ ）","options":["坚持“两个毫不动摇”","市场和资源“两头在外”的发展格局","以国内大循环为主体、国内国际双循环相互促进","发挥市场在资源配置中的决定性作用和更好发挥政府作用"],"answer":2,"answerLetter":"C","explanation":"新发展格局是指以国内大循环为主体、国内国际双循环相互促进的发展格局，这是我国应对国内外 形势变化作出的重要战略部署。A选项“两个毫不动摇”是关于公有制经济和非公有制经济的政策；B选项市 场和资源“两头在外”是过去的一种发展模式，不符合新发展格局要求；D选项强调的是市场与政府在资源配 置中的作用，与新发展格局概念不同。","score":2},{"id":"zt-2023-c-23","isSubjective":false,"num":23,"category":"2023年成考政治真题卷 · 单选","stem":"新时代推进全面依法治国的总抓手是（ ）","options":["坚持以人民为中心","建设中国特色社会主义法治体系","坚持统筹推进国内法治和涉外法治","坚持依法治国、依法执政、依法行政共同推进"],"answer":1,"answerLetter":"B","explanation":"建设中国特色社会主义法治体系是全面依法治国的总抓手，它涵盖了法治建设的各个方面，其他选 项虽也是依法治国重要内容，但并非总抓手。","score":2},{"id":"zt-2023-c-24","isSubjective":false,"num":24,"category":"2023年成考政治真题卷 · 单选","stem":"总体国家安全观明确，国家安全的宗旨和根本分别是（ ）","options":["人民安全和政治安全","科技安全和网络安全","经济安全和生态安全","资源安全和太空安全"],"answer":0,"answerLetter":"A","explanation":"总体国家安全观以人民安全为宗旨，以政治安全为根本。所以应选与这两项对应的选项。","score":2},{"id":"zt-2023-c-25","isSubjective":false,"num":25,"category":"2023年成考政治真题卷 · 单选","stem":"习近平强军思想中，反映军队的根本职能和军队建设的根本指向的是（ ）","options":["能打胜仗","作风优良","听党指挥","军民融合"],"answer":0,"answerLetter":"A","explanation":"军队的根本职能是打仗，军队建设的根本指向是能打胜仗，这是核心要求。作风优良主要关系军队 形象等；听党指挥是灵魂，确保军队性质；军民融合是发展途径等。","score":2},{"id":"zt-2023-c-26","isSubjective":false,"num":26,"category":"2023年成考政治真题卷 · 单选","stem":"2022年8月28日开工建设的西部陆海新通道骨干工程——平陆运河位于（ ）","options":["四川","云南","贵州","广西"],"answer":3,"answerLetter":"D","explanation":"平陆运河是广西内河水运规划中重要的一条出海通道，连接西江和北部湾，在广西建设。答案选D。","score":2},{"id":"zt-2023-c-27","isSubjective":false,"num":27,"category":"2023年成考政治真题卷 · 单选","stem":"党的二十大要求，全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必（ ）","options":["敢于斗争、善于斗争","增强自信、继续前进","自信自强、守正创新","踔厉奋发、勇毅前行"],"answer":0,"answerLetter":"A","explanation":"党的二十大报告明确提出全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于 斗争、善于斗争。这“三个务必”是基于党所处历史方位、面临形势任务、党情发展变化作出的重大论断。 答案：A。","score":2},{"id":"zt-2023-c-28","isSubjective":false,"num":28,"category":"2023年成考政治真题卷 · 单选","stem":"2023年3月26日，与我国建立外交关系的国家是（ ）","options":["哥伦比亚","洪都拉斯","南非","古巴"],"answer":1,"answerLetter":"B","explanation":"2023 年 3 月 26 日，中国同洪都拉斯签署《中华人民共和国和洪都拉斯共和国关于建立外交关系 的联合公报》，宣布自公报签署之日起，两国相互承认并建立大使级外交关系。答案选B。","score":2},{"id":"zt-2023-c-29","isSubjective":false,"num":29,"category":"2023年成考政治真题卷 · 单选","stem":"2023年5月19日，首届中国一中亚峰会发表《中国一中亚峰会西安宣言》，与会六国决心携手构建（ ）","options":["中国—中亚丝路开发银行","中国—中亚自由贸易区","中国—中亚经济合作组织","中国—中亚命运共同体"],"answer":3,"answerLetter":"D","explanation":"首届中国 - 中亚峰会旨在推动中国与中亚地区更紧密合作，构建命运共同体是这种合作的长远目标 和愿景，符合峰会主旨及双方合作方向。而A选项中国 - 中亚丝路开发银行并非此次峰会提出；B选项中国 - 中亚自由贸易区当时未提此构建目标；C选项中国 - 中亚经济合作组织也非峰会相关内容。答案：D.中国 —中亚命运共同体","score":2},{"id":"zt-2023-c-30","isSubjective":false,"num":30,"category":"2023年成考政治真题卷 · 单选","stem":"2023年6月26日至28日，十四届全国人大常委会第三次会议在北京召开。会议决定将每年8月15日设立为 （ ）","options":["全国土地日","国家宪法日","全国生态日","全民健身日"],"answer":2,"answerLetter":"C","explanation":"2023年6月，十四届全国人大常委会第三次会议决定将每年8月15日设立为全国生态日 。全国土地日 是6月25日，国家宪法日是12月4日，全民健身日是8月8日。","score":2},{"id":"zt-2023-c-31","isSubjective":false,"num":31,"category":"2023年成考政治真题卷 · 单选","stem":"思维和存在的关系问题是（ ）","options":["全部哲学的基本问题","历史观的基本问题","思想路线的核心问题","辩证法的核心问题"],"answer":0,"answerLetter":"A","explanation":"思维和存在的关系问题贯穿哲学发展始终，对这一问题的不同回答，划分出唯物主义和唯心主义 ，是全部哲学的基本问题。历史观基本问题是社会存在与社会意识关系问题；思想路线核心问题通常指实事 求是；辩证法核心问题是对立统一规律。","score":2},{"id":"zt-2023-c-32","isSubjective":false,"num":32,"category":"2023年成考政治真题卷 · 单选","stem":"马克思主义的产生具有深刻的思想渊源。作为马克思主义哲学直接理论来源的是（ ）","options":["古希腊罗马哲学","近代英国哲学","近代法国哲学","德国古典哲学"],"answer":3,"answerLetter":"D","explanation":"马克思主义哲学的直接理论来源是德国古典哲学，其中主要是黑格尔的辩证法和费尔巴哈的唯物主 义。其他选项虽对哲学发展有影响，但并非马克思主义哲学直接理论来源。","score":2},{"id":"zt-2023-c-33","isSubjective":false,"num":33,"category":"2023年成考政治真题卷 · 单选","stem":"“笑一笑十年少，愁一愁白了头”表明意识具有（ ）","options":["目的性","指导实践改造客观世界的作用","创造性","调控人的行为和生理活动的作用"],"answer":3,"answerLetter":"D","explanation":"“笑一笑十年少，愁一愁白了头”描述的是人的情绪（意识的一种表现）对人自身生理状态的影响 ，体现了意识对人的行为和生理活动有调控作用。","score":2},{"id":"zt-2023-c-34","isSubjective":false,"num":34,"category":"2023年成考政治真题卷 · 单选","stem":"人类社会是物质存在的一种特定形态，人的意识统一于物质，这是（ ）","options":["主观唯心主义的观点","辩证唯物主义的观点","客观唯心主义的观点","庸俗唯物主义的观点"],"answer":1,"answerLetter":"B","explanation":"辩证唯物主义认为世界是物质的，物质决定意识，意识是物质的反映，人的意识统一于物质，这符 合辩证唯物主义对物质和意识关系的阐述。 主观唯心主义把人的主观精神当作世界的本原，A选项不符合题 意。 客观唯心主义把客观精神（如上帝、理念等）看作世界的本原，C选项不符合题意。 庸俗唯物主义把意 识直接归结为物质，忽略了意识的主观性等特性，D选项不符合题意。","score":2},{"id":"zt-2023-c-35","isSubjective":false,"num":35,"category":"2023年成考政治真题卷 · 单选","stem":"对立统一规律提供的认识世界和改造世界的根本方法是（ ）","options":["阶级分析方法","历史分析方法","矛盾分析方法","逻辑分析方法"],"answer":2,"answerLetter":"C","explanation":"对立统一规律揭示了事物普遍联系的根本内容和永恒发展的内在动力，矛盾是对立统一的体现，所 以对立统一规律提供的根本方法就是矛盾分析方法 。","score":2},{"id":"zt-2023-s-36","isSubjective":true,"num":36,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"简述社会存在和社会意识的辩证关系。","answer":"(1)社会存在决定社会意识，社会意识对社会存在具有反作用。(3分) (2)先进的社会意识对社会发展起积极的推动作用，落后的社会意识对社会发展起阻碍作用。(3分) (3)社会意识具有相对独立性。(4分)","explanation":"(1)社会存在决定社会意识，社会意识对社会存在具有反作用。(3分) (2)先进的社会意识对社会发展起积极的推动作用，落后的社会意识对社会发展起阻碍作用。(3分) (3)社会意识具有相对独立性。(4分)","score":10},{"id":"zt-2023-s-37","isSubjective":true,"num":37,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"简述近代中国社会的主要矛盾和历史任务。","answer":"(1)近代中国社会的主要矛盾是帝国主义和中华民族的矛盾，封建主义和人民大众的矛盾。(5分) (2)近代中国社会的历史任务是争取民族独立、人民解放和实现国家富强、人民幸福。(5分)","explanation":"(1)近代中国社会的主要矛盾是帝国主义和中华民族的矛盾，封建主义和人民大众的矛盾。(5分) (2)近代中国社会的历史任务是争取民族独立、人民解放和实现国家富强、人民幸福。(5分)","score":10},{"id":"zt-2023-s-38","isSubjective":true,"num":38,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"简述科学发展观的科学内涵。","answer":"(1)科学发展观的第一要义是发展。(3分) (2)科学发展观的核心是以人为本。(3分) (3)科学发展观的基本要求是全面协调可持续。(2分) (4)科学发展观的根本方法是统筹兼顾。(2分)","explanation":"(1)科学发展观的第一要义是发展。(3分) (2)科学发展观的核心是以人为本。(3分) (3)科学发展观的基本要求是全面协调可持续。(2分) (4)科学发展观的根本方法是统筹兼顾。(2分)","score":10},{"id":"zt-2023-s-39","isSubjective":true,"num":39,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"为什么说党的领导是中国特色社会主义最本质的特征？","answer":"(1)这是由中国特色社会主义迈向新征程的实践逻辑所决定的。(4分) (2)这是由科学社会主义的理论逻辑所决定的。(3分) (3)这是由中国特色社会主义产生与发展的历史逻辑所决定的。(3分)","explanation":"(1)这是由中国特色社会主义迈向新征程的实践逻辑所决定的。(4分) (2)这是由科学社会主义的理论逻辑所决定的。(3分) (3)这是由中国特色社会主义产生与发展的历史逻辑所决定的。(3分)","score":10},{"id":"zt-2023-s-40","isSubjective":true,"num":40,"category":"2023年成考政治真题卷 · 论述题 (20分)","stem":"试述感性认识和理性认识的辩证关系，并说明割裂二者的统一在实际工作中会导致的错误。","answer":"感性认识和理性认识之间是对立统一的辩证关系。(3分) (1)感性认识有待于发展和深化为理性认识。(4分) (2)理性认识依赖于感性认识。(4分) (3)感性认识和理性认识相互渗透、相互包含。(4分) 割裂感性认识和理性认识的统一，在实际工作中会导致经验主义或教条主义的错误。经验主义夸大个别的、 局部的经验的作用，否认科学理论的指导意义；教条主义夸大理论和书本知识的作用，轻视实际经验，把理 论当成教条，到处生搬硬套。(5分)","explanation":"感性认识和理性认识之间是对立统一的辩证关系。(3分) (1)感性认识有待于发展和深化为理性认识。(4分) (2)理性认识依赖于感性认识。(4分) (3)感性认识和理性认识相互渗透、相互包含。(4分) 割裂感性认识和理性认识的统一，在实际工作中会导致经验主义或教条主义的错误。经验主义夸大个别的、 局部的经验的作用，否认科学理论的指导意义；教条主义夸大理论和书本知识的作用，轻视实际经验，把理 论当成教条，到处生搬硬套。(5分)","score":20},{"id":"zt-2023-s-41","isSubjective":true,"num":41,"category":"2023年成考政治真题卷 · 论述题 (20分)","stem":"党的十八大以来，以习近平同志为核心的党中央牢牢把握中国和世界发展大势，深刻思考人类前途命运 ，积极推进重大外交理论和实践创新，形成了习近平外交思想，指引外交工作取得全方位、开创性历史成就 。试述新时代中国独立自主的和平外交政策的主要内涵。","answer":"(1)把国家主权和安全放在第一位，坚定地维护我国的国家利益，反对任何国家损害我国的独立、主 权、安全和尊严。(4分) (2)一切从我国人民和世界人民的根本利益出发，根据事情本身的是非曲直决定自己的政治立场和政策，不屈 从于任何外来压力。(4分) (3)坚持各国的事务应由各国政府和人民决定，世界上的事情应由各国政府和人民平等协商，反对霸权主义和 强权政治。(4分) (4)坚持在和平共处五项原则基础上同世界各国建立和发展友好关系。(4分) (5)不结盟、不搞军事集团，不参加军备竞赛，不进行军事扩张，不谋求霸权。(4分)","explanation":"(1)把国家主权和安全放在第一位，坚定地维护我国的国家利益，反对任何国家损害我国的独立、主 权、安全和尊严。(4分) (2)一切从我国人民和世界人民的根本利益出发，根据事情本身的是非曲直决定自己的政治立场和政策，不屈 从于任何外来压力。(4分) (3)坚持各国的事务应由各国政府和人民决定，世界上的事情应由各国政府和人民平等协商，反对霸权主义和 强权政治。(4分) (4)坚持在和平共处五项原则基础上同世界各国建立和发展友好关系。(4分) (5)不结盟、不搞军事集团，不参加军备竞赛，不进行军事扩张，不谋求霸权。(4分)","score":20}]},{"id":"zt-2022","title":"2022年成考政治真题卷","type":"past","year":2022,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2022-c-1","isSubjective":false,"num":1,"category":"2022年成考政治真题卷 · 单选","stem":"马克思主义的物质范畴从自然与社会存在中抽象出的共同特征是（ ）。","options":["客观实在性","可知性","时空限定性","运动性"],"answer":0,"answerLetter":"A","explanation":"马克思主义认为物质的唯一特性是客观实在性，它是从万事万物即自然与社会存在中抽象出的共同 本质特征。可知性强调能被认识；时空限定性并非共同特征；运动性是物质的根本属性。","score":2},{"id":"zt-2022-c-2","isSubjective":false,"num":2,"category":"2022年成考政治真题卷 · 单选","stem":"世界的物质统一性是（ ）。","options":["阶段性的统一","条件性的统一","多样性的统一","历史性的统一"],"answer":2,"answerLetter":"C","explanation":"世界的物质统一性原理表明，世界是在物质基础上的统一，这种统一不是单一的、无差别的，而是 包含着无限多样的物质形态和物质运动形式的统一。物质世界在客观实在性的基础上，呈现出丰富的多样性 。而阶段性、条件性、历史性的统一表述均未抓住世界物质统一性本质特征。","score":2},{"id":"zt-2022-c-3","isSubjective":false,"num":3,"category":"2022年成考政治真题卷 · 单选","stem":"从本质上讲，唯物辩证法是（ ）。","options":["客观实在性","可知性","时空限定性","运动性"],"answer":0,"answerLetter":"A","explanation":"【标准答案：A】","score":2},{"id":"zt-2022-c-4","isSubjective":false,"num":4,"category":"2022年成考政治真题卷 · 单选","stem":"辩证否定的实质（ ）。","options":["全盘否定","自我否定","回复","扬弃"],"answer":3,"answerLetter":"D","explanation":"辩证否定既不是简单地肯定一切，也不是简单地否定一切，而是既肯定又否定，既克服又保留，其 实质是“扬弃”。“扬弃”就是新事物对旧事物既批判又继承、既克服其消极因素又保留其积极因素。A选项 “全盘否定”错误，不符合辩证否定观；B选项“自我否定”没有突出辩证否定实质的核心内涵；C选项“回 复”与辩证否定实质无关。","score":2},{"id":"zt-2022-c-5","isSubjective":false,"num":5,"category":"2022年成考政治真题卷 · 单选","stem":"实践是人类能动地改造世界的社会性的物质活动，其基本特征是客观实在性，自觉能动性及（ ）。","options":["社会历史性","主观创造性","主体多元性","目标单一性"],"answer":0,"answerLetter":"A","explanation":"实践的基本特征有客观实在性（物质性）、自觉能动性（目的性）、社会历史性（受历史条件制约 ） ，这是实践的三个基本特征。B选项主观创造性表述不准确；C主体多元性、D目标单一性不属于实践基本 特征。","score":2},{"id":"zt-2022-c-6","isSubjective":false,"num":6,"category":"2022年成考政治真题卷 · 单选","stem":"价值是客体对个人，群体乃至整个社会的生活和活动所具有的（ ）。","options":["积极意义","绝对意义","消极意义","相对意义"],"answer":0,"answerLetter":"A","explanation":"价值通常被理解为客体对主体（个人、群体、社会等）所具有的积极作用和意义，是能满足主体某 种需求、带来益处的，并非绝对意义、消极意义或相对意义。","score":2},{"id":"zt-2022-c-7","isSubjective":false,"num":7,"category":"2022年成考政治真题卷 · 单选","stem":"社会存在主要包括自然环境，人口因素以及（ ）。","options":["物质生产方式","社会风俗","政治文化建设","历史传统"],"answer":0,"answerLetter":"A","explanation":"社会存在是社会生活的物质方面，主要包括自然环境、人口因素和物质生产方式。物质生产方式是 社会存在和发展的基础及决定力量。而社会风俗、政治文化建设、历史传统都属于社会意识范畴。","score":2},{"id":"zt-2022-c-8","isSubjective":false,"num":8,"category":"2022年成考政治真题卷 · 单选","stem":"政治上层建筑的核心（ ）。","options":["政党","国家政权","立法司法制度","行政制度"],"answer":1,"answerLetter":"B","explanation":"政治上层建筑是指人们在一定经济基础上建起的政治、法律制度以及建立的军队、警察、法庭、监 狱、政府部门、党派等国家机器和政治组织。其中，国家政权是政治上层建筑的核心，因为它掌控着社会的 统治权力，对其他政治上层建筑要素起着决定性的支配作用。","score":2},{"id":"zt-2022-c-9","isSubjective":false,"num":9,"category":"2022年成考政治真题卷 · 单选","stem":"社会领域存在着很多矛盾，其中生产力和生产关系，经济基础和上层建筑的矛盾是（ ）。","options":["社会主要矛盾","社会基本矛盾","次要矛盾","非基本矛盾"],"answer":1,"answerLetter":"B","explanation":"生产力和生产关系、经济基础和上层建筑的矛盾贯穿人类社会始终，是推动社会发展的基本动力 ，所以被称为社会基本矛盾。","score":2},{"id":"zt-2022-c-10","isSubjective":false,"num":10,"category":"2022年成考政治真题卷 · 单选","stem":"在生产关系中，最基本的是（ ）。","options":["生产资料所有制关系","政治关系","缺","家庭关系"],"answer":0,"answerLetter":"A","explanation":"生产关系包括生产资料所有制关系、人们在生产中的地位及相互关系、产品分配关系，其中生产资 料所有制关系是最基本的，它决定着其他关系。政治关系和家庭关系不属于生产关系范畴。","score":2},{"id":"zt-2022-c-11","isSubjective":false,"num":11,"category":"2022年成考政治真题卷 · 单选","stem":"毛泽东思想初步形成的标志是（ ）。","options":["《中国社会各阶级的分析》的发表","农村包围城市，武装夺取政权道路思想的提出和阐述","中国七届二中全会提出党的工作重心由农村转为城市","第一届全国人民代表大会的召开"],"answer":1,"answerLetter":"B","explanation":"毛泽东思想初步形成的重要标志是农村包围城市、武装夺取政权道路理论的提出，这一理论指明了 中国革命的独特道路。A选项是毛泽东早期著作，此时思想尚未初步形成；C选项是在解放战争即将胜利时 ，毛泽东思想成熟后的内容；D选项与毛泽东思想初步形成无关。","score":2},{"id":"zt-2022-c-12","isSubjective":false,"num":12,"category":"2022年成考政治真题卷 · 单选","stem":"开始确立以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位的会议是（ ）。","options":["八七会议","古田会议","遵义会议","瓦窑堡会议"],"answer":2,"answerLetter":"C","explanation":"遵义会议结束了王明“左”倾冒险主义在中共中央的统治，确立了以毛泽东为代表的新的中央的正 确领导，在极端危急的历史关头，挽救了党，挽救了红军，挽救了中国革命。","score":2},{"id":"zt-2022-c-13","isSubjective":false,"num":13,"category":"2022年成考政治真题卷 · 单选","stem":"我国新民主主义革命的最基本动力是（ ）。","options":["城市小资产阶级","农民阶级","民族资产阶级","无产阶级"],"answer":3,"answerLetter":"D","explanation":"无产阶级是中国革命最基本的动力。无产阶级是新的社会生产力的代表，是近代中国最进步的阶级 。农民阶级是主力军，城市小资产阶级是基本动力之一，民族资产阶级有两面性，是革命力量之一但不是最 基本动力。","score":2},{"id":"zt-2022-c-14","isSubjective":false,"num":14,"category":"2022年成考政治真题卷 · 单选","stem":"在土地革命，武装斗争，农村革命根据地建设的相互关系中，中国革命的战略阵地是（ ）。","options":["土地革命","农村革命根据地","武装斗争","城市隐蔽战线"],"answer":1,"answerLetter":"B","explanation":"农村革命根据地是中国革命的战略阵地，它为武装斗争和土地革命提供了依托。土地革命是民主革 命的基本内容；武装斗争是中国革命的主要形式；城市隐蔽战线与题干所问关系不大。","score":2},{"id":"zt-2022-c-15","isSubjective":false,"num":15,"category":"2022年成考政治真题卷 · 单选","stem":"从中华人民共和国成立到社会主义改造基本完成的历史时期是指（ ）。","options":["从封建社会向资本主义社会转变的时期","从旧民主主义革命的时期向新民主主义革命转变的时期","从新民主主义到社会主义过渡的时期","从社会主义向共产主义的过渡时期"],"answer":2,"answerLetter":"C","explanation":"新中国成立到社会主义改造基本完成，这一阶段是我国从新民主主义社会向社会主义社会过渡的阶 段。A 选项不符合史实，我国没有从封建社会向资本主义社会转变这一过程；B 选项旧民主主义革命向新民 主主义革命转变是五四运动；D 选项社会主义改造完成后才进入社会主义，当时还没到从社会主义向共产主 义过渡阶段。","score":2},{"id":"zt-2022-c-16","isSubjective":false,"num":16,"category":"2022年成考政治真题卷 · 单选","stem":"《论十大关系》从十个方面论述了我国社会主义建设需要重点把握的一系列重大关系，前五个方面主要讨 论的是（ ）。","options":["经济领域问题","国际战略问题","政治生活问题","思想文化问题"],"answer":0,"answerLetter":"A","explanation":"《论十大关系》前五个方面主要涉及重工业和轻工业、农业的关系，沿海工业和内地工业的关系 ，经济建设和国防建设的关系等，这些都属于经济领域问题。","score":2},{"id":"zt-2022-c-17","isSubjective":false,"num":17,"category":"2022年成考政治真题卷 · 单选","stem":"贯穿邓小平理论的思想路线是（ ）。","options":["放下包袱轻装入阵","开拓创新与时俱进","开放脑筋集思广益","解放思想实事求是"],"answer":3,"answerLetter":"D","explanation":"邓小平理论的精髓是解放思想、实事求是 ，这也是贯穿邓小平理论的思想路线。解放思想是实事求 是的前提，实事求是是解放思想的目的和归宿。","score":2},{"id":"zt-2022-c-18","isSubjective":false,"num":18,"category":"2022年成考政治真题卷 · 单选","stem":"社会主义初级阶段基本路线最主要的内容可概括为（ ）。","options":["抓革命促生产","一要吃饭二要建设","两手抓，两手都要硬","一个中心，两个基本点"],"answer":3,"answerLetter":"D","explanation":"社会主义初级阶段基本路线是以经济建设为中心，坚持四项基本原则，坚持改革开放，即“一个中 心，两个基本点” 。A选项“抓革命促生产”是特定历史时期口号；B选项“一要吃饭二要建设”并非基本路 线内容；C选项“两手抓，两手都要硬”是关于物质文明和精神文明建设等方面的要求，不是基本路线最主要 内容。","score":2},{"id":"zt-2022-c-19","isSubjective":false,"num":19,"category":"2022年成考政治真题卷 · 单选","stem":"三个代表重要思想可集中概括为：我们党必须始终代表中国先进生产力的发展要求，代表中国先进文化的 前进方向，代表中国最广大人民的（ ）。","options":["当前利益","长远利益","根本利益","全部利益"],"answer":2,"answerLetter":"C","explanation":"“三个代表”重要思想明确表述为党要始终代表中国最广大人民的根本利益 ，强调的是从整体、长 远和本质上维护人民利益，并非局限于当前、长远某一方面利益或全部利益。","score":2},{"id":"zt-2022-c-20","isSubjective":false,"num":20,"category":"2022年成考政治真题卷 · 单选","stem":"在全面建设小康社会进程中形成的科学发展观，其基本要求是（ ）。","options":["推动经济社会发展","以人为本","全面协调可持续","统筹兼顾"],"answer":2,"answerLetter":"C","explanation":"科学发展观，第一要义是推动经济社会发展，核心立场是以人为本，基本要求是全面协调可持续 ，根本方法是统筹兼顾。所以选体现基本要求的选项。","score":2},{"id":"zt-2022-c-21","isSubjective":false,"num":21,"category":"2022年成考政治真题卷 · 单选","stem":"新时代中国特色社会主义事业总体布局是（ ）。","options":["一根红线","两个大局","四个全面","五位一体"],"answer":3,"answerLetter":"D","explanation":"新时代中国特色社会主义事业总体布局是“五位一体”，即经济建设、政治建设、文化建设、社会 建设、生态文明建设五位一体。“四个全面”是战略布局；“一根红线”并非事业总体布局相关表述；“两 个大局”指中华民族伟大复兴战略全局和世界百年未有之大变局，与总体布局无关。答案：D 。","score":2},{"id":"zt-2022-c-22","isSubjective":false,"num":22,"category":"2022年成考政治真题卷 · 单选","stem":"中华民族伟大复兴的形象表达是（ ）。","options":["工业化","中国梦","小康社会","天下大同"],"answer":1,"answerLetter":"B","explanation":"中国梦，就是实现中华民族伟大复兴，它是中华民族伟大复兴的形象表达。工业化是经济发展的一 个阶段特征；小康社会是阶段性奋斗目标；天下大同是一种理想社会状态，但并非中华民族伟大复兴的形象 表达。","score":2},{"id":"zt-2022-c-23","isSubjective":false,"num":23,"category":"2022年成考政治真题卷 · 单选","stem":"党的十九大提出的“两步走”战略安排的第二步是（ ）。","options":["到2035年，基本实现现代化","到2035年，全体人民共同富裕取得更为明显的实质性进展","到本世纪中叶，把我国建成富强文明民主和谐的社会主义现代化国家","到本世纪中叶，把我国建成富强文明民主和谐美丽的社会主义现代化强国"],"answer":3,"answerLetter":"D","explanation":"党的十九大提出的“两步走”战略安排，第一步是到2035年基本实现社会主义现代化；第二步是到 本世纪中叶，把我国建成富强民主文明和谐美丽的社会主义现代化强国。A选项是第一步内容；B选项并非 “两步走”战略第二步核心表述；C选项缺少“美丽”且表述为之前的“三步走”战略目标。","score":2},{"id":"zt-2022-c-24","isSubjective":false,"num":24,"category":"2022年成考政治真题卷 · 单选","stem":"立足新发展阶段，必须贯彻新发展理念，构建新发展格局，其中，构建新发展格局明确了我国现代化建设 的是（ ）。","options":["历史方位","指导原则","路径选择","根本立场"],"answer":2,"answerLetter":"C","explanation":"新发展阶段明确了我国发展的历史方位；新发展理念是我国现代化建设的指导原则；构建新发展格 局是我国经济现代化的路径选择；人民至上是新发展理念的根本立场。","score":2},{"id":"zt-2022-c-25","isSubjective":false,"num":25,"category":"2022年成考政治真题卷 · 单选","stem":"在社会主义核心价值观的基本内容中，作为社会层面价值要求的是（ ）。","options":["富强、民主、文明、和谐","自由、平等、公正、法治","博学、明辨、慎思、笃行","爱国、敬业、诚信、友善"],"answer":1,"answerLetter":"B","explanation":"社会主义核心价值观中，国家层面是富强、民主、文明、和谐；社会层面是自由、平等、公正、法 治；个人层面是爱国、敬业、诚信、友善。C选项“博学、明辨、慎思、笃行”不属于社会主义核心价值观内 容。答案选B 。","score":2},{"id":"zt-2022-c-26","isSubjective":false,"num":26,"category":"2022年成考政治真题卷 · 单选","stem":"中国特色社会主义政治经济学的最新成就是（ ）。","options":["毛泽东思想","周恩来经济思想","邓小平经济思想","习近平经济思想"],"answer":3,"answerLetter":"D","explanation":"习近平经济思想是中国特色社会主义政治经济学的最新成果，是运用马克思主义政治经济学基本原 理指导新时代经济发展实践形成的重大理论成果。毛泽东思想、周恩来经济思想所处时代中国特色社会主义 政治经济学还在探索发展阶段；邓小平经济思想为中国特色社会主义政治经济学发展作出重要贡献，但不是 最新成果。","score":2},{"id":"zt-2022-c-27","isSubjective":false,"num":27,"category":"2022年成考政治真题卷 · 单选","stem":"全面从严治党摆在首位的是（ ）。","options":["政治建设","思想建设","组织建设","作风建设"],"answer":0,"answerLetter":"A","explanation":"党的政治建设是党的根本性建设，决定党的建设方向和效果，所以全面从严治党要把政治建设摆在 首位。","score":2},{"id":"zt-2022-c-28","isSubjective":false,"num":28,"category":"2022年成考政治真题卷 · 单选","stem":"坚持总体国家安全观，必须坚持人民安全、政治安全、国家利益至上有机统一。其中，国家安全的根本是 （ ）。","options":["人民安全","政治安全","国家利益至上","生态安全"],"answer":1,"answerLetter":"B","explanation":"总体国家安全观中，政治安全是根本，它关乎国家的主权、政权等核心要素。人民安全是宗旨，国 家利益至上是准则 ，生态安全属于国家安全体系的一部分，但不是根本。","score":2},{"id":"zt-2022-c-29","isSubjective":false,"num":29,"category":"2022年成考政治真题卷 · 单选","stem":"习近平强军思想强调，人民军队建军之本、强军之魂是（ ）。","options":["党对军队的绝对领导","能打仗，打胜仗","作风优良","军民融合发展"],"answer":0,"answerLetter":"A","explanation":"党对军队的绝对领导是人民军队的建军之本、强军之魂，这是基于历史经验、国家性质和军队使命 等多方面得出的重要论断。其他选项中，能打仗、打胜仗是军队的根本职能和军队建设的根本指向；作风优 良是我军鲜明特色和政治优势；军民融合发展是国家战略。答案：A。","score":2},{"id":"zt-2022-c-30","isSubjective":false,"num":30,"category":"2022年成考政治真题卷 · 单选","stem":"新时代中国外交政策的宗旨仍然是（ ）。","options":["重持公道，伸张正义","亲仁善邻，协和万邦","维护世界和平，促进共同发展","弘义融利、扶危济困"],"answer":2,"answerLetter":"C","explanation":"这是对新时代中国外交政策宗旨这一基础知识点的考查。中国外交政策宗旨自确定后未发生改变 ，一直是维护世界和平、促进共同发展。答案选C。","score":2},{"id":"zt-2022-c-31","isSubjective":false,"num":31,"category":"2022年成考政治真题卷 · 单选","stem":"审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》的会议是（ ）。","options":["中共十九届三中全会","中共十九届四中全会","中共十九届五中全会","中共十九届六中全会"],"answer":3,"answerLetter":"D","explanation":"中共十九届六中全会审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》，这是总 结党的百年奋斗历程的重要文件，具有重大历史意义。其他几次会议各有重要议题，但与该决议无关。答案 ：D","score":2},{"id":"zt-2022-c-32","isSubjective":false,"num":32,"category":"2022年成考政治真题卷 · 单选","stem":"2021年我国GDP总量首次超过（ ）。","options":["80万亿元","90万亿元","100万亿元","110万亿元"],"answer":3,"answerLetter":"D","explanation":"2021年我国GDP总量为114.4万亿元，首次超过110万亿元 。","score":2},{"id":"zt-2022-c-33","isSubjective":false,"num":33,"category":"2022年成考政治真题卷 · 单选","stem":"2022年2月20日，第二十四届冬季奥林匹克运动会闭幕式顺利举行，举办城市成为历史首位“双奥之城 ”。该城市是（ ）。","options":["北京","悉尼","纽约","伦敦"],"answer":0,"answerLetter":"A","explanation":"2008 年夏季奥运会和 2022 年冬奥会都在北京举办，北京是世界首个“双奥之城”。悉尼、纽约、 伦敦都不符合这一情况。","score":2},{"id":"zt-2022-c-34","isSubjective":false,"num":34,"category":"2022年成考政治真题卷 · 单选","stem":"2022年6月17日，我国举行第三艘航空母舰下水命名仪式，经中央军委批准，我国第三艘航空母舰命名为 中国人民解放军海军（ ）。","options":["辽宁舰","山东舰","福建舰","广东舰"],"answer":2,"answerLetter":"C","explanation":"2022年6月17日，我国第三艘航空母舰命名为中国人民解放军海军福建舰。辽宁舰是我国第一艘航母 ，山东舰是第二艘。广东舰未存在这样的航母命名。","score":2},{"id":"zt-2022-c-35","isSubjective":false,"num":35,"category":"2022年成考政治真题卷 · 单选","stem":"2022年6月，第三次全国国土调查结果显示，我国现有耕地19.18亿亩，牢牢守住了耕地红线，我国划定的 耕地红线的面积是（ ）。","options":["16亿亩","17亿亩","18亿亩","19亿亩"],"answer":2,"answerLetter":"C","explanation":"我国划定的耕地红线是18亿亩。","score":2},{"id":"zt-2022-s-36","isSubjective":true,"num":36,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"简述矛盾的同一性和斗争性。","answer":"(1)矛盾的同一性和斗争性相互区别，相互联结。 (2)同一性：矛盾双方相互联系、相互吸引的性质。斗争性：矛盾双方相互排斥、相互对立的性质。矛盾的同 一性和斗争性是两种相反的属性。同一性是相对的;斗争性是绝对的。 (3)同一性不能脱离斗争性，没有斗争性就没有同一性;斗争性寓于同一性之中，没有同一性也就没有斗争性 。 (4)我们在分析和处理矛盾时，必须在对立中把握同一，在同一中把握对立。社会主义在发展中，一方面要学 习和引进资本主义的先进成果，否则不利于社会主义的发展，另一方面，又要警惕资本主义的干扰和挑战 ，否则社会主义制度就无法坚持。 【考点】事物的联系、发展及其规律——唯物辩证法的基本规律","explanation":"(1)矛盾的同一性和斗争性相互区别，相互联结。 (2)同一性：矛盾双方相互联系、相互吸引的性质。斗争性：矛盾双方相互排斥、相互对立的性质。矛盾的同 一性和斗争性是两种相反的属性。同一性是相对的;斗争性是绝对的。 (3)同一性不能脱离斗争性，没有斗争性就没有同一性;斗争性寓于同一性之中，没有同一性也就没有斗争性 。 (4)我们在分析和处理矛盾时，必须在对立中把握同一，在同一中把握对立。社会主义在发展中，一方面要学 习和引进资本主义的先进成果，否则不利于社会主义的发展，另一方面，又要警惕资本主义的干扰和挑战 ，否则社会主义制度就无法坚持。 【考点】事物的联系、发展及其规律——唯物辩证法的基本规律","score":10},{"id":"zt-2022-s-37","isSubjective":true,"num":37,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"简述毛泽东思想活的灵魂及其内涵。","answer":"(1)实事求是：一切从客观实际出发，理论联系实际，坚持在实践中检验和发展真理。是毛泽东思想 的世界观和方法论的基础，是毛泽东思想的精髓。 (2)群众路线：一切为了群众，一切依靠群众，从群众中来，到群众中去。是中国共产党的一切工作必须遵循 的基本路线和基本方法。 (3)独立自主：就是从中国实际出发，依靠本国革命力量和人民群众的努力，走出适合本国特点的革命建设道 路。 【考点】毛泽东思想及其历史地位——毛泽东思想的主要内容、活的灵魂和历史地位","explanation":"(1)实事求是：一切从客观实际出发，理论联系实际，坚持在实践中检验和发展真理。是毛泽东思想 的世界观和方法论的基础，是毛泽东思想的精髓。 (2)群众路线：一切为了群众，一切依靠群众，从群众中来，到群众中去。是中国共产党的一切工作必须遵循 的基本路线和基本方法。 (3)独立自主：就是从中国实际出发，依靠本国革命力量和人民群众的努力，走出适合本国特点的革命建设道 路。 【考点】毛泽东思想及其历史地位——毛泽东思想的主要内容、活的灵魂和历史地位","score":10},{"id":"zt-2022-s-38","isSubjective":true,"num":38,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"简述确立社会主义基本制度的重大意义。","answer":"(1)极大地提高了工人阶级和广大劳动人民的积极性、创造性，极大地促进了我国社会生产力的发展 。 (2)是我国历史上最深刻最伟大的社会变革，使广大劳动人民真正成为国家的主人。 (3)使占世界人口四分之一的东方大国进入社会主义社会，对世界格局产生了积极影响。 (4)是马克思列宁主义关于社会主义革命理论在中国的正确运用和创造性的发展。 【考点】社会主义改造理论——社会主义制度在中国的确立","explanation":"(1)极大地提高了工人阶级和广大劳动人民的积极性、创造性，极大地促进了我国社会生产力的发展 。 (2)是我国历史上最深刻最伟大的社会变革，使广大劳动人民真正成为国家的主人。 (3)使占世界人口四分之一的东方大国进入社会主义社会，对世界格局产生了积极影响。 (4)是马克思列宁主义关于社会主义革命理论在中国的正确运用和创造性的发展。 【考点】社会主义改造理论——社会主义制度在中国的确立","score":10},{"id":"zt-2022-s-39","isSubjective":true,"num":39,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"邓小平社会主义市场经济理论要点有哪些?","answer":"(1)计划经济和市场经济不是区分社会主义和资本主义的标志，计划经济不等于社会主义，市场经济 也不等于资本主义。市场经济作为资源配置的一种方式，本身不具有制度属性，可以和不同社会制度结合 ，从而表现出不同性质。 (2)计划和市场都是调节经济的手段，各有优势和长处，社会主义市场经济要把计划和市场两者结合起来。 (3)社会主义市场经济是为了更好发展社会生产力，社会主义与市场经济之间不存在根本矛盾。实践证明，社 会主义搞市场经济更有利于解放和发展生产力。 【考点】邓小平理论——邓小平理论的基本问题和主要内容","explanation":"(1)计划经济和市场经济不是区分社会主义和资本主义的标志，计划经济不等于社会主义，市场经济 也不等于资本主义。市场经济作为资源配置的一种方式，本身不具有制度属性，可以和不同社会制度结合 ，从而表现出不同性质。 (2)计划和市场都是调节经济的手段，各有优势和长处，社会主义市场经济要把计划和市场两者结合起来。 (3)社会主义市场经济是为了更好发展社会生产力，社会主义与市场经济之间不存在根本矛盾。实践证明，社 会主义搞市场经济更有利于解放和发展生产力。 【考点】邓小平理论——邓小平理论的基本问题和主要内容","score":10},{"id":"zt-2022-s-40","isSubjective":true,"num":40,"category":"2022年成考政治真题卷 · 论述题 (20分)","stem":"习近平指出不能用今天的时代条件，发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人 才能干出来的成绩。试着评价历史人物的正确方法。","answer":"(1)坚持历史主义的原则和方法，即杰出人物是一定历史条件的产物，将其放到他所在的历史条件下 加以评价。不能用今天的时代条件、发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人才 能干出的业绩来。 (2)坚持阶级分析的原则和方法，即联系杰出人物的阶级属性来评价杰出人物; (3)坚持全面辩证分析的原则和方法。不能把历史顺境中的成功简单归功于个人，也不能把历史逆境中的挫折 简单归咎于个人。既要肯定杰出人物的巨大历史功绩，又要分析其缺点错误，进行全面评价。 【考点】社会历史发展的动力——人民群众在历史发展中的作用","explanation":"(1)坚持历史主义的原则和方法，即杰出人物是一定历史条件的产物，将其放到他所在的历史条件下 加以评价。不能用今天的时代条件、发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人才 能干出的业绩来。 (2)坚持阶级分析的原则和方法，即联系杰出人物的阶级属性来评价杰出人物; (3)坚持全面辩证分析的原则和方法。不能把历史顺境中的成功简单归功于个人，也不能把历史逆境中的挫折 简单归咎于个人。既要肯定杰出人物的巨大历史功绩，又要分析其缺点错误，进行全面评价。 【考点】社会历史发展的动力——人民群众在历史发展中的作用","score":20},{"id":"zt-2022-s-41","isSubjective":true,"num":41,"category":"2022年成考政治真题卷 · 论述题 (20分)","stem":"2021年7月1日，习近平在庆祝中国共产党成立100周年大会上的讲话中强调：“中国共产党领导是中国特 色社会主义最本质的特征，中国特色社会主义制度的最大优势，是党和国家的根本所在，命脉所有，是全国 各族人民利益所系，命运所系。”如何理解中国共产党领导是中国特色社会主义制度的最大优势?","answer":"(1)中国共产党是中国特色社会主义制度的创建者。没有党就没有中国特色社会主义制度，制度优势 也就无从谈起。在党的领导下通过改革不断完善和发展中国特色社会主义制度，推进国家治理体系和治理能 力现代化，使中国特色社会主义制度更加成熟、更加定型。 (2)中国共产党的领导是充分发挥中国特色社会主义制度优势的根本保障。中国共产党是中国工人阶级、中国 人民和中华民族的先锋队，能够充分调动广大人民的积极性、主动性、创造性，有利于充分发挥中国特色社 会主义制度在保持党和国家活力方面的优势;党是先进生产力发展要求和先进文化发展方向的代表，有利于发 挥中国特色社会主义制度在解放和发展社会生产力、推动经济社会全面发展方面的优势;党代表了中国最广大 人民的根本利益，有利于充分发挥中国特色社会主义制度在维护和促进社会公平正义、实现全体人民共同富 裕方面的优势;党能够总揽全局，协调各方，有利于充分发挥中国特色社会主义制度集中力量办大事、有效应 对前进道路上的各种风险挑战方面的优势;党是领导和团结全国各族人民的核心力量，有利于充分发挥中国特 色社会主义制度在维护民族团结、社会稳定、国家统一方面的优势。 (3)中国共产党的自身优势是中国特色社会主义制度优势的主要来源。以马克思主义为指导，用马克思主义中 国化理论成果武装全党、教育人民的理论优势;坚定崇高的政治理想、政治信念和百折不挠的革命意志的政治 优势;遵循马克思主义建党原则，严密组织体系、严格组织生活、严明组织纪律，使党成为统一整体的组织优 势;实行民主集中制的制度优势;密切联系群众的作风优势。 【考点】坚持和加强党的领导——实现中华民族伟大复兴关键在党","explanation":"(1)中国共产党是中国特色社会主义制度的创建者。没有党就没有中国特色社会主义制度，制度优势 也就无从谈起。在党的领导下通过改革不断完善和发展中国特色社会主义制度，推进国家治理体系和治理能 力现代化，使中国特色社会主义制度更加成熟、更加定型。 (2)中国共产党的领导是充分发挥中国特色社会主义制度优势的根本保障。中国共产党是中国工人阶级、中国 人民和中华民族的先锋队，能够充分调动广大人民的积极性、主动性、创造性，有利于充分发挥中国特色社 会主义制度在保持党和国家活力方面的优势;党是先进生产力发展要求和先进文化发展方向的代表，有利于发 挥中国特色社会主义制度在解放和发展社会生产力、推动经济社会全面发展方面的优势;党代表了中国最广大 人民的根本利益，有利于充分发挥中国特色社会主义制度在维护和促进社会公平正义、实现全体人民共同富 裕方面的优势;党能够总揽全局，协调各方，有利于充分发挥中国特色社会主义制度集中力量办大事、有效应 对前进道路上的各种风险挑战方面的优势;党是领导和团结全国各族人民的核心力量，有利于充分发挥中国特 色社会主义制度在维护民族团结、社会稳定、国家统一方面的优势。 (3)中国共产党的自身优势是中国特色社会主义制度优势的主要来源。以马克思主义为指导，用马克思主义中 国化理论成果武装全党、教育人民的理论优势;坚定崇高的政治理想、政治信念和百折不挠的革命意志的政治 优势;遵循马克思主义建党原则，严密组织体系、严格组织生活、严明组织纪律，使党成为统一整体的组织优 势;实行民主集中制的制度优势;密切联系群众的作风优势。 【考点】坚持和加强党的领导——实现中华民族伟大复兴关键在党","score":20}]},{"id":"yc-1","title":"2026年成考预测试卷(一)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-1-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(一) · 单选","stem":"区分新事物和旧事物的根本标志是（ ）","options":["事物的全局性质未变，局部性质发生了根本变化","事物的主要矛盾未变化，次要矛盾发生了变化","事物的根据和条件发生了质的变化","事物的发展方向和道路发生了根本变化"],"answer":2,"answerLetter":"C","explanation":"区分新事物和旧事物的根本标志在于是否符合事物发展的必然趋势，是否具有强大的生命力和远大 的发展前途，而这通常意味着事物的根据和条件发生了质的变化。新事物是在旧事物的“母体”中孕育成熟 的，它否定了旧事物中消极腐朽的东西，吸收了旧事物中合理的、仍然适合新的条件的因素，并添加了旧事 物所不能容纳的新内容。选项A、B所描述并非区分新、旧事物的根本标志；选项D发展方向和道路的变化不能 直接等同于新、旧事物的区分。","score":2},{"id":"yc-1-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(一) · 单选","stem":"系统科学产生的意义在于它（ ）","options":["抛弃了唯物辩证法","代替了唯物辩证法","丰富了唯物辩证法","高于唯物辩证法"],"answer":2,"answerLetter":"C","explanation":"唯物辩证法是科学的世界观和方法论，具有普遍的指导意义。系统科学作为一门具体科学，它的产 生是对具体领域的研究成果。具体科学是哲学的基础，具体科学的发展为哲学的发展提供丰富的素材。系统 科学的产生丰富了唯物辩证法对世界联系和发展等方面的认识。 选项A，系统科学不可能抛弃唯物辩证法 ，唯物辩证法是科学的理论，对具体科学有指导作用，二者不是对立关系。 选项B，具体科学不能代替哲学 ，系统科学不能代替唯物辩证法，它们研究的层次和范围不同。 选项D，唯物辩证法是对整个世界最一般规 律的概括和总结，具有最高的普遍性和指导性，系统科学不能高于唯物辩证法。","score":2},{"id":"yc-1-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(一) · 单选","stem":"质量互变规律揭示了事物发展的（ ）","options":["源泉和动力","状态和形式","方向和道路","波浪式前进运动"],"answer":1,"answerLetter":"B","explanation":"质量互变规律表明事物发展是量变与质变的统一，量变与质变是事物发展变化存在的两种基本状态 和形式 。A选项，对立统一规律揭示事物发展的源泉和动力；C选项，否定之否定规律揭示事物发展的方向和 道路；D选项波浪式前进运动体现的是否定之否定规律。","score":2},{"id":"yc-1-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(一) · 单选","stem":"下列选项中属于因果联系的是（ ）","options":["先有闪电，后有雷鸣","夏天过去，秋天到来","白天过去，黑夜降临","实践出真知，斗争长才干"],"answer":3,"answerLetter":"D","explanation":"因果联系是指事物之间存在引起和被引起的关系。A选项中闪电和雷鸣是同时发生，只是由于光传播 速度比声音快才先看到闪电后听到雷鸣，并非因果关系；B选项夏天过去秋天到来、C选项白天过去黑夜降临 ，都是自然的时间顺序更替，不存在引起和被引起关系；D选项实践能引发获得真知，斗争会促使增长才干 ，存在引起和被引起的关系，属于因果联系。","score":2},{"id":"yc-1-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(一) · 单选","stem":"可能性是指（ ）","options":["头脑中的构造物","已经存在着的事物","预示事物发展前途的种种趋势","失去必然性的东西"],"answer":2,"answerLetter":"C","explanation":"可能性是事物发展过程中所包含的预示事物发展前途的种种趋势，它是基于事物的内在根据和外在 条件而存在的，并非头脑中的构造物，也不是已存在的事物，更不是失去必然性的东西。答案选C。","score":2},{"id":"yc-1-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(一) · 单选","stem":"内容与形式存在矛盾的根据是（ ）","options":["内容总是落后于形式的变化","内容活跃易变，形式相对稳定","形式决定内容，内容反作用于形式","形式活跃易变，内容相对稳定"],"answer":1,"answerLetter":"B","explanation":"内容和形式的关系中，内容是活跃易变的，形式则相对稳定，这种特性使得二者存在矛盾。A选项说 法错误，一般是形式落后于内容变化；C选项表述错误，是内容决定形式，形式反作用于内容；D选项说反了 。","score":2},{"id":"yc-1-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(一) · 单选","stem":"在认识论中坚持反映的原则（ ）","options":["是所有唯物主义的观点","仅是辩证唯物主义的观点","只是机械唯物主义的观点","是不可知论的观点"],"answer":0,"answerLetter":"A","explanation":"唯物主义都认为物质第一性，意识第二性，意识是对物质的反映，所以在认识论中坚持反映原则是 所有唯物主义的观点。辩证唯物主义、机械唯物主义都属于唯物主义阵营，都坚持反映原则，不只是辩证唯 物主义或机械唯物主义的观点。而不可知论是否认认识世界或彻底认识世界的可能性，与坚持反映原则相悖 。","score":2},{"id":"yc-1-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(一) · 单选","stem":"实践是认识的基础表明（ ）","options":["每个人必须事事实践才能有认识","只有参加实践就一定能获得正确认识","直接知识来自实践","一切认识归根到底来自实践"],"answer":3,"answerLetter":"D","explanation":"A选项“每个人必须事事实践才能有认识”过于绝对，人们可以通过间接经验获得认识，不一定要 事事都亲身实践。 B选项“只有参加实践就一定能获得正确认识”错误，实践不一定就能直接获得正确认识 ，认识有正确和错误之分，还要经过认识的发展过程等。 C选项“直接知识来自实践”表述不准确，直接知 识是相对间接知识而言，虽然直接知识与实践紧密相关，但不能简单说直接知识就来自实践，人们获取知识 途径多样。 D选项“一切认识归根到底来自实践”，实践是认识的来源，即使是通过间接经验获得的认识 ，追根溯源也是他人实践的结果，这体现了实践是认识的基础。","score":2},{"id":"yc-1-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(一) · 单选","stem":"认识的主体性原则是指（ ）","options":["主观性原则","主体决定客体原则","主体的能动性原则","客体依赖主体原则"],"answer":2,"answerLetter":"C","explanation":"认识的主体性原则强调的是主体在认识过程中的主动、能动作用。主体不是被动地反映客体，而是 积极主动地去认识、改造客体。","score":2},{"id":"yc-1-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(一) · 单选","stem":"实践高于理论的认识是因为实践具有（ ）","options":["普遍性","客观实在性","直接现实性","社会历史性"],"answer":2,"answerLetter":"C","explanation":"实践的直接现实性是指它能把理论变为实际，直接产生客观效果，这是理论认识所不具备的，所以 实践高于理论认识。答案：C 。","score":2},{"id":"yc-1-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(一) · 单选","stem":"社会进步的内在根据是（ ）","options":["社会基本矛盾运动","人与自然的和谐发展","各族人民的和睦相处","人与人之间的团结协作"],"answer":0,"answerLetter":"A","explanation":"社会基本矛盾即生产力和生产关系、经济基础和上层建筑的矛盾，这两对矛盾相互联系、相互作用 ，推动着人类社会从低级向高级发展，是社会进步的内在根据。B选项人与自然和谐发展、C选项各族人民和 睦相处、D选项人与人之间团结协作虽然对社会发展有积极作用，但不是社会进步的内在根据。答案：A。","score":2},{"id":"yc-1-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(一) · 单选","stem":"社会进步的最高标准是（ ）","options":["生产关系的改变","生产力的发展","文化素质的提高","人与人的团结一致"],"answer":1,"answerLetter":"B","explanation":"生产力是社会发展的最终决定力量，生产力的发展是衡量社会进步与否的根本标准，因为生产力发 展会带动生产关系变革等一系列变化，推动社会进步。","score":2},{"id":"yc-1-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(一) · 单选","stem":"法国资产阶级革命后出现多次封建王朝复辟，这说明（ ）","options":["社会进步无规律可言","社会进步是前进性与曲折性的统一","社会进步是人们的主观愿望","社会进步没有客观标准"],"answer":1,"answerLetter":"B","explanation":"法国资产阶级革命后虽出现多次封建王朝复辟，但资产阶级最终战胜封建势力，推动了社会进步。 这表明社会进步不是一帆风顺的，既有前进的趋势，又会经历曲折过程。答案：B 。社会进步是前进性与曲 折性的统一，法国资产阶级革命后的情况正是这一观点的体现。A选项社会进步是有规律的；C选项社会进步 是客观的，不是主观愿望；D选项社会进步有客观标准。所以ACD错误。","score":2},{"id":"yc-1-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(一) · 单选","stem":"人的本质属性是（ ）","options":["自然属性","先天属性","生理属性","社会属性"],"answer":3,"answerLetter":"D","explanation":"人既有自然属性也有社会属性，而社会属性是人区别于其他动物的本质属性，人是在社会关系中存 在和发展的。","score":2},{"id":"yc-1-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(一) · 单选","stem":"世界观是人们在实践中形成的（ ）","options":["对于自然现象的基本观点","对于整个世界的根本观点","对于人生意义的独特见解","对于社会问题的具体看法"],"answer":1,"answerLetter":"B","explanation":"世界观强调的是对整个世界的总的、根本的观点。A选项只提及自然现象，范围太窄；C选项说的是 人生意义，属于人生观范畴；D选项社会问题具体看法也不是对整个世界根本观点。只有B符合世界观定义。","score":2},{"id":"yc-1-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(一) · 单选","stem":"新民主主义的总路线的核心是（ ）","options":["无产阶级的领导","人民大众的参与","反帝","反封建"],"answer":0,"answerLetter":"A","explanation":"新民主主义革命总路线中，无产阶级的领导权是中国革命的中心问题，也是新民主主义革命理论的 核心问题，所以核心是无产阶级领导。","score":2},{"id":"yc-1-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(一) · 单选","stem":"新民主主义革命的指导思想是（ ）","options":["新三民主义","马克思列宁主义","社会主义","民粹主义"],"answer":1,"answerLetter":"B","explanation":"新民主主义革命是无产阶级领导的资产阶级民主革命，其指导思想是马克思列宁主义。新三民主义 是孙中山提出的资产阶级革命纲领，是旧民主主义革命时期的指导思想之一，但不是新民主主义革命指导思 想；社会主义是新民主主义革命胜利后要建立的社会形态，不是指导思想；民粹主义不符合中国革命实际 ，并非中国新民主主义革命指导思想。","score":2},{"id":"yc-1-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(一) · 单选","stem":"实现无产阶级领导权的根本保证是（ ）","options":["建立以工农联盟为基础的广泛统一战线","实行独立自主的方针","建立一支强大的革命武装","加强无产阶级政党的建设"],"answer":3,"answerLetter":"D","explanation":"无产阶级政党是无产阶级的先锋队，只有加强无产阶级政党建设，党才能制定正确路线方针政策 ，组织和领导革命取得胜利，实现领导权。其他选项虽重要，但不是根本保证。","score":2},{"id":"yc-1-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(一) · 单选","stem":"新民主主义革命的前途是（ ）","options":["建立资产阶级专政的资本主义制度","立即建立社会主义","经过新民主主义逐步过渡到社会主义","实现共产主义"],"answer":2,"answerLetter":"C","explanation":"新民主主义革命胜利后不可能建立资产阶级专政的资本主义制度，A 错误；新民主主义革命胜利后 不能立即建立社会主义，要经过过渡阶段，B 错误；共产主义是长远目标，不是新民主主义革命直接前途，D 错误。新民主主义革命的前途是经过新民主主义逐步过渡到社会主义 。","score":2},{"id":"yc-1-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(一) · 单选","stem":"毛泽东明确提出了新民主主义的三大经济纲领是在（ ）","options":["《目前形势和我们的任务》","《论联合政府》","《在中共七届二中全会上的讲话》","《新民主主义论》"],"answer":0,"answerLetter":"A","explanation":"1947 年毛泽东在《目前形势和我们的任务》中明确提出新民主主义三大经济纲领。《论联合政府》 主要阐述了党的三大作风等内容；《在中共七届二中全会上的讲话》提出党的工作重心转移等；《新民主主 义论》系统阐述新民主主义革命理论等。","score":2},{"id":"yc-1-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(一) · 单选","stem":"邓小平曾说：“现在我们虽然也在搞社会主义，但事实上不够格。”这说明（ ）","options":["我国实际上还处于向社会主义社会过渡的时期","我国搞的社会主义事实上是在补资本主义的课","我国的生产力不发达，还没有摆脱贫困，而贫穷不是社会主义","我国还严重地存在着封建残余、小生产习惯势力和资本主义腐朽思想的影响"],"answer":2,"answerLetter":"C","explanation":"邓小平这句话强调我国虽进入社会主义，但生产力水平还较低，没有达到理想中社会主义应有的发 达程度。A选项，我国早已过渡到社会主义社会；B选项，我国走的是社会主义道路并非补资本主义课；D选项 与题干所表达生产力方面内容无关。C选项指出我国生产力不发达，符合邓小平这句话含义。","score":2},{"id":"yc-1-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(一) · 单选","stem":"一切从实际出发，中国最大的实际就是（ ）","options":["人口多，劳动者素质不高","生产力水平低，发展不平衡","自然条件差，资源相对短缺","现在处于并长期处于社会主义初级阶段"],"answer":3,"answerLetter":"D","explanation":"“一切从实际出发”，中国最大实际就是我国现阶段的基本国情，即现在处于并长期处于社会主义 初级阶段 ，它涵盖了生产力、生产关系等多方面情况，而A、B、C选项只是国情的部分表现。","score":2},{"id":"yc-1-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(一) · 单选","stem":"改革和发展的前提是（ ）","options":["四项基本原则","依法治国","社会公平","社会稳定"],"answer":3,"answerLetter":"D","explanation":"改革、发展和稳定三者紧密相连，其中社会稳定是改革和发展得以顺利进行的前提条件。没有稳定 的社会环境，改革和发展都难以推进。","score":2},{"id":"yc-1-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(一) · 单选","stem":"社会主义初级阶段是指（ ）","options":["任何国家进入社会主义都要经历的起始阶段","在生产力落后、商品经济不发达条件下，建设社会主义必然要经历的特定阶段","从新民主主义社会向共产主义社会过渡的阶段","从社会主义向共产主义过渡的阶段"],"answer":1,"answerLetter":"B","explanation":"社会主义初级阶段不是泛指任何国家进入社会主义都必经阶段，而是特指我国在生产力落后、商品 经济不发达条件下建设社会主义必然要经历的特定阶段。A选项错误，不是任何国家；C选项，不是从新民主 主义向共产主义过渡；D选项，不是从社会主义向共产主义过渡。","score":2},{"id":"yc-1-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(一) · 单选","stem":"抓住机遇，深化改革，扩大开放，促进发展，保持稳定是党在社会主义初级阶段的（ ）","options":["基本纲领","基本路线","基本方针","基本政策"],"answer":2,"answerLetter":"C","explanation":"党在社会主义初级阶段基本纲领涵盖经济、政治、文化等方面具体目标和政策；基本路线是以经济 建设为中心，坚持四项基本原则，坚持改革开放；基本政策较为具体针对某方面工作。而“抓住机遇，深化 改革，扩大开放，促进发展，保持稳定”是一段时间内指导全局工作的基本方针，它协调了改革、发展与稳 定等关键要素间的关系。","score":2},{"id":"yc-1-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(一) · 单选","stem":"我国现阶段，个人收入分配必须贯彻（ ）","options":["多劳多得，少劳少得的原则","效率优先，兼顾公平的原则","股份制企业职工的按股分红收入","集体企业职工的工资奖金收入"],"answer":1,"answerLetter":"B","explanation":"我国现阶段个人收入分配制度是按劳分配为主体、多种分配方式并存，在分配过程中要处理好效率 与公平的关系，当前强调初次分配和再分配都要兼顾效率与公平，而在过去较长一段时间强调效率优先、兼 顾公平，这一理念对分配有重要指导意义。A选项“多劳多得，少劳少得”是按劳分配原则的部分体现，不全 面；C选项“股份制企业职工按股分红收入”和D选项“集体企业职工工资奖金收入”只是具体的分配形式 ，并非个人收入分配需贯彻的原则。","score":2},{"id":"yc-1-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(一) · 单选","stem":"私营经济中的劳动者的收入属于（ ）","options":["按劳分配的收入","按资分配","按劳动力价值分配","按经营分配"],"answer":2,"answerLetter":"C","explanation":"按劳分配是在公有制经济范围内，按照劳动者提供的劳动数量和质量进行分配，私营经济不属于公 有制经济，A选项错误。 按资分配是凭借资本所有权参与分配，劳动者一般不凭借资本获取收入，B选项错误 。 在私营经济中，劳动者把自己的劳动力作为商品出卖给私营企业主，其收入是按劳动力价值分配所得 ，C选项正确。 按经营分配主要是经营者依据经营成果等进行分配，劳动者并非经营主体，D选项错误。答案 ：C","score":2},{"id":"yc-1-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(一) · 单选","stem":"在社会保障中居核心地位的是（ ）","options":["社会保险","社会救济","社会福利","社会优抚"],"answer":0,"answerLetter":"A","explanation":"社会保险是社会保障体系的核心部分，因为它覆盖人群广，涉及养老、医疗、失业、工伤和生育等 关乎人们基本生活和经济来源的重要方面。而社会救济是对困难群体的救助；社会福利是更高层次的保障 ；社会优抚针对特定优抚对象。答案：A。","score":2},{"id":"yc-1-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(一) · 单选","stem":"在社会主义初级阶段，和按劳分配结合在一起的是（ ）","options":["按劳动力价值分配","按生产要素分配","按风险分配","按经营分配"],"answer":1,"answerLetter":"B","explanation":"在社会主义初级阶段，实行按劳分配为主体、多种分配方式并存的分配制度，多种分配方式实质是 按生产要素分配，所以按劳分配是和按生产要素分配结合在一起的。","score":2},{"id":"yc-1-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(一) · 单选","stem":"我国经济体制改革确立什么样的目标，是关系整个社会主义现代化建设全局的一个重大问题。这个问题的 核心是正确认识和处理（ ）","options":["改革与发展的关系","速度与效益的关系","计划与市场的关系","中央与地方的关系"],"answer":2,"answerLetter":"C","explanation":"我国经济体制改革的核心问题是计划与市场的关系，经济体制改革目标的确立关键就在于对计划和 市场关系的正确认识。计划和市场都是资源配置手段，社会主义也可以有市场。","score":2},{"id":"yc-1-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(一) · 单选","stem":"社会主义物质文明建设和精神文明建设的关系是（ ）","options":["相辅相成，相互促进","物质文明是内容，精神文明是形式","相互独立，互不相干","精神文明是内容，物质文明是形式"],"answer":0,"answerLetter":"A","explanation":"社会主义物质文明与精神文明是相辅相成、相互促进的关系。物质文明为精神文明提供物质基础 ，精神文明为物质文明提供智力支持、精神动力和思想保证 。B、D 选项将二者简单归结为内容与形式关系 不准确，C 选项说相互独立互不相干错误。","score":2},{"id":"yc-1-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(一) · 单选","stem":"党的十一届三中全会以来，邓小平和党中央提出了一系列两手抓的战略方针，其中关键是（ ）","options":["一手抓改革开放，一手抓打击犯罪","一手抓经济建设，一手抓民主法制","一手抓改革开放，一手抓惩治腐败","一手抓物质文明，一手抓精神文明"],"answer":3,"answerLetter":"D","explanation":"在邓小平提出的一系列“两手抓”战略方针中，物质文明与精神文明建设是根本性的，物质文明是 基础，精神文明提供动力和智力支持等，二者相辅相成，共同推动社会全面发展，所以两手抓关键是一手抓 物质文明，一手抓精神文明。","score":2},{"id":"yc-1-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(一) · 单选","stem":"社会主义精神文明建设的目标是（ ）","options":["引导人们树立正确的人生观、世界观、价值观","弘扬爱国主义精神","建立面向现代化、面向世界、面向未来的民族的、科学的、大众的文化","培养有理想、有道德、有文化、有纪律的公民"],"answer":3,"answerLetter":"D","explanation":"社会主义精神文明建设包括思想道德建设和教育科学文化建设，其根本目标是培育“四有”公民 ，即有理想、有道德、有文化、有纪律的公民。A、B选项属于思想道德建设方面的内容；C选项是中国特色社 会主义文化的内涵。","score":2},{"id":"yc-1-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(一) · 单选","stem":"党的十五大指出，有中国特色的社会主义文化，是综合国力的（ ）","options":["重要内容","重要标志","重要基础","重要支持"],"answer":1,"answerLetter":"B","explanation":"党的十五大明确指出，有中国特色的社会主义文化是综合国力的重要标志 。强调了文化在衡量综合 国力中的关键地位与独特标识作用。","score":2},{"id":"yc-1-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(一) · 单选","stem":"教育科学文化建设要解决的是（ ）","options":["提高整个民族的科学文化素质问题","在全社会形成共同理想和精神支柱问题","全体公民树立正确的人生观、世界观、价值观的问题","精神文明建设的方向问题"],"answer":0,"answerLetter":"A","explanation":"教育科学文化建设主要目的就是提升民族科学文化素质。B选项形成共同理想和精神支柱是思想道德 建设方面；C选项树立正确三观主要也靠思想道德等多方面综合，并非教育科学文化建设专门解决；D选项精 神文明建设方向由诸多因素共同决定，不是教育科学文化建设解决。","score":2},{"id":"yc-1-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"简述对立统一规律是唯物辩证法的实质与核心。","answer":"（1）在唯物辩证法的理论体系中，对立统一规律占有十分重要的地位，是唯物辩证法的实质与核 心。 第一，唯物辩证法揭示的是事物的联系与发展，而对立统一规律揭示的是普遍联系的根本内容和永恒发展的 根本动力，也就是说，所谓联系实质上是矛盾与矛盾、矛盾这方面与矛盾那方面的联系，所谓发展实质上是 矛盾推动下的发展。 第二，唯物辩证法是有着丰富内容的完整的科学理论体系，而对立统一规律则是理解唯物辩证法全部理论的 关键，唯物辩证法的其他规律与范畴都是对立统一规律在某一方面的展开。 第三，唯物辩证法与形而上学是两种根本对立的世界观，而是否承认矛盾则是唯物辩证法与形而上学对立的 焦点。 第四，唯物辩证法既是世界观，又是方法论，矛盾分析法则是最根本的认识方法。 （2）唯物辩证法是一个内容丰富的完整理论体系，对立统一规律是唯物辩证法的实质与核心，但不是唯物辩 证法的总体。马克思主义哲学要求我们在掌握对立统一规律的基础上，全面完整地掌握唯物辩证法的科学理 论体系。","explanation":"（1）在唯物辩证法的理论体系中，对立统一规律占有十分重要的地位，是唯物辩证法的实质与核 心。 第一，唯物辩证法揭示的是事物的联系与发展，而对立统一规律揭示的是普遍联系的根本内容和永恒发展的 根本动力，也就是说，所谓联系实质上是矛盾与矛盾、矛盾这方面与矛盾那方面的联系，所谓发展实质上是 矛盾推动下的发展。 第二，唯物辩证法是有着丰富内容的完整的科学理论体系，而对立统一规律则是理解唯物辩证法全部理论的 关键，唯物辩证法的其他规律与范畴都是对立统一规律在某一方面的展开。 第三，唯物辩证法与形而上学是两种根本对立的世界观，而是否承认矛盾则是唯物辩证法与形而上学对立的 焦点。 第四，唯物辩证法既是世界观，又是方法论，矛盾分析法则是最根本的认识方法。 （2）唯物辩证法是一个内容丰富的完整理论体系，对立统一规律是唯物辩证法的实质与核心，但不是唯物辩 证法的总体。马克思主义哲学要求我们在掌握对立统一规律的基础上，全面完整地掌握唯物辩证法的科学理 论体系。","score":10},{"id":"yc-1-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"简述“工农武装割据”的思想内容。","answer":"第一，土地革命是中国革命的基本内容，农民是民主革命的主力军，只有满足了农民的土地要求 ，才能最广泛地动员和组织广大农民群众参加武装斗争，巩固和扩大革命根据地。 第二，武装斗争是中国民主革命的主要斗争形式，是进行土地革命，巩固和发展革命根据地的最有力的工具 。 第三，农村根据地是中国民主革命的战略基地，是开展土地革命，实行武装斗争的基础和依托。","explanation":"第一，土地革命是中国革命的基本内容，农民是民主革命的主力军，只有满足了农民的土地要求 ，才能最广泛地动员和组织广大农民群众参加武装斗争，巩固和扩大革命根据地。 第二，武装斗争是中国民主革命的主要斗争形式，是进行土地革命，巩固和发展革命根据地的最有力的工具 。 第三，农村根据地是中国民主革命的战略基地，是开展土地革命，实行武装斗争的基础和依托。","score":10},{"id":"yc-1-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"“一国两制”构想的基本内容是什么？","answer":"“一国两制”是“一个国家，两种制度”的简称。“一国两制”构想是邓小平理论的重要组成部 分。其基本内容是： （1）坚持“一个中国”。世界上只有一个中国，中国的中央政府在北京，在国际上代表中国的只能是中华人 民共和国。 （2）实行“两种制度”。在统一的中华人民共和国内，作为国家主体的大陆地区坚持社会主义制度，台湾、 香港、澳门则保持原有的资本主义制度和生活方式，两种制度长期共存。 （3）设置特别行政区，保证台湾、香港、澳门的高度自治和繁荣稳定。 （4）实行“一国两制”长期不变。这种不变，既是承诺，又有《基本法》作保障。","explanation":"“一国两制”是“一个国家，两种制度”的简称。“一国两制”构想是邓小平理论的重要组成部 分。其基本内容是： （1）坚持“一个中国”。世界上只有一个中国，中国的中央政府在北京，在国际上代表中国的只能是中华人 民共和国。 （2）实行“两种制度”。在统一的中华人民共和国内，作为国家主体的大陆地区坚持社会主义制度，台湾、 香港、澳门则保持原有的资本主义制度和生活方式，两种制度长期共存。 （3）设置特别行政区，保证台湾、香港、澳门的高度自治和繁荣稳定。 （4）实行“一国两制”长期不变。这种不变，既是承诺，又有《基本法》作保障。","score":10},{"id":"yc-1-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"为什么说“三个代表”重要思想是我们党的立党之本、执政之基、力量之源？","answer":"（1）“三个代表”重要思想是党的立党之本。“三个代表”重要思想深刻揭示了党的性质、宗旨 的深刻内涵，集中体现了党的性质、宗旨的精神实质。什么时候坚持了“三个代表”重要思想，党就会兴旺 发达，就能够不断地向前发展。反之，什么时候偏离或没有完全做到“三个代表”重要思想，党就会遇到失 误和挫折，就会蜕化变质走向自己的反面。正是从这个意义上说，“三个代表”重要思想是党的性质最集中 、最完整的展示，是决定党的生死存亡的根本。 （2）“三个代表”重要思想是党的执政之基。我们党的执政地位是历史赋予的、人民赋予的。我们党执政的 内容和任务，就是要不断解放和发展中国社会的生产力，增强综合国力，推进社会发展；就是要不断建设和 发展社会主义文化，培育“四有”公民：弘扬民族精神；就是要全心全意为人民服务，维护最广大人民的根 本利益，不断提高人民生活的质量和水平。“三个代表”重要思想从根本上说明了我们党执政的基础、内容 、任务和要求。所以，只有始终做到“三个代表”重要思想，用好人民赋予的执政权力，不断提高党的领导 水平和执政水平，不断增强抵御风险和拒腐防变能力，才能巩固党的执政基础，使党真正成为中国社会主义 事业坚强有力的领导核心。 （3）“三个代表”重要思想是党的力量之源。我们党所以能获得人民的拥护，是因为我们党作为中国工人阶 级的先锋队，在革命、建设、改革的各个历史时期，能经受各种风浪、磨难的考验，不断发展壮大，并得到 人民群众的衷心拥护和支持，归根结底就在于我们党能够始终促进中国社会生产力的发展，推动中国先进文 化的前进，切切实实地为人民办实事、谋利益。人民群众的拥护和支持是我们党的力量之源，是我们党能够 取得伟大胜利的真谛。","explanation":"（1）“三个代表”重要思想是党的立党之本。“三个代表”重要思想深刻揭示了党的性质、宗旨 的深刻内涵，集中体现了党的性质、宗旨的精神实质。什么时候坚持了“三个代表”重要思想，党就会兴旺 发达，就能够不断地向前发展。反之，什么时候偏离或没有完全做到“三个代表”重要思想，党就会遇到失 误和挫折，就会蜕化变质走向自己的反面。正是从这个意义上说，“三个代表”重要思想是党的性质最集中 、最完整的展示，是决定党的生死存亡的根本。 （2）“三个代表”重要思想是党的执政之基。我们党的执政地位是历史赋予的、人民赋予的。我们党执政的 内容和任务，就是要不断解放和发展中国社会的生产力，增强综合国力，推进社会发展；就是要不断建设和 发展社会主义文化，培育“四有”公民：弘扬民族精神；就是要全心全意为人民服务，维护最广大人民的根 本利益，不断提高人民生活的质量和水平。“三个代表”重要思想从根本上说明了我们党执政的基础、内容 、任务和要求。所以，只有始终做到“三个代表”重要思想，用好人民赋予的执政权力，不断提高党的领导 水平和执政水平，不断增强抵御风险和拒腐防变能力，才能巩固党的执政基础，使党真正成为中国社会主义 事业坚强有力的领导核心。 （3）“三个代表”重要思想是党的力量之源。我们党所以能获得人民的拥护，是因为我们党作为中国工人阶 级的先锋队，在革命、建设、改革的各个历史时期，能经受各种风浪、磨难的考验，不断发展壮大，并得到 人民群众的衷心拥护和支持，归根结底就在于我们党能够始终促进中国社会生产力的发展，推动中国先进文 化的前进，切切实实地为人民办实事、谋利益。人民群众的拥护和支持是我们党的力量之源，是我们党能够 取得伟大胜利的真谛。","score":10},{"id":"yc-1-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(一) · 论述题 (20分)","stem":"我国实行对外开放，为什么必须坚持独立自主、自力更生的方针？","answer":"（1）我国是社会主义国家，必须维护国家的政治、经济的独立自主权利，决不允许别国干涉。 （2）我国是拥有十几亿人口的大国，现代化建设不可能依靠别人，必须立足于依靠本国人民的力量。 （3）强调独立自主、自力更生，可以调动全国人民的积极性、创造性，促使人们奋发努力。（4）取得外援 要付出代价，放弃自力更生，就会丧失独立自主的权利。","explanation":"（1）我国是社会主义国家，必须维护国家的政治、经济的独立自主权利，决不允许别国干涉。 （2）我国是拥有十几亿人口的大国，现代化建设不可能依靠别人，必须立足于依靠本国人民的力量。 （3）强调独立自主、自力更生，可以调动全国人民的积极性、创造性，促使人们奋发努力。（4）取得外援 要付出代价，放弃自力更生，就会丧失独立自主的权利。","score":20},{"id":"yc-1-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(一) · 论述题 (20分)","stem":"简述意识的能动作用的主要表现。","answer":"（1）意识活动具有目的性和计划性。人在认识客观世界、尊重客观规律的同时，还总是根据一定的 目的和要求去确定反映什么、不反映什么，以及怎样反映，从而表现出主体的选择性。 （2）意识活动具有创造性。人的意识不仅采取感觉、知觉、表象等形式，反映事物的外部现象，而且运用概 念、判断、推理等形式，对感性材料进行加工制作和选择建构，在思维中构造一个现实中所没有的理想世界 。 （3）意识具有指导实践改造客观世界的作用。意识的能动作用不限于从实践中形成一定的思想，形成活动的 目的、计划、方法等观念的东西，更重要的在于以这些观念的东西为指导，通过实践使之一步步变为客观现 实。 （4）意识具有调控人的行为和生理活动的作用。现代科学和医学实验证明：意识、心理因素能够对人的行为 选择和健康状况产生重要影响。","explanation":"（1）意识活动具有目的性和计划性。人在认识客观世界、尊重客观规律的同时，还总是根据一定的 目的和要求去确定反映什么、不反映什么，以及怎样反映，从而表现出主体的选择性。 （2）意识活动具有创造性。人的意识不仅采取感觉、知觉、表象等形式，反映事物的外部现象，而且运用概 念、判断、推理等形式，对感性材料进行加工制作和选择建构，在思维中构造一个现实中所没有的理想世界 。 （3）意识具有指导实践改造客观世界的作用。意识的能动作用不限于从实践中形成一定的思想，形成活动的 目的、计划、方法等观念的东西，更重要的在于以这些观念的东西为指导，通过实践使之一步步变为客观现 实。 （4）意识具有调控人的行为和生理活动的作用。现代科学和医学实验证明：意识、心理因素能够对人的行为 选择和健康状况产生重要影响。","score":20}]},{"id":"yc-2","title":"2026年成考预测试卷(二)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-2-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法认为，联系是以（ ）","options":["事物的区别为前提的","事物的共同性为前提的","事物之间相互转化为前提的","事物的发展为前提的"],"answer":0,"answerLetter":"A","explanation":"唯物辩证法认为，联系是指事物内部各要素之间和事物之间相互影响、相互制约和相互作用的关系 。联系是以事物之间以及事物内部诸要素之间的差别为前提的，没有区别就无所谓联系，是对立统一的关系 。","score":2},{"id":"yc-2-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(二) · 单选","stem":"系统论的基本原则是（ ）","options":["区别性","整体性","合理性","联系性"],"answer":1,"answerLetter":"B","explanation":"系统论强调将事物看作一个整体，整体具有不同于部分简单相加的特性和功能，整体性是系统论的 核心和基本原则。答案选B。","score":2},{"id":"yc-2-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法的总特征是（ ）","options":["运动变化的科学","事物矛盾的科学","联系和发展的科学","否定之否定的科学"],"answer":2,"answerLetter":"C","explanation":"唯物辩证法认为世界是普遍联系和永恒发展的，联系的观点和发展的观点是唯物辩证法的总特征。 A选项运动变化表述不准确；B选项事物矛盾是唯物辩证法的实质和核心；D选项否定之否定是唯物辩证法的三 大规律之一。","score":2},{"id":"yc-2-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法的本质和核心是（ ）","options":["因果的必然性","对立统一规律","质量与变化规律","否定之否定规律"],"answer":1,"answerLetter":"B","explanation":"在唯物辩证法中，对立统一规律揭示了事物发展的源泉和动力，贯穿于其他规律和范畴之中，是理 解其他规律和范畴的钥匙，所以它是唯物辩证法的本质和核心。","score":2},{"id":"yc-2-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法与形而上学的根本对立的焦点是（ ）","options":["联系的观点与孤立的观点的对立","发展的观点与不变的观点的对立","全面的观点与片面的观点的对立","是否承认矛盾及矛盾是事物发展根本动力观点的对立"],"answer":3,"answerLetter":"D","explanation":"唯物辩证法和形而上学对立的焦点在于是否承认矛盾，矛盾是唯物辩证法的实质与核心，承认矛盾 推动事物发展是唯物辩证法观点，不承认则是形而上学。前三个选项都是二者对立的表现，但不是根本焦点 。","score":2},{"id":"yc-2-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(二) · 单选","stem":"真理一元论认为对于一个确定的对象（ ）","options":["只能有一种认识","正确的认识只有一个","正确的认识只能一次获得","正确的认识只能用一种方法获得"],"answer":1,"answerLetter":"B","explanation":"真理一元论强调在同一条件下，对同一对象的真理性认识只有一个，因为真理具有客观性，符合客 观事物及其规律的正确认识只有一个。","score":2},{"id":"yc-2-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(二) · 单选","stem":"真理是人造的供人使用的工具的看法是（ ）","options":["主观唯心主义","客观唯物主义","机械唯物主义","辩证唯物主义"],"answer":0,"answerLetter":"A","explanation":"认为真理是人造的供人使用的工具，这把真理的判定完全归于人的主观意愿，以人的主观需求来定 义真理，而不是基于客观实际。 主观唯心主义把人的主观精神，如感觉、经验、心灵等当作世界的本原。这 种对真理的看法正是将人的主观意志凌驾于客观之上，属于主观唯心主义观点。","score":2},{"id":"yc-2-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(二) · 单选","stem":"真理的发展是一个（ ） A，真理和谬论不断调和的过程 B.真理和谬论相互补充的过程 C.真理和谬论相互转化的过程 D.由相对真理向绝对真理转化的过程","options":["a","b","c","d"],"answer":3,"answerLetter":"D","explanation":"真理和谬误是对立统一的，但不是不断调和与相互补充，A、B 错误；真理和谬误在一定条件下相互 转化，但这不是真理发展的本质，C 不准确。真理的发展是由相对真理不断向绝对真理转化的过程，这是真 理发展的规律。","score":2},{"id":"yc-2-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(二) · 单选","stem":"实践标准的不确定性是因为（ ）","options":["有些真理根本无法通过实践来检验","实践检验必须有逻辑证明来补充","社会实践总受历史条件的限制","不同人、不同阶级有不同实践"],"answer":2,"answerLetter":"C","explanation":"实践标准的不确定性是指实践对真理的检验是一个过程，受到一定历史条件的制约。A选项说法错误 ，所有真理都能通过实践检验；B选项逻辑证明是对实践检验的补充，但不是实践标准不确定性的原因；D选 项不同人、不同阶级实践不同并非实践标准不确定性的根源。实践标准不确定性主要源于社会实践受历史条 件限制。","score":2},{"id":"yc-2-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(二) · 单选","stem":"划分唯物史观与唯心史观的根本标准是（ ）","options":["是否承认阶级斗争","是否承认社会历史的规律性","是否承认社会意识的能动作用","是否承认社会存在决定社会意识"],"answer":3,"answerLetter":"D","explanation":"唯物史观认为社会存在决定社会意识，唯心史观认为社会意识决定社会存在，二者的根本分歧就在 于对社会存在和社会意识何者为第一性的不同回答，这也是划分唯物史观与唯心史观的根本标准。","score":2},{"id":"yc-2-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东思想产生的时代特点是（ ）","options":["战争与革命","和平与发展","资本主义上升","帝国主义腐朽没落"],"answer":0,"answerLetter":"A","explanation":"毛泽东思想形成和发展于20世纪前中期，当时时代的主要特点是战争与革命。1914年第一次世界大 战爆发，1917年俄国十月革命胜利，开启了世界无产阶级革命的新时代，这一时期战争与革命成为时代主题 。B选项和平与发展是邓小平理论形成时的时代主题；C选项资本主义上升时期并非毛泽东思想产生时代的主 要特征；D选项帝国主义腐朽没落表述片面，战争与革命才是当时整体时代特点。","score":2},{"id":"yc-2-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东思想产生的思想理论条件是（ ）","options":["三民主义","马列主义的传播","实用主义","空想社会主义"],"answer":1,"answerLetter":"B","explanation":"毛泽东思想是马克思列宁主义基本原理和中国革命具体实际相结合的产物，马列主义的传播为毛泽 东思想的产生提供了思想理论条件。而三民主义是孙中山所倡导的民主革命纲领；实用主义是西方哲学流派 ；空想社会主义是现代社会主义思想的来源之一，但都不是毛泽东思想产生的思想理论条件。","score":2},{"id":"yc-2-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东思想产生的实践基础是（ ）","options":["辛亥革命","五四运动","新文化运动","党领导的人民革命"],"answer":3,"answerLetter":"D","explanation":"毛泽东思想是中国共产党领导中国人民在进行革命和建设的实践过程中形成的理论成果。党领导的 人民革命为毛泽东思想的产生提供了丰富素材和实践基础。辛亥革命、五四运动、新文化运动虽对中国社会 发展有重要意义，但并非毛泽东思想产生的实践基础。","score":2},{"id":"yc-2-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(二) · 单选","stem":"第一次提出毛泽东思想这一概念的是（ ）","options":["朱德","刘少奇","王稼祥","周恩来"],"answer":2,"answerLetter":"C","explanation":"1943年7月，王稼祥在《中国共产党与中国民族解放的道路》一文中，首次提出“毛泽东思想”这一 科学概念。","score":2},{"id":"yc-2-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(二) · 单选","stem":"正式规定毛泽东思想为党的一切工作的指导思想会议是（ ）","options":["遵义会议","古田会议","中共六大","中共七大"],"answer":3,"answerLetter":"D","explanation":"中共七大正式确立毛泽东思想为党的指导思想并写入党章 。遵义会议事实上确立了以毛泽东为核心 的党中央的正确领导；古田会议确立了思想建党、政治建军原则；中共六大在莫斯科召开，主要是为了系统 地总结第一次国内革命的经验教训，批判右倾投降主义和“左”倾盲动主义的错误 。","score":2},{"id":"yc-2-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(二) · 单选","stem":"第一次国共合作的政治基础和共同纲领是（ ）","options":["三民主义","三大政策","民主革命纲领","新三民主义"],"answer":3,"answerLetter":"D","explanation":"新三民主义与中国共产党的民主革命纲领在若干基本原则上是一致的，成为第一次国共合作的政治 基础和共同纲领。三民主义未明确反帝反封建，不能成为合作基础；三大政策是实现新三民主义的方法和手 段；中共民主革命纲领与新三民主义有区别。","score":2},{"id":"yc-2-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(二) · 单选","stem":"1935年12月，毛泽东系统地阐述抗日民族统一战线新政策的会议是（ ）","options":["瓦窑堡会议","洛川会议","遵义会议","延安会议"],"answer":0,"answerLetter":"A","explanation":"1935 年 12 月，中共中央在陕北瓦窑堡召开政治局会议，提出了在抗日的条件下与民族资产阶级重 建统一战线的新政策，系统地阐述了抗日民族统一战线新政策。洛川会议是制定全面抗战路线；遵义会议是 结束“左”倾错误在中央的统治；延安会议主要是为了确定党在抗日民族统一战线新形势下的新任务。所以 答案是 A 选项瓦窑堡会议。","score":2},{"id":"yc-2-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(二) · 单选","stem":"中国革命的特点和优点是（ ）","options":["它是由中国共产党领导的人民革命","它的目标是争取民族独立，人民解放，最终实现国家的繁荣富强","它以反帝反封建作为两大革命任务","它以武装的革命反抗武装的反革命"],"answer":3,"answerLetter":"D","explanation":"武装斗争是中国革命的主要斗争形式，以武装的革命反抗武装的反革命，这是中国革命的特点和优 点之一 。因为中国反动统治阶级异常残暴且掌握庞大反革命武装，这就决定中国革命只能走武装斗争道路。","score":2},{"id":"yc-2-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东关于党的建设理论最核心的内容和最主要的特点是（ ）","options":["着重于从思想上建设党","加强党的组织建设","加强党员的党性修养","保持党的优良作风"],"answer":0,"answerLetter":"A","explanation":"毛泽东关于党的建设理论中，着重从思想上建党是最核心内容和主要特点。这是基于中国特殊国情 ，党员多来自农民和小资产阶级，只有从思想上建党，才能保证党的无产阶级先锋队性质。","score":2},{"id":"yc-2-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(二) · 单选","stem":"中国共产党各方面建设的基础是（ ）","options":["组织建设","思想建设","作风建设","政治建设"],"answer":1,"answerLetter":"B","explanation":"思想建设解决的是党员的理想信念、认识水平等根本性问题，为党的其他各项建设提供思想基础。 只有思想上清醒坚定，组织建设、作风建设、政治建设等才有坚实保障。","score":2},{"id":"yc-2-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(二) · 单选","stem":"我国农业合作化的方针是（ ）","options":["积极领导，稳步前进","自愿互利，典型示范，国家帮助","循序渐进，由初级到高级","先合作化，后机械化"],"answer":0,"answerLetter":"A","explanation":"我国农业合作化的方针是积极领导、稳步前进。B选项是农业合作化遵循的原则；C选项是农业合作 化的步骤特点；D选项是农业合作化与机械化的关系。","score":2},{"id":"yc-2-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(二) · 单选","stem":"我国农业合作化的原则是（ ）","options":["积极领导，稳步前进","自愿互利，典型示范，国家帮助","先合作化，后机械化","循序渐进，由初级到高级"],"answer":1,"answerLetter":"B","explanation":"我国农业合作化遵循自愿互利、典型示范和国家帮助的原则，引导农民走合作化道路。A选项是农业 合作化的方针；C选项是农业合作化与机械化的关系特点；D选项是农业合作化的步骤特点。","score":2},{"id":"yc-2-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(二) · 单选","stem":"我国农业合作化的步骤是（ ）","options":["积极领导，稳步前进","自愿互利，典型示范，国家帮助","先合作化，后机械化","循序渐进，由初级到高级"],"answer":3,"answerLetter":"D","explanation":"我国农业合作化遵循循序渐进的原则，经历了由互助组到初级社再到高级社的由低级到高级的步骤 。A选项“积极领导，稳步前进”是农业合作化的方针；B选项“自愿互利，典型示范，国家帮助”是农业合 作化的原则；C选项“先合作化，后机械化”是关于农业改造和发展的一种思路，并非农业合作化步骤。答案 选D。","score":2},{"id":"yc-2-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(二) · 单选","stem":"在土地改革完成以后，我国的社会主要矛盾是（ ）","options":["农民与地主阶级的矛盾","中华民族同帝国主义的矛盾","工人阶级同资产阶级的矛盾","人民大众同国民党的矛盾"],"answer":2,"answerLetter":"C","explanation":"土地改革完成后，地主阶级被基本消灭，A选项农民与地主阶级矛盾不再是主要矛盾；新中国成立后 ，帝国主义势力基本被清除，B选项中华民族同帝国主义矛盾已不是主要的；国民党在大陆统治已被推翻 ，D选项人民大众同国民党矛盾也不是主要矛盾。而随着土地改革完成，国内阶级关系发生变化，工人阶级和 资产阶级的矛盾逐渐突出。答案选C。","score":2},{"id":"yc-2-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(二) · 单选","stem":"1956年社会主义三大改造基本完成，标志着我国已进入（ ）","options":["共产主义社会","社会主义初级阶段","资本主义社会","新民主主义社会"],"answer":1,"answerLetter":"B","explanation":"1956 年社会主义三大改造基本完成，使中国进入社会主义初级阶段。共产主义社会是社会主义发展 的高级阶段，当时远未达到；中国在改造后告别了资本主义社会；新民主主义社会是过渡阶段，三大改造完 成就结束了这一阶段。","score":2},{"id":"yc-2-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(二) · 单选","stem":"坚持社会主义初级阶段基本路线100年不动摇的关键是坚持（ ）","options":["以经济建设为中心不动摇","四项基本原则不动摇","改革开放不动摇","自力更生，艰苦创业不动摇"],"answer":0,"answerLetter":"A","explanation":"以经济建设为中心是兴国之要，是我们党、我们国家兴旺发达和长治久安的根本要求。社会主义初 级阶段基本路线的核心是“一个中心，两个基本点”，坚持党的基本路线不动摇，关键是坚持以经济建设为 中心不动摇。答案：A。","score":2},{"id":"yc-2-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(二) · 单选","stem":"我国社会主义建设的目标是（ ）","options":["实现农业、工业、国防和科技现代化","实现工业化和经济的社会化、市场化和现代化","实现经济、政治、文化现代化","把我国建设成为富强、民主、文明、和谐的社会主义现代化国家"],"answer":3,"answerLetter":"D","explanation":"我国社会主义建设目标即社会主义初级阶段的奋斗目标，是把我国建设成为富强、民主、文明、和 谐、美丽的社会主义现代化强国（题干选项为早期表述）。A选项“四个现代化”是特定时期目标；B选项表 述侧重经济方面；C选项表述不全面。D选项全面涵盖了各方面，是正确的建设目标表述。","score":2},{"id":"yc-2-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(二) · 单选","stem":"我国社会主义建设发展战略的第三步是指，到21世纪中叶，人均国民生产总值要（ ）","options":["达到发达国家水平","接近国家水平","接近中等发达国家水平","达到中等发达国家水平"],"answer":3,"answerLetter":"D","explanation":"我国社会主义建设发展战略第三步目标是到21世纪中叶，人均国民生产总值达到中等发达国家水平 ，人民生活比较富裕，基本实现现代化。","score":2},{"id":"yc-2-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(二) · 单选","stem":"我国社会主义建设发展战略的出发点和归宿点是（ ）","options":["发展生产力","提高综合国力","提高人民生活水平","实现现代化"],"answer":2,"answerLetter":"C","explanation":"我国社会主义建设各项战略举措，根本目的都是为了人民，让人民过上更好生活。发展生产力、提 高综合国力、实现现代化最终都是为提高人民生活水平服务。所以出发点和归宿点是提高人民生活水平。答 案：C","score":2},{"id":"yc-2-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(二) · 单选","stem":"我国的国民经济基础是（ ）","options":["农业","工业","支柱产业","信息产业"],"answer":0,"answerLetter":"A","explanation":"农业是人类社会的衣食之源，生存之本，是支撑国民经济建设与发展的基础产业。而工业是国民经 济的主导，支柱产业对国民经济发展起支撑作用，信息产业属于新兴产业，并非基础。","score":2},{"id":"yc-2-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(二) · 单选","stem":"发展社会主义文化必须坚持的二为方向是（ ）","options":["为精神文明建设服务，为物质文明建设服务","为人民服务，为社会主义服务","为政治稳定服务，为经济发展服务","为党的工作服务，为行政工作服务"],"answer":1,"answerLetter":"B","explanation":"发展社会主义文化要坚持为人民服务、为社会主义服务的方向，这是社会主义文化建设的根本方向 。“二为”方向明确了文化工作的服务对象和目标。答案选B 。","score":2},{"id":"yc-2-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(二) · 单选","stem":"社会主义道德的核心和集中体现是","options":["爱国主义","社会主义","集体主义","为人民服务"],"answer":3,"answerLetter":"D","explanation":"社会主义道德以为人民服务为核心，这是社会主义本质特征的集中体现，也是社会主义道德区别和 优越于其他社会形态道德的显著标志。集体主义是社会主义道德的原则。爱国主义是民族精神的核心。社会 主义是一种社会制度和思想体系等。答案选D。","score":2},{"id":"yc-2-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(二) · 单选","stem":"社会主义道德建设的原则是（ ）","options":["毫不利己，专门利人","集体主义","全心全意为人民服务","个人主义"],"answer":1,"answerLetter":"B","explanation":"社会主义道德建设以为人民服务为核心，以集体主义为原则。A选项“毫不利己，专门利人”是一种 高尚道德境界的体现，但不是原则；C选项全心全意为人民服务是核心；D选项个人主义与社会主义道德建设 相悖。","score":2},{"id":"yc-2-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(二) · 单选","stem":"提出两岸尽快实现三通的是（ ）","options":["《告台湾同胞书》","叶剑英九条方针","《中国大陆和台湾和平统一的设想》","《为促进祖国统一而继续奋斗》"],"answer":0,"answerLetter":"A","explanation":"1979 年全国人大常委会发表《告台湾同胞书》，其中提出两岸尽快实现通航通邮通商。答案：A 。","score":2},{"id":"yc-2-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(二) · 单选","stem":"我国实行一国两制不会改变人民民主专政国家的社会主义性质。这是因为（ ）","options":["特别行政区只是中华人民共和国的一个行政区域","特别行政区政府是在中华人民共和国中央人民政府的统一领导下","特别行政区享有内地一般地方行政区域所没有的高度自治权","两种制度的地位不同，社会主义制度是主体"],"answer":3,"answerLetter":"D","explanation":"“一国两制”下，社会主义制度是主体，决定了国家的社会主义性质，这是我国实行“一国两制 ”不会改变人民民主专政国家社会主义性质的根本原因。","score":2},{"id":"yc-2-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"简述实践及其对认识的决定作用。","answer":"（1）实践是指人类能动地改造和探索现实世界的一切社会性的客观物质活动，具有自觉能动性、 客观物质性和社会历史性等三个特点，表现为生产实践、处理社会关系实践和科学实验等三种基本形式。 （2）在实践和认识的辩证关系中，实践是认识的基础，实践决定认识。这表现在： 第一，实践是认识的来源。首先，实践的需要决定认识的产生，也就是说，人们改造世界的需要产生了认识 世界的需要。其次，实践出真知，人类的一切认识，无论直接经验，还是间接经验，归根结底都是来自实践 的。 第二，实践是认识发展的动力。首先，实践不断给人们提出新的认识课题，并提供解决新课题的新的经验材 料。其次，实践的发展不断给人们提供日益完备的认识手段和物质条件。再次，实践不断推动人的认识能力 的提高。 第三，实践是检验认识正确与否的唯一标准，除此之外，再无其他标准。 第四，实践是认识的最终目的，正确认识世界的目的是为了有效改造世界。","explanation":"（1）实践是指人类能动地改造和探索现实世界的一切社会性的客观物质活动，具有自觉能动性、 客观物质性和社会历史性等三个特点，表现为生产实践、处理社会关系实践和科学实验等三种基本形式。 （2）在实践和认识的辩证关系中，实践是认识的基础，实践决定认识。这表现在： 第一，实践是认识的来源。首先，实践的需要决定认识的产生，也就是说，人们改造世界的需要产生了认识 世界的需要。其次，实践出真知，人类的一切认识，无论直接经验，还是间接经验，归根结底都是来自实践 的。 第二，实践是认识发展的动力。首先，实践不断给人们提出新的认识课题，并提供解决新课题的新的经验材 料。其次，实践的发展不断给人们提供日益完备的认识手段和物质条件。再次，实践不断推动人的认识能力 的提高。 第三，实践是检验认识正确与否的唯一标准，除此之外，再无其他标准。 第四，实践是认识的最终目的，正确认识世界的目的是为了有效改造世界。","score":10},{"id":"yc-2-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"简述走农村包围城市，武装夺取政权道路的必要性。","answer":"第一，中国是一个半殖民地半封建国家，外部没有民族独立而受帝国主义压迫，内部没有民主制度 而受封建制度压迫，无产阶级及其政党无议会可以利用，没有组织工人罢工的合法权利，只能以武装的革命 反对武装的反革命。 第二，中国是一个经济落后的农业大国，农民占全国人口总数的80％以上，这就决定了农民是民主革命的主 力军。中国的民主革命实质上是农民革命，武装斗争实质上是无产阶级领导的以农民为主力军的革命斗争。 “工农武装割据”是无产阶级领导的革命斗争的最高形式。 第三，大革命失败后，中国共产党人多次奋斗的结局也证明，革命在城市首先取得胜利的可能性已不存在 ，而反动统治相对薄弱的广大农村地区，正是实行“工农武装割据”的革命阵地和夺取城市、夺取全国政权 的出发点。","explanation":"第一，中国是一个半殖民地半封建国家，外部没有民族独立而受帝国主义压迫，内部没有民主制度 而受封建制度压迫，无产阶级及其政党无议会可以利用，没有组织工人罢工的合法权利，只能以武装的革命 反对武装的反革命。 第二，中国是一个经济落后的农业大国，农民占全国人口总数的80％以上，这就决定了农民是民主革命的主 力军。中国的民主革命实质上是农民革命，武装斗争实质上是无产阶级领导的以农民为主力军的革命斗争。 “工农武装割据”是无产阶级领导的革命斗争的最高形式。 第三，大革命失败后，中国共产党人多次奋斗的结局也证明，革命在城市首先取得胜利的可能性已不存在 ，而反动统治相对薄弱的广大农村地区，正是实行“工农武装割据”的革命阵地和夺取城市、夺取全国政权 的出发点。","score":10},{"id":"yc-2-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"简述人民民主专政理论的基本内容。","answer":"第一，论述了在中国建立人民民主专政的历史必然性。 第二，科学地分析了各个阶级在人民民主专政国家政权中的地位及其相互地位。 第三，论述了人民民主专政的本质特征。 第四，论述了人民民主专政的职能和任务。人民民主专政的职能和任务，对外是防止帝国主义与各国反动派 的颠覆和破坏，维护国家的独立和安全，维护世界和平；对内是镇压敌对势力的反抗，保护人民民主权利 ，组织和管理国家经济建设，发展社会生产力，促进中国由农业国向工业国、由新民主主义向社会主转变 ，并最终实现消灭一切阶级和一切国家的伟大目标。","explanation":"第一，论述了在中国建立人民民主专政的历史必然性。 第二，科学地分析了各个阶级在人民民主专政国家政权中的地位及其相互地位。 第三，论述了人民民主专政的本质特征。 第四，论述了人民民主专政的职能和任务。人民民主专政的职能和任务，对外是防止帝国主义与各国反动派 的颠覆和破坏，维护国家的独立和安全，维护世界和平；对内是镇压敌对势力的反抗，保护人民民主权利 ，组织和管理国家经济建设，发展社会生产力，促进中国由农业国向工业国、由新民主主义向社会主转变 ，并最终实现消灭一切阶级和一切国家的伟大目标。","score":10},{"id":"yc-2-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"我国独立自主的外交政策体现在哪些方面？我国为什么必须实行对外开放？","answer":"我国独立自主的外交政策体现在： 坚持独立自主。这是指国家的主权是独立的，不允许任何外来的干涉与侵犯，每个国家都有权根据自己的实 际情况独立地、自主地处理本国对内对外一切事物。坚持独立自主，主要体现在：①坚持把国家主权和国家 利益放在首位。主权是国家的根本属性，是一个国家独立自主地处理对内对外事物的最高权力。国家活动的 目的是追求国家利益，处理国与国之间关系主要应该从国家自身的战略利益出发，以自己国家的利益为最高 准则。②真正的不结盟。不结盟就是不参加任何国家集团与军事集团，不同任何国家结成同盟。只有不结盟 才能更有效地、独立自主地处理各种事物，③反对霸权主义和强权政治。霸权主义和强权政治是威胁世界和 平与稳定，干涉、侵犯他国主权的主要根源。反对霸权主义和强权政治是我国外交政策的纲领。 （2）维护世界和平。争取世界和平是我国对外政策的首要任务。维护世界和平，主要体现在：①坚持和平共 处五项原则。和平共处五项原则，是指在处理国家之间的关系中，坚持相互尊重主权和领土完整、互不侵犯 、互不干涉内政、平等互利、和平共处的原则。和平共处五项原则是处理国与国之间关系的最好形式。②通 过对话协商解决国与国之间存在的分歧和争端。我们坚持反对诉诸武力或以武力相威胁。③建立国际政治经 济新秩序。建立国际新秩序，核心是强调不干涉别国的内政，尊重和维护世界各国的主权独立和国家利益 ，建立民主、平等、合理、公正的新型国际关系，以促进世界的持久和平与人类的共同繁荣。 实行对外开放的原因： （1）对外开放作为我国一项长期的基本国策是经济生活国际化的客观要求，也是对当代世界经济、科技发展 和国际形势发展敏锐观察的结果。现在的世界是开放的世界，科学技术发展一日千里，只有参与国际经济竞 争与合作，充分利用国际经济资源和科技成果，才能发展自己，赶上当代世界的科技和经济发展潮流。 （2）对外开放作为我国一项长期的基本国策是对中国长期停滞落后的历史教训深刻总结的结果。长期闭关自 守，把我国搞得贫穷落后，愚昧无知。历史的经验一再告诉我们，关起门来搞建设是不行的，把自己孤立于 世界之外是不利的。中国的发展离不开世界。 （3）对外开放作为我国一项长期的基本国策是我国社会主义现代化建设的迫切需要。扩大对外开放，可以引 进国外资金、先进的技术设备和管理经验、人才，以克服我国资金短缺、技术落后、管理经验不足等困难 ；可以充分利用国外资源，大力开拓国际市场，通有无，取长补短，趋利避害，促进我国经济发展；可以参 与国际经济、科学、技术，人才和信息的交流，有利于我们及时了解和掌握各种经济、科技信息；可以广泛 吸收世界文明成果，发挥后发优势，在较高的技术基础上发展经济，尽快缩小与发达国家经济技术发展程度 的差距。 总之，我国必须坚持对外开放和独立自主、自力更生的统一。独立自主、自力更生，是我国进行现代化建设 的立足点和基点。独立自主、自力更生是对外开放的前提和基础，而对外开放可以加快经济发展，增强国家 综合国力，从而提高独立自主、自力更生的能力和水平。","explanation":"我国独立自主的外交政策体现在： 坚持独立自主。这是指国家的主权是独立的，不允许任何外来的干涉与侵犯，每个国家都有权根据自己的实 际情况独立地、自主地处理本国对内对外一切事物。坚持独立自主，主要体现在：①坚持把国家主权和国家 利益放在首位。主权是国家的根本属性，是一个国家独立自主地处理对内对外事物的最高权力。国家活动的 目的是追求国家利益，处理国与国之间关系主要应该从国家自身的战略利益出发，以自己国家的利益为最高 准则。②真正的不结盟。不结盟就是不参加任何国家集团与军事集团，不同任何国家结成同盟。只有不结盟 才能更有效地、独立自主地处理各种事物，③反对霸权主义和强权政治。霸权主义和强权政治是威胁世界和 平与稳定，干涉、侵犯他国主权的主要根源。反对霸权主义和强权政治是我国外交政策的纲领。 （2）维护世界和平。争取世界和平是我国对外政策的首要任务。维护世界和平，主要体现在：①坚持和平共 处五项原则。和平共处五项原则，是指在处理国家之间的关系中，坚持相互尊重主权和领土完整、互不侵犯 、互不干涉内政、平等互利、和平共处的原则。和平共处五项原则是处理国与国之间关系的最好形式。②通 过对话协商解决国与国之间存在的分歧和争端。我们坚持反对诉诸武力或以武力相威胁。③建立国际政治经 济新秩序。建立国际新秩序，核心是强调不干涉别国的内政，尊重和维护世界各国的主权独立和国家利益 ，建立民主、平等、合理、公正的新型国际关系，以促进世界的持久和平与人类的共同繁荣。 实行对外开放的原因： （1）对外开放作为我国一项长期的基本国策是经济生活国际化的客观要求，也是对当代世界经济、科技发展 和国际形势发展敏锐观察的结果。现在的世界是开放的世界，科学技术发展一日千里，只有参与国际经济竞 争与合作，充分利用国际经济资源和科技成果，才能发展自己，赶上当代世界的科技和经济发展潮流。 （2）对外开放作为我国一项长期的基本国策是对中国长期停滞落后的历史教训深刻总结的结果。长期闭关自 守，把我国搞得贫穷落后，愚昧无知。历史的经验一再告诉我们，关起门来搞建设是不行的，把自己孤立于 世界之外是不利的。中国的发展离不开世界。 （3）对外开放作为我国一项长期的基本国策是我国社会主义现代化建设的迫切需要。扩大对外开放，可以引 进国外资金、先进的技术设备和管理经验、人才，以克服我国资金短缺、技术落后、管理经验不足等困难 ；可以充分利用国外资源，大力开拓国际市场，通有无，取长补短，趋利避害，促进我国经济发展；可以参 与国际经济、科学、技术，人才和信息的交流，有利于我们及时了解和掌握各种经济、科技信息；可以广泛 吸收世界文明成果，发挥后发优势，在较高的技术基础上发展经济，尽快缩小与发达国家经济技术发展程度 的差距。 总之，我国必须坚持对外开放和独立自主、自力更生的统一。独立自主、自力更生，是我国进行现代化建设 的立足点和基点。独立自主、自力更生是对外开放的前提和基础，而对外开放可以加快经济发展，增强国家 综合国力，从而提高独立自主、自力更生的能力和水平。","score":10},{"id":"yc-2-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(二) · 论述题 (20分)","stem":"简述量变和质变的关系。","answer":"（1）量变是质变的必要准备。任何事物的变化都有一个量变的积累过程，没有量变的积累，质变就 不会发生。 （2）质变是量变的必然结果。单纯的量变不会永远持续下去，量变达到一定程度必然引起质变。 （3）量变和质变是相互渗透的。一方面，在总的量变过程中有阶段性和局部性的部分质变；另一方面，在质 变过程中也有旧质在量上的收缩和新质在量上的扩张。量变和质变是相互依存、相互贯通的，量变引起质变 ，在新质的基础上，事物又开始新的量变，如此交替循环，构成了事物的发展过程。量变质变规律体现了事 物发展的渐进性和飞跃性的统一。","explanation":"（1）量变是质变的必要准备。任何事物的变化都有一个量变的积累过程，没有量变的积累，质变就 不会发生。 （2）质变是量变的必然结果。单纯的量变不会永远持续下去，量变达到一定程度必然引起质变。 （3）量变和质变是相互渗透的。一方面，在总的量变过程中有阶段性和局部性的部分质变；另一方面，在质 变过程中也有旧质在量上的收缩和新质在量上的扩张。量变和质变是相互依存、相互贯通的，量变引起质变 ，在新质的基础上，事物又开始新的量变，如此交替循环，构成了事物的发展过程。量变质变规律体现了事 物发展的渐进性和飞跃性的统一。","score":20},{"id":"yc-2-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(二) · 论述题 (20分)","stem":"为什么说农民阶级是无产阶级最坚固最可靠的同盟军？","answer":"（1）中国是一个以农业为主要经济成分的国家，农民人数最多。占全国总人口的80％，是“人民大 众”的主体。（2）农民身处社会的最底层，受压迫最深，受剥削最重，蕴藏着极大的革命积极性。（3）中 国产业工人的前身多是破产农民，因而农民和工人有天然的联盟关系，工农联盟是革命胜利的基石。（4）农 民是中国军队的来源，是中国民主政治的主要力量。","explanation":"（1）中国是一个以农业为主要经济成分的国家，农民人数最多。占全国总人口的80％，是“人民大 众”的主体。（2）农民身处社会的最底层，受压迫最深，受剥削最重，蕴藏着极大的革命积极性。（3）中 国产业工人的前身多是破产农民，因而农民和工人有天然的联盟关系，工农联盟是革命胜利的基石。（4）农 民是中国军队的来源，是中国民主政治的主要力量。","score":20}]},{"id":"yc-3","title":"2026年成考预测试卷(三)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-3-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(三) · 单选","stem":"我国现代化实行的独立自主、自力更生方针的理论依据是（ ）","options":["量变引起质变的原理","主次矛盾相互转化的原理","内外因辩证关系的原理","共性和个性辩证关系的原理"],"answer":2,"answerLetter":"C","explanation":"独立自主、自力更生强调依靠自身内部力量发展，这体现了内因是事物发展的根据。同时我国现代 化建设也需要对外开放等外部条件，外因是事物发展的条件，内外因相互作用推动事物发展。所以这一方针 的理论依据是内外因辩证关系原理。","score":2},{"id":"yc-3-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(三) · 单选","stem":"实践中一刀切的工作方法是由于忽视了（ ）","options":["矛盾的同一性","矛盾的普遍性","矛盾的斗争性","矛盾的特殊性"],"answer":3,"answerLetter":"D","explanation":"“一刀切”就是不考虑具体情况，用同一种方式处理所有问题。而矛盾特殊性要求我们具体问题具 体分析，“一刀切”正是忽视了矛盾特殊性，没有看到不同事物矛盾的差异。","score":2},{"id":"yc-3-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(三) · 单选","stem":"区分量变和质变的根本标志是（ ）","options":["事物的变化是否快速","事物的变化是否明显","事物的变化是否超越了度的范围","事物的变化幅度的大小"],"answer":2,"answerLetter":"C","explanation":"量变和质变的区别关键在于事物的变化是否超出度的范围，在度的范围内的变化是量变，超出度的 变化就是质变。A选项变化快速、B选项变化明显、D选项变化幅度大小都不是区分二者的根本标志。","score":2},{"id":"yc-3-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(三) · 单选","stem":"发展的本质是（ ）","options":["事物质的变化","一切变化的过程","新事物的产生和旧事物的灭亡","事物由肯定到否定"],"answer":2,"answerLetter":"C","explanation":"发展的本质强调的是事物上升、前进的运动变化，是具有前进性和上升性的质变，其核心体现为新 事物产生，旧事物灭亡，新事物代替旧事物。A选项事物质变不一定是发展，也可能是倒退；B选项一切变化 包含了倒退等非发展的变化；D选项事物由肯定到否定表述不完整且未突出发展本质特征。","score":2},{"id":"yc-3-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(三) · 单选","stem":"事物矛盾的精髓是（ ）","options":["矛盾的同一性和斗争性的关系","矛盾的对抗与非对抗的关系","主要矛盾和次要矛盾的关系","矛盾的共性、个性、绝对、相对的关系"],"answer":3,"answerLetter":"D","explanation":"矛盾的共性（普遍性）和个性（特殊性）、绝对和相对的关系是关于事物矛盾问题的精髓。它贯穿 于矛盾学说的各个方面，是正确理解矛盾学说的关键 。","score":2},{"id":"yc-3-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(三) · 单选","stem":"直接经验和间接经验的关系是（ ）","options":["第一性和第二性的关系","认识的源和流的关系","主观和客观的关系","反映和被反映的关系"],"answer":1,"answerLetter":"B","explanation":"直接经验是通过亲身实践获得的知识，间接经验是从他人或书本等途径获取的知识。实践是认识的 来源，直接经验是认识的“源”，而间接经验归根结底也是源于他人的实践，是认识的“流”。","score":2},{"id":"yc-3-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(三) · 单选","stem":"坚持感性认识是理性认识的基础，就是在认识论上坚持了（ ）","options":["可知论","唯物论","辩证法","唯心论"],"answer":1,"answerLetter":"B","explanation":"感性认识是对事物现象的认识，理性认识是对事物本质的认识。坚持感性认识是理性认识的基础 ，强调认识来源于实践中对事物现象的感知，这符合物质第一性，意识第二性，认识是对物质的反映这一唯 物论观点。因为只有通过实践获取关于物质世界的感性材料，才能上升到理性认识。","score":2},{"id":"yc-3-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(三) · 单选","stem":"感性认识和理性认识统一的基础是（ ）","options":["客观对象","认识的主体","认识的客体","社会实践"],"answer":3,"answerLetter":"D","explanation":"感性认识和理性认识是认识过程的两个阶段，它们统一的基础是社会实践。实践是认识的来源、动 力、目的和检验标准，只有通过实践，才能使感性认识上升到理性认识，两者在实践基础上相互依存、相互 转化。","score":2},{"id":"yc-3-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(三) · 单选","stem":"认识的起点是感觉，这是（ ）","options":["只有唯物主义才承认的观点","唯物主义和唯心主义都可以承认的观点","只有辩证唯物主义才承认的观点","唯心主义承认的观点"],"answer":1,"answerLetter":"B","explanation":"认识始于感觉，无论是唯物主义还是唯心主义都可承认这一点。唯物主义认为感觉是对客观世界的 反映，以此为起点进一步认识世界；唯心主义虽对感觉来源解释不同，但也认可感觉是认识起点。","score":2},{"id":"yc-3-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(三) · 单选","stem":"一种认识是不是真理，要看它（ ）","options":["是否被多数人拥护","是否被社会普遍承认","是否与客观事物及其规律相一致","是否能满足人的需要"],"answer":2,"answerLetter":"C","explanation":"真理是标志主观与客观相符合的哲学范畴，是对客观事物及其规律的正确反映。判断一种认识是不 是真理关键在于它是否与客观事物及其规律相一致，而不是看被多少人拥护、社会是否普遍承认或者能否满 足人的需要。","score":2},{"id":"yc-3-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(三) · 单选","stem":"人的价值包括两方面，它们是（ ）","options":["经济价值和政治价值","物质价值和精神价值","潜在价值和现实价值","自我价值和社会价值"],"answer":3,"answerLetter":"D","explanation":"人的价值包含自我价值和社会价值两个方面。自我价值是个体的生存和发展得到满足，社会价值是 个体对社会作出的贡献。这是关于人的价值的基本理论。","score":2},{"id":"yc-3-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(三) · 单选","stem":"人生观是人们（ ）","options":["对世界的根本看法","对人生目的的意义和根本看法","对人性的根本看法","对主观领域的根本看法"],"answer":1,"answerLetter":"B","explanation":"人生观主要围绕人生的目的、意义等展开探讨。A选项对世界根本看法是世界观；C选项对人性根本 看法只是人生观一部分；D选项对主观领域根本看法表述不准确。只有B符合人生观定义。","score":2},{"id":"yc-3-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(三) · 单选","stem":"人类历史发展的总趋势是（ ）","options":["由低级到高级的过程","周而复始的循环过程","前进和倒退相互交替的过程","进步与落后相混杂的过程"],"answer":0,"answerLetter":"A","explanation":"人类历史是不断向前发展的，是从低级向高级演进，虽然发展过程会有曲折，但总体趋势是上升进 步的。B选项循环过程不符合人类历史发展有质的飞跃的实际；C选项前进和倒退相互交替不是总趋势；D选项 进步与落后相混杂也不能准确表述总趋势。","score":2},{"id":"yc-3-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(三) · 单选","stem":"马克思主义哲学认为自由是（ ）","options":["人们按照自己的意志创造历史","不受必然性制约的绝对自由","对必然性的认识和对客观世界的改造","按照多数人的意见去行动"],"answer":2,"answerLetter":"C","explanation":"马克思主义哲学认为自由不是随心所欲，A选项按自己意志创造历史忽视社会规律；B选项不受必然 性制约的绝对自由不存在，自由是相对的；D选项按多数人意见行动不一定就代表自由。马克思主义认为自由 是对必然性（规律）的认识和对客观世界的改造。","score":2},{"id":"yc-3-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(三) · 单选","stem":"人类解放就是（ ）","options":["实现绝对自由","不受任何束缚和限制","摆脱盲目必然性和社会关系的奴役","创造有利于全面发展的规律"],"answer":2,"answerLetter":"C","explanation":"人类解放意味着从自然和社会的奴役中摆脱出来。A选项绝对自由不存在；B选项不受任何束缚限制 不现实；D选项规律不能被创造。而C选项摆脱盲目必然性（自然方面）和社会关系的奴役（社会方面）符合 人类解放的内涵。","score":2},{"id":"yc-3-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(三) · 单选","stem":"新民主主义社会的国体是（ ）","options":["无产阶级专政","资产阶级专政","几个革命阶级的联合专政","大地主资产阶级专政"],"answer":2,"answerLetter":"C","explanation":"新民主主义社会是过渡性质社会，其国体既不是无产阶级专政（这是社会主义社会国体），也不是 资产阶级专政或大地主资产阶级专政，而是几个革命阶级的联合专政，这体现了新民主主义革命的各革命阶 级联合的特点。","score":2},{"id":"yc-3-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(三) · 单选","stem":"新民主主义国家的政体是（ ）","options":["民主集中制的人民代表大会制","议会制","委员会制","政治协商制"],"answer":0,"answerLetter":"A","explanation":"新民主主义国家的政体是实行民主集中制的人民代表大会制度。这是符合中国国情的，能体现人民 当家作主。议会制、委员会制不符合新民主主义国家性质，政治协商制是中国政党制度的重要机构形式，并 非政体。","score":2},{"id":"yc-3-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(三) · 单选","stem":"革命统一战线最根本的问题是","options":["革命目标问题","政策和策略问题","领导权问题","工农联盟问题"],"answer":2,"answerLetter":"C","explanation":"领导权问题是革命统一战线最根本的问题，领导权掌握在谁手中决定着统一战线的方向和革命的走 向。没有正确的领导权，统一战线就无法巩固和发展，革命就难以成功。","score":2},{"id":"yc-3-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(三) · 单选","stem":"革命统一战线的基础是（ ）","options":["国共合作","工农联盟","与民族资产阶级合作","反对共同敌人"],"answer":1,"answerLetter":"B","explanation":"革命统一战线中，工人阶级和农民阶级都受压迫最深，有着共同利益和革命诉求，工农联盟是革命 统一战线得以建立和发展的基本力量，是革命统一战线的基础。","score":2},{"id":"yc-3-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(三) · 单选","stem":"中国共产党初步提出统一战线方针的会议是（ ）","options":["中共一大","中共二大","中共三大","中共四大"],"answer":1,"answerLetter":"B","explanation":"中共二大在对中国社会各阶级的状况作了初步分析后，提出组成“民主主义的联合战线”的主张 ，初步提出统一战线方针。中共一大主要是党的创建，中共三大主要是决定与国民党合作，中共四大主要是 提出无产阶级领导权和工农联盟问题 。","score":2},{"id":"yc-3-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(三) · 单选","stem":"标志着人民民主专政理论完全形成的著作是（ ）","options":["《新民主主义论》","《论人民民主专政》","《论联合政府》","《将革命进行到底》"],"answer":1,"answerLetter":"B","explanation":"《论人民民主专政》全面阐述了人民民主专政的性质、领导者、阶级基础、职能等内容，标志着人 民民主专政理论完全形成。而A选项《新民主主义论》主要论述新民主主义革命的基本理论、路线和纲领等 ；C选项《论联合政府》主要阐述党的一般纲领和具体纲领等；D选项《将革命进行到底》主要是号召将革命 进行到底。","score":2},{"id":"yc-3-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(三) · 单选","stem":"人民民主专政政权的组织形式是（ ）","options":["参议会制度","政治协商会议制度","人民代表大会制度","共产党领导的多党合作制度"],"answer":2,"answerLetter":"C","explanation":"人民代表大会制度是我国的根本政治制度，是人民民主专政政权的组织形式。参议会制度是抗战时 期的，与题干不符；政治协商会议制度、共产党领导的多党合作制度是政党制度相关，并非政权组织形式。","score":2},{"id":"yc-3-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(三) · 单选","stem":"1949年10月，中华人民共和国成立，标志着中国从半殖民地半封建社会进入（ ）","options":["资本主义社会","新民主主义社会","社会主义社会形态","共产主义社会形态"],"answer":1,"answerLetter":"B","explanation":"中华人民共和国成立，结束了半殖民地半封建社会，此时中国进入新民主主义社会，因为社会主义 公有制等社会主义经济基础尚未完全建立。1956年底社会主义改造基本完成才标志着进入社会主义社会。资 本主义社会不符合中国发展路径，共产主义社会形态目前远未达到。","score":2},{"id":"yc-3-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(三) · 单选","stem":"新民主主义社会是一种（ ）","options":["独立的社会形态","固定不变的社会形态","过渡性质的社会形态","从属于资本主义的社会形态"],"answer":2,"answerLetter":"C","explanation":"新民主主义社会是近代中国由半殖民地半封建社会走向社会主义社会的中介与桥梁，具有过渡性质 。它不是独立社会形态，也并非固定不变，更不从属于资本主义。","score":2},{"id":"yc-3-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(三) · 单选","stem":"中国共产党七届三中全会确定国民经济恢复时期的中心任务是（ ）","options":["迅速消灭国民党残余势力","统一全国财政经济工作","新解放区土地改革的完成","争取国家财政经济状况的基本好转"],"answer":3,"answerLetter":"D","explanation":"七届三中全会确定，要获得国家财政经济状况的根本好转，要用三年左右的时间，创造三个条件 ，即土地改革的完成、现有工商业的合理调整、国家机构所需经费的大量节减。所以中心任务是争取国家财 政经济状况的基本好转。","score":2},{"id":"yc-3-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(三) · 单选","stem":"党在社会主义初级阶段基本路线的核心和主体是（ ）","options":["经济建设","改革开放","四项基本原则","安定团结的政治局面"],"answer":0,"answerLetter":"A","explanation":"党在社会主义初级阶段基本路线的核心内容是“一个中心，两个基本点”，“一个中心”即以经济 建设为中心，它是核心和主体，其他方面围绕这个中心展开。答案：A。","score":2},{"id":"yc-3-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(三) · 单选","stem":"坚持以经济建设为中心，从根本上说是由（ ）","options":["当前的国情决定的","社会主义初级阶段的主要矛盾决定的","当前的国际环境决定的","党的方针政策决定的"],"answer":1,"answerLetter":"B","explanation":"社会主义初级阶段的主要矛盾是人民日益增长的物质文化需要同落后的社会生产之间的矛盾。解决 这一矛盾的根本途径就是大力发展生产力，而坚持以经济建设为中心，就是为了大力发展生产力，所以坚持 以经济建设为中心从根本上说是由社会主义初级阶段的主要矛盾决定的。 国情范围较宽泛，不是最根本决定 因素；国际环境只是外部影响，不是根本原因；党的方针政策是基于一定情况制定的，不是以经济建设为中 心的根本决定因素。","score":2},{"id":"yc-3-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(三) · 单选","stem":"四项基本原则为经济建设提供了（ ）","options":["政治保证","组织保证","物质保证","发展动力"],"answer":0,"answerLetter":"A","explanation":"四项基本原则规定了我国的社会主义性质、道路、领导核心等根本问题，它能确保经济建设沿着正 确的政治方向前进，为其提供政治保证。","score":2},{"id":"yc-3-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(三) · 单选","stem":"改革开放为经济建设提供了（ ）","options":["政治保证","组织保证","思想保证","发展动力"],"answer":3,"answerLetter":"D","explanation":"改革开放通过变革生产关系、释放市场活力等，为经济建设注入源源不断的活力，推动经济不断向 前发展，所以它为经济建设提供发展动力。而政治保证一般是党的领导等；组织保证多涉及党组织建设等方 面；思想保证通常是先进理论等的指导。","score":2},{"id":"yc-3-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(三) · 单选","stem":"建设中国特色社会主义文化的基本目标是（ ）","options":["以马克思主义为指导，以培育有理想、有道德、有文化、有纪律的公民为目标，发展面向现代化、面向世 界、面向未来的民族的、科学的、大众的社会主义文化","坚持用邓小平理论武装全党，教育人民","努力提高全民族的思想道德素质和教育科学文化水平","坚持为人民服务、为社会主义服务的方向和百花齐放、百家争鸣的方针，重在建设、繁荣学术和文艺"],"answer":0,"answerLetter":"A","explanation":"建设中国特色社会主义文化的基本目标在教材中有明确表述，A选项完整阐述了建设中国特色社会主 义文化在指导思想、培育目标、文化特征等方面的内容，符合基本目标的定义。","score":2},{"id":"yc-3-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(三) · 单选","stem":"市场机制中的核心机制是（ ）","options":["供求机制","激励机制","价格机制","竞争机制"],"answer":2,"answerLetter":"C","explanation":"价格机制影响着供求、竞争等机制的运行，在市场机制中居于核心地位。","score":2},{"id":"yc-3-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(三) · 单选","stem":"社会主义市场经济中的宏观调控是以（ ）","options":["直接调控为主","间接调控为主","结构调控为主","总体调控为主"],"answer":1,"answerLetter":"B","explanation":"在社会主义市场经济体制下，市场在资源配置中起决定性作用，政府宏观调控主要运用经济、法律 手段，通过市场机制间接影响经济主体行为，所以宏观调控以间接调控为主。","score":2},{"id":"yc-3-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(三) · 单选","stem":"转变政府职能的关键是（ ）","options":["中央政府和地方政府合理划分职权","处理好国家和企业的关系","处理好中央和地方的关系","政企职责分开"],"answer":3,"answerLetter":"D","explanation":"政府职能转变的核心是处理好政府与市场、社会的关系，关键在于政企职责分开，只有实现政企分 开，才能真正让政府从微观经济事务中解脱出来，更好地履行宏观调控、市场监管等职能。","score":2},{"id":"yc-3-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(三) · 单选","stem":"社会主义宏观调控的基本目标（ ）","options":["抑制通货膨胀","促进经济结构优化","保持经济增长","保持经济总平衡"],"answer":3,"answerLetter":"D","explanation":"社会主义宏观调控的基本目标是保持经济总量平衡，即保持社会总供给和社会总需求的平衡 ，这是 保证国民经济持续、稳定、协调发展的基础。其他选项如抑制通货膨胀、促进经济结构优化、保持经济增长 都是宏观调控的具体目标。","score":2},{"id":"yc-3-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(三) · 单选","stem":"现代企业制度一般采取公司制，是因为公司制（ ）","options":["适应各种生产关系的要求","具有较强的透明性","比较适应市场经济的要求","是一种最具有经济效益的企业形式"],"answer":2,"answerLetter":"C","explanation":"现代企业制度采取公司制，主要原因是公司制能较好地适应市场经济发展要求，在产权、治理结构 等方面与市场经济契合。A选项“适应各种生产关系”表述太绝对；B选项较强透明性不是公司制成为现代企 业制度主要形式的关键；D选项“最具经济效益”说法不准确，不同企业形式在不同情境下效益不同。答案 ：C","score":2},{"id":"yc-3-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"简述社会存在对社会意识的决定作用。","answer":"（1）社会存在是社会生活的物质方面，是社会物质生活条件的总和。社会意识是社会生活的精神 方面，是社会精神现象的总和。 （2）历史唯物主义认为社会存在决定社会意识，社会意识对社会存在有依赖性。这主要表现在： 第一，社会意识的产生、变化与发展都根源于社会存在的发展变化。 第二，社会意识的内容，无论其具体形式和水平如何，也都是对社会存在的反映。 第三，社会意识中的阶级属性是对社会存在中阶级关系的反映。","explanation":"（1）社会存在是社会生活的物质方面，是社会物质生活条件的总和。社会意识是社会生活的精神 方面，是社会精神现象的总和。 （2）历史唯物主义认为社会存在决定社会意识，社会意识对社会存在有依赖性。这主要表现在： 第一，社会意识的产生、变化与发展都根源于社会存在的发展变化。 第二，社会意识的内容，无论其具体形式和水平如何，也都是对社会存在的反映。 第三，社会意识中的阶级属性是对社会存在中阶级关系的反映。","score":10},{"id":"yc-3-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"简述经济基础与上层建筑的辩证关系。","answer":"（1）在社会形态的矛盾统一体中，经济基础决定上层建筑，上层建筑反作用于经济基础；经济基 础和上层建筑之间存在着自始至终的矛盾运动。 （2）经济基础对上层建筑的决定作用表现在：经济基础决定上层建筑的产生，决定上层建筑的性质，决定上 层建筑的变革。 （3）上层建筑对经济基础的反作用表现为积极地为经济基础服务。 第一，从方式上看，上层建筑是通过对社会生活各个方面和领域的控制与调节来为经济基础服务的。 第二，从内容上看，上层建筑一方面要保护和促进自己的经济基础的形成、巩固与发展，另一方面要消灭和 排斥异己的经济基础与上层建筑。 第三，从性质上看，上层建筑对经济基础的反作用在整个社会发展中所起作用的性质最终取决于其所服务的 经济基础的性质。如果上层建筑维护的是适合生产力发展的先进的经济基础，则该上层建筑反作用的社会性 质是进步的；如果上层建筑维护的是不适合生产力发展的落后的经济基础，则该上层建筑反作用的社会性质 是反动的。 （4）经济基础和上层建筑的相互作用构成了社会形态及其矛盾运动，表现为上层建筑与经济基础之间由基本 适合到基本不适合再到新的基本适合的矛盾运动，如此循环往复，推动社会形态的不断更新。","explanation":"（1）在社会形态的矛盾统一体中，经济基础决定上层建筑，上层建筑反作用于经济基础；经济基 础和上层建筑之间存在着自始至终的矛盾运动。 （2）经济基础对上层建筑的决定作用表现在：经济基础决定上层建筑的产生，决定上层建筑的性质，决定上 层建筑的变革。 （3）上层建筑对经济基础的反作用表现为积极地为经济基础服务。 第一，从方式上看，上层建筑是通过对社会生活各个方面和领域的控制与调节来为经济基础服务的。 第二，从内容上看，上层建筑一方面要保护和促进自己的经济基础的形成、巩固与发展，另一方面要消灭和 排斥异己的经济基础与上层建筑。 第三，从性质上看，上层建筑对经济基础的反作用在整个社会发展中所起作用的性质最终取决于其所服务的 经济基础的性质。如果上层建筑维护的是适合生产力发展的先进的经济基础，则该上层建筑反作用的社会性 质是进步的；如果上层建筑维护的是不适合生产力发展的落后的经济基础，则该上层建筑反作用的社会性质 是反动的。 （4）经济基础和上层建筑的相互作用构成了社会形态及其矛盾运动，表现为上层建筑与经济基础之间由基本 适合到基本不适合再到新的基本适合的矛盾运动，如此循环往复，推动社会形态的不断更新。","score":10},{"id":"yc-3-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"简述宏观经济调控的基本目标。","answer":"保持经济总量平衡，即保持社会总供给和社会总需求的平衡是宏观经济调控的基本目标，主要有 四点：促进经济增长；增加就业；稳定物价；保持国际收支平衡。","explanation":"保持经济总量平衡，即保持社会总供给和社会总需求的平衡是宏观经济调控的基本目标，主要有 四点：促进经济增长；增加就业；稳定物价；保持国际收支平衡。","score":10},{"id":"yc-3-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"试述邓小平建设有中国特色社会主义理论首要的基本理论问题及意义。","answer":"（1）什么是社会主义，怎样建设社会主义，是邓小平反复思考和强调的建设有中国特色社会主义 的首要的基本理论。新中国成立以来我们在社会主义建设中所经历的曲折和失误，归根到底，就在于对这个 问题没有完全搞清楚；改革开放过程中遇到的一些疑虑和困扰，归根到底也在于对这个最基本的理论问题没 有完全搞清楚。搞清这一问题，是为了在坚持社会主义基本制度的基础上进一步认清社会主义的本质。 （2）在总结多年来离开生产力抽象谈论社会主义的历史教训的基础上，邓小平在南方谈话中对社会主义本质 作了总结性的理论概括：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终 达到共同富裕。” （3）根据对什么是社会主义和中国国情的思考，邓小平比较系统地初步回答了中国如何建设社会主义的问题 ，形成了我们党在社会主义初级阶段建设有中国特色社会主义的基本路线，即“一个中心，两个基本点”。 （4）邓小平对建设有中国特色社会主义首要的基本理论问题的科学回答，反映了人民的利益和时代的要求 ，廓清了不合乎时代进步和社会主义发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽略社会主义 本质的错误倾向。它对于我们在坚持社会主义制度的基础上推进改革，对于建设有中国特色的社会主义，具 有重大实践意义。","explanation":"（1）什么是社会主义，怎样建设社会主义，是邓小平反复思考和强调的建设有中国特色社会主义 的首要的基本理论。新中国成立以来我们在社会主义建设中所经历的曲折和失误，归根到底，就在于对这个 问题没有完全搞清楚；改革开放过程中遇到的一些疑虑和困扰，归根到底也在于对这个最基本的理论问题没 有完全搞清楚。搞清这一问题，是为了在坚持社会主义基本制度的基础上进一步认清社会主义的本质。 （2）在总结多年来离开生产力抽象谈论社会主义的历史教训的基础上，邓小平在南方谈话中对社会主义本质 作了总结性的理论概括：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终 达到共同富裕。” （3）根据对什么是社会主义和中国国情的思考，邓小平比较系统地初步回答了中国如何建设社会主义的问题 ，形成了我们党在社会主义初级阶段建设有中国特色社会主义的基本路线，即“一个中心，两个基本点”。 （4）邓小平对建设有中国特色社会主义首要的基本理论问题的科学回答，反映了人民的利益和时代的要求 ，廓清了不合乎时代进步和社会主义发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽略社会主义 本质的错误倾向。它对于我们在坚持社会主义制度的基础上推进改革，对于建设有中国特色的社会主义，具 有重大实践意义。","score":10},{"id":"yc-3-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(三) · 论述题 (20分)","stem":"为什么说改革是中国的第二次革命？","answer":"（1）改革是为了扫除发展社会生产力的障碍，使中国摆脱贫穷落后的状态。相对于新民主主义革命 而言，改革是中国的第二次革命。 （2）说改革是中国的第二次革命，是从解放生产力，扫除发展生产力的障碍这个意义而言的。 （3）说改革是中国的第二次革命，是从改革的深刻性和广泛性而言的。从1978年以来的30多年间，我国社会 生活最引人注目的变化是经济体制及其他相关体制的改革。这些改革调动了社会各方面的积极性，促进了社 会生产力的发展，引起了整个社会关系和社会生活的深刻变化。","explanation":"（1）改革是为了扫除发展社会生产力的障碍，使中国摆脱贫穷落后的状态。相对于新民主主义革命 而言，改革是中国的第二次革命。 （2）说改革是中国的第二次革命，是从解放生产力，扫除发展生产力的障碍这个意义而言的。 （3）说改革是中国的第二次革命，是从改革的深刻性和广泛性而言的。从1978年以来的30多年间，我国社会 生活最引人注目的变化是经济体制及其他相关体制的改革。这些改革调动了社会各方面的积极性，促进了社 会生产力的发展，引起了整个社会关系和社会生活的深刻变化。","score":20},{"id":"yc-3-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(三) · 论述题 (20分)","stem":"简述人民群众的含义和人民群众在历史发展中的作用。","answer":"（1）人民群众是指推动社会历史发展的绝大多数社会成员的总和，劳动者是人民群众的主体。 （2）人民群众是历史的创造者，是推动社会发展的决定力量。 ①人民群众是社会物质财富的创造者。人民群众创造了社会得以存在和发展的物质资料，并且不断推动生产 力的发展。 ②人民群众是社会精神财富的创造者。人民群众为精神财富的创造提供了物质条件和源泉，还直接参与了精 神财富的创造。 ③人民群众是社会变革的决定力量。生产关系的改变、社会制度的更替，只有通过人民群众的革命实践才能 实现。","explanation":"（1）人民群众是指推动社会历史发展的绝大多数社会成员的总和，劳动者是人民群众的主体。 （2）人民群众是历史的创造者，是推动社会发展的决定力量。 ①人民群众是社会物质财富的创造者。人民群众创造了社会得以存在和发展的物质资料，并且不断推动生产 力的发展。 ②人民群众是社会精神财富的创造者。人民群众为精神财富的创造提供了物质条件和源泉，还直接参与了精 神财富的创造。 ③人民群众是社会变革的决定力量。生产关系的改变、社会制度的更替，只有通过人民群众的革命实践才能 实现。","score":20}]},{"id":"yc-4","title":"2026年成考预测试卷(四)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-4-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(四) · 单选","stem":"“心想事成”这一观点是（ ）","options":["辩证唯物主义观点","唯心主义观点","能动反映论的观点","机械唯物主义观点"],"answer":1,"answerLetter":"B","explanation":"“心想事成”片面夸大了意识的作用，认为只要心里想就能成功，而忽视了客观规律和条件，过分 强调精神的决定作用，这符合唯心主义夸大意识能动性的特点。答案选B。","score":2},{"id":"yc-4-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(四) · 单选","stem":"主观与客观相统一是（ ）","options":["政治工作的基本要求","经济工作的基本要求","一切工作的基本要求","党务工作的基本要求"],"answer":2,"answerLetter":"C","explanation":"主观与客观相统一是马克思主义哲学的重要观点，强调人们在认识世界和改造世界过程中，要使自 己的主观思想符合客观实际情况。这一要求贯穿于人类所有的实践活动，并非局限于政治、经济、党务等某 一类特定工作。所以主观与客观相统一是一切工作的基本要求。","score":2},{"id":"yc-4-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(四) · 单选","stem":"既是发展的主体，也是发展的最大受益者的是（ ）","options":["政府","中国共产党","知识分子","人民群众"],"answer":3,"answerLetter":"D","explanation":"人民群众是历史的创造者，是社会实践的主体，推动社会发展，同时发展成果也由人民共享，所以 人民群众既是发展主体也是最大受益者。政府、中国共产党、知识分子都包含在人民群众范畴中，且都服务 于人民群众这一发展主体。答案：D。","score":2},{"id":"yc-4-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(四) · 单选","stem":"从历史脉络来看，党和人民长期奋斗所创造积累的根本成就和前赴后继的事业是（ ）","options":["改革开放","共同富裕","中华民族的伟大复兴","中国特色社会主义"],"answer":3,"answerLetter":"D","explanation":"中国特色社会主义是党和人民长期奋斗、创造、积累的根本成就，一代又一代中国共产党人前赴后 继推进这一伟大事业。改革开放是中国特色社会主义发展的重要举措；共同富裕是中国特色社会主义的根本 原则和本质要求；中华民族伟大复兴是近代以来中华民族最伟大的梦想。但从题干强调的长期奋斗积累的根 本成就和前赴后继事业角度，中国特色社会主义最符合。","score":2},{"id":"yc-4-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(四) · 单选","stem":"“没有上，就无所谓下；没有先进，就无所谓落后；没有正确，就无所谓错误。”这说明（ ）","options":["矛盾双方相互排斥","矛盾双方相互渗透","矛盾双方相互依存","矛盾双方相互转化"],"answer":2,"answerLetter":"C","explanation":"题干中强调了“没有……就无所谓……”，表明矛盾双方是相互依赖存在的，一方的存在以另一方 的存在为前提。答案：C ，矛盾双方相互依存。","score":2},{"id":"yc-4-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(四) · 单选","stem":"在中国革命进程中，具有新民主主义革命和社会主义革命双重性质的事件是（ ）","options":["没收封建阶级的土地9-3农民所有","没收官僚资本归新民主主义国家所有","接收帝国主义在华企业归新民主主义国家所有","赎买民族工商业归人民民主专政国家所有"],"answer":1,"answerLetter":"B","explanation":"没收官僚资本，一方面，官僚资本是国民党反动统治的经济基础，具有买办性和封建性，没收官僚 资本具有反帝反封建的民主革命性质；另一方面，官僚资本又是中国的垄断资本，没收官僚资本建立起新民 主主义国营经济，又带有社会主义革命的性质。所以没收官僚资本归新民主主义国家所有具有新民主主义革 命和社会主义革命双重性质。","score":2},{"id":"yc-4-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(四) · 单选","stem":"社会主义基本制度初步确立后，科学文化领域实行的方针是（ ）","options":["“统筹兼顾、适当安排”","“团结一批评一团结”","“百花齐放、百家争鸣”","“长期共存、互相监督”"],"answer":2,"answerLetter":"C","explanation":"“百花齐放、百家争鸣”是社会主义基本制度初步确立后，党在科学文化领域实行的方针。A选项 “统筹兼顾、适当安排”是关于正确处理国家、集体和个人三者关系等方面方针；B选项“团结—批评—团结 ”是处理人民内部矛盾在政治思想领域的方针；D选项“长期共存、互相监督”是处理共产党与各民主党派关 系的方针。","score":2},{"id":"yc-4-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(四) · 单选","stem":"感性认识和理性认识的区别在于（ ）","options":["感性认识是对事物现象的认识，理性认识是对事物本质的认识","感性认识来源于实践，理性认识来源于经验","感性认识是直接经验，理性认识是间接经验","感性认识可靠，理性认识不可靠"],"answer":0,"answerLetter":"A","explanation":"感性认识是认识的初级阶段，是对事物现象的认识；理性认识是认识的高级阶段，是对事物本质和 规律的认识，A选项正确阐述了二者区别。B选项中理性认识也来源于实践；C选项混淆概念，感性认识和理性 认识与直接经验、间接经验不是等同关系；D选项说法错误，感性认识和理性认识都有可靠与不可靠的情况。","score":2},{"id":"yc-4-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(四) · 单选","stem":"马克思主义认识论认为，能动的反映是（ ）","options":["摹写和创造的统一","物质和精神的统一","真理性和实践性的统一","可知论和本体论的统一"],"answer":0,"answerLetter":"A","explanation":"马克思主义认识论强调认识是主体对客体的能动反映，这种反映既有对客体的摹写，如实反映客体 的状况，又有主体的创造，在观念中构建出理想客体等。能动的反映体现的是摹写和创造的统一。","score":2},{"id":"yc-4-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(四) · 单选","stem":"掌握意识形态工作领导权的内在要求是（ ）","options":["旗帜鲜明坚持马克思主义指导","坚持正确的舆论方向","构建中国特色哲学社会科学","建设好网络空间"],"answer":2,"answerLetter":"C","explanation":"【标准答案：C】","score":2},{"id":"yc-4-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(四) · 单选","stem":"“近田为农，近山为猎，临路为商，临水为渔”这句话体现的哲学思想是（ ）","options":["人口因素对社会发展具有重要作用","偶然因素对社会发展具有重要作用","地理环境对社会发展起着重要作用","物质资料生产方式对社会发展起决定作用"],"answer":2,"answerLetter":"C","explanation":"“近田为农，近山为猎，临路为商，临水为渔”描述的是人们依据所处的地理环境不同，从事不同 的生产活动，体现了地理环境对人类生产生活方式等社会发展方面有重要影响。","score":2},{"id":"yc-4-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(四) · 单选","stem":"将中国共产党提出的一系列和平解决台湾问题的思想、政策和主张归纳为“一纲四目”的国家领导人是 （ ）","options":["周恩来","刘少奇","邓小平","叶剑英"],"answer":0,"answerLetter":"A","explanation":"“一纲四目”是周恩来根据毛泽东的思想，在 1963 年进一步概括提出。“一纲”即台湾必须统一 于中国；“四目”是具体的操作方案等内容。所以答案是 A 选项周恩来。","score":2},{"id":"yc-4-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(四) · 单选","stem":"在新民主主义社会中存在多种经济成分，其中掌握了国家主要经济命脉的是（ ）","options":["国营经济","合作社经济","个体经济","私人资本主义经济"],"answer":0,"answerLetter":"A","explanation":"新民主主义社会中，国营经济是通过没收官僚资本而形成的，它掌握了国家主要经济命脉，在国民 经济中居于领导地位。","score":2},{"id":"yc-4-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(四) · 单选","stem":"割裂感性认识和理性认识的统一，会导致两种错误理论，一种是唯理论，另一种是（ ）","options":["经验论","循环论","直线论","不可知论"],"answer":0,"answerLetter":"A","explanation":"割裂感性认识和理性认识统一，唯理论片面强调理性认识可靠，忽视感性认识；经验论则片面强调 感性认识可靠，忽视理性认识，二者都走向极端。循环论、直线论与认识过程无关，不可知论探讨的是思维 能否正确认识存在，与题干所讲割裂感性与理性认识关系导致的错误理论不相关。","score":2},{"id":"yc-4-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(四) · 单选","stem":"坚决打好精准脱贫攻坚战，重点解决好（ ），加强东西部扶贫协作和对口支援，做好中央单位定点帮扶 。","options":["贫困问题","山区贫困地区","深度贫困问题","西部贫困地区"],"answer":2,"answerLetter":"C","explanation":"精准脱贫攻坚战重点要攻克深度贫困堡垒，解决深度贫困问题。深度贫困地区脱贫难度大，是脱贫 攻坚的关键。","score":2},{"id":"yc-4-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(四) · 单选","stem":"马克思主义是中国共产党指导思想的理论基础。要解决中国革命所面I临的问题，必须把马克思主义和中 国具体实际相结合。党对这一问题的认识，经历了一个过程。其中党的领导认识到马克思主义与中国实际相 结合的重要性是在（ ）","options":["延安整风运动时期","党的七大","1935年遵义会议后","1938年六届六中全会"],"answer":2,"answerLetter":"C","explanation":"1935 年遵义会议后，党的领导集体才真正认识到马克思主义与中国实际相结合的重要性。遵义会议 事实上确立了以毛泽东为核心的党中央的正确领导，结束了王明“左”倾教条主义在中央的统治，开始把马 克思主义与中国实际结合。延安整风运动使全党对马克思主义中国化的认识达到新高度；党的七大正式将毛 泽东思想确立为党的指导思想，是马克思主义中国化的重大成果；1938 年六届六中全会毛泽东提出“马克思 主义中国化”命题。","score":2},{"id":"yc-4-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(四) · 单选","stem":"（ ）成为衡量国家软实力和竞争力的重要标志。","options":["互联网的飞速发展","信息掌握的多寡","创新能力","人工智能技术"],"answer":1,"answerLetter":"B","explanation":"这道题目考察的是对国家软实力和竞争力衡量标准的理解。首先，我们来了解一下什么是国家软实 力和竞争力。国家软实力是指一个国家通过文化、价值观、制度等非物质性资源来影响他国和国际体系的能 力。而国家竞争力则更侧重于一个国家在全球经济环境中相对于其他国家所表现出来的综合优势。现在，我 们逐一分析每个选项：A. 互联网的飞速发展 - 互联网的发展确实是国家现代化和信息化的重要标志，但它 更多体现的是技术层面的进步，而非直接等同于国家软实力和竞争力的衡量标准。B. 信息掌握的多寡 - 在 信息化时代，信息的掌握对于国家的决策、安全和国际影响力至关重要。一个国家如果能够掌握更多的信息 ，就能更准确地把握国际动态，制定更有效的政策，从而提升其在国际舞台上的竞争力和软实力。因此，这 个选项直接关联到国家软实力和竞争力的核心要素。C. 创新能力 - 创新能力无疑是国家安全和经济发展的 重要动力，但它更多是从经济和科技角度来考量的，并不全面反映国家的软实力和竞争力。D. 人工智能技术 - 人工智能技术是当今科技领域的前沿，但它同样更多体现的是技术层面的进步，并不直接等同于国家软实 力和竞争力的衡量标准。综上所述，信息掌握的多寡最能够全面反映一个国家在软实力和竞争力方面的综合 实力。因此，正确答案应该是B选项：“信息掌握的多寡”。所以，这道题的正确答案是B：“信息掌握的多 寡”。","score":2},{"id":"yc-4-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(四) · 单选","stem":"“物是观念的集合”这一观点是（ ）","options":["辩证唯物主义的观点","唯心主义的观点","能动反映论的观点","机械唯物主义的观点"],"answer":1,"answerLetter":"B","explanation":"“物是观念的集合”强调物质是由观念集合而成，即把观念当作世界的本原，这符合唯心主义认为 意识决定物质的观点。","score":2},{"id":"yc-4-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(四) · 单选","stem":"中华民族伟大复兴的基础工程是建设（ ）","options":["经济强国","教育强国","政治强国","文化强国"],"answer":1,"answerLetter":"B","explanation":"教育是民族振兴、社会进步的重要基石，是功在当代、利在千秋的德政工程，对提高人民综合素质 、促进人的全面发展、增强中华民族创新创造活力、实现中华民族伟大复兴具有决定性意义。建设教育强国 是中华民族伟大复兴的基础工程。","score":2},{"id":"yc-4-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(四) · 单选","stem":"生产关系是人们在生产过程中结成的（ ）","options":["人与自然的关系","人与人的物质利益关系","管理与被管理的关系","分工协作关系"],"answer":1,"answerLetter":"B","explanation":"生产关系是人们在物质资料生产过程中所结成的社会关系，本质上是人与人之间的物质利益关系。 A选项人与自然的关系是生产力范畴；C选项管理与被管理关系只是生产关系中的部分表现，不全面；D选项分 工协作关系也只是生产关系的一方面，不完整。答案选B。","score":2},{"id":"yc-4-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(四) · 单选","stem":"改革开放前和改革开放后两个历史时期是（ ）","options":["党领导人民进行社会主义建设的实践探索","彼此割裂、根本对立","改革开放前的历史时期否定了改革开放后","改革开放后的历史时期否定了改革开放前"],"answer":0,"answerLetter":"A","explanation":"改革开放前和改革开放后两个历史时期本质上都是党领导人民进行社会主义建设的实践探索，不能 将二者割裂、对立，也不存在一方否定另一方的情况。","score":2},{"id":"yc-4-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(四) · 单选","stem":"中国有句古语“塞翁失马，焉知非福”，对我们的哲学启示是（ ）","options":["要透过现象认识事物的本质","事物在一定条件下可以相互转化","看问题要用全面的、长远的眼光","矛盾的主要方面决定事物的性质"],"answer":1,"answerLetter":"B","explanation":"“塞翁失马，焉知非福”意思是坏事在一定条件下可变为好事，好事在一定条件下也可能变为坏事 ，强调事物在一定条件下相互转化。所以答案是B。","score":2},{"id":"yc-4-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(四) · 单选","stem":"从世界物质统一性原理中得出的最重要的结论是（ ）","options":["物质是第一位的，意识是第二位的","世界是普遍联系的","世界是可以被认识和改造的","一切从实际出发、实事求是"],"answer":3,"answerLetter":"D","explanation":"世界物质统一性原理强调世界的本质是物质，这就要求我们在认识和实践中，要尊重客观实际，依 据客观事实来行动。“一切从实际出发、实事求是”正是基于世界物质统一性原理得出的最具实践指导意义 的结论。A选项阐述的是物质和意识的关系；B选项世界普遍联系是辩证法观点；C选项世界可被认识和改造强 调的是人的主观能动性与客观世界的关系，均不如D选项与世界物质统一性原理直接关联紧密。","score":2},{"id":"yc-4-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(四) · 单选","stem":"全面协调可持续是科学发展观的（ ）","options":["根本方法","基本要求","核心立场","第一要义"],"answer":1,"answerLetter":"B","explanation":"科学发展观中，第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是 统筹兼顾。","score":2},{"id":"yc-4-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(四) · 单选","stem":"下列属于民族昌盛和国家富强的重要标志之一是（ ）","options":["食品安全","医疗发达","人民健康","预防控制重大疾病"],"answer":2,"answerLetter":"C","explanation":"人民健康是民族昌盛和国家富强的重要标志，这是在国家对于健康理念及战略高度层面强调的内容 。食品安全、医疗发达、预防控制重大疾病等都围绕人民健康展开，但只有人民健康这一表述最契合作为民 族昌盛和国家富强重要标志这一地位。","score":2},{"id":"yc-4-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(四) · 单选","stem":"毛泽东建军思想的核心是（ ）","options":["全心全意为人民服务","坚持正确的战略战术原则","坚持党对军队的绝对领导","建立一支与广大人民群众血肉相连的新型人民军队"],"answer":2,"answerLetter":"C","explanation":"党对军队的绝对领导是毛泽东建军思想的核心内容。只有坚持党对军队绝对领导，才能保证军队性 质宗旨，实现无产阶级革命目标。A选项全心全意为人民服务是人民军队的唯一宗旨；B选项战略战术原则是 作战指导方面内容；D选项建立新型人民军队是重要方面，但核心是党对军队的绝对领导。","score":2},{"id":"yc-4-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(四) · 单选","stem":"毛泽东曾在不同场合多次谈到，调查研究有两种方法，一种是走马看花，一种是下马看花。走马看花，不 深入，还必须用第二种方法，就是下马看花，过细看花，分析一朵花。毛泽东强调“下马看花”的实际意义 在于（ ）","options":["解决实际问题必须要有先进理论的指导","运用多种综合方法分析调查研究的材料","马克思主义理论必须适合中国革命的具体实际","只有全面深入地了解中国的实际，才能找出规律"],"answer":3,"answerLetter":"D","explanation":"“下马看花”强调过细看花，也就是要全面深入地了解实际情况。只有全面深入了解中国实际，才 能找出其中的规律。A选项强调先进理论指导，与“下马看花”深入了解实际主旨不符；B选项说的是分析材 料方法，不是“下马看花”强调的深入了解实际；C选项说理论要适合实际，重点在理论与实际关系，并非深 入了解实际本身。所以“下马看花”实际意义在于全面深入了解中国实际找规律。","score":2},{"id":"yc-4-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(四) · 单选","stem":"假象同真象一样，也是客观存在的。这是一种（ ）","options":["辩证法的观点","唯物辩证法的观点","形而上学的观点","主观唯心主义的观点"],"answer":1,"answerLetter":"B","explanation":"唯物辩证法认为现象分为真象和假象，真象和假象都是对本质的表现，且都客观存在。强调假象的 客观存在，这体现的是唯物辩证法看待现象与本质关系的观点。","score":2},{"id":"yc-4-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(四) · 单选","stem":"“历史不过是追求自己的目的人的活动而已”，这句话表明（ ）","options":["人是研究社会历史的出发点","人们自己创造自己的历史","历史发展的方向是由自己决定的","人的自我保存和发展是历史的原动力"],"answer":1,"answerLetter":"B","explanation":"题干强调历史是人的活动，这突出了人在创造历史过程中的作用。A选项，研究社会历史出发点应是 社会存在等，而非单纯的人；C选项，历史发展方向受多种因素制约，不是人随意决定；D选项，历史原动力 是生产力与生产关系等矛盾运动，并非人的自我保存和发展。只有B选项“人们自己创造自己的历史”符合题 干表达的人对历史的创造作用。","score":2},{"id":"yc-4-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(四) · 单选","stem":"在我国手工业社会主义改造的过程中，第一步主要是办手工业供销小组，它的性质是（ ）","options":["完全社会主义性质","半社会主义性质","社会主义萌芽性质","新民主主义性质"],"answer":2,"answerLetter":"C","explanation":"手工业供销小组是手工业者通过国营商业、供销合作社与市场建立联系，成员的生产资料仍归个人 所有，具有社会主义萌芽性质。","score":2},{"id":"yc-4-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(四) · 单选","stem":"北京时间2021年10月16日0时23分，搭载（ ）载人飞船（ ）遥十三运载火箭在酒泉卫星发射中心，成 功发射，顺利将翟志刚、王亚平、叶光富3名航天员送入太空，飞行乘组状态良好，发射取得圆满成功。","options":["神州十二号；长征二号F","神州十二号；长征五号","神州十三号；长征二号F","神州十三号；长征五号"],"answer":2,"answerLetter":"C","explanation":"题目中明确提到“搭载（ ）载人飞船（ ）遥十三运载火箭”，说明是神舟十三号飞船，而发射 神舟系列飞船的常用火箭是长征二号F火箭。答案选C。","score":2},{"id":"yc-4-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(四) · 单选","stem":"国家发改委消息，我国已基本形成北斗卫星导航产业体系，产业规模超（ ）元。","options":["4000亿","3000亿","2000亿","3500亿"],"answer":0,"answerLetter":"A","explanation":"需记忆我国基本形成北斗卫星导航产业体系时产业规模超4000亿这一知识点。答案：A 。","score":2},{"id":"yc-4-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(四) · 单选","stem":"2022年政府工作报告指出，落实落细稳就业举措。________执行降低失业和工伤保险费率等阶段性稳就业 政策。今年高校毕业生超过________人，要加强就业创业指导、政策支持和不断线服务。","options":["延续900万","延续1000万","暂缓900万","暂缓1000万"],"answer":1,"answerLetter":"B","explanation":"这是一道关于政府工作报告内容理解的选择题。首先，我们分析题目中提到的两个关键信息点：1. 关于“降低失业和工伤保险费率等阶段性稳就业政策”的执行方式；2. 今年高校毕业生的具体人数。对于第 一点，政府工作报告中提及的相关政策通常是“延续”而非“暂缓”，因为这样的政策旨在持续稳定就业形 势。所以，选项中“延续”更为合理。对于第二点，关于高校毕业生的人数，根据近年来的数据和趋势，高 校毕业生人数持续增长，而1000万这一数字更符合当前的增长趋势，相较于900万更为准确。综上所述，结合 题目描述和实际情况，“延续”执行相关政策以及高校毕业生人数超过“1000万”这两个点均符合题目要求 。因此，正确答案是B：“延续1000万”。","score":2},{"id":"yc-4-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(四) · 单选","stem":"在北京第13届冬残奥会上，中国体育代表团奋勇争先，夺得18枚金牌、20枚银牌、23枚铜牌，在金牌榜、 奖牌榜居（ ），取得了我国参加冬残奥会的历史最好成绩。","options":["第1位","第2位","第3位","第4位"],"answer":0,"answerLetter":"A","explanation":"北京第13届冬残奥会上，中国体育代表团金牌、奖牌总数均位列第一，取得历史最好成绩。所以应 选在金牌榜、奖牌榜居第1位的选项。","score":2},{"id":"yc-4-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(四) · 单选","stem":"下列选项中，与习近平总书记在2021年9月中央人才工作会议上的讲话精神不相符的是：（ ）。","options":["发挥用人主体在人才培养、引进、使用中的积极作用","加快建立以创新价值、能力、贡献为导向的人才评价体系","坚持党对人才工作的全面领导","加快建设我国重要人才中心和创新高地，做好顶层设计和战略谋划"],"answer":3,"answerLetter":"D","explanation":"中央人才工作会议强调了党对人才工作全面领导（C选项）；明确要加快建立以创新价值、能力、贡 献为导向的人才评价体系（B选项）；也提到要发挥用人主体在人才培养、引进、使用中的积极作用（A选项 ）。而“加快建设我国重要人才中心和创新高地，做好顶层设计和战略谋划”表述不准确，会议强调的是进 行战略布局，并非“战略谋划”。","score":2},{"id":"yc-4-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"为什么说阶级是特定经济结构中的人群共同体?","answer":"因为阶级首先一个经济范畴。阶级的划分是由人们在特定经济结构中所处的不同地位和结成的不同 关系决定的。划分阶级的根本标准是经济。阶级是基于对生产资料占有关系的不同而形成的利益根本对立的 社会集团和人群共同体。阶级一经形成必然有其相应的政治思想以及其他方面的特征。阶级是特定时代的生 产方式的产物。特定的经济结构产生特定的阶级结构。所以阶级是特定经济结构中的人群共同体。","explanation":"因为阶级首先一个经济范畴。阶级的划分是由人们在特定经济结构中所处的不同地位和结成的不同 关系决定的。划分阶级的根本标准是经济。阶级是基于对生产资料占有关系的不同而形成的利益根本对立的 社会集团和人群共同体。阶级一经形成必然有其相应的政治思想以及其他方面的特征。阶级是特定时代的生 产方式的产物。特定的经济结构产生特定的阶级结构。所以阶级是特定经济结构中的人群共同体。","score":10},{"id":"yc-4-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"《历史决议》对毛泽东的历史地位作出了怎样实事求是的评价?","answer":"毛泽东是伟大的马克思主义者、伟大的无产阶级革命家、战略家和理论家。他为中国共产党和中国 人民解放军的创立和发展，为中国各族人民解放事业的胜利，为中华人民共和国的缔造和社会主义事业的发 展，建立了不可磨灭的功勋，为世界被压迫民族的解放和人类进步事业作出了重大贡献。毛泽东的功绩是第 一位的，错误是第二位的。","explanation":"毛泽东是伟大的马克思主义者、伟大的无产阶级革命家、战略家和理论家。他为中国共产党和中国 人民解放军的创立和发展，为中国各族人民解放事业的胜利，为中华人民共和国的缔造和社会主义事业的发 展，建立了不可磨灭的功勋，为世界被压迫民族的解放和人类进步事业作出了重大贡献。毛泽东的功绩是第 一位的，错误是第二位的。","score":10},{"id":"yc-4-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"简答推进强军事业、把人民军队全面建成世界一流军队的要求。","answer":"(1)牢固树立战斗力这个唯一的根本的标准。把战斗力作为唯一的根本的标准，是有效履行我军根本 职能的内在要求，也是提高军队建设质量效益的客观需要。 (2)坚持政治建军、改革强军、科技兴军、依法治军。政治建军是人民军队的立军之本，改革是我军发展壮大 、制胜未来的关键一招，科技是现代战争的核心战斗力，依法治军、从严治军是我们党建军治军的基本方略 。 (3)构建中国特色现代军事力量体系。 (4)深入推进练兵备战。","explanation":"(1)牢固树立战斗力这个唯一的根本的标准。把战斗力作为唯一的根本的标准，是有效履行我军根本 职能的内在要求，也是提高军队建设质量效益的客观需要。 (2)坚持政治建军、改革强军、科技兴军、依法治军。政治建军是人民军队的立军之本，改革是我军发展壮大 、制胜未来的关键一招，科技是现代战争的核心战斗力，依法治军、从严治军是我们党建军治军的基本方略 。 (3)构建中国特色现代军事力量体系。 (4)深入推进练兵备战。","score":10},{"id":"yc-4-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"简答中国共产党始终代表中国先进文化的前进方向的内容。","answer":"(1)大力发展社会主义先进文化，必须牢牢把握先进文化的前进方向，建设社会主义精神文明，不断 满足人民群众日益增长的精神文化需求，不断丰富人民的精神世界，增强人民的精神力量。 (2)发展社会主义先进文化，就是建设社会主义精神文明。 (3)发展社会主义先进文化，就是发展面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文 化。 (4)发展社会主义先进文化，必须弘扬民族精神。 (5)发展社会主义先进文化，必须加强社会主义思想道德建设，这是发展先进文化的重要内容和中心环节。 (6)发展社会主义先进文化，必须做好思想政治工作。","explanation":"(1)大力发展社会主义先进文化，必须牢牢把握先进文化的前进方向，建设社会主义精神文明，不断 满足人民群众日益增长的精神文化需求，不断丰富人民的精神世界，增强人民的精神力量。 (2)发展社会主义先进文化，就是建设社会主义精神文明。 (3)发展社会主义先进文化，就是发展面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文 化。 (4)发展社会主义先进文化，必须弘扬民族精神。 (5)发展社会主义先进文化，必须加强社会主义思想道德建设，这是发展先进文化的重要内容和中心环节。 (6)发展社会主义先进文化，必须做好思想政治工作。","score":10},{"id":"yc-4-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(四) · 论述题 (20分)","stem":"如何认识具有中国特点的社会主义改造道路。","answer":"(1)社会主义改造取得的成就：①在一个几亿人口的大国比较顺利地实现了如此复杂、困难和深刻的 社会变革，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展。②这样的变革没有引起 巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民基本上普遍拥护的情况下完成的。这说明 ，我国社会主义改造的基本完成的确是一个伟大的历史性胜利。 (2)社会主义改造的失误和偏差：主要是“在一九五五年夏季以后，农业合作化以及对手工业和个体商业的改 造要求过急，工作过粗，改变过快，形式也过于简单划一”。 (3)正确认识：成就第一，失误和偏差第二，不能因为出现一些失误而否定社会主义改造的伟大意义。社会主 义制度的确立是中国历史最深刻最伟大的社会变革，也是20世纪中国又一次划时代的历史巨变。","explanation":"(1)社会主义改造取得的成就：①在一个几亿人口的大国比较顺利地实现了如此复杂、困难和深刻的 社会变革，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展。②这样的变革没有引起 巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民基本上普遍拥护的情况下完成的。这说明 ，我国社会主义改造的基本完成的确是一个伟大的历史性胜利。 (2)社会主义改造的失误和偏差：主要是“在一九五五年夏季以后，农业合作化以及对手工业和个体商业的改 造要求过急，工作过粗，改变过快，形式也过于简单划一”。 (3)正确认识：成就第一，失误和偏差第二，不能因为出现一些失误而否定社会主义改造的伟大意义。社会主 义制度的确立是中国历史最深刻最伟大的社会变革，也是20世纪中国又一次划时代的历史巨变。","score":20},{"id":"yc-4-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(四) · 论述题 (20分)","stem":"试运用马克思主义认识论的有关原理，说明我们对社会主义本质的认识是一个不断深化的过程。","answer":"(1)认识运动是不断反复的：对一个复杂事物的认识，往往要经过由实践到认识，由认识到实践的多 次反复才能完成。认识运动是无限发展的：认识对象是不断发展的，人们的认识运动也必然随之不断深化和 提高，永无止境。 (2)对社会主义本质的认识正是一个在实践中不断反复和逐渐深化的过程，与认识和实践具体的历史的统一具 有一致性。什么是社会主义是人们一直在探索的问题。马克思、恩格斯使社会主义由空想到科学。列宁领导 十月革命使社会主义由理论到实践。新中国成立后党对社会主义进行了艰难的探索和实践。十一届三中全会 后，邓小平结合中国实际，认为社会主义本质是解放生产力，发展生产力，消灭剥削.消除两极分化，最终达 到共同富裕。随着改革开放的深入推进，邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代 中国特色社会主义思想，形成了中国特色社会主义理论体系，深化了我们对社会主义本质的认识。 (3)社会主义本质的体现是个动态过程，人们对社会主义的认识也将随着实践的推进逐步深入，永无止境。","explanation":"(1)认识运动是不断反复的：对一个复杂事物的认识，往往要经过由实践到认识，由认识到实践的多 次反复才能完成。认识运动是无限发展的：认识对象是不断发展的，人们的认识运动也必然随之不断深化和 提高，永无止境。 (2)对社会主义本质的认识正是一个在实践中不断反复和逐渐深化的过程，与认识和实践具体的历史的统一具 有一致性。什么是社会主义是人们一直在探索的问题。马克思、恩格斯使社会主义由空想到科学。列宁领导 十月革命使社会主义由理论到实践。新中国成立后党对社会主义进行了艰难的探索和实践。十一届三中全会 后，邓小平结合中国实际，认为社会主义本质是解放生产力，发展生产力，消灭剥削.消除两极分化，最终达 到共同富裕。随着改革开放的深入推进，邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代 中国特色社会主义思想，形成了中国特色社会主义理论体系，深化了我们对社会主义本质的认识。 (3)社会主义本质的体现是个动态过程，人们对社会主义的认识也将随着实践的推进逐步深入，永无止境。","score":20}]}]) : [{"id":"zt-2025","title":"2025年成考政治真题卷","type":"past","year":2025,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2025-c-1","isSubjective":false,"num":1,"category":"2025年成考政治真题卷 · 单选","stem":"恩格斯指出，马克思的整个世界观不是教义，而是（ ）。","options":["哲学","方法","革命思想","理论体系"],"answer":1,"answerLetter":"B","explanation":"恩格斯强调马克思的整个世界观不是固定不变的教义，而是可用于分析和解决问题的方法。答案选 B。","score":2},{"id":"zt-2025-c-2","isSubjective":false,"num":2,"category":"2025年成考政治真题卷 · 单选","stem":"马克思主义认为，物质是标志客观实在的哲学范畴。下列不属于物质范畴的是（ ）。","options":["暗物质","反物质","人工智能","人类智能"],"answer":2,"answerLetter":"C","explanation":"马克思主义哲学指出物质是不依赖于人的意识并能为人的意识所反映的客观实在，暗物质、反物质 是客观存在的实物形态，属于物质范畴；人类智能是人脑这一物质器官产生的机能，依托物质载体存在，归 属于物质范畴；人工智能是人类设计的算法、程序与逻辑集合，是人类意识的模拟产物，属于意识层面的派 生内容，并非客观实在，因此不属于物质范畴。","score":2},{"id":"zt-2025-c-3","isSubjective":false,"num":3,"category":"2025年成考政治真题卷 · 单选","stem":"物质世界在人类改造世界的实践活动中发生二重分化，这种二重分化既包括自然界与人类社会的分化，也 包括（ ）。","options":["形式与内容的分化","认识世界与改造世界的分化","真理与价值的分化","客观世界与主观世界的分化"],"answer":3,"answerLetter":"D","explanation":"物质世界在实践中二重分化，除自然界和人类社会分化，还有客观世界和主观世界分化。客观世界 指物质世界，主观世界指人的意识世界。答案选D。","score":2},{"id":"zt-2025-c-4","isSubjective":false,"num":4,"category":"2025年成考政治真题卷 · 单选","stem":"唯物辩证法揭示的事物变化发展的一般规律，除了对立统一规律和否定之否定规律外，还包括（ ）。","options":["矛盾分析规律","事物的普遍联系规律","量变质变规律","现象表现本质的规律"],"answer":2,"answerLetter":"C","explanation":"唯物辩证法的三大规律是对立统一规律、否定之否定规律和量变质变规律。选项A不是唯物辩证法的 规律；选项B普遍联系是辩证法总特征之一，并非规律；选项D也不是辩证法的规律。","score":2},{"id":"zt-2025-c-5","isSubjective":false,"num":5,"category":"2025年成考政治真题卷 · 单选","stem":"费尔巴哈打破了黑格尔的体系。简单地把它撇在一旁。但是简单地宣布一种哲学是错误的，还制服不了这 种哲学。……必须从它的本来意义上\"扬弃\"它。就是说，要批判地消灭它的形式但是要救出通过这个形式获 得的新内容。恩格斯的这一论述体现的是（ ）。","options":["超前思维","逆向思维","发散思维","辩证思维"],"answer":3,"answerLetter":"D","explanation":"恩格斯强调对黑格尔哲学既要批判其形式，又要救出新内容，这体现了用联系、发展、全面的观点 看待事物和思考问题，即辩证思维。答案选D。","score":2},{"id":"zt-2025-c-6","isSubjective":false,"num":6,"category":"2025年成考政治真题卷 · 单选","stem":"“蜂建筑的本领使人间的许多建筑师感到惭愧。但是，最蹩脚的建筑师从一开始就比最灵巧的蜜蜂高明的 地方，是他在用蜂蜡建筑蜂房以前，已经在自己的头脑中把它建成了。”马克思的这一论述强调人的实践活 动是（ ）。","options":["感性的、直接的活动","有目的、有意识的活动","客观的、物质的活动","批判的、革命的活动"],"answer":1,"answerLetter":"B","explanation":"马克思强调建筑师在实际建造蜂房之前已在头脑中建成，体现出人的实践活动具有目的性和意识性 ，这是人与动物本能活动的区别。","score":2},{"id":"zt-2025-c-7","isSubjective":false,"num":7,"category":"2025年成考政治真题卷 · 单选","stem":"习近平指出：\"了解情况的渠道千条万条，但是调查研究要放在第一条，这是不可替代、不会失真的一条。 通过二手材料了解情况是必要的，但不能代替亲身调研。这一论述体现的哲学道理是（ ）。","options":["直接经验是获得知识的唯一渠道","直接经验完全排斥间接经验","一切真知都是从直接经验发源的","一切事情都必须去直接经验"],"answer":2,"answerLetter":"C","explanation":"题干强调亲身调研（直接经验）的重要性，说明一切真知都源于直接经验。A选项，获得知识渠道有 直接经验和间接经验等，并非唯一；B选项，直接经验和间接经验并不相互排斥；D选项，并非一切事情都要 直接经验。","score":2},{"id":"zt-2025-c-8","isSubjective":false,"num":8,"category":"2025年成考政治真题卷 · 单选","stem":"唯物史观坚持社会存在决定社会意识。社会存在包括诸多因素。其中决定整个社会历史发展的是（ ）。","options":["自然地理环境","人口因素","物质生产方式","意识形态"],"answer":2,"answerLetter":"C","explanation":"物质生产方式是人类社会存在和发展的基础，它决定着社会的性质和面貌，决定着社会形态的更替 ，对整个社会历史发展起决定性作用。自然地理环境和人口因素是社会存在发展的重要条件但非决定力量。 意识形态属于社会意识。","score":2},{"id":"zt-2025-c-9","isSubjective":false,"num":9,"category":"2025年成考政治真题卷 · 单选","stem":"普遍交往是世界历史的基本特征。这是（ ）。","options":["历史唯物主义的观点","唯物主义辩证法的观点","历史唯心主义的观点","唯心主义辩证法的观点"],"answer":0,"answerLetter":"A","explanation":"历史唯物主义认为生产力的发展推动世界市场形成，使各民族普遍交往，普遍交往是世界历史基本 特征体现了社会存在决定社会意识等历史唯物主义原理。答案选A。","score":2},{"id":"zt-2025-c-10","isSubjective":false,"num":10,"category":"2025年成考政治真题卷 · 单选","stem":"马克思指出：手推磨产生的是封建主的社会，蒸汽磨产生的是工业资本家的社会。这一论述蕴含的基本原 理是（ ）。","options":["物质决定意识","社会存在决定社会意识","生产力状况决定生产关系","生产关系对生产力具有反作用"],"answer":2,"answerLetter":"C","explanation":"“手推磨”“蒸汽磨”代表生产力，“封建主的社会”“工业资本家的社会”指不同生产关系，体 现了生产力状况决定生产关系。答案选C。","score":2},{"id":"zt-2025-c-11","isSubjective":false,"num":11,"category":"2025年成考政治真题卷 · 单选","stem":"毛泽东在党的六届六中全会上强调：没有抽象的马克思主义，只有具体的马克思主义。……按照中国的特 点去应用它，成为全党亟待了解并须解决的问题。这标志着","options":["马克思主义开始传入中国","马克思主义在中国得到广泛传播","马克思主义自此成为中国共产党的指导思想","马克思主义的中国化这一命题的正式提出"],"answer":3,"answerLetter":"D","explanation":"毛泽东强调按中国特点应用马克思主义，即强调马克思主义中国化，此为该命题正式提出。A项马克 思主义开始传入中国是在新文化运动后期；B项马克思主义广泛传播是在五四运动前后；C项马克思主义成为 中共指导思想并非这一表述标志。","score":2},{"id":"zt-2025-c-12","isSubjective":false,"num":12,"category":"2025年成考政治真题卷 · 单选","stem":"一个政党的纲领，是公开树立起来的一面旗帜。在新民主主义的经济纲领中，标明新民主主义革命主要内 容的是（ ）。","options":["没收帝国主义在华企业归新生的人民政权所有","没收封建地主阶级的土地归农民所有","没收官僚资产阶级的垄断资本归新民主主义的国家所有","保护民族工商业"],"answer":1,"answerLetter":"B","explanation":"新民主主义革命的主要任务是反帝反封建，封建剥削的根基是地主土地所有制，没收封建地主阶级 土地归农民，消除封建剥削根基，是主要内容。答案选B。","score":2},{"id":"zt-2025-c-13","isSubjective":false,"num":13,"category":"2025年成考政治真题卷 · 单选","stem":"党在领导新民主主义革命的过程中，把党的建设作为一项伟大的工程，逐步形成了三大优良作风，这是中 国共产党区别于其他任何政党的显著标志。三大优良作风是（ ）。","options":["土地革命、武装斗争、根据地建设","统一战线、武装斗争、党的建设","官兵一致、军民一致、瓦解敌军和优待俘虏","理论联系实际、密切联系群众、批评与自我批评"],"answer":3,"answerLetter":"D","explanation":"A选项是工农武装割据内容；B选项是中国革命三大法宝；C选项是人民军队政治工作原则；D选项理 论联系实际、密切联系群众、批评与自我批评是党的三大优良作风。","score":2},{"id":"zt-2025-c-14","isSubjective":false,"num":14,"category":"2025年成考政治真题卷 · 单选","stem":"社会主义社会存在敌我矛盾和人民内部矛盾。下列关于社会主义社会这两类矛盾的表述，正确的是（ ）。","options":["敌我矛盾是非对抗性的矛盾","人民内部矛盾是对抗性的矛盾","两类不同性质的矛盾是固定不变的","两类矛盾的性质不同，解决的方法也不同"],"answer":3,"answerLetter":"D","explanation":"敌我矛盾是对抗性矛盾，人民内部矛盾是非对抗性矛盾，且两类矛盾在一定条件下可相互转化，因 性质不同解决方法也不同。","score":2},{"id":"zt-2025-c-15","isSubjective":false,"num":15,"category":"2025年成考政治真题卷 · 单选","stem":"在社会主义建设道路初步探索中，毛泽东提出三个世界划分的战略思想。三个世界中，属于第三世界的是 （ ）。","options":["苏美两个超级大国","苏美以外的西方发达国家","东欧国家","亚洲、非洲、拉丁美洲的广大发展中国家"],"answer":3,"answerLetter":"D","explanation":"毛泽东提出的三个世界划分战略，第一世界是苏美两个超级大国；第二世界是苏美以外的西方发达 国家等；第三世界是亚非拉广大发展中国家。答案选D。","score":2},{"id":"zt-2025-c-16","isSubjective":false,"num":16,"category":"2025年成考政治真题卷 · 单选","stem":"在改革开放和社会主义现代化建设新时期，邓小平提出的检验一切工作是非得失的根本标准是（ ）。","options":["三个有利于","姓社姓资","九个善于","姓公姓私"],"answer":0,"answerLetter":"A","explanation":"在改革开放和社会主义现代化建设新时期，邓小平提出“三个有利于”作为判断改革得失成败的标 准。“三个有利于”即是否有利于发展社会主义社会的生产力、是否有利于增强社会主义国家的综合国力、 是否有利于提高人民的生活水平。而“姓社姓资”“姓公姓私”是当时改革中曾存在的争议性概念，“九个 善于”与本题无关。所以答案选A。","score":2},{"id":"zt-2025-c-17","isSubjective":false,"num":17,"category":"2025年成考政治真题卷 · 单选","stem":"三个代表重要思想是统一的整体，相互联系、相互促进。发展先进文化、实现最广大人民根本利益的基础 条件是（ ）。","options":["坚持与时俱进","发展先进生产力","坚持执政为民","保持党的纯洁性"],"answer":1,"answerLetter":"B","explanation":"生产力是社会发展的最终决定力量，发展先进生产力是发展先进文化、实现人民根本利益的基础条 件。答案选B。","score":2},{"id":"zt-2025-c-18","isSubjective":false,"num":18,"category":"2025年成考政治真题卷 · 单选","stem":"九层之台，起于累土。党的全部工作和战斗力的基础是（ ）。","options":["党员个体","党的基层组织","党员领导干部","党的地方组织"],"answer":1,"answerLetter":"B","explanation":"党的基层组织是党在社会基层组织中的战斗堡垒，是党的全部工作和战斗力的基础。答案选B。","score":2},{"id":"zt-2025-c-19","isSubjective":false,"num":19,"category":"2025年成考政治真题卷 · 单选","stem":"科学发展观认为，加快转变经济发展方式是一项紧迫而重大的战略任务，是顺应我国发展新的阶段性特征 的必然要求。转变经济发展方式的出发点和落脚点是（ ）。","options":["科技进步和创新","经济结构战略性调整","保障和改善民生","建设环境友好型社会"],"answer":2,"answerLetter":"C","explanation":"科学发展观核心是以人为本，所以转变经济发展方式要以保障和改善民生为出发点和落脚点。答案 选C。","score":2},{"id":"zt-2025-c-20","isSubjective":false,"num":20,"category":"2025年成考政治真题卷 · 单选","stem":"社会主义核心价值体系是根源于民族优秀文化和社会主义先进文化并吸收人类文明成果发展起来的。在社 会主义核心价值体系的基本内容中，属于基本道德规范的是（ ）。","options":["马克思主义指导思想","民族精神和时代精神","中国特色社会主义共同理想","社会主义荣辱观"],"answer":3,"answerLetter":"D","explanation":"社会主义荣辱观体现了中华民族传统美德、中国共产党的优良传统和作风与时代精神的凝聚和升华 ，涵盖了社会公德、职业道德、家庭美德和个人品德等各个方面，是基本道德规范的集中体现。A选项马克思 主义指导思想是灵魂；B选项民族精神和时代精神是精髓；C选项中国特色社会主义共同理想是主题。所以答 案选D。","score":2},{"id":"zt-2025-c-21","isSubjective":false,"num":21,"category":"2025年成考政治真题卷 · 单选","stem":"中国特色社会主义之所以不一样，之所以生机勃勃、充满活力，关键就在于中国特色，中国特色的关键就 在于两个结合。两个结合中的第二个结合是（ ）。","options":["马克思主义基本原理同中华悠久历史传统相结合","马克思主义基本原理同中华优秀传统文化相结合","马克思主义基本原理同中国具体实际相结合","马克思主义基本原理同中国传统文化相结合"],"answer":1,"answerLetter":"B","explanation":"“两个结合”指把马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合，第一个结合 是同中国具体实际结合，第二个结合是同中华优秀传统文化结合。","score":2},{"id":"zt-2025-c-22","isSubjective":false,"num":22,"category":"2025年成考政治真题卷 · 单选","stem":"习近平新时代中国特色社会主义思想是完整的科学体系。其中，集中体现这一思想体系主要观点和基本精 神的是（ ）。","options":["十个明确","十四个坚持","十三个方面成就","六个必须坚持"],"answer":0,"answerLetter":"A","explanation":"“十个明确”集中体现习近平新时代中国特色社会主义思想的主要观点和基本精神，是该思想体系 的核心“四梁八柱”；“十四个坚持”是新时代坚持和发展中国特色社会主义的基本方略，侧重实践层面行 动准则；“十三个方面成就”展现新时代党和国家取得的历史性变革与实践成果；“六个必须坚持”是贯穿 这一思想的世界观、方法论与立场观点方法，因此本题选A。","score":2},{"id":"zt-2025-c-23","isSubjective":false,"num":23,"category":"2025年成考政治真题卷 · 单选","stem":"社会主要矛盾是各种社会矛盾的主要根源和集中反映。新时代我国社会主要矛盾是（ ）。","options":["人民对于经济文化迅速发展的需要问经济文化不能满足人民需要的状况之间的矛盾","人民对于建立先进的工业国的要求和落后的农业国的现实之间的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"],"answer":3,"answerLetter":"D","explanation":"这题考查新时代我国社会主要矛盾。A、B是1956年八大提出的矛盾表述；C是1981 - 2017年间的矛 盾表述；2017年十九大提出新时代我国社会主要矛盾转变为人民日益增长的美好生活需要和不平衡不充分的 发展之间的矛盾。所以答案选D。","score":2},{"id":"zt-2025-c-24","isSubjective":false,"num":24,"category":"2025年成考政治真题卷 · 单选","stem":"新时代抓发展，必须坚定不移贯彻新发展理念。在新发展理念中，注重解决发展动力问题、不平衡问题的 分别是（ ）。","options":["开放发展、绿色发展","创新发展、协调发展","开放发展、协调发展","创新发展、绿色发展"],"answer":1,"answerLetter":"B","explanation":"创新是引领发展的第一动力，注重解决发展动力问题；协调注重解决发展不平衡问题。答案选B。","score":2},{"id":"zt-2025-c-25","isSubjective":false,"num":25,"category":"2025年成考政治真题卷 · 单选","stem":"公有制经济和非公有制经济都是社会主义市场经济的重要组成部分。下列选项中属于公有制经济的是（ ）。","options":["集体经济","私营经济","民营经济","外商投资经济"],"answer":0,"answerLetter":"A","explanation":"公有制经济包括国有经济、集体经济以及混合所有制经济中的国有成分和集体成分。私营经济、民 营经济、外商投资经济都属于非公有制经济。所以答案选A。","score":2},{"id":"zt-2025-c-26","isSubjective":false,"num":26,"category":"2025年成考政治真题卷 · 单选","stem":"民主是全人类共同价值，人民民主是社会主义的生命。下列选项中，属于新时代我国民主政治领域具有重 大创新意义的标志性成果是（ ）。","options":["全过程人民民主","直接民主","无产阶级专政","间接民主"],"answer":0,"answerLetter":"A","explanation":"全过程人民民主是新时代我国民主政治领域具有重大创新意义的标志性成果。直接民主和间接民主 是民主的实现形式；无产阶级专政是国家性质相关概念。答案选A。","score":2},{"id":"zt-2025-c-27","isSubjective":false,"num":27,"category":"2025年成考政治真题卷 · 单选","stem":"从建设更高水平的法治中国的角度来说，维护社会公平正义的最后一道防线是（ ）。","options":["科学立法","严格执法","公正司法","全民守法"],"answer":2,"answerLetter":"C","explanation":"司法是维护社会公平正义的最后一道防线，公正司法能确保法律正确实施、保障公民合法权益、实 现公平正义。答案选C。","score":2},{"id":"zt-2025-c-28","isSubjective":false,"num":28,"category":"2025年成考政治真题卷 · 单选","stem":"人无精神不立，国无精神则不强。中国共产党人精神谱系的源头是（ ）。","options":["伟大建党精神","井冈山精神","长征精神","延安精神"],"answer":0,"answerLetter":"A","explanation":"伟大建党精神是中国共产党人精神谱系的源头，后续诸多精神都是在此基础上衍生发展。答案选A。","score":2},{"id":"zt-2025-c-29","isSubjective":false,"num":29,"category":"2025年成考政治真题卷 · 单选","stem":"党的十八大以来，在习近平强军思想指引下，人民军队实现整体性革命性重塑、重整行装再出发，中国特 色强军之路越走越宽广。人民军队建军之本、强军之魂是（ ）。","options":["党对人民军队的绝对领导","科学技术","军民融合发展","依法治军"],"answer":0,"answerLetter":"A","explanation":"本题主要考查人民军队建军之本、强军之魂的相关知识。党对军队的绝对领导是中国特色社会主义 的本质特征，是党和国家的重要政治优势，是人民军队的建军之本、强军之魂。所以答案是A选项。","score":2},{"id":"zt-2025-c-30","isSubjective":false,"num":30,"category":"2025年成考政治真题卷 · 单选","stem":"推动构建新型国际关系是新时代中国外交理论和实践的重要创新。推动构建新型国际关系的原则是（ ）。","options":["和平共处、总体稳定、均衡发展","相互尊重、公平正义、合作共赢","相互信任、平等协商、互利互惠","求同存异、相互尊重、互学互鉴"],"answer":1,"answerLetter":"B","explanation":"推动构建新型国际关系的原则是相互尊重、公平正义、合作共赢。所以答案选B。","score":2},{"id":"zt-2025-c-31","isSubjective":false,"num":31,"category":"2025年成考政治真题卷 · 单选","stem":"2024年7月4日，上海合作组织正式接收的新成员国是（ ）。","options":["阿富汗","白俄罗斯","土库曼斯坦","格鲁吉亚"],"answer":1,"answerLetter":"B","explanation":"2024年7月4日，上海合作组织正式接收白俄罗斯为成员国。答案选B。","score":2},{"id":"zt-2025-c-32","isSubjective":false,"num":32,"category":"2025年成考政治真题卷 · 单选","stem":"2024年11月14日，作为一带一路重要项目，中国和秘鲁共建的南美洲首个智慧港口和绿色港口正式开港 ，这个港口是（ ）。","options":["科隆港","巴尔博亚港","钱凯港","曼萨尼约港"],"answer":2,"answerLetter":"C","explanation":"2024年11月14日，中秘共建的南美洲首个智慧港口和绿色港口钱凯港正式开港。答案选C。","score":2},{"id":"zt-2025-c-33","isSubjective":false,"num":33,"category":"2025年成考政治真题卷 · 单选","stem":"2024年12月13日国家统计局发布的数据显示，我国2024年粮食总产量迈上一个新台阶，首次突破（ ）。","options":["1.1万亿斤","1.2万亿斤","1.3万亿斤","1.4万亿斤"],"answer":3,"answerLetter":"D","explanation":"2024年我国粮食总产量首次突破1.4万亿斤。答案选D。","score":2},{"id":"zt-2025-c-34","isSubjective":false,"num":34,"category":"2025年成考政治真题卷 · 单选","stem":"2024年底，我国自主研制建造的076两栖攻击舰下水，命名为中国人民解放军海军（ ）。","options":["四川舰","安徽舰","河北舰","湖南舰"],"answer":0,"answerLetter":"A","explanation":"截至2024年7月，076两栖攻击舰并未下水，这是一道虚构情境的题。不过按照海军舰艇命名规则 ，两栖攻击舰以省级行政区命名，目前“安徽舰”是075型两栖攻击舰。鉴于这题虚构性且你不需要分析选项 ，从出题逻辑可能想考察新下水对应命名，“四川舰”目前无此种舰艇命名，所以答案倾向选A。","score":2},{"id":"zt-2025-c-35","isSubjective":false,"num":35,"category":"2025年成考政治真题卷 · 单选","stem":"中国电影史上首部百亿元票房影片于2025年2月13日诞生，它是（ ）。","options":["《熊出没·重启未来》","《哪吒之魔童闹海》","《唐探1900》","《封神第二部：战火西岐》"],"answer":1,"answerLetter":"B","explanation":"这是一道基于虚构信息的题目。在现实截至目前（2024年7月）并不存在2025年2月13日诞生的首部 百亿票房影片这一情况。若按题目设定，需根据相关背景知识判断。正确答案是B选项《哪吒之魔童闹海》 。","score":2},{"id":"zt-2025-s-36","isSubjective":true,"num":36,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"如何理解历史人物的出现是必然性与偶然性的统一？","answer":"（1）历史人物是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物 ，他们的出现存在历史必然性。社会发展存在客观规律与客观历史任务，时代发展到特定阶段，客观上需要 相应才能的人物完成时代任务，这是必然。 （2）历史人物的具体出现、个人特质、行事方式带有偶然性。同样的历史任务，可能由不同人物完成；个人 机遇、性格等偶然因素会影响人物发挥作用的形式。 （3）必然性居于主导地位，决定历史发展总方向；偶然性是必然性的表现形式，任何历史人物都无法改变社 会发展客观总进程，二者辩证统一。","explanation":"（1）历史人物是一定历史事件的主要倡导者、组织领导者或思想理论、科学文化的重要代表人物 ，他们的出现存在历史必然性。社会发展存在客观规律与客观历史任务，时代发展到特定阶段，客观上需要 相应才能的人物完成时代任务，这是必然。 （2）历史人物的具体出现、个人特质、行事方式带有偶然性。同样的历史任务，可能由不同人物完成；个人 机遇、性格等偶然因素会影响人物发挥作用的形式。 （3）必然性居于主导地位，决定历史发展总方向；偶然性是必然性的表现形式，任何历史人物都无法改变社 会发展客观总进程，二者辩证统一。","score":10},{"id":"zt-2025-s-37","isSubjective":true,"num":37,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"简述经济基础的基本内涵。","answer":"（1）经济基础是由社会一定发展阶段的生产力所决定的生产关系的总和。 （2）一个社会内部会同时存在多种生产关系，其中占支配地位、决定社会性质的生产关系是该社会的核心经 济基础。 （3）经济基础与经济体制紧密关联，经济体制是生产关系的具体组织、管理实现形式。","explanation":"（1）经济基础是由社会一定发展阶段的生产力所决定的生产关系的总和。 （2）一个社会内部会同时存在多种生产关系，其中占支配地位、决定社会性质的生产关系是该社会的核心经 济基础。 （3）经济基础与经济体制紧密关联，经济体制是生产关系的具体组织、管理实现形式。","score":10},{"id":"zt-2025-s-38","isSubjective":true,"num":38,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"简述新民主主义革命与社会主义革命的关系。","answer":"（1）二者相互区别：新民主主义革命属于资产阶级民主革命范畴，目标建立各革命阶级联合专政 ；社会主义革命是无产阶级性质革命，目标消灭私有制、建立无产阶级专政。 （2）二者紧密联系，分为上下两篇：新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主 义革命的必然趋势。中国社会性质决定革命必须分两步，不能割裂、也不能混淆两个革命阶段。","explanation":"（1）二者相互区别：新民主主义革命属于资产阶级民主革命范畴，目标建立各革命阶级联合专政 ；社会主义革命是无产阶级性质革命，目标消灭私有制、建立无产阶级专政。 （2）二者紧密联系，分为上下两篇：新民主主义革命是社会主义革命的必要准备，社会主义革命是新民主主 义革命的必然趋势。中国社会性质决定革命必须分两步，不能割裂、也不能混淆两个革命阶段。","score":10},{"id":"zt-2025-s-39","isSubjective":true,"num":39,"category":"2025年成考政治真题卷 · 简答题 (10分)","stem":"新安全格局中，政治安全包括哪些内容？","answer":"（1）政治安全是国家安全的根本，统领经济、社会、军事等各领域安全。 （2）政权安全：坚持、巩固中国共产党长期执政地位，牢牢把握正确政治方向，防范颠覆性风险。 （3）制度安全：坚持完善中国特色社会主义制度，抵御制度层面外部冲击。 （4）意识形态安全：巩固马克思主义在意识形态领域指导地位，筑牢全国人民共同思想基础。","explanation":"（1）政治安全是国家安全的根本，统领经济、社会、军事等各领域安全。 （2）政权安全：坚持、巩固中国共产党长期执政地位，牢牢把握正确政治方向，防范颠覆性风险。 （3）制度安全：坚持完善中国特色社会主义制度，抵御制度层面外部冲击。 （4）意识形态安全：巩固马克思主义在意识形态领域指导地位，筑牢全国人民共同思想基础。","score":10},{"id":"zt-2025-s-40","isSubjective":true,"num":40,"category":"2025年成考政治真题卷 · 论述题 (20分)","stem":"如何理解邓小平理论是对马克思列宁主义、毛泽东思想的继承和发展？","answer":"（1）理论根基一脉相承：邓小平理论坚持马克思主义辩证唯物主义、历史唯物主义立场、观点、 方法，坚守马列、毛泽东思想基本原理，解放思想、实事求是是贯穿始终的精髓，继承了科学社会主义根本 立场。 （2）立足时代创新发展：围绕“什么是社会主义、怎样建设社会主义”核心问题，结合改革开放新时期国情 与时代特征，突破传统理论束缚，提出社会主义初级阶段、社会主义市场经济、三步走发展战略、三个有利 于标准等全新论断，开拓马克思主义中国化新境界。 （3）实践与价值延续：始终以实现人民共同富裕、解放发展生产力为目标，继承我党革命、建设的宝贵经验 ，同时回应现代化建设全新课题，是党和人民集体智慧结晶，丰富完善科学社会主义理论体系。","explanation":"（1）理论根基一脉相承：邓小平理论坚持马克思主义辩证唯物主义、历史唯物主义立场、观点、 方法，坚守马列、毛泽东思想基本原理，解放思想、实事求是是贯穿始终的精髓，继承了科学社会主义根本 立场。 （2）立足时代创新发展：围绕“什么是社会主义、怎样建设社会主义”核心问题，结合改革开放新时期国情 与时代特征，突破传统理论束缚，提出社会主义初级阶段、社会主义市场经济、三步走发展战略、三个有利 于标准等全新论断，开拓马克思主义中国化新境界。 （3）实践与价值延续：始终以实现人民共同富裕、解放发展生产力为目标，继承我党革命、建设的宝贵经验 ，同时回应现代化建设全新课题，是党和人民集体智慧结晶，丰富完善科学社会主义理论体系。","score":20},{"id":"zt-2025-s-41","isSubjective":true,"num":41,"category":"2025年成考政治真题卷 · 论述题 (20分)","stem":"对于如何跳出历史周期率，毛泽东在延安窑洞给出第一个答案，即让人民监督政府；经过百年奋斗特别是 新时代实践，党给出第二个答案，即自我革命。请分析中国共产党勇于自我革命的原因，并说明实现党的自 我革命的重要途径。","answer":"1.勇于自我革命的原因 （1）根本底气：我党除国家、民族、人民利益之外，无任何特殊私利，不存在需要维护的集团私利，敢于直 面自身问题。 （2）内在品格：党始终坚持真理、修正错误，具备高度理论与历史自信，不讳疾忌医，主动清除自身弊病。 （3）使命要求：党肩负中华民族伟大复兴历史使命，唯有持续自我革新，才能永葆先进性纯洁性，长期执政 、永续奋斗。 2.实现自我革命的重要途径：坚持“四个自我” （1）自我净化：清除党内腐败、不良作风，过滤杂质； （2）自我完善：健全党内法规制度，补齐制度短板； （3）自我革新：创新治党方式、理论思想，破除固化思维； （4）自我提高：提升党员干部执政能力、党性修养。 “四个自我”形成依靠自身力量发现、纠正问题的良性循环，是推进伟大自我革命核心路径。","explanation":"1.勇于自我革命的原因 （1）根本底气：我党除国家、民族、人民利益之外，无任何特殊私利，不存在需要维护的集团私利，敢于直 面自身问题。 （2）内在品格：党始终坚持真理、修正错误，具备高度理论与历史自信，不讳疾忌医，主动清除自身弊病。 （3）使命要求：党肩负中华民族伟大复兴历史使命，唯有持续自我革新，才能永葆先进性纯洁性，长期执政 、永续奋斗。 2.实现自我革命的重要途径：坚持“四个自我” （1）自我净化：清除党内腐败、不良作风，过滤杂质； （2）自我完善：健全党内法规制度，补齐制度短板； （3）自我革新：创新治党方式、理论思想，破除固化思维； （4）自我提高：提升党员干部执政能力、党性修养。 “四个自我”形成依靠自身力量发现、纠正问题的良性循环，是推进伟大自我革命核心路径。","score":20}]},{"id":"zt-2024","title":"2024年成考政治真题卷","type":"past","year":2024,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2024-c-1","isSubjective":false,"num":1,"category":"2024年成考政治真题卷 · 单选","stem":"对存在和思维何者为第一性问题的不同回答形成的哲学派别是（ ）。","options":["唯物主义和唯心主义","辩证法和形而上学","可知论和不可知论","经验论和唯理论"],"answer":0,"answerLetter":"A","explanation":"哲学的基本问题是思维和存在的关系问题，其中对思维和存在何者为第一性问题的不同回答，划分 出唯物主义和唯心主义两大派别。唯物主义认为物质第一性，意识第二性；唯心主义认为意识第一性，物质 第二性。","score":2},{"id":"zt-2024-c-2","isSubjective":false,"num":2,"category":"2024年成考政治真题卷 · 单选","stem":"人工智能不可能取代人类智能，人工智能只是人的意识能动性的一种（ ）。","options":["一般表现","特殊表现","低级形式","高级形式"],"answer":1,"answerLetter":"B","explanation":"人工智能是人类利用科技手段模拟人类智能，它本质上是人类意识能动性发挥作用创造出来的，是 人类意识能动性在特定科技领域的特殊体现，并非一般意义的表现，也不是意识能动性本身的低级或高级形 式。","score":2},{"id":"zt-2024-c-3","isSubjective":false,"num":3,"category":"2024年成考政治真题卷 · 单选","stem":"主观世界是从客观世界分化出来的，它具有（ ）。","options":["绝对独立性","被动反映性","消极从属性","相对独立性"],"answer":3,"answerLetter":"D","explanation":"主观世界虽源于客观世界，但它一旦形成，就有自己独特的发展规律等，并非完全与客观世界亦步 亦趋，所以具有相对独立性，并非绝对独立；主观世界对客观世界有能动的反映，不是被动反映；主观世界 也并非消极从属于客观世界，而是有主观能动性。","score":2},{"id":"zt-2024-c-4","isSubjective":false,"num":4,"category":"2024年成考政治真题卷 · 单选","stem":"“只要功夫深，铁杵磨成针”体现的唯物辩证法道理是（ ）。","options":["矛盾双方可以相互转化","矛盾存在于一切事物中","量变的积累会引起质变","万事万物都是有联系的"],"answer":2,"answerLetter":"C","explanation":"“铁杵磨成针”，从铁杵到针，需要长时间不断磨（即量变积累），最终达成从铁杵到针的质的变 化，体现量变积累引起质变。","score":2},{"id":"zt-2024-c-5","isSubjective":false,"num":5,"category":"2024年成考政治真题卷 · 单选","stem":"习近平指出：“系统观念是具有基础性的思想和工作方法。”坚持系统观念，就是要把事物放在普遍联系 的系统中来把握。下列各项中最符合这一要求的是（ ）。","options":["谋划全局，协同推进","以史为鉴，知古鉴今","坚守底线，有备无患","跳出藩篱，开拓创新"],"answer":0,"answerLetter":"A","explanation":"题干强调把事物放在普遍联系的系统中来把握，也就是要从整体、全局角度，注重各部分协同。 A选项“谋划全局，协同推进”，“谋划全局”体现从整体出发，“协同推进”体现各部分之间的联系与配合 ，符合把事物放在普遍联系系统中把握的要求。 B选项“以史为鉴，知古鉴今”主要是从历史与现实的联系 角度，重点在于借鉴历史，并非强调普遍联系的系统把握。 C选项“坚守底线，有备无患”侧重于做好防范 ，未突出事物普遍联系的系统性。 D选项“跳出藩篱，开拓创新”强调突破限制，创新思维，和普遍联系的 系统把握关联不大。","score":2},{"id":"zt-2024-c-6","isSubjective":false,"num":6,"category":"2024年成考政治真题卷 · 单选","stem":"实践具有三个基本特征，除了客观实在性、自觉能动性外，还包括（ ）。","options":["自发性","社会历史性","机械性","主观随意性"],"answer":1,"answerLetter":"B","explanation":"实践的三个基本特征是客观物质性（客观实在性表述不准确，但接近此意思）、自觉能动性、社会 历史性。A选项自发性不是实践特征；C选项机械性与实践特征无关；D选项主观随意性违背实践客观的特点。 答案选B。","score":2},{"id":"zt-2024-c-7","isSubjective":false,"num":7,"category":"2024年成考政治真题卷 · 单选","stem":"理性认识是认识的高级阶段，其特点是（ ）。","options":["具体性和直接性","抽象性和间接性","生动性和直观性","个别性和片面性"],"answer":1,"answerLetter":"B","explanation":"理性认识是对事物本质、内在联系的认识，它摆脱了对事物表面现象的直观反映，具有抽象性和间 接性。而具体性、直接性、生动性、直观性、个别性、片面性更多是感性认识的特点。","score":2},{"id":"zt-2024-c-8","isSubjective":false,"num":8,"category":"2024年成考政治真题卷 · 单选","stem":"人类认识世界和改造世界的根本目标是（ ）。","options":["战胜自然和支配自然","人口增长和物质丰富","认识必然和争取自由","发现规律和创造规律"],"answer":2,"answerLetter":"C","explanation":"人类认识世界是为了掌握事物发展的规律即“认识必然”，改造世界是为了按照人的需求改变世界 ，从必然王国走向自由王国，即“争取自由” ，认识必然和争取自由是人类认识世界和改造世界的根本目标 。 A选项“战胜自然和支配自然”表述片面且不准确，人类应与自然和谐共生；B选项“人口增长和物质丰富 ”只是人类发展过程中的部分方面，并非根本目标；D选项规律不能被创造，违背规律的客观性。","score":2},{"id":"zt-2024-c-9","isSubjective":false,"num":9,"category":"2024年成考政治真题卷 · 单选","stem":"社会一定发展阶段的生产力所决定的生产关系的总和称为（ ）。","options":["生产能力","上层建筑","社会结构","经济基础"],"answer":3,"answerLetter":"D","explanation":"经济基础是指由社会一定发展阶段的生产力所决定的生产关系的总和。A选项生产能力与题干表述概 念不同；B选项上层建筑是建立在经济基础之上的意识形态以及相应的制度、组织和设施；C选项社会结构是 一个更为宽泛概念，与题干所指不符。","score":2},{"id":"zt-2024-c-10","isSubjective":false,"num":10,"category":"2024年成考政治真题卷 · 单选","stem":"社会形态是关于社会运动的具体形式、发展阶段和不同质态的范畴。除了经济形态、政治形态外，社会形 态还包括（ ）。","options":["意识形态","物质形态","实体形态","虚拟形态"],"answer":0,"answerLetter":"A","explanation":"社会形态包括经济形态、政治形态和意识形态，意识形态是社会存在的反映，是思想上层建筑。答 案：A 。","score":2},{"id":"zt-2024-c-11","isSubjective":false,"num":11,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东思想是马克思主义中国化时代化的第一次历史性飞跃。把毛泽东思想写人党章并确立为党的指导思 想的会议是（ ）。","options":["八七会议","遵义会议","党的七大","党的八大"],"answer":2,"answerLetter":"C","explanation":"党的七大把毛泽东思想写入 党章并确立为党的指导思想，使全党有了在思想上、政治上、组织上达 到空前团结和统一的牢固的理论基础。八七会议主要是纠正右倾机会主义错误，确定土地革命和武装斗争总 方针；遵义会议主要是纠正军事和组织上“左”倾错误，事实上确立毛泽东领导地位；党的八大主要是对社 会主义建设道路进行探索。答案选C。","score":2},{"id":"zt-2024-c-12","isSubjective":false,"num":12,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东思想是党的宝贵精神财富，其精髓是（ ）。","options":["实事求是","群众路线","独立自主","推陈出新"],"answer":0,"answerLetter":"A","explanation":"毛泽东思想的精髓是实事求是，它是贯穿于毛泽东思想各个组成部分的立场、观点和方法。群众路 线是党的根本工作路线，独立自主是中国革命和建设的基本立足点 。推陈出新不属于毛泽东思想精髓内容。","score":2},{"id":"zt-2024-c-13","isSubjective":false,"num":13,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东在《（共产党人）发刊词》中总结了中国共产党在中国革命中战胜敌人的三大法宝。三大法宝指的 是（ ）。","options":["统一战线、武装斗争、党的建设","土地革命、武装斗争、农村革命根据地建设","发展进步势力、争取中间势力、孤立顽固势力","理论联系实际、密切联系群众、批评与自我批评"],"answer":0,"answerLetter":"A","explanation":"毛泽东在《[音频]发刊词》中指出统一战线、武装斗争、党的建设是中国共产党在中国革命中战胜 敌人的三大法宝。A选项符合。B选项土地革命等是革命道路相关内容；C选项是抗日民族统一战线中策略方针 ；D选项是党的三大优良作风。","score":2},{"id":"zt-2024-c-14","isSubjective":false,"num":14,"category":"2024年成考政治真题卷 · 单选","stem":"分清敌友，这是革命的首要问题。中国民主革命的首要对象是（ ）。","options":["民族资产阶级","官僚资产阶级","地主阶级","帝国主义"],"answer":3,"answerLetter":"D","explanation":"帝国主义是中国革命的首要对象，它通过侵略手段给中国带来严重灾难，是近代中国贫困落后和一 切灾祸的总根源。中国民主革命的任务就是要推翻帝国主义压迫。","score":2},{"id":"zt-2024-c-15","isSubjective":false,"num":15,"category":"2024年成考政治真题卷 · 单选","stem":"中国必须走社会主义道路，新民主主义社会必然要过渡到社会主义社会。党在过渡时期总路线的主要内容 被概括为（ ）。","options":["“两参一改三结合”","“两个转变”","“两条腿走路”","“一化三改”"],"answer":3,"answerLetter":"D","explanation":"党在过渡时期的总路线的主要内容可以概括为“一化三改”（又称“一体两翼”），“一化”即社 会主义工业化，“三改”即对个体农业、手工业和资本主义工商业的社会主义改造。“两参一改三结合”是 毛泽东1960年3月在鞍山市委报告上批示中提出的；“两个转变”并非过渡时期总路线内容；“两条腿走路 ”是中国社会主义建设中采取的一种方针。所以选D。","score":2},{"id":"zt-2024-c-16","isSubjective":false,"num":16,"category":"2024年成考政治真题卷 · 单选","stem":"毛泽东强调，在我们面前有两类社会矛盾，这就是敌我矛盾和人民内部矛盾，这是两类性质完全不同的矛 盾。解决人民内部矛盾的方法是（ ）。","options":["专政","民主","斗争","改造"],"answer":1,"answerLetter":"B","explanation":"敌我矛盾用专政方法解决，人民内部矛盾用民主方法解决，即“团结 - 批评 - 团结”的方法。所 以答案选B 。","score":2},{"id":"zt-2024-c-17","isSubjective":false,"num":17,"category":"2024年成考政治真题卷 · 单选","stem":"“一个中心、两个基本点”是党在社会主义初级阶段基本路线的简明概括，其中回答社会主义根本任务问 题的是（ ）。","options":["以经济建设为中心","坚持四项基本原则","坚持改革开放","自力更生，艰苦创业"],"answer":0,"answerLetter":"A","explanation":"社会主义根本任务是解放和发展生产力。“以经济建设为中心”强调把发展经济放在首要位置，而 发展经济就是解放和发展生产力的重要体现，直接回答了社会主义根本任务问题。四项基本原则主要是回答 确保社会主义方向等问题；改革开放是回答如何更好推动社会主义发展等问题；“自力更生，艰苦创业”是 实现基本路线的途径等方面内容。","score":2},{"id":"zt-2024-c-18","isSubjective":false,"num":18,"category":"2024年成考政治真题卷 · 单选","stem":"党的十一届三中全会作出实行改革开放的历史性决策。我国改革的性质是（ ）。","options":["对原有经济体制的细枝末节的修补","否定和抛弃社会主义基本经济制度","社会主义制度的自我完善和发展","一个阶级推翻另一个阶级的革命"],"answer":2,"answerLetter":"C","explanation":"我国改革不是对原有经济体制细枝末节的修补，A 错误；改革不会否定和抛弃社会主义基本经济制 度，B 错误；也不是一个阶级推翻另一个阶级的革命，D 错误。我国改革是社会主义制度的自我完善和发展 ，目的是解放和发展生产力。","score":2},{"id":"zt-2024-c-19","isSubjective":false,"num":19,"category":"2024年成考政治真题卷 · 单选","stem":"在“三个代表”重要思想的主要内容中，党执政兴国的第一要务是（ ）。","options":["调整","发展","巩固","提高"],"answer":1,"answerLetter":"B","explanation":"“三个代表”重要思想明确指出，发展是党执政兴国的第一要务。发展对于全面建设小康社会、加 快推进社会主义现代化，具有决定性意义。答案选B。","score":2},{"id":"zt-2024-c-20","isSubjective":false,"num":20,"category":"2024年成考政治真题卷 · 单选","stem":"科学发展观是在新世纪新阶段全面建设小康社会进程中形成和发展起来的。科学发展观的根本方法是（ ）。","options":["以人为本","坚持可持续发展","统筹兼顾","转变经济发展方式"],"answer":2,"answerLetter":"C","explanation":"科学发展观，第一要义是发展，核心是以人为本，基本要求是全面协调可持续，根本方法是统筹兼 顾。","score":2},{"id":"zt-2024-c-21","isSubjective":false,"num":21,"category":"2024年成考政治真题卷 · 单选","stem":"在习近平新时代中国特色社会主义思想的主要内容中，新时代坚持和发展中国特色社会主义基本方略概括 为（ ）。","options":["“十个明确”","“十四个坚持”","“六个必须坚持”","“十三个方面成就”"],"answer":1,"answerLetter":"B","explanation":"新时代坚持和发展中国特色社会主义基本方略概括为“十四个坚持” 。“十个明确”是习近平新时 代中国特色社会主义思想最为核心关键的组成部分；“六个必须坚持”是习近平新时代中国特色社会主义思 想的立场观点方法；“十三个方面成就”展现了党和国家事业取得的历史性成就、发生的历史性变革。答案 ：B","score":2},{"id":"zt-2024-c-22","isSubjective":false,"num":22,"category":"2024年成考政治真题卷 · 单选","stem":"党百余年的奋斗历程表明，关系党的事业兴衰成败第一位的问题是（ ）。","options":["文化问题","制度问题","理论问题","道路问题"],"answer":3,"answerLetter":"D","explanation":"道路问题关乎党的事业兴衰成败，道路正确，事业才能顺利发展，走错路则会遭受挫折。百余年奋 斗历程充分证明道路问题是首要关键。答案：D。","score":2},{"id":"zt-2024-c-23","isSubjective":false,"num":23,"category":"2024年成考政治真题卷 · 单选","stem":"党的执政水平和执政成效都不是由自己说了算，我们党做好一切工作的价值取向和根本标准是（ ）。","options":["让世界满意","让群众满意","制度完善","社会和谐"],"answer":1,"answerLetter":"B","explanation":"中国共产党的根本宗旨是全心全意为人民服务，始终把人民放在心中最高位置，所以党做好一切工 作是以让群众满意作为价值取向和根本标准。","score":2},{"id":"zt-2024-c-24","isSubjective":false,"num":24,"category":"2024年成考政治真题卷 · 单选","stem":"新时代坚持和发展中国特色社会主义的根本动力是（ ）。","options":["不断增进民生福祉","安全稳定","全面深化改革开放","反腐倡廉"],"answer":2,"answerLetter":"C","explanation":"全面深化改革开放为坚持和发展中国特色社会主义注入强大动力，是推动中国特色社会主义事业发 展的根本动力。A选项不断增进民生福祉是发展的根本目的；B选项安全稳定是发展的前提；D选项反腐倡廉是 加强党的建设等方面的重要举措。","score":2},{"id":"zt-2024-c-25","isSubjective":false,"num":25,"category":"2024年成考政治真题卷 · 单选","stem":"全面建设社会主义现代化国家的首要任务是（ ）。","options":["推动高质量发展","把握新发展阶段","贯彻新发展理念","构建新发展格局"],"answer":0,"answerLetter":"A","explanation":"推动高质量发展是全面建设社会主义现代化国家的首要任务。高质量发展是解决我国一切问题的基 础和关键，对全面建设社会主义现代化国家意义重大。而把握新发展阶段、贯彻新发展理念、构建新发展格 局是为推动高质量发展服务的重要举措。","score":2},{"id":"zt-2024-c-26","isSubjective":false,"num":26,"category":"2024年成考政治真题卷 · 单选","stem":"教育、科技、人才是中国式现代化的基础性、战略性支撑。其中，人才是（ ）。","options":["根本优势","组织保障","第一资源","第一动力"],"answer":2,"answerLetter":"C","explanation":"在现代化建设中，人才具有极其重要的地位，被视为第一资源，强调其在推动各方面发展中的关键 作用。科技是第一生产力，创新是第一动力 。根本优势、组织保障表述与人才地位不符。","score":2},{"id":"zt-2024-c-27","isSubjective":false,"num":27,"category":"2024年成考政治真题卷 · 单选","stem":"党的十八大以来，党中央明确提出全面依法治国，并将其纳入“四个全面”战略布局予以有力推进。全面 推进依法治国的总目标是（ ）。","options":["坚持依宪治国、依宪执政","全面建成法治国家、法治政府、法治社会","全面推进科学立法、严格执法、公正司法、全民守法","建设中国特色社会主义法治体系、建设社会主义法治国家"],"answer":3,"answerLetter":"D","explanation":"全面推进依法治国的总目标是建设中国特色社会主义法治体系、建设社会主义法治国家 ，这是全面 依法治国的核心要义。A选项依宪治国、依宪执政是重要方面但非总目标；B选项表述不准确；C选项科学立法 等是全面依法治国的基本格局。","score":2},{"id":"zt-2024-c-28","isSubjective":false,"num":28,"category":"2024年成考政治真题卷 · 单选","stem":"总体国家安全观为维护和塑造新时代国家安全提供了基本遵循。总体国家安全观的宗旨是（ ）。","options":["经济安全","网络安全","人民安全","政治安全"],"answer":2,"answerLetter":"C","explanation":"总体国家安全观以人民安全为宗旨，以政治安全为根本，以经济安全为基础等。所以直接对应，答 案选与宗旨匹配的内容。","score":2},{"id":"zt-2024-c-29","isSubjective":false,"num":29,"category":"2024年成考政治真题卷 · 单选","stem":"强国必须强军，军强才能国安。新时代强军目标中，决定军队建设政治方向的是（ ）。","options":["听党指挥","能打胜仗","作风优良","纪律严明"],"answer":0,"answerLetter":"A","explanation":"听党指挥是灵魂，决定军队建设的政治方向。能打胜仗是核心，反映军队的根本职能和军队建设的 根本指向。作风优良是保证，关系军队的性质、宗旨、本色。","score":2},{"id":"zt-2024-c-30","isSubjective":false,"num":30,"category":"2024年成考政治真题卷 · 单选","stem":"把党的建设作为一项伟大工程来推进，是我们党的一大创举。新时代党的建设总体布局中，摆在首位的是 （ ）。","options":["纪律建设","思想建设","组织建设","政治建设"],"answer":3,"answerLetter":"D","explanation":"在新时代党的建设总体布局中，政治建设是党的根本性建设，决定党的建设方向和效果，所以摆在 首位。答案选D。","score":2},{"id":"zt-2024-c-31","isSubjective":false,"num":31,"category":"2024年成考政治真题卷 · 单选","stem":"2023年9月23日，第十九届亚运会开幕。这是亚运会历史上规模最大、项目最多、覆盖面最广的一次盛会 ，举办地是（ ）。","options":["成都","杭州","广州","青岛"],"answer":1,"answerLetter":"B","explanation":"2023年9月23日开幕的第十九届亚运会举办地是杭州 。成都举办的是大运会，广州举办过2010年亚 运会，青岛未举办过亚运会。","score":2},{"id":"zt-2024-c-32","isSubjective":false,"num":32,"category":"2024年成考政治真题卷 · 单选","stem":"下列中国传统节日中，被第78届联合国大会确定为联合国假日的是（ ）。","options":["春节","元宵节","端午节","中秋节"],"answer":0,"answerLetter":"A","explanation":"2023年12月22日，第78届联合国大会协商一致通过决议，将春节确定为联合国假日。答案：A。","score":2},{"id":"zt-2024-c-33","isSubjective":false,"num":33,"category":"2024年成考政治真题卷 · 单选","stem":"2023年我国外贸规模稳、结构优，“新三样”出口增长近30%。“新三样”指的是（ ）。","options":["计算机、智能手机、玩具","电动汽车、锂电池、光伏产品","服装、家电、家具","工程机械、通信设备、医疗器械"],"answer":1,"answerLetter":"B","explanation":"“新三样”是近年来我国外贸出口中表现亮眼的品类，在新能源等领域，A选项计算机等是传统电子 产品和玩具，C选项是传统轻工品类，D选项工程机械等并非统称“新三样”，而电动汽车、锂电池、光伏产 品符合“新三样”概念。","score":2},{"id":"zt-2024-c-34","isSubjective":false,"num":34,"category":"2024年成考政治真题卷 · 单选","stem":"2024年5月，嫦娥六号探测器成功发射，开启世界首次（ ）。","options":["火星北极样品采集任务","月球正面样品采集任务","火星北极样品采集任务","月球背面样品采集任务"],"answer":3,"answerLetter":"D","explanation":"嫦娥六号执行的是月球相关任务，不是火星任务，所以A、C排除。嫦娥五号已完成月球正面采样返 回，嫦娥六号开启世界首次月球背面样品采集任务。答案选D。","score":2},{"id":"zt-2024-c-35","isSubjective":false,"num":35,"category":"2024年成考政治真题卷 · 单选","stem":"2024年6月30日，我国建成开通的全球首个集“桥、岛、隧、水下互通”为一体的重大工程是（ ）。","options":["平陆运河","川藏铗路","深圳至中山跨江通道","引汉济渭工程"],"answer":2,"answerLetter":"C","explanation":"2024 年 6 月 30 日，深中通道建成通车，它是全球首个集“桥、岛、隧、水下互通”为一体的跨 海通道 。平陆运河是内河航运运河；川藏铁路重点在铁路建设；引汉济渭是调水工程，均不符合。","score":2},{"id":"zt-2024-s-36","isSubjective":true,"num":36,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"确立社会主义基本制度的重大意义是什么?","answer":"社会主义基本制度的确立，是中国共产党领导人民在百年奋斗中实现的一次具有里程碑意义的伟 大变革，它从根本上扭转了近代以来中国积贫积弱的发展命运，为当代中国的发展进步筑牢了制度根基，也 为中国特色社会主义道路的开辟与拓展提供了根本性前提。 （1）社会主义基本制度的确立，充分解放了生产关系中束缚生产力发展的桎梏，极大激发了工人阶级及广大 劳动人民的主人翁意识与创造活力。通过确立生产资料公有制为主体的经济制度，使劳动者与生产资料实现 直接结合，从根本上调动了全社会的生产积极性，有力推动了我国工业、农业等各领域生产力水平的跨越式 提升。 （2）社会主义基本制度的确立，彻底终结了中国历史上长期存在的剥削制度与阶级压迫，使广大劳动人民真 正实现了从“被统治阶级”到“国家主人”的历史转变。这一变革重构了中国的阶级关系，使工人阶级领导 的、以工农联盟为基础的人民民主专政政权拥有了坚实的阶级依托和经济支撑，极大巩固了人民当家作主的 政治地位。 （3）社会主义基本制度的确立，让占世界总人口四分之一的中国成功迈入社会主义行列，这是世界社会主义 运动在20世纪取得的又一辉煌成就。它打破了资本主义制度在全球范围内的扩张态势，重塑了当时的世界政 治经济格局，显著增强了国际社会主义阵营的力量，为维护世界和平、促进人类进步事业作出了重要贡献。 （4）社会主义基本制度的确立，是马克思列宁主义基本原理与中国具体国情相结合的光辉典范，是中国共产 党对社会主义革命理论的创造性运用与发展。这一实践不仅验证了马克思列宁主义关于社会主义革命理论的 科学性与真理性，更以中国独特的实践经验丰富了科学社会主义的理论体系，为其他发展中国家探索符合自 身国情的发展道路提供了有益借鉴。","explanation":"社会主义基本制度的确立，是中国共产党领导人民在百年奋斗中实现的一次具有里程碑意义的伟 大变革，它从根本上扭转了近代以来中国积贫积弱的发展命运，为当代中国的发展进步筑牢了制度根基，也 为中国特色社会主义道路的开辟与拓展提供了根本性前提。 （1）社会主义基本制度的确立，充分解放了生产关系中束缚生产力发展的桎梏，极大激发了工人阶级及广大 劳动人民的主人翁意识与创造活力。通过确立生产资料公有制为主体的经济制度，使劳动者与生产资料实现 直接结合，从根本上调动了全社会的生产积极性，有力推动了我国工业、农业等各领域生产力水平的跨越式 提升。 （2）社会主义基本制度的确立，彻底终结了中国历史上长期存在的剥削制度与阶级压迫，使广大劳动人民真 正实现了从“被统治阶级”到“国家主人”的历史转变。这一变革重构了中国的阶级关系，使工人阶级领导 的、以工农联盟为基础的人民民主专政政权拥有了坚实的阶级依托和经济支撑，极大巩固了人民当家作主的 政治地位。 （3）社会主义基本制度的确立，让占世界总人口四分之一的中国成功迈入社会主义行列，这是世界社会主义 运动在20世纪取得的又一辉煌成就。它打破了资本主义制度在全球范围内的扩张态势，重塑了当时的世界政 治经济格局，显著增强了国际社会主义阵营的力量，为维护世界和平、促进人类进步事业作出了重要贡献。 （4）社会主义基本制度的确立，是马克思列宁主义基本原理与中国具体国情相结合的光辉典范，是中国共产 党对社会主义革命理论的创造性运用与发展。这一实践不仅验证了马克思列宁主义关于社会主义革命理论的 科学性与真理性，更以中国独特的实践经验丰富了科学社会主义的理论体系，为其他发展中国家探索符合自 身国情的发展道路提供了有益借鉴。","score":10},{"id":"zt-2024-s-37","isSubjective":true,"num":37,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"简述邓小平理论的历史地位。","answer":"（1）邓小平理论是马克思列宁主义、毛泽东思想的继承和发展。 （2）邓小平理论是中国特色社会主义理论体系的开篇之作。 （3）邓小平理论是改革开放和社会主义现代化建设的科学指南。","explanation":"（1）邓小平理论是马克思列宁主义、毛泽东思想的继承和发展。 （2）邓小平理论是中国特色社会主义理论体系的开篇之作。 （3）邓小平理论是改革开放和社会主义现代化建设的科学指南。","score":10},{"id":"zt-2024-s-38","isSubjective":true,"num":38,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"“三个代表”重要思想的集中概括是什么?","answer":"“三个代表”重要思想的集中概括是： （1）我们党必须始终代表中国先进生产力的发展要求。 （2）我们党必须始终代表中国先进文化的前进方向。 （3）我们党必须始终代表中国最广大人民的根本利益。","explanation":"“三个代表”重要思想的集中概括是： （1）我们党必须始终代表中国先进生产力的发展要求。 （2）我们党必须始终代表中国先进文化的前进方向。 （3）我们党必须始终代表中国最广大人民的根本利益。","score":10},{"id":"zt-2024-s-39","isSubjective":true,"num":39,"category":"2024年成考政治真题卷 · 简答题 (10分)","stem":"中国式现代化的中国特色有哪些?","answer":"（1）中国式现代化是人口规模巨大的现代化。 （2）中国式现代化是全体人民共同富裕的现代化。 （3）中国式现代化是物质文明和精神文明相协调的现代化。 （4）中国式现代化是人与自然和谐共生的现代化。 （5）中国式现代化是走和平发展道路的现代化。","explanation":"（1）中国式现代化是人口规模巨大的现代化。 （2）中国式现代化是全体人民共同富裕的现代化。 （3）中国式现代化是物质文明和精神文明相协调的现代化。 （4）中国式现代化是人与自然和谐共生的现代化。 （5）中国式现代化是走和平发展道路的现代化。","score":10},{"id":"zt-2024-s-40","isSubjective":true,"num":40,"category":"2024年成考政治真题卷 · 论述题 (20分)","stem":"文化兴则国家兴，文化强则民族强。试从社会历史发展动力的角度论述文化在社会发展中的作用。","answer":"（1）文化是驱动社会历史前进的关键动力之一。文化凝结了人类在长期实践中形成的智慧结晶、 价值取向与人文情怀，是国家与民族赖以生存和发展的精神根基。文化的繁荣兴盛直接关系到国家的兴旺发 达和民族的强大复兴。在当今时代，文化的战略地位愈发凸显，不仅成为民族复兴进程中不可或缺的精神源 泉与社会发展的重要支撑，更是衡量综合国力竞争的核心要素之一，而满足人民群众日益增长的精神文化需 求、丰富其精神世界，也已成为社会发展的重要目标。 （2）文化对社会发展的作用具有多维度、深层次的影响。从作用性质来看，文化可分为先进文化与落后文化 ，先进文化能为社会发展注入正能量，推动社会进步；落后文化则可能成为社会发展的阻碍，制约社会前进 。从作用程度来看，文化的影响力强弱直接关系到社会发展的速度，积极向上的文化能加速社会发展进程 ，消极滞后的文化则会延缓社会发展步伐。因此，准确把握文化发展的正确方向，最大限度发挥先进文化的 引领和推动作用，对把握社会发展规律、引领社会发展进程具有决定性意义。 第一，文化为社会发展提供科学的思想导向。文化作为社会经济基础和政治制度在观念形态上的反映，具有 对现实社会的辩护与批判功能，进而深刻影响社会发展的总体走向。先进文化能够基于社会发展规律，明确 社会变革的目标与路径，为生产力的解放和发展、社会制度的完善和进步提供思想引领。中国特色社会主义 文化既传承了中华民族的精神基因，承载着中华民族的精神追求，又以马克思主义为科学指导，构筑起中国 人民在新时代砥砺奋进的思想灯塔和精神支柱。 第二，文化为社会发展注入强大的精神动能。民族的复兴是物质文明与精神文明的协同发展，仅有坚实的物 质基础不足以支撑民族的长久屹立，还需要强大的精神力量作为支撑。缺乏先进文化的引领，人民的精神世 界就会匮乏，民族的精神凝聚力就会削弱，国家发展就会失去内在动力。先进文化通过培育民族精神、弘扬 时代新风，能够激发全体人民的创造热情和奋斗精神，为社会发展提供不竭的精神动力。 第三，文化为社会发展凝聚坚实的社会共识。文化的核心是价值观念，占主导地位的主流价值观能够通过引 领社会思潮、规范道德行为，将不同群体的思想和行动凝聚起来，形成共同的价值追求和社会认同。文化作 为连接民族情感的精神纽带，能够增强民族归属感和向心力，促进全社会形成心往一处想、劲往一处使的强 大合力，为社会发展提供稳定的精神支撑和团结基础。","explanation":"（1）文化是驱动社会历史前进的关键动力之一。文化凝结了人类在长期实践中形成的智慧结晶、 价值取向与人文情怀，是国家与民族赖以生存和发展的精神根基。文化的繁荣兴盛直接关系到国家的兴旺发 达和民族的强大复兴。在当今时代，文化的战略地位愈发凸显，不仅成为民族复兴进程中不可或缺的精神源 泉与社会发展的重要支撑，更是衡量综合国力竞争的核心要素之一，而满足人民群众日益增长的精神文化需 求、丰富其精神世界，也已成为社会发展的重要目标。 （2）文化对社会发展的作用具有多维度、深层次的影响。从作用性质来看，文化可分为先进文化与落后文化 ，先进文化能为社会发展注入正能量，推动社会进步；落后文化则可能成为社会发展的阻碍，制约社会前进 。从作用程度来看，文化的影响力强弱直接关系到社会发展的速度，积极向上的文化能加速社会发展进程 ，消极滞后的文化则会延缓社会发展步伐。因此，准确把握文化发展的正确方向，最大限度发挥先进文化的 引领和推动作用，对把握社会发展规律、引领社会发展进程具有决定性意义。 第一，文化为社会发展提供科学的思想导向。文化作为社会经济基础和政治制度在观念形态上的反映，具有 对现实社会的辩护与批判功能，进而深刻影响社会发展的总体走向。先进文化能够基于社会发展规律，明确 社会变革的目标与路径，为生产力的解放和发展、社会制度的完善和进步提供思想引领。中国特色社会主义 文化既传承了中华民族的精神基因，承载着中华民族的精神追求，又以马克思主义为科学指导，构筑起中国 人民在新时代砥砺奋进的思想灯塔和精神支柱。 第二，文化为社会发展注入强大的精神动能。民族的复兴是物质文明与精神文明的协同发展，仅有坚实的物 质基础不足以支撑民族的长久屹立，还需要强大的精神力量作为支撑。缺乏先进文化的引领，人民的精神世 界就会匮乏，民族的精神凝聚力就会削弱，国家发展就会失去内在动力。先进文化通过培育民族精神、弘扬 时代新风，能够激发全体人民的创造热情和奋斗精神，为社会发展提供不竭的精神动力。 第三，文化为社会发展凝聚坚实的社会共识。文化的核心是价值观念，占主导地位的主流价值观能够通过引 领社会思潮、规范道德行为，将不同群体的思想和行动凝聚起来，形成共同的价值追求和社会认同。文化作 为连接民族情感的精神纽带，能够增强民族归属感和向心力，促进全社会形成心往一处想、劲往一处使的强 大合力，为社会发展提供稳定的精神支撑和团结基础。","score":20},{"id":"zt-2024-s-41","isSubjective":true,"num":41,"category":"2024年成考政治真题卷 · 论述题 (20分)","stem":"党的十八大以来，以习近平同志为核心的党中央积极回应人民对民主政治的新要求新期待，提出全过程人 民民主重大理念。全过程人民民主是新时代我国民主政治领域具有重大创新意义的标志性成果。如何理解全 过程人民民主是社会主义民主政治的本质属性？","answer":"全过程人民民主是社会主义民主政治的本质属性，可以从以下几个方面理解： （1）全过程人民民主是社会主义民主政治的伟大创造。全过程人民民主是中国共产党团结带领人民追求民主 、发展民主、实现民主的伟大创造，是党不断推进中国民主理论创新、制度创新、实践创新的经验结晶。它 植根于我国社会主义民主的长期实践，是马克思主义基本原理同中国具体实际相结合的产物，实现了过程民 主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志的统一。 （2）全过程人民民主是全链条、全方位、全覆盖的民主。全过程人民民主既有完整的制度程序，也有完整的 参与实践，将民主选举、民主协商、民主决策、民主管理、民主监督贯通起来，覆盖经济、政治、文化、社 会、生态文明等各个领域，贯穿国家发展大事、社会治理难事、百姓日常琐事，在时间上具有连续性，在内 容上具有整体性，在运行上具有协同性，在人民参与上具有广泛性和持续性。 （3）全过程人民民主是最广泛、最真实、最管用的民主。全过程人民民主坚持以人民为中心，能确保人民充 分享有各方面权利，人民依法通过各种途径和形式管理国家事务、管理经济和文化事业、管理社会事务。它 有效促进了国家治理高效和社会和谐稳定，维护和保障了人民群众的根本利益，既强调把民主价值和理念转 化为科学有效的制度安排，又转化为具体现实的民主实践，是经得起实践检验、得到人民认可的民主。","explanation":"全过程人民民主是社会主义民主政治的本质属性，可以从以下几个方面理解： （1）全过程人民民主是社会主义民主政治的伟大创造。全过程人民民主是中国共产党团结带领人民追求民主 、发展民主、实现民主的伟大创造，是党不断推进中国民主理论创新、制度创新、实践创新的经验结晶。它 植根于我国社会主义民主的长期实践，是马克思主义基本原理同中国具体实际相结合的产物，实现了过程民 主和成果民主、程序民主和实质民主、直接民主和间接民主、人民民主和国家意志的统一。 （2）全过程人民民主是全链条、全方位、全覆盖的民主。全过程人民民主既有完整的制度程序，也有完整的 参与实践，将民主选举、民主协商、民主决策、民主管理、民主监督贯通起来，覆盖经济、政治、文化、社 会、生态文明等各个领域，贯穿国家发展大事、社会治理难事、百姓日常琐事，在时间上具有连续性，在内 容上具有整体性，在运行上具有协同性，在人民参与上具有广泛性和持续性。 （3）全过程人民民主是最广泛、最真实、最管用的民主。全过程人民民主坚持以人民为中心，能确保人民充 分享有各方面权利，人民依法通过各种途径和形式管理国家事务、管理经济和文化事业、管理社会事务。它 有效促进了国家治理高效和社会和谐稳定，维护和保障了人民群众的根本利益，既强调把民主价值和理念转 化为科学有效的制度安排，又转化为具体现实的民主实践，是经得起实践检验、得到人民认可的民主。","score":20}]},{"id":"zt-2023","title":"2023年成考政治真题卷","type":"past","year":2023,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2023-c-1","isSubjective":false,"num":1,"category":"2023年成考政治真题卷 · 单选","stem":"下列选项中体现事物因果联系的是（ ）","options":["有无相生","过犹不及","冬去春来","摩擦生热"],"answer":3,"answerLetter":"D","explanation":"因果联系是指事物之间一种先行后续，引起和被引起的关系。 A选项“有无相生”体现的是矛盾双 方相互依存、相互转化的关系，并非因果联系。 B选项“过犹不及”强调的是要把握适度原则，和因果联系 无关。 C选项“冬去春来”是自然现象的循环更替，不存在引起和被引起的关系，不是因果联系。 D选项 “摩擦”会引起“生热”，“摩擦”是原因，“生热”是结果，体现了因果联系。","score":2},{"id":"zt-2023-c-2","isSubjective":false,"num":2,"category":"2023年成考政治真题卷 · 单选","stem":"否定之否定规律揭示了事物的发展是（ ）","options":["绝对性与相对性的统一","有限性与无限性的统一","前进性与曲折性的统一","稳定性与变动性的统一"],"answer":2,"answerLetter":"C","explanation":"否定之否定规律表明，事物发展的总方向、总趋势是前进上升的，具体道路是曲折的，即事物发展 是前进性与曲折性的统一。","score":2},{"id":"zt-2023-c-3","isSubjective":false,"num":3,"category":"2023年成考政治真题卷 · 单选","stem":"观念上层建筑指的是（ ）","options":["意识形态","政治制度","法律制度","政治组织"],"answer":0,"answerLetter":"A","explanation":"观念上层建筑主要指社会的意识形态，它是对一定社会经济基础的反映并为其服务。而政治制度、 法律制度、政治组织属于政治上层建筑。","score":2},{"id":"zt-2023-c-4","isSubjective":false,"num":4,"category":"2023年成考政治真题卷 · 单选","stem":"马克思主义认为，社会革命根源于（ ）","options":["人口数量和结构的变化","思想观念斗争的尖锐化","自然资源和环境的变化","社会基本矛盾的尖锐化"],"answer":3,"answerLetter":"D","explanation":"社会革命是推动社会发展的重要动力，其根源在于生产力与生产关系、经济基础与上层建筑这一社 会基本矛盾的尖锐化。当旧的生产关系严重阻碍生产力发展，旧的上层建筑维护旧的生产关系，就会引发社 会革命。而人口数量和结构变化、思想观念斗争尖锐化、自然资源和环境变化都不是社会革命的根源。答案 ：D","score":2},{"id":"zt-2023-c-5","isSubjective":false,"num":5,"category":"2023年成考政治真题卷 · 单选","stem":"习近平指出，人民既是历史的创造者、也是历史的见证者，既是历史的“剧中人”、也是历史的“剧作者 ”。这一论断的理论依据是（ ）","options":["历史宿命论","历史决定论","英雄史观","群众史观"],"answer":3,"answerLetter":"D","explanation":"题干强调人民在历史中的重要创造作用，历史宿命论认为历史发展由不可抗拒的命运决定，否定人 的主观能动性，A 不符；历史决定论强调社会历史发展有其客观规律，但题干重点突出人民作用，B 不准确 ；英雄史观夸大英雄人物在历史中的作用，忽视人民，C 错误；群众史观强调人民群众是历史的创造者，符 合题干表述。","score":2},{"id":"zt-2023-c-6","isSubjective":false,"num":6,"category":"2023年成考政治真题卷 · 单选","stem":"毛泽东思想开始萌芽的标志是（ ）","options":["人民民主专政理论的形成","关于新民主主义革命基本思想的提出","农村包围城市、武装夺取政权道路的开辟","马克思主义中国化第一次历史性飞跃的实现"],"answer":1,"answerLetter":"B","explanation":"毛泽东思想开始萌芽于中国共产党创建和大革命时期。关于新民主主义革命基本思想的提出，标志 着毛泽东思想开始萌芽。A选项人民民主专政理论形成于解放战争时期，是毛泽东思想发展的重要成果；C选 项农村包围城市、武装夺取政权道路开辟是毛泽东思想初步形成的标志；D选项马克思主义中国化第一次历史 性飞跃的实现以毛泽东思想的形成为标志。","score":2},{"id":"zt-2023-c-7","isSubjective":false,"num":7,"category":"2023年成考政治真题卷 · 单选","stem":"新民主主义革命的主力军是（ ）","options":["无产阶级","小资产阶级","农民","知识分子"],"answer":2,"answerLetter":"C","explanation":"农民是中国革命的主力军，因为中国是农业大国，农民占人口绝大多数，且深受压迫，有强烈革命 要求和积极性，无产阶级最可靠的同盟军也是农民。","score":2},{"id":"zt-2023-c-8","isSubjective":false,"num":8,"category":"2023年成考政治真题卷 · 单选","stem":"过渡时期总路线中，“过渡时期”是指（ ）","options":["从资本主义社会向社会主义社会过渡","从封建社会向半殖民地半封建社会演变","从半殖民地半封建社会向资本主义社会转变","从中华人民共和国成立到社会主义改造基本完成"],"answer":3,"answerLetter":"D","explanation":"过渡时期总路线中的“过渡时期”，是中国从新民主主义社会向社会主义社会过渡的时期，时间跨 度是从中华人民共和国成立到社会主义改造基本完成。A选项说法不准确，中国不是从资本主义社会过渡 ；B选项封建社会向半殖民地半封建社会演变是鸦片战争后的情况；C选项不符合史实。","score":2},{"id":"zt-2023-c-9","isSubjective":false,"num":9,"category":"2023年成考政治真题卷 · 单选","stem":"在社会主义社会两类社会矛盾中，工人阶级同民族资产阶级的矛盾是（ ）","options":["敌我矛盾","人民内部矛盾","基本矛盾","社会主要矛盾"],"answer":1,"answerLetter":"B","explanation":"在社会主义社会，民族资产阶级具有两面性，工人阶级同民族资产阶级的矛盾属于人民内部矛盾。 A选项敌我矛盾不符，C选项基本矛盾是生产力与生产关系等，D选项当时社会主要矛盾不是这两者矛盾。答案 ：B","score":2},{"id":"zt-2023-c-10","isSubjective":false,"num":10,"category":"2023年成考政治真题卷 · 单选","stem":"毛泽东中国工业化道路思想强调，实现四个现代化关键在于（ ）","options":["农业现代化","工业现代化","国防现代化","科学技术现代化"],"answer":3,"answerLetter":"D","explanation":"在毛泽东关于中国工业化道路思想及实现四个现代化进程中，科学技术现代化是关键。因为科学技 术能推动农业、工业、国防等各领域发展，是实现其他现代化的重要支撑和驱动力。","score":2},{"id":"zt-2023-c-11","isSubjective":false,"num":11,"category":"2023年成考政治真题卷 · 单选","stem":"改革开放以来，我们党和国家生存发展的政治基石是（ ）","options":["四项基本原则","以德治国","国际政治秩序","依宪治国"],"answer":0,"answerLetter":"A","explanation":"四项基本原则是立国之本，是我们党和国家生存发展的政治基石。以德治国、依宪治国主要侧重于 治国理政的方式，国际政治秩序并非党和国家生存发展的政治基石。答案：A 。","score":2},{"id":"zt-2023-c-12","isSubjective":false,"num":12,"category":"2023年成考政治真题卷 · 单选","stem":"邓小平指出，中国解决所有问题的关键是（ ）","options":["要靠照搬马克思主义理论","要靠自己的发展","要靠模仿周边国家的经验","要靠别国的支持"],"answer":1,"answerLetter":"B","explanation":"中国不能照搬理论、模仿他国经验，也不能依赖别国支持，发展才是硬道理，中国解决所有问题关 键要靠自身发展，通过自身发展增强综合国力等，来应对各种挑战和解决各类问题。","score":2},{"id":"zt-2023-c-13","isSubjective":false,"num":13,"category":"2023年成考政治真题卷 · 单选","stem":"“三个代表”重要思想强调，我们党进行的一切奋斗，归根到底都是为了（ ）","options":["社会生产力的快速发展","社会主义和谐社会的建成","最广大人民的根本利益","社会主义市场经济的完善"],"answer":2,"answerLetter":"C","explanation":"“三个代表”重要思想始终强调以人民为中心，党一切奋斗的根本目的就是维护好、实现好、发展 好最广大人民的根本利益。A选项社会生产力发展是手段之一；B选项社会主义和谐社会提出晚于“三个代表 ”重要思想；D选项社会主义市场经济完善也是发展过程中的举措，并非最终目的。","score":2},{"id":"zt-2023-c-14","isSubjective":false,"num":14,"category":"2023年成考政治真题卷 · 单选","stem":"坚持中国特色社会主义政治发展道路，最根本的是（ ）","options":["坚持改革、发展、稳定的辩证统一","坚持生产发展、生活富裕、生态良好的有机统一","坚持党的使命、国家的前途、人民的福祉的辩证统一","坚持党的领导、人民当家作主、依法治国的有机统"],"answer":3,"answerLetter":"D","explanation":"中国特色社会主义政治发展道路，强调要把坚持党的领导、人民当家作主、依法治国有机统一起来 ，这是最根本的。A选项强调的是改革发展稳定关系，属于总体发展层面；B选项围绕生产、生活、生态，是 生态文明相关方面；C选项表述并非政治发展道路最根本内容。","score":2},{"id":"zt-2023-c-15","isSubjective":false,"num":15,"category":"2023年成考政治真题卷 · 单选","stem":"社会主义核心价值观中，富强、民主、文明、和谐体现的是（ ）","options":["国家层面的价值要求","社会层面的价值要求","公民层面的价值要求","组织层面的价值要求"],"answer":0,"answerLetter":"A","explanation":"社会主义核心价值观包括国家、社会、公民三个层面。富强、民主、文明、和谐是国家层面的价值 目标，自由、平等、公正、法治是社会层面的价值取向，爱国、敬业、诚信、友善是公民个人层面的价值准 则。所以富强、民主、文明、和谐体现的是国家层面的价值要求。","score":2},{"id":"zt-2023-c-16","isSubjective":false,"num":16,"category":"2023年成考政治真题卷 · 单选","stem":"党的十八大以来，我们党的全部理论和实践探索都是（ ）","options":["围绕推动高质量发展来展开、深化和拓展的","围绕全面建成小康社会来展开、深化和拓展的","围绕坚持和发展中国特色社会主义来展开、深化和拓展的","围绕传承和弘扬中华优秀传统文化来展开、深化和拓展的"],"answer":2,"answerLetter":"C","explanation":"党的十八大以来，我们党的全部理论和实践探索都是围绕坚持和发展中国特色社会主义这个主题来 展开、深化和拓展的 。中国特色社会主义是改革开放以来党的全部理论和实践的主题。","score":2},{"id":"zt-2023-c-17","isSubjective":false,"num":17,"category":"2023年成考政治真题卷 · 单选","stem":"中国特色社会主义事业总体布局和战略布局分别是（ ）","options":["“两个转变”和“一体两翼”","“五位一体”和“四个全面”","“八个明确”和“四面八方”","“一个中心”和“五湖四海”"],"answer":1,"answerLetter":"B","explanation":"中国特色社会主义事业总体布局是“五位一体”，即经济建设、政治建设、文化建设、社会建设、 生态文明建设五位一体；战略布局是“四个全面”，即全面建设社会主义现代化国家、全面深化改革、全面 依法治国、全面从严治党 。答案选B。","score":2},{"id":"zt-2023-c-18","isSubjective":false,"num":18,"category":"2023年成考政治真题卷 · 单选","stem":"习近平新时代中国特色社会主义思想的根本立场是（ ）","options":["人民立场","阶级立场","历史自觉","求真务实"],"answer":0,"answerLetter":"A","explanation":"人民立场是中国共产党的根本政治立场，习近平新时代中国特色社会主义思想始终强调以人民为中 心，把人民对美好生活的向往作为奋斗目标，其根本立场就是人民立场。","score":2},{"id":"zt-2023-c-19","isSubjective":false,"num":19,"category":"2023年成考政治真题卷 · 单选","stem":"习近平指出：“实现中国梦必须走中国道路、弘扬中国精神、凝聚中国力量。”中国力量指的是（ ）","options":["科技创新的力量","文化创新的力量","全国各族人民大团结的力量","全世界人民大团结的力量"],"answer":2,"answerLetter":"C","explanation":"中国力量指全国各族人民大团结的力量，这是实现中国梦的重要支撑。ABD选项表述不符。","score":2},{"id":"zt-2023-c-20","isSubjective":false,"num":20,"category":"2023年成考政治真题卷 · 单选","stem":"全面建设社会主义现代化国家的进程分两个阶段来安排，其中第二个阶段的目标是到本世纪中叶（ ）","options":["实现总体小康","消除绝对贫困","人均国内生产总值达到中等发达国家的水平","把我国建成富强民主文明和谐美丽的社会主义现代化强国"],"answer":3,"answerLetter":"D","explanation":"全面建设社会主义现代化国家进程分两个阶段，第二个阶段是从2035年到本世纪中叶，目标是建成 富强民主文明和谐美丽的社会主义现代化强国。A选项实现总体小康在20世纪末已达成；B选项消除绝对贫困 在2020年完成；C选项人均国内生产总值达到中等发达国家水平是第一阶段2035年要实现的目标之一。答案 ：D","score":2},{"id":"zt-2023-c-21","isSubjective":false,"num":21,"category":"2023年成考政治真题卷 · 单选","stem":"在新发展理念中，注重解决发展不平衡问题的是（ ）","options":["创新发展","协调发展","绿色发展","共享发展"],"answer":1,"answerLetter":"B","explanation":"创新发展注重解决发展动力问题；协调发展注重解决发展不平衡问题；绿色发展注重解决人与自然 和谐共生问题；共享发展注重解决社会公平正义问题。所以注重解决发展不平衡问题的是协调发展。","score":2},{"id":"zt-2023-c-22","isSubjective":false,"num":22,"category":"2023年成考政治真题卷 · 单选","stem":"构建新发展格局明确了我国经济现代化的路径选择。新发展格局指的是（ ）","options":["坚持“两个毫不动摇”","市场和资源“两头在外”的发展格局","以国内大循环为主体、国内国际双循环相互促进","发挥市场在资源配置中的决定性作用和更好发挥政府作用"],"answer":2,"answerLetter":"C","explanation":"新发展格局是指以国内大循环为主体、国内国际双循环相互促进的发展格局，这是我国应对国内外 形势变化作出的重要战略部署。A选项“两个毫不动摇”是关于公有制经济和非公有制经济的政策；B选项市 场和资源“两头在外”是过去的一种发展模式，不符合新发展格局要求；D选项强调的是市场与政府在资源配 置中的作用，与新发展格局概念不同。","score":2},{"id":"zt-2023-c-23","isSubjective":false,"num":23,"category":"2023年成考政治真题卷 · 单选","stem":"新时代推进全面依法治国的总抓手是（ ）","options":["坚持以人民为中心","建设中国特色社会主义法治体系","坚持统筹推进国内法治和涉外法治","坚持依法治国、依法执政、依法行政共同推进"],"answer":1,"answerLetter":"B","explanation":"建设中国特色社会主义法治体系是全面依法治国的总抓手，它涵盖了法治建设的各个方面，其他选 项虽也是依法治国重要内容，但并非总抓手。","score":2},{"id":"zt-2023-c-24","isSubjective":false,"num":24,"category":"2023年成考政治真题卷 · 单选","stem":"总体国家安全观明确，国家安全的宗旨和根本分别是（ ）","options":["人民安全和政治安全","科技安全和网络安全","经济安全和生态安全","资源安全和太空安全"],"answer":0,"answerLetter":"A","explanation":"总体国家安全观以人民安全为宗旨，以政治安全为根本。所以应选与这两项对应的选项。","score":2},{"id":"zt-2023-c-25","isSubjective":false,"num":25,"category":"2023年成考政治真题卷 · 单选","stem":"习近平强军思想中，反映军队的根本职能和军队建设的根本指向的是（ ）","options":["能打胜仗","作风优良","听党指挥","军民融合"],"answer":0,"answerLetter":"A","explanation":"军队的根本职能是打仗，军队建设的根本指向是能打胜仗，这是核心要求。作风优良主要关系军队 形象等；听党指挥是灵魂，确保军队性质；军民融合是发展途径等。","score":2},{"id":"zt-2023-c-26","isSubjective":false,"num":26,"category":"2023年成考政治真题卷 · 单选","stem":"2022年8月28日开工建设的西部陆海新通道骨干工程——平陆运河位于（ ）","options":["四川","云南","贵州","广西"],"answer":3,"answerLetter":"D","explanation":"平陆运河是广西内河水运规划中重要的一条出海通道，连接西江和北部湾，在广西建设。答案选D。","score":2},{"id":"zt-2023-c-27","isSubjective":false,"num":27,"category":"2023年成考政治真题卷 · 单选","stem":"党的二十大要求，全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必（ ）","options":["敢于斗争、善于斗争","增强自信、继续前进","自信自强、守正创新","踔厉奋发、勇毅前行"],"answer":0,"answerLetter":"A","explanation":"党的二十大报告明确提出全党同志务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于 斗争、善于斗争。这“三个务必”是基于党所处历史方位、面临形势任务、党情发展变化作出的重大论断。 答案：A。","score":2},{"id":"zt-2023-c-28","isSubjective":false,"num":28,"category":"2023年成考政治真题卷 · 单选","stem":"2023年3月26日，与我国建立外交关系的国家是（ ）","options":["哥伦比亚","洪都拉斯","南非","古巴"],"answer":1,"answerLetter":"B","explanation":"2023 年 3 月 26 日，中国同洪都拉斯签署《中华人民共和国和洪都拉斯共和国关于建立外交关系 的联合公报》，宣布自公报签署之日起，两国相互承认并建立大使级外交关系。答案选B。","score":2},{"id":"zt-2023-c-29","isSubjective":false,"num":29,"category":"2023年成考政治真题卷 · 单选","stem":"2023年5月19日，首届中国一中亚峰会发表《中国一中亚峰会西安宣言》，与会六国决心携手构建（ ）","options":["中国—中亚丝路开发银行","中国—中亚自由贸易区","中国—中亚经济合作组织","中国—中亚命运共同体"],"answer":3,"answerLetter":"D","explanation":"首届中国 - 中亚峰会旨在推动中国与中亚地区更紧密合作，构建命运共同体是这种合作的长远目标 和愿景，符合峰会主旨及双方合作方向。而A选项中国 - 中亚丝路开发银行并非此次峰会提出；B选项中国 - 中亚自由贸易区当时未提此构建目标；C选项中国 - 中亚经济合作组织也非峰会相关内容。答案：D.中国 —中亚命运共同体","score":2},{"id":"zt-2023-c-30","isSubjective":false,"num":30,"category":"2023年成考政治真题卷 · 单选","stem":"2023年6月26日至28日，十四届全国人大常委会第三次会议在北京召开。会议决定将每年8月15日设立为 （ ）","options":["全国土地日","国家宪法日","全国生态日","全民健身日"],"answer":2,"answerLetter":"C","explanation":"2023年6月，十四届全国人大常委会第三次会议决定将每年8月15日设立为全国生态日 。全国土地日 是6月25日，国家宪法日是12月4日，全民健身日是8月8日。","score":2},{"id":"zt-2023-c-31","isSubjective":false,"num":31,"category":"2023年成考政治真题卷 · 单选","stem":"思维和存在的关系问题是（ ）","options":["全部哲学的基本问题","历史观的基本问题","思想路线的核心问题","辩证法的核心问题"],"answer":0,"answerLetter":"A","explanation":"思维和存在的关系问题贯穿哲学发展始终，对这一问题的不同回答，划分出唯物主义和唯心主义 ，是全部哲学的基本问题。历史观基本问题是社会存在与社会意识关系问题；思想路线核心问题通常指实事 求是；辩证法核心问题是对立统一规律。","score":2},{"id":"zt-2023-c-32","isSubjective":false,"num":32,"category":"2023年成考政治真题卷 · 单选","stem":"马克思主义的产生具有深刻的思想渊源。作为马克思主义哲学直接理论来源的是（ ）","options":["古希腊罗马哲学","近代英国哲学","近代法国哲学","德国古典哲学"],"answer":3,"answerLetter":"D","explanation":"马克思主义哲学的直接理论来源是德国古典哲学，其中主要是黑格尔的辩证法和费尔巴哈的唯物主 义。其他选项虽对哲学发展有影响，但并非马克思主义哲学直接理论来源。","score":2},{"id":"zt-2023-c-33","isSubjective":false,"num":33,"category":"2023年成考政治真题卷 · 单选","stem":"“笑一笑十年少，愁一愁白了头”表明意识具有（ ）","options":["目的性","指导实践改造客观世界的作用","创造性","调控人的行为和生理活动的作用"],"answer":3,"answerLetter":"D","explanation":"“笑一笑十年少，愁一愁白了头”描述的是人的情绪（意识的一种表现）对人自身生理状态的影响 ，体现了意识对人的行为和生理活动有调控作用。","score":2},{"id":"zt-2023-c-34","isSubjective":false,"num":34,"category":"2023年成考政治真题卷 · 单选","stem":"人类社会是物质存在的一种特定形态，人的意识统一于物质，这是（ ）","options":["主观唯心主义的观点","辩证唯物主义的观点","客观唯心主义的观点","庸俗唯物主义的观点"],"answer":1,"answerLetter":"B","explanation":"辩证唯物主义认为世界是物质的，物质决定意识，意识是物质的反映，人的意识统一于物质，这符 合辩证唯物主义对物质和意识关系的阐述。 主观唯心主义把人的主观精神当作世界的本原，A选项不符合题 意。 客观唯心主义把客观精神（如上帝、理念等）看作世界的本原，C选项不符合题意。 庸俗唯物主义把意 识直接归结为物质，忽略了意识的主观性等特性，D选项不符合题意。","score":2},{"id":"zt-2023-c-35","isSubjective":false,"num":35,"category":"2023年成考政治真题卷 · 单选","stem":"对立统一规律提供的认识世界和改造世界的根本方法是（ ）","options":["阶级分析方法","历史分析方法","矛盾分析方法","逻辑分析方法"],"answer":2,"answerLetter":"C","explanation":"对立统一规律揭示了事物普遍联系的根本内容和永恒发展的内在动力，矛盾是对立统一的体现，所 以对立统一规律提供的根本方法就是矛盾分析方法 。","score":2},{"id":"zt-2023-s-36","isSubjective":true,"num":36,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"简述社会存在和社会意识的辩证关系。","answer":"(1)社会存在决定社会意识，社会意识对社会存在具有反作用。(3分) (2)先进的社会意识对社会发展起积极的推动作用，落后的社会意识对社会发展起阻碍作用。(3分) (3)社会意识具有相对独立性。(4分)","explanation":"(1)社会存在决定社会意识，社会意识对社会存在具有反作用。(3分) (2)先进的社会意识对社会发展起积极的推动作用，落后的社会意识对社会发展起阻碍作用。(3分) (3)社会意识具有相对独立性。(4分)","score":10},{"id":"zt-2023-s-37","isSubjective":true,"num":37,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"简述近代中国社会的主要矛盾和历史任务。","answer":"(1)近代中国社会的主要矛盾是帝国主义和中华民族的矛盾，封建主义和人民大众的矛盾。(5分) (2)近代中国社会的历史任务是争取民族独立、人民解放和实现国家富强、人民幸福。(5分)","explanation":"(1)近代中国社会的主要矛盾是帝国主义和中华民族的矛盾，封建主义和人民大众的矛盾。(5分) (2)近代中国社会的历史任务是争取民族独立、人民解放和实现国家富强、人民幸福。(5分)","score":10},{"id":"zt-2023-s-38","isSubjective":true,"num":38,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"简述科学发展观的科学内涵。","answer":"(1)科学发展观的第一要义是发展。(3分) (2)科学发展观的核心是以人为本。(3分) (3)科学发展观的基本要求是全面协调可持续。(2分) (4)科学发展观的根本方法是统筹兼顾。(2分)","explanation":"(1)科学发展观的第一要义是发展。(3分) (2)科学发展观的核心是以人为本。(3分) (3)科学发展观的基本要求是全面协调可持续。(2分) (4)科学发展观的根本方法是统筹兼顾。(2分)","score":10},{"id":"zt-2023-s-39","isSubjective":true,"num":39,"category":"2023年成考政治真题卷 · 简答题 (10分)","stem":"为什么说党的领导是中国特色社会主义最本质的特征？","answer":"(1)这是由中国特色社会主义迈向新征程的实践逻辑所决定的。(4分) (2)这是由科学社会主义的理论逻辑所决定的。(3分) (3)这是由中国特色社会主义产生与发展的历史逻辑所决定的。(3分)","explanation":"(1)这是由中国特色社会主义迈向新征程的实践逻辑所决定的。(4分) (2)这是由科学社会主义的理论逻辑所决定的。(3分) (3)这是由中国特色社会主义产生与发展的历史逻辑所决定的。(3分)","score":10},{"id":"zt-2023-s-40","isSubjective":true,"num":40,"category":"2023年成考政治真题卷 · 论述题 (20分)","stem":"试述感性认识和理性认识的辩证关系，并说明割裂二者的统一在实际工作中会导致的错误。","answer":"感性认识和理性认识之间是对立统一的辩证关系。(3分) (1)感性认识有待于发展和深化为理性认识。(4分) (2)理性认识依赖于感性认识。(4分) (3)感性认识和理性认识相互渗透、相互包含。(4分) 割裂感性认识和理性认识的统一，在实际工作中会导致经验主义或教条主义的错误。经验主义夸大个别的、 局部的经验的作用，否认科学理论的指导意义；教条主义夸大理论和书本知识的作用，轻视实际经验，把理 论当成教条，到处生搬硬套。(5分)","explanation":"感性认识和理性认识之间是对立统一的辩证关系。(3分) (1)感性认识有待于发展和深化为理性认识。(4分) (2)理性认识依赖于感性认识。(4分) (3)感性认识和理性认识相互渗透、相互包含。(4分) 割裂感性认识和理性认识的统一，在实际工作中会导致经验主义或教条主义的错误。经验主义夸大个别的、 局部的经验的作用，否认科学理论的指导意义；教条主义夸大理论和书本知识的作用，轻视实际经验，把理 论当成教条，到处生搬硬套。(5分)","score":20},{"id":"zt-2023-s-41","isSubjective":true,"num":41,"category":"2023年成考政治真题卷 · 论述题 (20分)","stem":"党的十八大以来，以习近平同志为核心的党中央牢牢把握中国和世界发展大势，深刻思考人类前途命运 ，积极推进重大外交理论和实践创新，形成了习近平外交思想，指引外交工作取得全方位、开创性历史成就 。试述新时代中国独立自主的和平外交政策的主要内涵。","answer":"(1)把国家主权和安全放在第一位，坚定地维护我国的国家利益，反对任何国家损害我国的独立、主 权、安全和尊严。(4分) (2)一切从我国人民和世界人民的根本利益出发，根据事情本身的是非曲直决定自己的政治立场和政策，不屈 从于任何外来压力。(4分) (3)坚持各国的事务应由各国政府和人民决定，世界上的事情应由各国政府和人民平等协商，反对霸权主义和 强权政治。(4分) (4)坚持在和平共处五项原则基础上同世界各国建立和发展友好关系。(4分) (5)不结盟、不搞军事集团，不参加军备竞赛，不进行军事扩张，不谋求霸权。(4分)","explanation":"(1)把国家主权和安全放在第一位，坚定地维护我国的国家利益，反对任何国家损害我国的独立、主 权、安全和尊严。(4分) (2)一切从我国人民和世界人民的根本利益出发，根据事情本身的是非曲直决定自己的政治立场和政策，不屈 从于任何外来压力。(4分) (3)坚持各国的事务应由各国政府和人民决定，世界上的事情应由各国政府和人民平等协商，反对霸权主义和 强权政治。(4分) (4)坚持在和平共处五项原则基础上同世界各国建立和发展友好关系。(4分) (5)不结盟、不搞军事集团，不参加军备竞赛，不进行军事扩张，不谋求霸权。(4分)","score":20}]},{"id":"zt-2022","title":"2022年成考政治真题卷","type":"past","year":2022,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"zt-2022-c-1","isSubjective":false,"num":1,"category":"2022年成考政治真题卷 · 单选","stem":"马克思主义的物质范畴从自然与社会存在中抽象出的共同特征是（ ）。","options":["客观实在性","可知性","时空限定性","运动性"],"answer":0,"answerLetter":"A","explanation":"马克思主义认为物质的唯一特性是客观实在性，它是从万事万物即自然与社会存在中抽象出的共同 本质特征。可知性强调能被认识；时空限定性并非共同特征；运动性是物质的根本属性。","score":2},{"id":"zt-2022-c-2","isSubjective":false,"num":2,"category":"2022年成考政治真题卷 · 单选","stem":"世界的物质统一性是（ ）。","options":["阶段性的统一","条件性的统一","多样性的统一","历史性的统一"],"answer":2,"answerLetter":"C","explanation":"世界的物质统一性原理表明，世界是在物质基础上的统一，这种统一不是单一的、无差别的，而是 包含着无限多样的物质形态和物质运动形式的统一。物质世界在客观实在性的基础上，呈现出丰富的多样性 。而阶段性、条件性、历史性的统一表述均未抓住世界物质统一性本质特征。","score":2},{"id":"zt-2022-c-3","isSubjective":false,"num":3,"category":"2022年成考政治真题卷 · 单选","stem":"从本质上讲，唯物辩证法是（ ）。","options":["客观实在性","可知性","时空限定性","运动性"],"answer":0,"answerLetter":"A","explanation":"【标准答案：A】","score":2},{"id":"zt-2022-c-4","isSubjective":false,"num":4,"category":"2022年成考政治真题卷 · 单选","stem":"辩证否定的实质（ ）。","options":["全盘否定","自我否定","回复","扬弃"],"answer":3,"answerLetter":"D","explanation":"辩证否定既不是简单地肯定一切，也不是简单地否定一切，而是既肯定又否定，既克服又保留，其 实质是“扬弃”。“扬弃”就是新事物对旧事物既批判又继承、既克服其消极因素又保留其积极因素。A选项 “全盘否定”错误，不符合辩证否定观；B选项“自我否定”没有突出辩证否定实质的核心内涵；C选项“回 复”与辩证否定实质无关。","score":2},{"id":"zt-2022-c-5","isSubjective":false,"num":5,"category":"2022年成考政治真题卷 · 单选","stem":"实践是人类能动地改造世界的社会性的物质活动，其基本特征是客观实在性，自觉能动性及（ ）。","options":["社会历史性","主观创造性","主体多元性","目标单一性"],"answer":0,"answerLetter":"A","explanation":"实践的基本特征有客观实在性（物质性）、自觉能动性（目的性）、社会历史性（受历史条件制约 ） ，这是实践的三个基本特征。B选项主观创造性表述不准确；C主体多元性、D目标单一性不属于实践基本 特征。","score":2},{"id":"zt-2022-c-6","isSubjective":false,"num":6,"category":"2022年成考政治真题卷 · 单选","stem":"价值是客体对个人，群体乃至整个社会的生活和活动所具有的（ ）。","options":["积极意义","绝对意义","消极意义","相对意义"],"answer":0,"answerLetter":"A","explanation":"价值通常被理解为客体对主体（个人、群体、社会等）所具有的积极作用和意义，是能满足主体某 种需求、带来益处的，并非绝对意义、消极意义或相对意义。","score":2},{"id":"zt-2022-c-7","isSubjective":false,"num":7,"category":"2022年成考政治真题卷 · 单选","stem":"社会存在主要包括自然环境，人口因素以及（ ）。","options":["物质生产方式","社会风俗","政治文化建设","历史传统"],"answer":0,"answerLetter":"A","explanation":"社会存在是社会生活的物质方面，主要包括自然环境、人口因素和物质生产方式。物质生产方式是 社会存在和发展的基础及决定力量。而社会风俗、政治文化建设、历史传统都属于社会意识范畴。","score":2},{"id":"zt-2022-c-8","isSubjective":false,"num":8,"category":"2022年成考政治真题卷 · 单选","stem":"政治上层建筑的核心（ ）。","options":["政党","国家政权","立法司法制度","行政制度"],"answer":1,"answerLetter":"B","explanation":"政治上层建筑是指人们在一定经济基础上建起的政治、法律制度以及建立的军队、警察、法庭、监 狱、政府部门、党派等国家机器和政治组织。其中，国家政权是政治上层建筑的核心，因为它掌控着社会的 统治权力，对其他政治上层建筑要素起着决定性的支配作用。","score":2},{"id":"zt-2022-c-9","isSubjective":false,"num":9,"category":"2022年成考政治真题卷 · 单选","stem":"社会领域存在着很多矛盾，其中生产力和生产关系，经济基础和上层建筑的矛盾是（ ）。","options":["社会主要矛盾","社会基本矛盾","次要矛盾","非基本矛盾"],"answer":1,"answerLetter":"B","explanation":"生产力和生产关系、经济基础和上层建筑的矛盾贯穿人类社会始终，是推动社会发展的基本动力 ，所以被称为社会基本矛盾。","score":2},{"id":"zt-2022-c-10","isSubjective":false,"num":10,"category":"2022年成考政治真题卷 · 单选","stem":"在生产关系中，最基本的是（ ）。","options":["生产资料所有制关系","政治关系","缺","家庭关系"],"answer":0,"answerLetter":"A","explanation":"生产关系包括生产资料所有制关系、人们在生产中的地位及相互关系、产品分配关系，其中生产资 料所有制关系是最基本的，它决定着其他关系。政治关系和家庭关系不属于生产关系范畴。","score":2},{"id":"zt-2022-c-11","isSubjective":false,"num":11,"category":"2022年成考政治真题卷 · 单选","stem":"毛泽东思想初步形成的标志是（ ）。","options":["《中国社会各阶级的分析》的发表","农村包围城市，武装夺取政权道路思想的提出和阐述","中国七届二中全会提出党的工作重心由农村转为城市","第一届全国人民代表大会的召开"],"answer":1,"answerLetter":"B","explanation":"毛泽东思想初步形成的重要标志是农村包围城市、武装夺取政权道路理论的提出，这一理论指明了 中国革命的独特道路。A选项是毛泽东早期著作，此时思想尚未初步形成；C选项是在解放战争即将胜利时 ，毛泽东思想成熟后的内容；D选项与毛泽东思想初步形成无关。","score":2},{"id":"zt-2022-c-12","isSubjective":false,"num":12,"category":"2022年成考政治真题卷 · 单选","stem":"开始确立以毛泽东为主要代表的马克思主义正确路线在党中央的领导地位的会议是（ ）。","options":["八七会议","古田会议","遵义会议","瓦窑堡会议"],"answer":2,"answerLetter":"C","explanation":"遵义会议结束了王明“左”倾冒险主义在中共中央的统治，确立了以毛泽东为代表的新的中央的正 确领导，在极端危急的历史关头，挽救了党，挽救了红军，挽救了中国革命。","score":2},{"id":"zt-2022-c-13","isSubjective":false,"num":13,"category":"2022年成考政治真题卷 · 单选","stem":"我国新民主主义革命的最基本动力是（ ）。","options":["城市小资产阶级","农民阶级","民族资产阶级","无产阶级"],"answer":3,"answerLetter":"D","explanation":"无产阶级是中国革命最基本的动力。无产阶级是新的社会生产力的代表，是近代中国最进步的阶级 。农民阶级是主力军，城市小资产阶级是基本动力之一，民族资产阶级有两面性，是革命力量之一但不是最 基本动力。","score":2},{"id":"zt-2022-c-14","isSubjective":false,"num":14,"category":"2022年成考政治真题卷 · 单选","stem":"在土地革命，武装斗争，农村革命根据地建设的相互关系中，中国革命的战略阵地是（ ）。","options":["土地革命","农村革命根据地","武装斗争","城市隐蔽战线"],"answer":1,"answerLetter":"B","explanation":"农村革命根据地是中国革命的战略阵地，它为武装斗争和土地革命提供了依托。土地革命是民主革 命的基本内容；武装斗争是中国革命的主要形式；城市隐蔽战线与题干所问关系不大。","score":2},{"id":"zt-2022-c-15","isSubjective":false,"num":15,"category":"2022年成考政治真题卷 · 单选","stem":"从中华人民共和国成立到社会主义改造基本完成的历史时期是指（ ）。","options":["从封建社会向资本主义社会转变的时期","从旧民主主义革命的时期向新民主主义革命转变的时期","从新民主主义到社会主义过渡的时期","从社会主义向共产主义的过渡时期"],"answer":2,"answerLetter":"C","explanation":"新中国成立到社会主义改造基本完成，这一阶段是我国从新民主主义社会向社会主义社会过渡的阶 段。A 选项不符合史实，我国没有从封建社会向资本主义社会转变这一过程；B 选项旧民主主义革命向新民 主主义革命转变是五四运动；D 选项社会主义改造完成后才进入社会主义，当时还没到从社会主义向共产主 义过渡阶段。","score":2},{"id":"zt-2022-c-16","isSubjective":false,"num":16,"category":"2022年成考政治真题卷 · 单选","stem":"《论十大关系》从十个方面论述了我国社会主义建设需要重点把握的一系列重大关系，前五个方面主要讨 论的是（ ）。","options":["经济领域问题","国际战略问题","政治生活问题","思想文化问题"],"answer":0,"answerLetter":"A","explanation":"《论十大关系》前五个方面主要涉及重工业和轻工业、农业的关系，沿海工业和内地工业的关系 ，经济建设和国防建设的关系等，这些都属于经济领域问题。","score":2},{"id":"zt-2022-c-17","isSubjective":false,"num":17,"category":"2022年成考政治真题卷 · 单选","stem":"贯穿邓小平理论的思想路线是（ ）。","options":["放下包袱轻装入阵","开拓创新与时俱进","开放脑筋集思广益","解放思想实事求是"],"answer":3,"answerLetter":"D","explanation":"邓小平理论的精髓是解放思想、实事求是 ，这也是贯穿邓小平理论的思想路线。解放思想是实事求 是的前提，实事求是是解放思想的目的和归宿。","score":2},{"id":"zt-2022-c-18","isSubjective":false,"num":18,"category":"2022年成考政治真题卷 · 单选","stem":"社会主义初级阶段基本路线最主要的内容可概括为（ ）。","options":["抓革命促生产","一要吃饭二要建设","两手抓，两手都要硬","一个中心，两个基本点"],"answer":3,"answerLetter":"D","explanation":"社会主义初级阶段基本路线是以经济建设为中心，坚持四项基本原则，坚持改革开放，即“一个中 心，两个基本点” 。A选项“抓革命促生产”是特定历史时期口号；B选项“一要吃饭二要建设”并非基本路 线内容；C选项“两手抓，两手都要硬”是关于物质文明和精神文明建设等方面的要求，不是基本路线最主要 内容。","score":2},{"id":"zt-2022-c-19","isSubjective":false,"num":19,"category":"2022年成考政治真题卷 · 单选","stem":"三个代表重要思想可集中概括为：我们党必须始终代表中国先进生产力的发展要求，代表中国先进文化的 前进方向，代表中国最广大人民的（ ）。","options":["当前利益","长远利益","根本利益","全部利益"],"answer":2,"answerLetter":"C","explanation":"“三个代表”重要思想明确表述为党要始终代表中国最广大人民的根本利益 ，强调的是从整体、长 远和本质上维护人民利益，并非局限于当前、长远某一方面利益或全部利益。","score":2},{"id":"zt-2022-c-20","isSubjective":false,"num":20,"category":"2022年成考政治真题卷 · 单选","stem":"在全面建设小康社会进程中形成的科学发展观，其基本要求是（ ）。","options":["推动经济社会发展","以人为本","全面协调可持续","统筹兼顾"],"answer":2,"answerLetter":"C","explanation":"科学发展观，第一要义是推动经济社会发展，核心立场是以人为本，基本要求是全面协调可持续 ，根本方法是统筹兼顾。所以选体现基本要求的选项。","score":2},{"id":"zt-2022-c-21","isSubjective":false,"num":21,"category":"2022年成考政治真题卷 · 单选","stem":"新时代中国特色社会主义事业总体布局是（ ）。","options":["一根红线","两个大局","四个全面","五位一体"],"answer":3,"answerLetter":"D","explanation":"新时代中国特色社会主义事业总体布局是“五位一体”，即经济建设、政治建设、文化建设、社会 建设、生态文明建设五位一体。“四个全面”是战略布局；“一根红线”并非事业总体布局相关表述；“两 个大局”指中华民族伟大复兴战略全局和世界百年未有之大变局，与总体布局无关。答案：D 。","score":2},{"id":"zt-2022-c-22","isSubjective":false,"num":22,"category":"2022年成考政治真题卷 · 单选","stem":"中华民族伟大复兴的形象表达是（ ）。","options":["工业化","中国梦","小康社会","天下大同"],"answer":1,"answerLetter":"B","explanation":"中国梦，就是实现中华民族伟大复兴，它是中华民族伟大复兴的形象表达。工业化是经济发展的一 个阶段特征；小康社会是阶段性奋斗目标；天下大同是一种理想社会状态，但并非中华民族伟大复兴的形象 表达。","score":2},{"id":"zt-2022-c-23","isSubjective":false,"num":23,"category":"2022年成考政治真题卷 · 单选","stem":"党的十九大提出的“两步走”战略安排的第二步是（ ）。","options":["到2035年，基本实现现代化","到2035年，全体人民共同富裕取得更为明显的实质性进展","到本世纪中叶，把我国建成富强文明民主和谐的社会主义现代化国家","到本世纪中叶，把我国建成富强文明民主和谐美丽的社会主义现代化强国"],"answer":3,"answerLetter":"D","explanation":"党的十九大提出的“两步走”战略安排，第一步是到2035年基本实现社会主义现代化；第二步是到 本世纪中叶，把我国建成富强民主文明和谐美丽的社会主义现代化强国。A选项是第一步内容；B选项并非 “两步走”战略第二步核心表述；C选项缺少“美丽”且表述为之前的“三步走”战略目标。","score":2},{"id":"zt-2022-c-24","isSubjective":false,"num":24,"category":"2022年成考政治真题卷 · 单选","stem":"立足新发展阶段，必须贯彻新发展理念，构建新发展格局，其中，构建新发展格局明确了我国现代化建设 的是（ ）。","options":["历史方位","指导原则","路径选择","根本立场"],"answer":2,"answerLetter":"C","explanation":"新发展阶段明确了我国发展的历史方位；新发展理念是我国现代化建设的指导原则；构建新发展格 局是我国经济现代化的路径选择；人民至上是新发展理念的根本立场。","score":2},{"id":"zt-2022-c-25","isSubjective":false,"num":25,"category":"2022年成考政治真题卷 · 单选","stem":"在社会主义核心价值观的基本内容中，作为社会层面价值要求的是（ ）。","options":["富强、民主、文明、和谐","自由、平等、公正、法治","博学、明辨、慎思、笃行","爱国、敬业、诚信、友善"],"answer":1,"answerLetter":"B","explanation":"社会主义核心价值观中，国家层面是富强、民主、文明、和谐；社会层面是自由、平等、公正、法 治；个人层面是爱国、敬业、诚信、友善。C选项“博学、明辨、慎思、笃行”不属于社会主义核心价值观内 容。答案选B 。","score":2},{"id":"zt-2022-c-26","isSubjective":false,"num":26,"category":"2022年成考政治真题卷 · 单选","stem":"中国特色社会主义政治经济学的最新成就是（ ）。","options":["毛泽东思想","周恩来经济思想","邓小平经济思想","习近平经济思想"],"answer":3,"answerLetter":"D","explanation":"习近平经济思想是中国特色社会主义政治经济学的最新成果，是运用马克思主义政治经济学基本原 理指导新时代经济发展实践形成的重大理论成果。毛泽东思想、周恩来经济思想所处时代中国特色社会主义 政治经济学还在探索发展阶段；邓小平经济思想为中国特色社会主义政治经济学发展作出重要贡献，但不是 最新成果。","score":2},{"id":"zt-2022-c-27","isSubjective":false,"num":27,"category":"2022年成考政治真题卷 · 单选","stem":"全面从严治党摆在首位的是（ ）。","options":["政治建设","思想建设","组织建设","作风建设"],"answer":0,"answerLetter":"A","explanation":"党的政治建设是党的根本性建设，决定党的建设方向和效果，所以全面从严治党要把政治建设摆在 首位。","score":2},{"id":"zt-2022-c-28","isSubjective":false,"num":28,"category":"2022年成考政治真题卷 · 单选","stem":"坚持总体国家安全观，必须坚持人民安全、政治安全、国家利益至上有机统一。其中，国家安全的根本是 （ ）。","options":["人民安全","政治安全","国家利益至上","生态安全"],"answer":1,"answerLetter":"B","explanation":"总体国家安全观中，政治安全是根本，它关乎国家的主权、政权等核心要素。人民安全是宗旨，国 家利益至上是准则 ，生态安全属于国家安全体系的一部分，但不是根本。","score":2},{"id":"zt-2022-c-29","isSubjective":false,"num":29,"category":"2022年成考政治真题卷 · 单选","stem":"习近平强军思想强调，人民军队建军之本、强军之魂是（ ）。","options":["党对军队的绝对领导","能打仗，打胜仗","作风优良","军民融合发展"],"answer":0,"answerLetter":"A","explanation":"党对军队的绝对领导是人民军队的建军之本、强军之魂，这是基于历史经验、国家性质和军队使命 等多方面得出的重要论断。其他选项中，能打仗、打胜仗是军队的根本职能和军队建设的根本指向；作风优 良是我军鲜明特色和政治优势；军民融合发展是国家战略。答案：A。","score":2},{"id":"zt-2022-c-30","isSubjective":false,"num":30,"category":"2022年成考政治真题卷 · 单选","stem":"新时代中国外交政策的宗旨仍然是（ ）。","options":["重持公道，伸张正义","亲仁善邻，协和万邦","维护世界和平，促进共同发展","弘义融利、扶危济困"],"answer":2,"answerLetter":"C","explanation":"这是对新时代中国外交政策宗旨这一基础知识点的考查。中国外交政策宗旨自确定后未发生改变 ，一直是维护世界和平、促进共同发展。答案选C。","score":2},{"id":"zt-2022-c-31","isSubjective":false,"num":31,"category":"2022年成考政治真题卷 · 单选","stem":"审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》的会议是（ ）。","options":["中共十九届三中全会","中共十九届四中全会","中共十九届五中全会","中共十九届六中全会"],"answer":3,"answerLetter":"D","explanation":"中共十九届六中全会审议通过《中共中央关于党的百年奋斗重大成就和历史经验的决议》，这是总 结党的百年奋斗历程的重要文件，具有重大历史意义。其他几次会议各有重要议题，但与该决议无关。答案 ：D","score":2},{"id":"zt-2022-c-32","isSubjective":false,"num":32,"category":"2022年成考政治真题卷 · 单选","stem":"2021年我国GDP总量首次超过（ ）。","options":["80万亿元","90万亿元","100万亿元","110万亿元"],"answer":3,"answerLetter":"D","explanation":"2021年我国GDP总量为114.4万亿元，首次超过110万亿元 。","score":2},{"id":"zt-2022-c-33","isSubjective":false,"num":33,"category":"2022年成考政治真题卷 · 单选","stem":"2022年2月20日，第二十四届冬季奥林匹克运动会闭幕式顺利举行，举办城市成为历史首位“双奥之城 ”。该城市是（ ）。","options":["北京","悉尼","纽约","伦敦"],"answer":0,"answerLetter":"A","explanation":"2008 年夏季奥运会和 2022 年冬奥会都在北京举办，北京是世界首个“双奥之城”。悉尼、纽约、 伦敦都不符合这一情况。","score":2},{"id":"zt-2022-c-34","isSubjective":false,"num":34,"category":"2022年成考政治真题卷 · 单选","stem":"2022年6月17日，我国举行第三艘航空母舰下水命名仪式，经中央军委批准，我国第三艘航空母舰命名为 中国人民解放军海军（ ）。","options":["辽宁舰","山东舰","福建舰","广东舰"],"answer":2,"answerLetter":"C","explanation":"2022年6月17日，我国第三艘航空母舰命名为中国人民解放军海军福建舰。辽宁舰是我国第一艘航母 ，山东舰是第二艘。广东舰未存在这样的航母命名。","score":2},{"id":"zt-2022-c-35","isSubjective":false,"num":35,"category":"2022年成考政治真题卷 · 单选","stem":"2022年6月，第三次全国国土调查结果显示，我国现有耕地19.18亿亩，牢牢守住了耕地红线，我国划定的 耕地红线的面积是（ ）。","options":["16亿亩","17亿亩","18亿亩","19亿亩"],"answer":2,"answerLetter":"C","explanation":"我国划定的耕地红线是18亿亩。","score":2},{"id":"zt-2022-s-36","isSubjective":true,"num":36,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"简述矛盾的同一性和斗争性。","answer":"(1)矛盾的同一性和斗争性相互区别，相互联结。 (2)同一性：矛盾双方相互联系、相互吸引的性质。斗争性：矛盾双方相互排斥、相互对立的性质。矛盾的同 一性和斗争性是两种相反的属性。同一性是相对的;斗争性是绝对的。 (3)同一性不能脱离斗争性，没有斗争性就没有同一性;斗争性寓于同一性之中，没有同一性也就没有斗争性 。 (4)我们在分析和处理矛盾时，必须在对立中把握同一，在同一中把握对立。社会主义在发展中，一方面要学 习和引进资本主义的先进成果，否则不利于社会主义的发展，另一方面，又要警惕资本主义的干扰和挑战 ，否则社会主义制度就无法坚持。 【考点】事物的联系、发展及其规律——唯物辩证法的基本规律","explanation":"(1)矛盾的同一性和斗争性相互区别，相互联结。 (2)同一性：矛盾双方相互联系、相互吸引的性质。斗争性：矛盾双方相互排斥、相互对立的性质。矛盾的同 一性和斗争性是两种相反的属性。同一性是相对的;斗争性是绝对的。 (3)同一性不能脱离斗争性，没有斗争性就没有同一性;斗争性寓于同一性之中，没有同一性也就没有斗争性 。 (4)我们在分析和处理矛盾时，必须在对立中把握同一，在同一中把握对立。社会主义在发展中，一方面要学 习和引进资本主义的先进成果，否则不利于社会主义的发展，另一方面，又要警惕资本主义的干扰和挑战 ，否则社会主义制度就无法坚持。 【考点】事物的联系、发展及其规律——唯物辩证法的基本规律","score":10},{"id":"zt-2022-s-37","isSubjective":true,"num":37,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"简述毛泽东思想活的灵魂及其内涵。","answer":"(1)实事求是：一切从客观实际出发，理论联系实际，坚持在实践中检验和发展真理。是毛泽东思想 的世界观和方法论的基础，是毛泽东思想的精髓。 (2)群众路线：一切为了群众，一切依靠群众，从群众中来，到群众中去。是中国共产党的一切工作必须遵循 的基本路线和基本方法。 (3)独立自主：就是从中国实际出发，依靠本国革命力量和人民群众的努力，走出适合本国特点的革命建设道 路。 【考点】毛泽东思想及其历史地位——毛泽东思想的主要内容、活的灵魂和历史地位","explanation":"(1)实事求是：一切从客观实际出发，理论联系实际，坚持在实践中检验和发展真理。是毛泽东思想 的世界观和方法论的基础，是毛泽东思想的精髓。 (2)群众路线：一切为了群众，一切依靠群众，从群众中来，到群众中去。是中国共产党的一切工作必须遵循 的基本路线和基本方法。 (3)独立自主：就是从中国实际出发，依靠本国革命力量和人民群众的努力，走出适合本国特点的革命建设道 路。 【考点】毛泽东思想及其历史地位——毛泽东思想的主要内容、活的灵魂和历史地位","score":10},{"id":"zt-2022-s-38","isSubjective":true,"num":38,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"简述确立社会主义基本制度的重大意义。","answer":"(1)极大地提高了工人阶级和广大劳动人民的积极性、创造性，极大地促进了我国社会生产力的发展 。 (2)是我国历史上最深刻最伟大的社会变革，使广大劳动人民真正成为国家的主人。 (3)使占世界人口四分之一的东方大国进入社会主义社会，对世界格局产生了积极影响。 (4)是马克思列宁主义关于社会主义革命理论在中国的正确运用和创造性的发展。 【考点】社会主义改造理论——社会主义制度在中国的确立","explanation":"(1)极大地提高了工人阶级和广大劳动人民的积极性、创造性，极大地促进了我国社会生产力的发展 。 (2)是我国历史上最深刻最伟大的社会变革，使广大劳动人民真正成为国家的主人。 (3)使占世界人口四分之一的东方大国进入社会主义社会，对世界格局产生了积极影响。 (4)是马克思列宁主义关于社会主义革命理论在中国的正确运用和创造性的发展。 【考点】社会主义改造理论——社会主义制度在中国的确立","score":10},{"id":"zt-2022-s-39","isSubjective":true,"num":39,"category":"2022年成考政治真题卷 · 简答题 (10分)","stem":"邓小平社会主义市场经济理论要点有哪些?","answer":"(1)计划经济和市场经济不是区分社会主义和资本主义的标志，计划经济不等于社会主义，市场经济 也不等于资本主义。市场经济作为资源配置的一种方式，本身不具有制度属性，可以和不同社会制度结合 ，从而表现出不同性质。 (2)计划和市场都是调节经济的手段，各有优势和长处，社会主义市场经济要把计划和市场两者结合起来。 (3)社会主义市场经济是为了更好发展社会生产力，社会主义与市场经济之间不存在根本矛盾。实践证明，社 会主义搞市场经济更有利于解放和发展生产力。 【考点】邓小平理论——邓小平理论的基本问题和主要内容","explanation":"(1)计划经济和市场经济不是区分社会主义和资本主义的标志，计划经济不等于社会主义，市场经济 也不等于资本主义。市场经济作为资源配置的一种方式，本身不具有制度属性，可以和不同社会制度结合 ，从而表现出不同性质。 (2)计划和市场都是调节经济的手段，各有优势和长处，社会主义市场经济要把计划和市场两者结合起来。 (3)社会主义市场经济是为了更好发展社会生产力，社会主义与市场经济之间不存在根本矛盾。实践证明，社 会主义搞市场经济更有利于解放和发展生产力。 【考点】邓小平理论——邓小平理论的基本问题和主要内容","score":10},{"id":"zt-2022-s-40","isSubjective":true,"num":40,"category":"2022年成考政治真题卷 · 论述题 (20分)","stem":"习近平指出不能用今天的时代条件，发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人 才能干出来的成绩。试着评价历史人物的正确方法。","answer":"(1)坚持历史主义的原则和方法，即杰出人物是一定历史条件的产物，将其放到他所在的历史条件下 加以评价。不能用今天的时代条件、发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人才 能干出的业绩来。 (2)坚持阶级分析的原则和方法，即联系杰出人物的阶级属性来评价杰出人物; (3)坚持全面辩证分析的原则和方法。不能把历史顺境中的成功简单归功于个人，也不能把历史逆境中的挫折 简单归咎于个人。既要肯定杰出人物的巨大历史功绩，又要分析其缺点错误，进行全面评价。 【考点】社会历史发展的动力——人民群众在历史发展中的作用","explanation":"(1)坚持历史主义的原则和方法，即杰出人物是一定历史条件的产物，将其放到他所在的历史条件下 加以评价。不能用今天的时代条件、发展水平、认识水平去衡量和要求前人，不能苛求前人干出只有后人才 能干出的业绩来。 (2)坚持阶级分析的原则和方法，即联系杰出人物的阶级属性来评价杰出人物; (3)坚持全面辩证分析的原则和方法。不能把历史顺境中的成功简单归功于个人，也不能把历史逆境中的挫折 简单归咎于个人。既要肯定杰出人物的巨大历史功绩，又要分析其缺点错误，进行全面评价。 【考点】社会历史发展的动力——人民群众在历史发展中的作用","score":20},{"id":"zt-2022-s-41","isSubjective":true,"num":41,"category":"2022年成考政治真题卷 · 论述题 (20分)","stem":"2021年7月1日，习近平在庆祝中国共产党成立100周年大会上的讲话中强调：“中国共产党领导是中国特 色社会主义最本质的特征，中国特色社会主义制度的最大优势，是党和国家的根本所在，命脉所有，是全国 各族人民利益所系，命运所系。”如何理解中国共产党领导是中国特色社会主义制度的最大优势?","answer":"(1)中国共产党是中国特色社会主义制度的创建者。没有党就没有中国特色社会主义制度，制度优势 也就无从谈起。在党的领导下通过改革不断完善和发展中国特色社会主义制度，推进国家治理体系和治理能 力现代化，使中国特色社会主义制度更加成熟、更加定型。 (2)中国共产党的领导是充分发挥中国特色社会主义制度优势的根本保障。中国共产党是中国工人阶级、中国 人民和中华民族的先锋队，能够充分调动广大人民的积极性、主动性、创造性，有利于充分发挥中国特色社 会主义制度在保持党和国家活力方面的优势;党是先进生产力发展要求和先进文化发展方向的代表，有利于发 挥中国特色社会主义制度在解放和发展社会生产力、推动经济社会全面发展方面的优势;党代表了中国最广大 人民的根本利益，有利于充分发挥中国特色社会主义制度在维护和促进社会公平正义、实现全体人民共同富 裕方面的优势;党能够总揽全局，协调各方，有利于充分发挥中国特色社会主义制度集中力量办大事、有效应 对前进道路上的各种风险挑战方面的优势;党是领导和团结全国各族人民的核心力量，有利于充分发挥中国特 色社会主义制度在维护民族团结、社会稳定、国家统一方面的优势。 (3)中国共产党的自身优势是中国特色社会主义制度优势的主要来源。以马克思主义为指导，用马克思主义中 国化理论成果武装全党、教育人民的理论优势;坚定崇高的政治理想、政治信念和百折不挠的革命意志的政治 优势;遵循马克思主义建党原则，严密组织体系、严格组织生活、严明组织纪律，使党成为统一整体的组织优 势;实行民主集中制的制度优势;密切联系群众的作风优势。 【考点】坚持和加强党的领导——实现中华民族伟大复兴关键在党","explanation":"(1)中国共产党是中国特色社会主义制度的创建者。没有党就没有中国特色社会主义制度，制度优势 也就无从谈起。在党的领导下通过改革不断完善和发展中国特色社会主义制度，推进国家治理体系和治理能 力现代化，使中国特色社会主义制度更加成熟、更加定型。 (2)中国共产党的领导是充分发挥中国特色社会主义制度优势的根本保障。中国共产党是中国工人阶级、中国 人民和中华民族的先锋队，能够充分调动广大人民的积极性、主动性、创造性，有利于充分发挥中国特色社 会主义制度在保持党和国家活力方面的优势;党是先进生产力发展要求和先进文化发展方向的代表，有利于发 挥中国特色社会主义制度在解放和发展社会生产力、推动经济社会全面发展方面的优势;党代表了中国最广大 人民的根本利益，有利于充分发挥中国特色社会主义制度在维护和促进社会公平正义、实现全体人民共同富 裕方面的优势;党能够总揽全局，协调各方，有利于充分发挥中国特色社会主义制度集中力量办大事、有效应 对前进道路上的各种风险挑战方面的优势;党是领导和团结全国各族人民的核心力量，有利于充分发挥中国特 色社会主义制度在维护民族团结、社会稳定、国家统一方面的优势。 (3)中国共产党的自身优势是中国特色社会主义制度优势的主要来源。以马克思主义为指导，用马克思主义中 国化理论成果武装全党、教育人民的理论优势;坚定崇高的政治理想、政治信念和百折不挠的革命意志的政治 优势;遵循马克思主义建党原则，严密组织体系、严格组织生活、严明组织纪律，使党成为统一整体的组织优 势;实行民主集中制的制度优势;密切联系群众的作风优势。 【考点】坚持和加强党的领导——实现中华民族伟大复兴关键在党","score":20}]},{"id":"yc-1","title":"2026年成考预测试卷(一)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-1-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(一) · 单选","stem":"区分新事物和旧事物的根本标志是（ ）","options":["事物的全局性质未变，局部性质发生了根本变化","事物的主要矛盾未变化，次要矛盾发生了变化","事物的根据和条件发生了质的变化","事物的发展方向和道路发生了根本变化"],"answer":2,"answerLetter":"C","explanation":"区分新事物和旧事物的根本标志在于是否符合事物发展的必然趋势，是否具有强大的生命力和远大 的发展前途，而这通常意味着事物的根据和条件发生了质的变化。新事物是在旧事物的“母体”中孕育成熟 的，它否定了旧事物中消极腐朽的东西，吸收了旧事物中合理的、仍然适合新的条件的因素，并添加了旧事 物所不能容纳的新内容。选项A、B所描述并非区分新、旧事物的根本标志；选项D发展方向和道路的变化不能 直接等同于新、旧事物的区分。","score":2},{"id":"yc-1-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(一) · 单选","stem":"系统科学产生的意义在于它（ ）","options":["抛弃了唯物辩证法","代替了唯物辩证法","丰富了唯物辩证法","高于唯物辩证法"],"answer":2,"answerLetter":"C","explanation":"唯物辩证法是科学的世界观和方法论，具有普遍的指导意义。系统科学作为一门具体科学，它的产 生是对具体领域的研究成果。具体科学是哲学的基础，具体科学的发展为哲学的发展提供丰富的素材。系统 科学的产生丰富了唯物辩证法对世界联系和发展等方面的认识。 选项A，系统科学不可能抛弃唯物辩证法 ，唯物辩证法是科学的理论，对具体科学有指导作用，二者不是对立关系。 选项B，具体科学不能代替哲学 ，系统科学不能代替唯物辩证法，它们研究的层次和范围不同。 选项D，唯物辩证法是对整个世界最一般规 律的概括和总结，具有最高的普遍性和指导性，系统科学不能高于唯物辩证法。","score":2},{"id":"yc-1-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(一) · 单选","stem":"质量互变规律揭示了事物发展的（ ）","options":["源泉和动力","状态和形式","方向和道路","波浪式前进运动"],"answer":1,"answerLetter":"B","explanation":"质量互变规律表明事物发展是量变与质变的统一，量变与质变是事物发展变化存在的两种基本状态 和形式 。A选项，对立统一规律揭示事物发展的源泉和动力；C选项，否定之否定规律揭示事物发展的方向和 道路；D选项波浪式前进运动体现的是否定之否定规律。","score":2},{"id":"yc-1-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(一) · 单选","stem":"下列选项中属于因果联系的是（ ）","options":["先有闪电，后有雷鸣","夏天过去，秋天到来","白天过去，黑夜降临","实践出真知，斗争长才干"],"answer":3,"answerLetter":"D","explanation":"因果联系是指事物之间存在引起和被引起的关系。A选项中闪电和雷鸣是同时发生，只是由于光传播 速度比声音快才先看到闪电后听到雷鸣，并非因果关系；B选项夏天过去秋天到来、C选项白天过去黑夜降临 ，都是自然的时间顺序更替，不存在引起和被引起关系；D选项实践能引发获得真知，斗争会促使增长才干 ，存在引起和被引起的关系，属于因果联系。","score":2},{"id":"yc-1-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(一) · 单选","stem":"可能性是指（ ）","options":["头脑中的构造物","已经存在着的事物","预示事物发展前途的种种趋势","失去必然性的东西"],"answer":2,"answerLetter":"C","explanation":"可能性是事物发展过程中所包含的预示事物发展前途的种种趋势，它是基于事物的内在根据和外在 条件而存在的，并非头脑中的构造物，也不是已存在的事物，更不是失去必然性的东西。答案选C。","score":2},{"id":"yc-1-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(一) · 单选","stem":"内容与形式存在矛盾的根据是（ ）","options":["内容总是落后于形式的变化","内容活跃易变，形式相对稳定","形式决定内容，内容反作用于形式","形式活跃易变，内容相对稳定"],"answer":1,"answerLetter":"B","explanation":"内容和形式的关系中，内容是活跃易变的，形式则相对稳定，这种特性使得二者存在矛盾。A选项说 法错误，一般是形式落后于内容变化；C选项表述错误，是内容决定形式，形式反作用于内容；D选项说反了 。","score":2},{"id":"yc-1-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(一) · 单选","stem":"在认识论中坚持反映的原则（ ）","options":["是所有唯物主义的观点","仅是辩证唯物主义的观点","只是机械唯物主义的观点","是不可知论的观点"],"answer":0,"answerLetter":"A","explanation":"唯物主义都认为物质第一性，意识第二性，意识是对物质的反映，所以在认识论中坚持反映原则是 所有唯物主义的观点。辩证唯物主义、机械唯物主义都属于唯物主义阵营，都坚持反映原则，不只是辩证唯 物主义或机械唯物主义的观点。而不可知论是否认认识世界或彻底认识世界的可能性，与坚持反映原则相悖 。","score":2},{"id":"yc-1-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(一) · 单选","stem":"实践是认识的基础表明（ ）","options":["每个人必须事事实践才能有认识","只有参加实践就一定能获得正确认识","直接知识来自实践","一切认识归根到底来自实践"],"answer":3,"answerLetter":"D","explanation":"A选项“每个人必须事事实践才能有认识”过于绝对，人们可以通过间接经验获得认识，不一定要 事事都亲身实践。 B选项“只有参加实践就一定能获得正确认识”错误，实践不一定就能直接获得正确认识 ，认识有正确和错误之分，还要经过认识的发展过程等。 C选项“直接知识来自实践”表述不准确，直接知 识是相对间接知识而言，虽然直接知识与实践紧密相关，但不能简单说直接知识就来自实践，人们获取知识 途径多样。 D选项“一切认识归根到底来自实践”，实践是认识的来源，即使是通过间接经验获得的认识 ，追根溯源也是他人实践的结果，这体现了实践是认识的基础。","score":2},{"id":"yc-1-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(一) · 单选","stem":"认识的主体性原则是指（ ）","options":["主观性原则","主体决定客体原则","主体的能动性原则","客体依赖主体原则"],"answer":2,"answerLetter":"C","explanation":"认识的主体性原则强调的是主体在认识过程中的主动、能动作用。主体不是被动地反映客体，而是 积极主动地去认识、改造客体。","score":2},{"id":"yc-1-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(一) · 单选","stem":"实践高于理论的认识是因为实践具有（ ）","options":["普遍性","客观实在性","直接现实性","社会历史性"],"answer":2,"answerLetter":"C","explanation":"实践的直接现实性是指它能把理论变为实际，直接产生客观效果，这是理论认识所不具备的，所以 实践高于理论认识。答案：C 。","score":2},{"id":"yc-1-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(一) · 单选","stem":"社会进步的内在根据是（ ）","options":["社会基本矛盾运动","人与自然的和谐发展","各族人民的和睦相处","人与人之间的团结协作"],"answer":0,"answerLetter":"A","explanation":"社会基本矛盾即生产力和生产关系、经济基础和上层建筑的矛盾，这两对矛盾相互联系、相互作用 ，推动着人类社会从低级向高级发展，是社会进步的内在根据。B选项人与自然和谐发展、C选项各族人民和 睦相处、D选项人与人之间团结协作虽然对社会发展有积极作用，但不是社会进步的内在根据。答案：A。","score":2},{"id":"yc-1-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(一) · 单选","stem":"社会进步的最高标准是（ ）","options":["生产关系的改变","生产力的发展","文化素质的提高","人与人的团结一致"],"answer":1,"answerLetter":"B","explanation":"生产力是社会发展的最终决定力量，生产力的发展是衡量社会进步与否的根本标准，因为生产力发 展会带动生产关系变革等一系列变化，推动社会进步。","score":2},{"id":"yc-1-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(一) · 单选","stem":"法国资产阶级革命后出现多次封建王朝复辟，这说明（ ）","options":["社会进步无规律可言","社会进步是前进性与曲折性的统一","社会进步是人们的主观愿望","社会进步没有客观标准"],"answer":1,"answerLetter":"B","explanation":"法国资产阶级革命后虽出现多次封建王朝复辟，但资产阶级最终战胜封建势力，推动了社会进步。 这表明社会进步不是一帆风顺的，既有前进的趋势，又会经历曲折过程。答案：B 。社会进步是前进性与曲 折性的统一，法国资产阶级革命后的情况正是这一观点的体现。A选项社会进步是有规律的；C选项社会进步 是客观的，不是主观愿望；D选项社会进步有客观标准。所以ACD错误。","score":2},{"id":"yc-1-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(一) · 单选","stem":"人的本质属性是（ ）","options":["自然属性","先天属性","生理属性","社会属性"],"answer":3,"answerLetter":"D","explanation":"人既有自然属性也有社会属性，而社会属性是人区别于其他动物的本质属性，人是在社会关系中存 在和发展的。","score":2},{"id":"yc-1-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(一) · 单选","stem":"世界观是人们在实践中形成的（ ）","options":["对于自然现象的基本观点","对于整个世界的根本观点","对于人生意义的独特见解","对于社会问题的具体看法"],"answer":1,"answerLetter":"B","explanation":"世界观强调的是对整个世界的总的、根本的观点。A选项只提及自然现象，范围太窄；C选项说的是 人生意义，属于人生观范畴；D选项社会问题具体看法也不是对整个世界根本观点。只有B符合世界观定义。","score":2},{"id":"yc-1-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(一) · 单选","stem":"新民主主义的总路线的核心是（ ）","options":["无产阶级的领导","人民大众的参与","反帝","反封建"],"answer":0,"answerLetter":"A","explanation":"新民主主义革命总路线中，无产阶级的领导权是中国革命的中心问题，也是新民主主义革命理论的 核心问题，所以核心是无产阶级领导。","score":2},{"id":"yc-1-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(一) · 单选","stem":"新民主主义革命的指导思想是（ ）","options":["新三民主义","马克思列宁主义","社会主义","民粹主义"],"answer":1,"answerLetter":"B","explanation":"新民主主义革命是无产阶级领导的资产阶级民主革命，其指导思想是马克思列宁主义。新三民主义 是孙中山提出的资产阶级革命纲领，是旧民主主义革命时期的指导思想之一，但不是新民主主义革命指导思 想；社会主义是新民主主义革命胜利后要建立的社会形态，不是指导思想；民粹主义不符合中国革命实际 ，并非中国新民主主义革命指导思想。","score":2},{"id":"yc-1-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(一) · 单选","stem":"实现无产阶级领导权的根本保证是（ ）","options":["建立以工农联盟为基础的广泛统一战线","实行独立自主的方针","建立一支强大的革命武装","加强无产阶级政党的建设"],"answer":3,"answerLetter":"D","explanation":"无产阶级政党是无产阶级的先锋队，只有加强无产阶级政党建设，党才能制定正确路线方针政策 ，组织和领导革命取得胜利，实现领导权。其他选项虽重要，但不是根本保证。","score":2},{"id":"yc-1-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(一) · 单选","stem":"新民主主义革命的前途是（ ）","options":["建立资产阶级专政的资本主义制度","立即建立社会主义","经过新民主主义逐步过渡到社会主义","实现共产主义"],"answer":2,"answerLetter":"C","explanation":"新民主主义革命胜利后不可能建立资产阶级专政的资本主义制度，A 错误；新民主主义革命胜利后 不能立即建立社会主义，要经过过渡阶段，B 错误；共产主义是长远目标，不是新民主主义革命直接前途，D 错误。新民主主义革命的前途是经过新民主主义逐步过渡到社会主义 。","score":2},{"id":"yc-1-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(一) · 单选","stem":"毛泽东明确提出了新民主主义的三大经济纲领是在（ ）","options":["《目前形势和我们的任务》","《论联合政府》","《在中共七届二中全会上的讲话》","《新民主主义论》"],"answer":0,"answerLetter":"A","explanation":"1947 年毛泽东在《目前形势和我们的任务》中明确提出新民主主义三大经济纲领。《论联合政府》 主要阐述了党的三大作风等内容；《在中共七届二中全会上的讲话》提出党的工作重心转移等；《新民主主 义论》系统阐述新民主主义革命理论等。","score":2},{"id":"yc-1-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(一) · 单选","stem":"邓小平曾说：“现在我们虽然也在搞社会主义，但事实上不够格。”这说明（ ）","options":["我国实际上还处于向社会主义社会过渡的时期","我国搞的社会主义事实上是在补资本主义的课","我国的生产力不发达，还没有摆脱贫困，而贫穷不是社会主义","我国还严重地存在着封建残余、小生产习惯势力和资本主义腐朽思想的影响"],"answer":2,"answerLetter":"C","explanation":"邓小平这句话强调我国虽进入社会主义，但生产力水平还较低，没有达到理想中社会主义应有的发 达程度。A选项，我国早已过渡到社会主义社会；B选项，我国走的是社会主义道路并非补资本主义课；D选项 与题干所表达生产力方面内容无关。C选项指出我国生产力不发达，符合邓小平这句话含义。","score":2},{"id":"yc-1-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(一) · 单选","stem":"一切从实际出发，中国最大的实际就是（ ）","options":["人口多，劳动者素质不高","生产力水平低，发展不平衡","自然条件差，资源相对短缺","现在处于并长期处于社会主义初级阶段"],"answer":3,"answerLetter":"D","explanation":"“一切从实际出发”，中国最大实际就是我国现阶段的基本国情，即现在处于并长期处于社会主义 初级阶段 ，它涵盖了生产力、生产关系等多方面情况，而A、B、C选项只是国情的部分表现。","score":2},{"id":"yc-1-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(一) · 单选","stem":"改革和发展的前提是（ ）","options":["四项基本原则","依法治国","社会公平","社会稳定"],"answer":3,"answerLetter":"D","explanation":"改革、发展和稳定三者紧密相连，其中社会稳定是改革和发展得以顺利进行的前提条件。没有稳定 的社会环境，改革和发展都难以推进。","score":2},{"id":"yc-1-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(一) · 单选","stem":"社会主义初级阶段是指（ ）","options":["任何国家进入社会主义都要经历的起始阶段","在生产力落后、商品经济不发达条件下，建设社会主义必然要经历的特定阶段","从新民主主义社会向共产主义社会过渡的阶段","从社会主义向共产主义过渡的阶段"],"answer":1,"answerLetter":"B","explanation":"社会主义初级阶段不是泛指任何国家进入社会主义都必经阶段，而是特指我国在生产力落后、商品 经济不发达条件下建设社会主义必然要经历的特定阶段。A选项错误，不是任何国家；C选项，不是从新民主 主义向共产主义过渡；D选项，不是从社会主义向共产主义过渡。","score":2},{"id":"yc-1-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(一) · 单选","stem":"抓住机遇，深化改革，扩大开放，促进发展，保持稳定是党在社会主义初级阶段的（ ）","options":["基本纲领","基本路线","基本方针","基本政策"],"answer":2,"answerLetter":"C","explanation":"党在社会主义初级阶段基本纲领涵盖经济、政治、文化等方面具体目标和政策；基本路线是以经济 建设为中心，坚持四项基本原则，坚持改革开放；基本政策较为具体针对某方面工作。而“抓住机遇，深化 改革，扩大开放，促进发展，保持稳定”是一段时间内指导全局工作的基本方针，它协调了改革、发展与稳 定等关键要素间的关系。","score":2},{"id":"yc-1-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(一) · 单选","stem":"我国现阶段，个人收入分配必须贯彻（ ）","options":["多劳多得，少劳少得的原则","效率优先，兼顾公平的原则","股份制企业职工的按股分红收入","集体企业职工的工资奖金收入"],"answer":1,"answerLetter":"B","explanation":"我国现阶段个人收入分配制度是按劳分配为主体、多种分配方式并存，在分配过程中要处理好效率 与公平的关系，当前强调初次分配和再分配都要兼顾效率与公平，而在过去较长一段时间强调效率优先、兼 顾公平，这一理念对分配有重要指导意义。A选项“多劳多得，少劳少得”是按劳分配原则的部分体现，不全 面；C选项“股份制企业职工按股分红收入”和D选项“集体企业职工工资奖金收入”只是具体的分配形式 ，并非个人收入分配需贯彻的原则。","score":2},{"id":"yc-1-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(一) · 单选","stem":"私营经济中的劳动者的收入属于（ ）","options":["按劳分配的收入","按资分配","按劳动力价值分配","按经营分配"],"answer":2,"answerLetter":"C","explanation":"按劳分配是在公有制经济范围内，按照劳动者提供的劳动数量和质量进行分配，私营经济不属于公 有制经济，A选项错误。 按资分配是凭借资本所有权参与分配，劳动者一般不凭借资本获取收入，B选项错误 。 在私营经济中，劳动者把自己的劳动力作为商品出卖给私营企业主，其收入是按劳动力价值分配所得 ，C选项正确。 按经营分配主要是经营者依据经营成果等进行分配，劳动者并非经营主体，D选项错误。答案 ：C","score":2},{"id":"yc-1-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(一) · 单选","stem":"在社会保障中居核心地位的是（ ）","options":["社会保险","社会救济","社会福利","社会优抚"],"answer":0,"answerLetter":"A","explanation":"社会保险是社会保障体系的核心部分，因为它覆盖人群广，涉及养老、医疗、失业、工伤和生育等 关乎人们基本生活和经济来源的重要方面。而社会救济是对困难群体的救助；社会福利是更高层次的保障 ；社会优抚针对特定优抚对象。答案：A。","score":2},{"id":"yc-1-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(一) · 单选","stem":"在社会主义初级阶段，和按劳分配结合在一起的是（ ）","options":["按劳动力价值分配","按生产要素分配","按风险分配","按经营分配"],"answer":1,"answerLetter":"B","explanation":"在社会主义初级阶段，实行按劳分配为主体、多种分配方式并存的分配制度，多种分配方式实质是 按生产要素分配，所以按劳分配是和按生产要素分配结合在一起的。","score":2},{"id":"yc-1-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(一) · 单选","stem":"我国经济体制改革确立什么样的目标，是关系整个社会主义现代化建设全局的一个重大问题。这个问题的 核心是正确认识和处理（ ）","options":["改革与发展的关系","速度与效益的关系","计划与市场的关系","中央与地方的关系"],"answer":2,"answerLetter":"C","explanation":"我国经济体制改革的核心问题是计划与市场的关系，经济体制改革目标的确立关键就在于对计划和 市场关系的正确认识。计划和市场都是资源配置手段，社会主义也可以有市场。","score":2},{"id":"yc-1-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(一) · 单选","stem":"社会主义物质文明建设和精神文明建设的关系是（ ）","options":["相辅相成，相互促进","物质文明是内容，精神文明是形式","相互独立，互不相干","精神文明是内容，物质文明是形式"],"answer":0,"answerLetter":"A","explanation":"社会主义物质文明与精神文明是相辅相成、相互促进的关系。物质文明为精神文明提供物质基础 ，精神文明为物质文明提供智力支持、精神动力和思想保证 。B、D 选项将二者简单归结为内容与形式关系 不准确，C 选项说相互独立互不相干错误。","score":2},{"id":"yc-1-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(一) · 单选","stem":"党的十一届三中全会以来，邓小平和党中央提出了一系列两手抓的战略方针，其中关键是（ ）","options":["一手抓改革开放，一手抓打击犯罪","一手抓经济建设，一手抓民主法制","一手抓改革开放，一手抓惩治腐败","一手抓物质文明，一手抓精神文明"],"answer":3,"answerLetter":"D","explanation":"在邓小平提出的一系列“两手抓”战略方针中，物质文明与精神文明建设是根本性的，物质文明是 基础，精神文明提供动力和智力支持等，二者相辅相成，共同推动社会全面发展，所以两手抓关键是一手抓 物质文明，一手抓精神文明。","score":2},{"id":"yc-1-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(一) · 单选","stem":"社会主义精神文明建设的目标是（ ）","options":["引导人们树立正确的人生观、世界观、价值观","弘扬爱国主义精神","建立面向现代化、面向世界、面向未来的民族的、科学的、大众的文化","培养有理想、有道德、有文化、有纪律的公民"],"answer":3,"answerLetter":"D","explanation":"社会主义精神文明建设包括思想道德建设和教育科学文化建设，其根本目标是培育“四有”公民 ，即有理想、有道德、有文化、有纪律的公民。A、B选项属于思想道德建设方面的内容；C选项是中国特色社 会主义文化的内涵。","score":2},{"id":"yc-1-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(一) · 单选","stem":"党的十五大指出，有中国特色的社会主义文化，是综合国力的（ ）","options":["重要内容","重要标志","重要基础","重要支持"],"answer":1,"answerLetter":"B","explanation":"党的十五大明确指出，有中国特色的社会主义文化是综合国力的重要标志 。强调了文化在衡量综合 国力中的关键地位与独特标识作用。","score":2},{"id":"yc-1-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(一) · 单选","stem":"教育科学文化建设要解决的是（ ）","options":["提高整个民族的科学文化素质问题","在全社会形成共同理想和精神支柱问题","全体公民树立正确的人生观、世界观、价值观的问题","精神文明建设的方向问题"],"answer":0,"answerLetter":"A","explanation":"教育科学文化建设主要目的就是提升民族科学文化素质。B选项形成共同理想和精神支柱是思想道德 建设方面；C选项树立正确三观主要也靠思想道德等多方面综合，并非教育科学文化建设专门解决；D选项精 神文明建设方向由诸多因素共同决定，不是教育科学文化建设解决。","score":2},{"id":"yc-1-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"简述对立统一规律是唯物辩证法的实质与核心。","answer":"（1）在唯物辩证法的理论体系中，对立统一规律占有十分重要的地位，是唯物辩证法的实质与核 心。 第一，唯物辩证法揭示的是事物的联系与发展，而对立统一规律揭示的是普遍联系的根本内容和永恒发展的 根本动力，也就是说，所谓联系实质上是矛盾与矛盾、矛盾这方面与矛盾那方面的联系，所谓发展实质上是 矛盾推动下的发展。 第二，唯物辩证法是有着丰富内容的完整的科学理论体系，而对立统一规律则是理解唯物辩证法全部理论的 关键，唯物辩证法的其他规律与范畴都是对立统一规律在某一方面的展开。 第三，唯物辩证法与形而上学是两种根本对立的世界观，而是否承认矛盾则是唯物辩证法与形而上学对立的 焦点。 第四，唯物辩证法既是世界观，又是方法论，矛盾分析法则是最根本的认识方法。 （2）唯物辩证法是一个内容丰富的完整理论体系，对立统一规律是唯物辩证法的实质与核心，但不是唯物辩 证法的总体。马克思主义哲学要求我们在掌握对立统一规律的基础上，全面完整地掌握唯物辩证法的科学理 论体系。","explanation":"（1）在唯物辩证法的理论体系中，对立统一规律占有十分重要的地位，是唯物辩证法的实质与核 心。 第一，唯物辩证法揭示的是事物的联系与发展，而对立统一规律揭示的是普遍联系的根本内容和永恒发展的 根本动力，也就是说，所谓联系实质上是矛盾与矛盾、矛盾这方面与矛盾那方面的联系，所谓发展实质上是 矛盾推动下的发展。 第二，唯物辩证法是有着丰富内容的完整的科学理论体系，而对立统一规律则是理解唯物辩证法全部理论的 关键，唯物辩证法的其他规律与范畴都是对立统一规律在某一方面的展开。 第三，唯物辩证法与形而上学是两种根本对立的世界观，而是否承认矛盾则是唯物辩证法与形而上学对立的 焦点。 第四，唯物辩证法既是世界观，又是方法论，矛盾分析法则是最根本的认识方法。 （2）唯物辩证法是一个内容丰富的完整理论体系，对立统一规律是唯物辩证法的实质与核心，但不是唯物辩 证法的总体。马克思主义哲学要求我们在掌握对立统一规律的基础上，全面完整地掌握唯物辩证法的科学理 论体系。","score":10},{"id":"yc-1-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"简述“工农武装割据”的思想内容。","answer":"第一，土地革命是中国革命的基本内容，农民是民主革命的主力军，只有满足了农民的土地要求 ，才能最广泛地动员和组织广大农民群众参加武装斗争，巩固和扩大革命根据地。 第二，武装斗争是中国民主革命的主要斗争形式，是进行土地革命，巩固和发展革命根据地的最有力的工具 。 第三，农村根据地是中国民主革命的战略基地，是开展土地革命，实行武装斗争的基础和依托。","explanation":"第一，土地革命是中国革命的基本内容，农民是民主革命的主力军，只有满足了农民的土地要求 ，才能最广泛地动员和组织广大农民群众参加武装斗争，巩固和扩大革命根据地。 第二，武装斗争是中国民主革命的主要斗争形式，是进行土地革命，巩固和发展革命根据地的最有力的工具 。 第三，农村根据地是中国民主革命的战略基地，是开展土地革命，实行武装斗争的基础和依托。","score":10},{"id":"yc-1-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"“一国两制”构想的基本内容是什么？","answer":"“一国两制”是“一个国家，两种制度”的简称。“一国两制”构想是邓小平理论的重要组成部 分。其基本内容是： （1）坚持“一个中国”。世界上只有一个中国，中国的中央政府在北京，在国际上代表中国的只能是中华人 民共和国。 （2）实行“两种制度”。在统一的中华人民共和国内，作为国家主体的大陆地区坚持社会主义制度，台湾、 香港、澳门则保持原有的资本主义制度和生活方式，两种制度长期共存。 （3）设置特别行政区，保证台湾、香港、澳门的高度自治和繁荣稳定。 （4）实行“一国两制”长期不变。这种不变，既是承诺，又有《基本法》作保障。","explanation":"“一国两制”是“一个国家，两种制度”的简称。“一国两制”构想是邓小平理论的重要组成部 分。其基本内容是： （1）坚持“一个中国”。世界上只有一个中国，中国的中央政府在北京，在国际上代表中国的只能是中华人 民共和国。 （2）实行“两种制度”。在统一的中华人民共和国内，作为国家主体的大陆地区坚持社会主义制度，台湾、 香港、澳门则保持原有的资本主义制度和生活方式，两种制度长期共存。 （3）设置特别行政区，保证台湾、香港、澳门的高度自治和繁荣稳定。 （4）实行“一国两制”长期不变。这种不变，既是承诺，又有《基本法》作保障。","score":10},{"id":"yc-1-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(一) · 简答题 (10分)","stem":"为什么说“三个代表”重要思想是我们党的立党之本、执政之基、力量之源？","answer":"（1）“三个代表”重要思想是党的立党之本。“三个代表”重要思想深刻揭示了党的性质、宗旨 的深刻内涵，集中体现了党的性质、宗旨的精神实质。什么时候坚持了“三个代表”重要思想，党就会兴旺 发达，就能够不断地向前发展。反之，什么时候偏离或没有完全做到“三个代表”重要思想，党就会遇到失 误和挫折，就会蜕化变质走向自己的反面。正是从这个意义上说，“三个代表”重要思想是党的性质最集中 、最完整的展示，是决定党的生死存亡的根本。 （2）“三个代表”重要思想是党的执政之基。我们党的执政地位是历史赋予的、人民赋予的。我们党执政的 内容和任务，就是要不断解放和发展中国社会的生产力，增强综合国力，推进社会发展；就是要不断建设和 发展社会主义文化，培育“四有”公民：弘扬民族精神；就是要全心全意为人民服务，维护最广大人民的根 本利益，不断提高人民生活的质量和水平。“三个代表”重要思想从根本上说明了我们党执政的基础、内容 、任务和要求。所以，只有始终做到“三个代表”重要思想，用好人民赋予的执政权力，不断提高党的领导 水平和执政水平，不断增强抵御风险和拒腐防变能力，才能巩固党的执政基础，使党真正成为中国社会主义 事业坚强有力的领导核心。 （3）“三个代表”重要思想是党的力量之源。我们党所以能获得人民的拥护，是因为我们党作为中国工人阶 级的先锋队，在革命、建设、改革的各个历史时期，能经受各种风浪、磨难的考验，不断发展壮大，并得到 人民群众的衷心拥护和支持，归根结底就在于我们党能够始终促进中国社会生产力的发展，推动中国先进文 化的前进，切切实实地为人民办实事、谋利益。人民群众的拥护和支持是我们党的力量之源，是我们党能够 取得伟大胜利的真谛。","explanation":"（1）“三个代表”重要思想是党的立党之本。“三个代表”重要思想深刻揭示了党的性质、宗旨 的深刻内涵，集中体现了党的性质、宗旨的精神实质。什么时候坚持了“三个代表”重要思想，党就会兴旺 发达，就能够不断地向前发展。反之，什么时候偏离或没有完全做到“三个代表”重要思想，党就会遇到失 误和挫折，就会蜕化变质走向自己的反面。正是从这个意义上说，“三个代表”重要思想是党的性质最集中 、最完整的展示，是决定党的生死存亡的根本。 （2）“三个代表”重要思想是党的执政之基。我们党的执政地位是历史赋予的、人民赋予的。我们党执政的 内容和任务，就是要不断解放和发展中国社会的生产力，增强综合国力，推进社会发展；就是要不断建设和 发展社会主义文化，培育“四有”公民：弘扬民族精神；就是要全心全意为人民服务，维护最广大人民的根 本利益，不断提高人民生活的质量和水平。“三个代表”重要思想从根本上说明了我们党执政的基础、内容 、任务和要求。所以，只有始终做到“三个代表”重要思想，用好人民赋予的执政权力，不断提高党的领导 水平和执政水平，不断增强抵御风险和拒腐防变能力，才能巩固党的执政基础，使党真正成为中国社会主义 事业坚强有力的领导核心。 （3）“三个代表”重要思想是党的力量之源。我们党所以能获得人民的拥护，是因为我们党作为中国工人阶 级的先锋队，在革命、建设、改革的各个历史时期，能经受各种风浪、磨难的考验，不断发展壮大，并得到 人民群众的衷心拥护和支持，归根结底就在于我们党能够始终促进中国社会生产力的发展，推动中国先进文 化的前进，切切实实地为人民办实事、谋利益。人民群众的拥护和支持是我们党的力量之源，是我们党能够 取得伟大胜利的真谛。","score":10},{"id":"yc-1-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(一) · 论述题 (20分)","stem":"我国实行对外开放，为什么必须坚持独立自主、自力更生的方针？","answer":"（1）我国是社会主义国家，必须维护国家的政治、经济的独立自主权利，决不允许别国干涉。 （2）我国是拥有十几亿人口的大国，现代化建设不可能依靠别人，必须立足于依靠本国人民的力量。 （3）强调独立自主、自力更生，可以调动全国人民的积极性、创造性，促使人们奋发努力。（4）取得外援 要付出代价，放弃自力更生，就会丧失独立自主的权利。","explanation":"（1）我国是社会主义国家，必须维护国家的政治、经济的独立自主权利，决不允许别国干涉。 （2）我国是拥有十几亿人口的大国，现代化建设不可能依靠别人，必须立足于依靠本国人民的力量。 （3）强调独立自主、自力更生，可以调动全国人民的积极性、创造性，促使人们奋发努力。（4）取得外援 要付出代价，放弃自力更生，就会丧失独立自主的权利。","score":20},{"id":"yc-1-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(一) · 论述题 (20分)","stem":"简述意识的能动作用的主要表现。","answer":"（1）意识活动具有目的性和计划性。人在认识客观世界、尊重客观规律的同时，还总是根据一定的 目的和要求去确定反映什么、不反映什么，以及怎样反映，从而表现出主体的选择性。 （2）意识活动具有创造性。人的意识不仅采取感觉、知觉、表象等形式，反映事物的外部现象，而且运用概 念、判断、推理等形式，对感性材料进行加工制作和选择建构，在思维中构造一个现实中所没有的理想世界 。 （3）意识具有指导实践改造客观世界的作用。意识的能动作用不限于从实践中形成一定的思想，形成活动的 目的、计划、方法等观念的东西，更重要的在于以这些观念的东西为指导，通过实践使之一步步变为客观现 实。 （4）意识具有调控人的行为和生理活动的作用。现代科学和医学实验证明：意识、心理因素能够对人的行为 选择和健康状况产生重要影响。","explanation":"（1）意识活动具有目的性和计划性。人在认识客观世界、尊重客观规律的同时，还总是根据一定的 目的和要求去确定反映什么、不反映什么，以及怎样反映，从而表现出主体的选择性。 （2）意识活动具有创造性。人的意识不仅采取感觉、知觉、表象等形式，反映事物的外部现象，而且运用概 念、判断、推理等形式，对感性材料进行加工制作和选择建构，在思维中构造一个现实中所没有的理想世界 。 （3）意识具有指导实践改造客观世界的作用。意识的能动作用不限于从实践中形成一定的思想，形成活动的 目的、计划、方法等观念的东西，更重要的在于以这些观念的东西为指导，通过实践使之一步步变为客观现 实。 （4）意识具有调控人的行为和生理活动的作用。现代科学和医学实验证明：意识、心理因素能够对人的行为 选择和健康状况产生重要影响。","score":20}]},{"id":"yc-2","title":"2026年成考预测试卷(二)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-2-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法认为，联系是以（ ）","options":["事物的区别为前提的","事物的共同性为前提的","事物之间相互转化为前提的","事物的发展为前提的"],"answer":0,"answerLetter":"A","explanation":"唯物辩证法认为，联系是指事物内部各要素之间和事物之间相互影响、相互制约和相互作用的关系 。联系是以事物之间以及事物内部诸要素之间的差别为前提的，没有区别就无所谓联系，是对立统一的关系 。","score":2},{"id":"yc-2-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(二) · 单选","stem":"系统论的基本原则是（ ）","options":["区别性","整体性","合理性","联系性"],"answer":1,"answerLetter":"B","explanation":"系统论强调将事物看作一个整体，整体具有不同于部分简单相加的特性和功能，整体性是系统论的 核心和基本原则。答案选B。","score":2},{"id":"yc-2-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法的总特征是（ ）","options":["运动变化的科学","事物矛盾的科学","联系和发展的科学","否定之否定的科学"],"answer":2,"answerLetter":"C","explanation":"唯物辩证法认为世界是普遍联系和永恒发展的，联系的观点和发展的观点是唯物辩证法的总特征。 A选项运动变化表述不准确；B选项事物矛盾是唯物辩证法的实质和核心；D选项否定之否定是唯物辩证法的三 大规律之一。","score":2},{"id":"yc-2-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法的本质和核心是（ ）","options":["因果的必然性","对立统一规律","质量与变化规律","否定之否定规律"],"answer":1,"answerLetter":"B","explanation":"在唯物辩证法中，对立统一规律揭示了事物发展的源泉和动力，贯穿于其他规律和范畴之中，是理 解其他规律和范畴的钥匙，所以它是唯物辩证法的本质和核心。","score":2},{"id":"yc-2-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(二) · 单选","stem":"唯物辩证法与形而上学的根本对立的焦点是（ ）","options":["联系的观点与孤立的观点的对立","发展的观点与不变的观点的对立","全面的观点与片面的观点的对立","是否承认矛盾及矛盾是事物发展根本动力观点的对立"],"answer":3,"answerLetter":"D","explanation":"唯物辩证法和形而上学对立的焦点在于是否承认矛盾，矛盾是唯物辩证法的实质与核心，承认矛盾 推动事物发展是唯物辩证法观点，不承认则是形而上学。前三个选项都是二者对立的表现，但不是根本焦点 。","score":2},{"id":"yc-2-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(二) · 单选","stem":"真理一元论认为对于一个确定的对象（ ）","options":["只能有一种认识","正确的认识只有一个","正确的认识只能一次获得","正确的认识只能用一种方法获得"],"answer":1,"answerLetter":"B","explanation":"真理一元论强调在同一条件下，对同一对象的真理性认识只有一个，因为真理具有客观性，符合客 观事物及其规律的正确认识只有一个。","score":2},{"id":"yc-2-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(二) · 单选","stem":"真理是人造的供人使用的工具的看法是（ ）","options":["主观唯心主义","客观唯物主义","机械唯物主义","辩证唯物主义"],"answer":0,"answerLetter":"A","explanation":"认为真理是人造的供人使用的工具，这把真理的判定完全归于人的主观意愿，以人的主观需求来定 义真理，而不是基于客观实际。 主观唯心主义把人的主观精神，如感觉、经验、心灵等当作世界的本原。这 种对真理的看法正是将人的主观意志凌驾于客观之上，属于主观唯心主义观点。","score":2},{"id":"yc-2-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(二) · 单选","stem":"真理的发展是一个（ ） A，真理和谬论不断调和的过程 B.真理和谬论相互补充的过程 C.真理和谬论相互转化的过程 D.由相对真理向绝对真理转化的过程","options":["a","b","c","d"],"answer":3,"answerLetter":"D","explanation":"真理和谬误是对立统一的，但不是不断调和与相互补充，A、B 错误；真理和谬误在一定条件下相互 转化，但这不是真理发展的本质，C 不准确。真理的发展是由相对真理不断向绝对真理转化的过程，这是真 理发展的规律。","score":2},{"id":"yc-2-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(二) · 单选","stem":"实践标准的不确定性是因为（ ）","options":["有些真理根本无法通过实践来检验","实践检验必须有逻辑证明来补充","社会实践总受历史条件的限制","不同人、不同阶级有不同实践"],"answer":2,"answerLetter":"C","explanation":"实践标准的不确定性是指实践对真理的检验是一个过程，受到一定历史条件的制约。A选项说法错误 ，所有真理都能通过实践检验；B选项逻辑证明是对实践检验的补充，但不是实践标准不确定性的原因；D选 项不同人、不同阶级实践不同并非实践标准不确定性的根源。实践标准不确定性主要源于社会实践受历史条 件限制。","score":2},{"id":"yc-2-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(二) · 单选","stem":"划分唯物史观与唯心史观的根本标准是（ ）","options":["是否承认阶级斗争","是否承认社会历史的规律性","是否承认社会意识的能动作用","是否承认社会存在决定社会意识"],"answer":3,"answerLetter":"D","explanation":"唯物史观认为社会存在决定社会意识，唯心史观认为社会意识决定社会存在，二者的根本分歧就在 于对社会存在和社会意识何者为第一性的不同回答，这也是划分唯物史观与唯心史观的根本标准。","score":2},{"id":"yc-2-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东思想产生的时代特点是（ ）","options":["战争与革命","和平与发展","资本主义上升","帝国主义腐朽没落"],"answer":0,"answerLetter":"A","explanation":"毛泽东思想形成和发展于20世纪前中期，当时时代的主要特点是战争与革命。1914年第一次世界大 战爆发，1917年俄国十月革命胜利，开启了世界无产阶级革命的新时代，这一时期战争与革命成为时代主题 。B选项和平与发展是邓小平理论形成时的时代主题；C选项资本主义上升时期并非毛泽东思想产生时代的主 要特征；D选项帝国主义腐朽没落表述片面，战争与革命才是当时整体时代特点。","score":2},{"id":"yc-2-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东思想产生的思想理论条件是（ ）","options":["三民主义","马列主义的传播","实用主义","空想社会主义"],"answer":1,"answerLetter":"B","explanation":"毛泽东思想是马克思列宁主义基本原理和中国革命具体实际相结合的产物，马列主义的传播为毛泽 东思想的产生提供了思想理论条件。而三民主义是孙中山所倡导的民主革命纲领；实用主义是西方哲学流派 ；空想社会主义是现代社会主义思想的来源之一，但都不是毛泽东思想产生的思想理论条件。","score":2},{"id":"yc-2-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东思想产生的实践基础是（ ）","options":["辛亥革命","五四运动","新文化运动","党领导的人民革命"],"answer":3,"answerLetter":"D","explanation":"毛泽东思想是中国共产党领导中国人民在进行革命和建设的实践过程中形成的理论成果。党领导的 人民革命为毛泽东思想的产生提供了丰富素材和实践基础。辛亥革命、五四运动、新文化运动虽对中国社会 发展有重要意义，但并非毛泽东思想产生的实践基础。","score":2},{"id":"yc-2-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(二) · 单选","stem":"第一次提出毛泽东思想这一概念的是（ ）","options":["朱德","刘少奇","王稼祥","周恩来"],"answer":2,"answerLetter":"C","explanation":"1943年7月，王稼祥在《中国共产党与中国民族解放的道路》一文中，首次提出“毛泽东思想”这一 科学概念。","score":2},{"id":"yc-2-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(二) · 单选","stem":"正式规定毛泽东思想为党的一切工作的指导思想会议是（ ）","options":["遵义会议","古田会议","中共六大","中共七大"],"answer":3,"answerLetter":"D","explanation":"中共七大正式确立毛泽东思想为党的指导思想并写入党章 。遵义会议事实上确立了以毛泽东为核心 的党中央的正确领导；古田会议确立了思想建党、政治建军原则；中共六大在莫斯科召开，主要是为了系统 地总结第一次国内革命的经验教训，批判右倾投降主义和“左”倾盲动主义的错误 。","score":2},{"id":"yc-2-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(二) · 单选","stem":"第一次国共合作的政治基础和共同纲领是（ ）","options":["三民主义","三大政策","民主革命纲领","新三民主义"],"answer":3,"answerLetter":"D","explanation":"新三民主义与中国共产党的民主革命纲领在若干基本原则上是一致的，成为第一次国共合作的政治 基础和共同纲领。三民主义未明确反帝反封建，不能成为合作基础；三大政策是实现新三民主义的方法和手 段；中共民主革命纲领与新三民主义有区别。","score":2},{"id":"yc-2-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(二) · 单选","stem":"1935年12月，毛泽东系统地阐述抗日民族统一战线新政策的会议是（ ）","options":["瓦窑堡会议","洛川会议","遵义会议","延安会议"],"answer":0,"answerLetter":"A","explanation":"1935 年 12 月，中共中央在陕北瓦窑堡召开政治局会议，提出了在抗日的条件下与民族资产阶级重 建统一战线的新政策，系统地阐述了抗日民族统一战线新政策。洛川会议是制定全面抗战路线；遵义会议是 结束“左”倾错误在中央的统治；延安会议主要是为了确定党在抗日民族统一战线新形势下的新任务。所以 答案是 A 选项瓦窑堡会议。","score":2},{"id":"yc-2-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(二) · 单选","stem":"中国革命的特点和优点是（ ）","options":["它是由中国共产党领导的人民革命","它的目标是争取民族独立，人民解放，最终实现国家的繁荣富强","它以反帝反封建作为两大革命任务","它以武装的革命反抗武装的反革命"],"answer":3,"answerLetter":"D","explanation":"武装斗争是中国革命的主要斗争形式，以武装的革命反抗武装的反革命，这是中国革命的特点和优 点之一 。因为中国反动统治阶级异常残暴且掌握庞大反革命武装，这就决定中国革命只能走武装斗争道路。","score":2},{"id":"yc-2-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(二) · 单选","stem":"毛泽东关于党的建设理论最核心的内容和最主要的特点是（ ）","options":["着重于从思想上建设党","加强党的组织建设","加强党员的党性修养","保持党的优良作风"],"answer":0,"answerLetter":"A","explanation":"毛泽东关于党的建设理论中，着重从思想上建党是最核心内容和主要特点。这是基于中国特殊国情 ，党员多来自农民和小资产阶级，只有从思想上建党，才能保证党的无产阶级先锋队性质。","score":2},{"id":"yc-2-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(二) · 单选","stem":"中国共产党各方面建设的基础是（ ）","options":["组织建设","思想建设","作风建设","政治建设"],"answer":1,"answerLetter":"B","explanation":"思想建设解决的是党员的理想信念、认识水平等根本性问题，为党的其他各项建设提供思想基础。 只有思想上清醒坚定，组织建设、作风建设、政治建设等才有坚实保障。","score":2},{"id":"yc-2-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(二) · 单选","stem":"我国农业合作化的方针是（ ）","options":["积极领导，稳步前进","自愿互利，典型示范，国家帮助","循序渐进，由初级到高级","先合作化，后机械化"],"answer":0,"answerLetter":"A","explanation":"我国农业合作化的方针是积极领导、稳步前进。B选项是农业合作化遵循的原则；C选项是农业合作 化的步骤特点；D选项是农业合作化与机械化的关系。","score":2},{"id":"yc-2-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(二) · 单选","stem":"我国农业合作化的原则是（ ）","options":["积极领导，稳步前进","自愿互利，典型示范，国家帮助","先合作化，后机械化","循序渐进，由初级到高级"],"answer":1,"answerLetter":"B","explanation":"我国农业合作化遵循自愿互利、典型示范和国家帮助的原则，引导农民走合作化道路。A选项是农业 合作化的方针；C选项是农业合作化与机械化的关系特点；D选项是农业合作化的步骤特点。","score":2},{"id":"yc-2-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(二) · 单选","stem":"我国农业合作化的步骤是（ ）","options":["积极领导，稳步前进","自愿互利，典型示范，国家帮助","先合作化，后机械化","循序渐进，由初级到高级"],"answer":3,"answerLetter":"D","explanation":"我国农业合作化遵循循序渐进的原则，经历了由互助组到初级社再到高级社的由低级到高级的步骤 。A选项“积极领导，稳步前进”是农业合作化的方针；B选项“自愿互利，典型示范，国家帮助”是农业合 作化的原则；C选项“先合作化，后机械化”是关于农业改造和发展的一种思路，并非农业合作化步骤。答案 选D。","score":2},{"id":"yc-2-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(二) · 单选","stem":"在土地改革完成以后，我国的社会主要矛盾是（ ）","options":["农民与地主阶级的矛盾","中华民族同帝国主义的矛盾","工人阶级同资产阶级的矛盾","人民大众同国民党的矛盾"],"answer":2,"answerLetter":"C","explanation":"土地改革完成后，地主阶级被基本消灭，A选项农民与地主阶级矛盾不再是主要矛盾；新中国成立后 ，帝国主义势力基本被清除，B选项中华民族同帝国主义矛盾已不是主要的；国民党在大陆统治已被推翻 ，D选项人民大众同国民党矛盾也不是主要矛盾。而随着土地改革完成，国内阶级关系发生变化，工人阶级和 资产阶级的矛盾逐渐突出。答案选C。","score":2},{"id":"yc-2-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(二) · 单选","stem":"1956年社会主义三大改造基本完成，标志着我国已进入（ ）","options":["共产主义社会","社会主义初级阶段","资本主义社会","新民主主义社会"],"answer":1,"answerLetter":"B","explanation":"1956 年社会主义三大改造基本完成，使中国进入社会主义初级阶段。共产主义社会是社会主义发展 的高级阶段，当时远未达到；中国在改造后告别了资本主义社会；新民主主义社会是过渡阶段，三大改造完 成就结束了这一阶段。","score":2},{"id":"yc-2-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(二) · 单选","stem":"坚持社会主义初级阶段基本路线100年不动摇的关键是坚持（ ）","options":["以经济建设为中心不动摇","四项基本原则不动摇","改革开放不动摇","自力更生，艰苦创业不动摇"],"answer":0,"answerLetter":"A","explanation":"以经济建设为中心是兴国之要，是我们党、我们国家兴旺发达和长治久安的根本要求。社会主义初 级阶段基本路线的核心是“一个中心，两个基本点”，坚持党的基本路线不动摇，关键是坚持以经济建设为 中心不动摇。答案：A。","score":2},{"id":"yc-2-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(二) · 单选","stem":"我国社会主义建设的目标是（ ）","options":["实现农业、工业、国防和科技现代化","实现工业化和经济的社会化、市场化和现代化","实现经济、政治、文化现代化","把我国建设成为富强、民主、文明、和谐的社会主义现代化国家"],"answer":3,"answerLetter":"D","explanation":"我国社会主义建设目标即社会主义初级阶段的奋斗目标，是把我国建设成为富强、民主、文明、和 谐、美丽的社会主义现代化强国（题干选项为早期表述）。A选项“四个现代化”是特定时期目标；B选项表 述侧重经济方面；C选项表述不全面。D选项全面涵盖了各方面，是正确的建设目标表述。","score":2},{"id":"yc-2-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(二) · 单选","stem":"我国社会主义建设发展战略的第三步是指，到21世纪中叶，人均国民生产总值要（ ）","options":["达到发达国家水平","接近国家水平","接近中等发达国家水平","达到中等发达国家水平"],"answer":3,"answerLetter":"D","explanation":"我国社会主义建设发展战略第三步目标是到21世纪中叶，人均国民生产总值达到中等发达国家水平 ，人民生活比较富裕，基本实现现代化。","score":2},{"id":"yc-2-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(二) · 单选","stem":"我国社会主义建设发展战略的出发点和归宿点是（ ）","options":["发展生产力","提高综合国力","提高人民生活水平","实现现代化"],"answer":2,"answerLetter":"C","explanation":"我国社会主义建设各项战略举措，根本目的都是为了人民，让人民过上更好生活。发展生产力、提 高综合国力、实现现代化最终都是为提高人民生活水平服务。所以出发点和归宿点是提高人民生活水平。答 案：C","score":2},{"id":"yc-2-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(二) · 单选","stem":"我国的国民经济基础是（ ）","options":["农业","工业","支柱产业","信息产业"],"answer":0,"answerLetter":"A","explanation":"农业是人类社会的衣食之源，生存之本，是支撑国民经济建设与发展的基础产业。而工业是国民经 济的主导，支柱产业对国民经济发展起支撑作用，信息产业属于新兴产业，并非基础。","score":2},{"id":"yc-2-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(二) · 单选","stem":"发展社会主义文化必须坚持的二为方向是（ ）","options":["为精神文明建设服务，为物质文明建设服务","为人民服务，为社会主义服务","为政治稳定服务，为经济发展服务","为党的工作服务，为行政工作服务"],"answer":1,"answerLetter":"B","explanation":"发展社会主义文化要坚持为人民服务、为社会主义服务的方向，这是社会主义文化建设的根本方向 。“二为”方向明确了文化工作的服务对象和目标。答案选B 。","score":2},{"id":"yc-2-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(二) · 单选","stem":"社会主义道德的核心和集中体现是","options":["爱国主义","社会主义","集体主义","为人民服务"],"answer":3,"answerLetter":"D","explanation":"社会主义道德以为人民服务为核心，这是社会主义本质特征的集中体现，也是社会主义道德区别和 优越于其他社会形态道德的显著标志。集体主义是社会主义道德的原则。爱国主义是民族精神的核心。社会 主义是一种社会制度和思想体系等。答案选D。","score":2},{"id":"yc-2-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(二) · 单选","stem":"社会主义道德建设的原则是（ ）","options":["毫不利己，专门利人","集体主义","全心全意为人民服务","个人主义"],"answer":1,"answerLetter":"B","explanation":"社会主义道德建设以为人民服务为核心，以集体主义为原则。A选项“毫不利己，专门利人”是一种 高尚道德境界的体现，但不是原则；C选项全心全意为人民服务是核心；D选项个人主义与社会主义道德建设 相悖。","score":2},{"id":"yc-2-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(二) · 单选","stem":"提出两岸尽快实现三通的是（ ）","options":["《告台湾同胞书》","叶剑英九条方针","《中国大陆和台湾和平统一的设想》","《为促进祖国统一而继续奋斗》"],"answer":0,"answerLetter":"A","explanation":"1979 年全国人大常委会发表《告台湾同胞书》，其中提出两岸尽快实现通航通邮通商。答案：A 。","score":2},{"id":"yc-2-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(二) · 单选","stem":"我国实行一国两制不会改变人民民主专政国家的社会主义性质。这是因为（ ）","options":["特别行政区只是中华人民共和国的一个行政区域","特别行政区政府是在中华人民共和国中央人民政府的统一领导下","特别行政区享有内地一般地方行政区域所没有的高度自治权","两种制度的地位不同，社会主义制度是主体"],"answer":3,"answerLetter":"D","explanation":"“一国两制”下，社会主义制度是主体，决定了国家的社会主义性质，这是我国实行“一国两制 ”不会改变人民民主专政国家社会主义性质的根本原因。","score":2},{"id":"yc-2-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"简述实践及其对认识的决定作用。","answer":"（1）实践是指人类能动地改造和探索现实世界的一切社会性的客观物质活动，具有自觉能动性、 客观物质性和社会历史性等三个特点，表现为生产实践、处理社会关系实践和科学实验等三种基本形式。 （2）在实践和认识的辩证关系中，实践是认识的基础，实践决定认识。这表现在： 第一，实践是认识的来源。首先，实践的需要决定认识的产生，也就是说，人们改造世界的需要产生了认识 世界的需要。其次，实践出真知，人类的一切认识，无论直接经验，还是间接经验，归根结底都是来自实践 的。 第二，实践是认识发展的动力。首先，实践不断给人们提出新的认识课题，并提供解决新课题的新的经验材 料。其次，实践的发展不断给人们提供日益完备的认识手段和物质条件。再次，实践不断推动人的认识能力 的提高。 第三，实践是检验认识正确与否的唯一标准，除此之外，再无其他标准。 第四，实践是认识的最终目的，正确认识世界的目的是为了有效改造世界。","explanation":"（1）实践是指人类能动地改造和探索现实世界的一切社会性的客观物质活动，具有自觉能动性、 客观物质性和社会历史性等三个特点，表现为生产实践、处理社会关系实践和科学实验等三种基本形式。 （2）在实践和认识的辩证关系中，实践是认识的基础，实践决定认识。这表现在： 第一，实践是认识的来源。首先，实践的需要决定认识的产生，也就是说，人们改造世界的需要产生了认识 世界的需要。其次，实践出真知，人类的一切认识，无论直接经验，还是间接经验，归根结底都是来自实践 的。 第二，实践是认识发展的动力。首先，实践不断给人们提出新的认识课题，并提供解决新课题的新的经验材 料。其次，实践的发展不断给人们提供日益完备的认识手段和物质条件。再次，实践不断推动人的认识能力 的提高。 第三，实践是检验认识正确与否的唯一标准，除此之外，再无其他标准。 第四，实践是认识的最终目的，正确认识世界的目的是为了有效改造世界。","score":10},{"id":"yc-2-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"简述走农村包围城市，武装夺取政权道路的必要性。","answer":"第一，中国是一个半殖民地半封建国家，外部没有民族独立而受帝国主义压迫，内部没有民主制度 而受封建制度压迫，无产阶级及其政党无议会可以利用，没有组织工人罢工的合法权利，只能以武装的革命 反对武装的反革命。 第二，中国是一个经济落后的农业大国，农民占全国人口总数的80％以上，这就决定了农民是民主革命的主 力军。中国的民主革命实质上是农民革命，武装斗争实质上是无产阶级领导的以农民为主力军的革命斗争。 “工农武装割据”是无产阶级领导的革命斗争的最高形式。 第三，大革命失败后，中国共产党人多次奋斗的结局也证明，革命在城市首先取得胜利的可能性已不存在 ，而反动统治相对薄弱的广大农村地区，正是实行“工农武装割据”的革命阵地和夺取城市、夺取全国政权 的出发点。","explanation":"第一，中国是一个半殖民地半封建国家，外部没有民族独立而受帝国主义压迫，内部没有民主制度 而受封建制度压迫，无产阶级及其政党无议会可以利用，没有组织工人罢工的合法权利，只能以武装的革命 反对武装的反革命。 第二，中国是一个经济落后的农业大国，农民占全国人口总数的80％以上，这就决定了农民是民主革命的主 力军。中国的民主革命实质上是农民革命，武装斗争实质上是无产阶级领导的以农民为主力军的革命斗争。 “工农武装割据”是无产阶级领导的革命斗争的最高形式。 第三，大革命失败后，中国共产党人多次奋斗的结局也证明，革命在城市首先取得胜利的可能性已不存在 ，而反动统治相对薄弱的广大农村地区，正是实行“工农武装割据”的革命阵地和夺取城市、夺取全国政权 的出发点。","score":10},{"id":"yc-2-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"简述人民民主专政理论的基本内容。","answer":"第一，论述了在中国建立人民民主专政的历史必然性。 第二，科学地分析了各个阶级在人民民主专政国家政权中的地位及其相互地位。 第三，论述了人民民主专政的本质特征。 第四，论述了人民民主专政的职能和任务。人民民主专政的职能和任务，对外是防止帝国主义与各国反动派 的颠覆和破坏，维护国家的独立和安全，维护世界和平；对内是镇压敌对势力的反抗，保护人民民主权利 ，组织和管理国家经济建设，发展社会生产力，促进中国由农业国向工业国、由新民主主义向社会主转变 ，并最终实现消灭一切阶级和一切国家的伟大目标。","explanation":"第一，论述了在中国建立人民民主专政的历史必然性。 第二，科学地分析了各个阶级在人民民主专政国家政权中的地位及其相互地位。 第三，论述了人民民主专政的本质特征。 第四，论述了人民民主专政的职能和任务。人民民主专政的职能和任务，对外是防止帝国主义与各国反动派 的颠覆和破坏，维护国家的独立和安全，维护世界和平；对内是镇压敌对势力的反抗，保护人民民主权利 ，组织和管理国家经济建设，发展社会生产力，促进中国由农业国向工业国、由新民主主义向社会主转变 ，并最终实现消灭一切阶级和一切国家的伟大目标。","score":10},{"id":"yc-2-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(二) · 简答题 (10分)","stem":"我国独立自主的外交政策体现在哪些方面？我国为什么必须实行对外开放？","answer":"我国独立自主的外交政策体现在： 坚持独立自主。这是指国家的主权是独立的，不允许任何外来的干涉与侵犯，每个国家都有权根据自己的实 际情况独立地、自主地处理本国对内对外一切事物。坚持独立自主，主要体现在：①坚持把国家主权和国家 利益放在首位。主权是国家的根本属性，是一个国家独立自主地处理对内对外事物的最高权力。国家活动的 目的是追求国家利益，处理国与国之间关系主要应该从国家自身的战略利益出发，以自己国家的利益为最高 准则。②真正的不结盟。不结盟就是不参加任何国家集团与军事集团，不同任何国家结成同盟。只有不结盟 才能更有效地、独立自主地处理各种事物，③反对霸权主义和强权政治。霸权主义和强权政治是威胁世界和 平与稳定，干涉、侵犯他国主权的主要根源。反对霸权主义和强权政治是我国外交政策的纲领。 （2）维护世界和平。争取世界和平是我国对外政策的首要任务。维护世界和平，主要体现在：①坚持和平共 处五项原则。和平共处五项原则，是指在处理国家之间的关系中，坚持相互尊重主权和领土完整、互不侵犯 、互不干涉内政、平等互利、和平共处的原则。和平共处五项原则是处理国与国之间关系的最好形式。②通 过对话协商解决国与国之间存在的分歧和争端。我们坚持反对诉诸武力或以武力相威胁。③建立国际政治经 济新秩序。建立国际新秩序，核心是强调不干涉别国的内政，尊重和维护世界各国的主权独立和国家利益 ，建立民主、平等、合理、公正的新型国际关系，以促进世界的持久和平与人类的共同繁荣。 实行对外开放的原因： （1）对外开放作为我国一项长期的基本国策是经济生活国际化的客观要求，也是对当代世界经济、科技发展 和国际形势发展敏锐观察的结果。现在的世界是开放的世界，科学技术发展一日千里，只有参与国际经济竞 争与合作，充分利用国际经济资源和科技成果，才能发展自己，赶上当代世界的科技和经济发展潮流。 （2）对外开放作为我国一项长期的基本国策是对中国长期停滞落后的历史教训深刻总结的结果。长期闭关自 守，把我国搞得贫穷落后，愚昧无知。历史的经验一再告诉我们，关起门来搞建设是不行的，把自己孤立于 世界之外是不利的。中国的发展离不开世界。 （3）对外开放作为我国一项长期的基本国策是我国社会主义现代化建设的迫切需要。扩大对外开放，可以引 进国外资金、先进的技术设备和管理经验、人才，以克服我国资金短缺、技术落后、管理经验不足等困难 ；可以充分利用国外资源，大力开拓国际市场，通有无，取长补短，趋利避害，促进我国经济发展；可以参 与国际经济、科学、技术，人才和信息的交流，有利于我们及时了解和掌握各种经济、科技信息；可以广泛 吸收世界文明成果，发挥后发优势，在较高的技术基础上发展经济，尽快缩小与发达国家经济技术发展程度 的差距。 总之，我国必须坚持对外开放和独立自主、自力更生的统一。独立自主、自力更生，是我国进行现代化建设 的立足点和基点。独立自主、自力更生是对外开放的前提和基础，而对外开放可以加快经济发展，增强国家 综合国力，从而提高独立自主、自力更生的能力和水平。","explanation":"我国独立自主的外交政策体现在： 坚持独立自主。这是指国家的主权是独立的，不允许任何外来的干涉与侵犯，每个国家都有权根据自己的实 际情况独立地、自主地处理本国对内对外一切事物。坚持独立自主，主要体现在：①坚持把国家主权和国家 利益放在首位。主权是国家的根本属性，是一个国家独立自主地处理对内对外事物的最高权力。国家活动的 目的是追求国家利益，处理国与国之间关系主要应该从国家自身的战略利益出发，以自己国家的利益为最高 准则。②真正的不结盟。不结盟就是不参加任何国家集团与军事集团，不同任何国家结成同盟。只有不结盟 才能更有效地、独立自主地处理各种事物，③反对霸权主义和强权政治。霸权主义和强权政治是威胁世界和 平与稳定，干涉、侵犯他国主权的主要根源。反对霸权主义和强权政治是我国外交政策的纲领。 （2）维护世界和平。争取世界和平是我国对外政策的首要任务。维护世界和平，主要体现在：①坚持和平共 处五项原则。和平共处五项原则，是指在处理国家之间的关系中，坚持相互尊重主权和领土完整、互不侵犯 、互不干涉内政、平等互利、和平共处的原则。和平共处五项原则是处理国与国之间关系的最好形式。②通 过对话协商解决国与国之间存在的分歧和争端。我们坚持反对诉诸武力或以武力相威胁。③建立国际政治经 济新秩序。建立国际新秩序，核心是强调不干涉别国的内政，尊重和维护世界各国的主权独立和国家利益 ，建立民主、平等、合理、公正的新型国际关系，以促进世界的持久和平与人类的共同繁荣。 实行对外开放的原因： （1）对外开放作为我国一项长期的基本国策是经济生活国际化的客观要求，也是对当代世界经济、科技发展 和国际形势发展敏锐观察的结果。现在的世界是开放的世界，科学技术发展一日千里，只有参与国际经济竞 争与合作，充分利用国际经济资源和科技成果，才能发展自己，赶上当代世界的科技和经济发展潮流。 （2）对外开放作为我国一项长期的基本国策是对中国长期停滞落后的历史教训深刻总结的结果。长期闭关自 守，把我国搞得贫穷落后，愚昧无知。历史的经验一再告诉我们，关起门来搞建设是不行的，把自己孤立于 世界之外是不利的。中国的发展离不开世界。 （3）对外开放作为我国一项长期的基本国策是我国社会主义现代化建设的迫切需要。扩大对外开放，可以引 进国外资金、先进的技术设备和管理经验、人才，以克服我国资金短缺、技术落后、管理经验不足等困难 ；可以充分利用国外资源，大力开拓国际市场，通有无，取长补短，趋利避害，促进我国经济发展；可以参 与国际经济、科学、技术，人才和信息的交流，有利于我们及时了解和掌握各种经济、科技信息；可以广泛 吸收世界文明成果，发挥后发优势，在较高的技术基础上发展经济，尽快缩小与发达国家经济技术发展程度 的差距。 总之，我国必须坚持对外开放和独立自主、自力更生的统一。独立自主、自力更生，是我国进行现代化建设 的立足点和基点。独立自主、自力更生是对外开放的前提和基础，而对外开放可以加快经济发展，增强国家 综合国力，从而提高独立自主、自力更生的能力和水平。","score":10},{"id":"yc-2-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(二) · 论述题 (20分)","stem":"简述量变和质变的关系。","answer":"（1）量变是质变的必要准备。任何事物的变化都有一个量变的积累过程，没有量变的积累，质变就 不会发生。 （2）质变是量变的必然结果。单纯的量变不会永远持续下去，量变达到一定程度必然引起质变。 （3）量变和质变是相互渗透的。一方面，在总的量变过程中有阶段性和局部性的部分质变；另一方面，在质 变过程中也有旧质在量上的收缩和新质在量上的扩张。量变和质变是相互依存、相互贯通的，量变引起质变 ，在新质的基础上，事物又开始新的量变，如此交替循环，构成了事物的发展过程。量变质变规律体现了事 物发展的渐进性和飞跃性的统一。","explanation":"（1）量变是质变的必要准备。任何事物的变化都有一个量变的积累过程，没有量变的积累，质变就 不会发生。 （2）质变是量变的必然结果。单纯的量变不会永远持续下去，量变达到一定程度必然引起质变。 （3）量变和质变是相互渗透的。一方面，在总的量变过程中有阶段性和局部性的部分质变；另一方面，在质 变过程中也有旧质在量上的收缩和新质在量上的扩张。量变和质变是相互依存、相互贯通的，量变引起质变 ，在新质的基础上，事物又开始新的量变，如此交替循环，构成了事物的发展过程。量变质变规律体现了事 物发展的渐进性和飞跃性的统一。","score":20},{"id":"yc-2-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(二) · 论述题 (20分)","stem":"为什么说农民阶级是无产阶级最坚固最可靠的同盟军？","answer":"（1）中国是一个以农业为主要经济成分的国家，农民人数最多。占全国总人口的80％，是“人民大 众”的主体。（2）农民身处社会的最底层，受压迫最深，受剥削最重，蕴藏着极大的革命积极性。（3）中 国产业工人的前身多是破产农民，因而农民和工人有天然的联盟关系，工农联盟是革命胜利的基石。（4）农 民是中国军队的来源，是中国民主政治的主要力量。","explanation":"（1）中国是一个以农业为主要经济成分的国家，农民人数最多。占全国总人口的80％，是“人民大 众”的主体。（2）农民身处社会的最底层，受压迫最深，受剥削最重，蕴藏着极大的革命积极性。（3）中 国产业工人的前身多是破产农民，因而农民和工人有天然的联盟关系，工农联盟是革命胜利的基石。（4）农 民是中国军队的来源，是中国民主政治的主要力量。","score":20}]},{"id":"yc-3","title":"2026年成考预测试卷(三)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-3-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(三) · 单选","stem":"我国现代化实行的独立自主、自力更生方针的理论依据是（ ）","options":["量变引起质变的原理","主次矛盾相互转化的原理","内外因辩证关系的原理","共性和个性辩证关系的原理"],"answer":2,"answerLetter":"C","explanation":"独立自主、自力更生强调依靠自身内部力量发展，这体现了内因是事物发展的根据。同时我国现代 化建设也需要对外开放等外部条件，外因是事物发展的条件，内外因相互作用推动事物发展。所以这一方针 的理论依据是内外因辩证关系原理。","score":2},{"id":"yc-3-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(三) · 单选","stem":"实践中一刀切的工作方法是由于忽视了（ ）","options":["矛盾的同一性","矛盾的普遍性","矛盾的斗争性","矛盾的特殊性"],"answer":3,"answerLetter":"D","explanation":"“一刀切”就是不考虑具体情况，用同一种方式处理所有问题。而矛盾特殊性要求我们具体问题具 体分析，“一刀切”正是忽视了矛盾特殊性，没有看到不同事物矛盾的差异。","score":2},{"id":"yc-3-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(三) · 单选","stem":"区分量变和质变的根本标志是（ ）","options":["事物的变化是否快速","事物的变化是否明显","事物的变化是否超越了度的范围","事物的变化幅度的大小"],"answer":2,"answerLetter":"C","explanation":"量变和质变的区别关键在于事物的变化是否超出度的范围，在度的范围内的变化是量变，超出度的 变化就是质变。A选项变化快速、B选项变化明显、D选项变化幅度大小都不是区分二者的根本标志。","score":2},{"id":"yc-3-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(三) · 单选","stem":"发展的本质是（ ）","options":["事物质的变化","一切变化的过程","新事物的产生和旧事物的灭亡","事物由肯定到否定"],"answer":2,"answerLetter":"C","explanation":"发展的本质强调的是事物上升、前进的运动变化，是具有前进性和上升性的质变，其核心体现为新 事物产生，旧事物灭亡，新事物代替旧事物。A选项事物质变不一定是发展，也可能是倒退；B选项一切变化 包含了倒退等非发展的变化；D选项事物由肯定到否定表述不完整且未突出发展本质特征。","score":2},{"id":"yc-3-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(三) · 单选","stem":"事物矛盾的精髓是（ ）","options":["矛盾的同一性和斗争性的关系","矛盾的对抗与非对抗的关系","主要矛盾和次要矛盾的关系","矛盾的共性、个性、绝对、相对的关系"],"answer":3,"answerLetter":"D","explanation":"矛盾的共性（普遍性）和个性（特殊性）、绝对和相对的关系是关于事物矛盾问题的精髓。它贯穿 于矛盾学说的各个方面，是正确理解矛盾学说的关键 。","score":2},{"id":"yc-3-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(三) · 单选","stem":"直接经验和间接经验的关系是（ ）","options":["第一性和第二性的关系","认识的源和流的关系","主观和客观的关系","反映和被反映的关系"],"answer":1,"answerLetter":"B","explanation":"直接经验是通过亲身实践获得的知识，间接经验是从他人或书本等途径获取的知识。实践是认识的 来源，直接经验是认识的“源”，而间接经验归根结底也是源于他人的实践，是认识的“流”。","score":2},{"id":"yc-3-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(三) · 单选","stem":"坚持感性认识是理性认识的基础，就是在认识论上坚持了（ ）","options":["可知论","唯物论","辩证法","唯心论"],"answer":1,"answerLetter":"B","explanation":"感性认识是对事物现象的认识，理性认识是对事物本质的认识。坚持感性认识是理性认识的基础 ，强调认识来源于实践中对事物现象的感知，这符合物质第一性，意识第二性，认识是对物质的反映这一唯 物论观点。因为只有通过实践获取关于物质世界的感性材料，才能上升到理性认识。","score":2},{"id":"yc-3-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(三) · 单选","stem":"感性认识和理性认识统一的基础是（ ）","options":["客观对象","认识的主体","认识的客体","社会实践"],"answer":3,"answerLetter":"D","explanation":"感性认识和理性认识是认识过程的两个阶段，它们统一的基础是社会实践。实践是认识的来源、动 力、目的和检验标准，只有通过实践，才能使感性认识上升到理性认识，两者在实践基础上相互依存、相互 转化。","score":2},{"id":"yc-3-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(三) · 单选","stem":"认识的起点是感觉，这是（ ）","options":["只有唯物主义才承认的观点","唯物主义和唯心主义都可以承认的观点","只有辩证唯物主义才承认的观点","唯心主义承认的观点"],"answer":1,"answerLetter":"B","explanation":"认识始于感觉，无论是唯物主义还是唯心主义都可承认这一点。唯物主义认为感觉是对客观世界的 反映，以此为起点进一步认识世界；唯心主义虽对感觉来源解释不同，但也认可感觉是认识起点。","score":2},{"id":"yc-3-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(三) · 单选","stem":"一种认识是不是真理，要看它（ ）","options":["是否被多数人拥护","是否被社会普遍承认","是否与客观事物及其规律相一致","是否能满足人的需要"],"answer":2,"answerLetter":"C","explanation":"真理是标志主观与客观相符合的哲学范畴，是对客观事物及其规律的正确反映。判断一种认识是不 是真理关键在于它是否与客观事物及其规律相一致，而不是看被多少人拥护、社会是否普遍承认或者能否满 足人的需要。","score":2},{"id":"yc-3-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(三) · 单选","stem":"人的价值包括两方面，它们是（ ）","options":["经济价值和政治价值","物质价值和精神价值","潜在价值和现实价值","自我价值和社会价值"],"answer":3,"answerLetter":"D","explanation":"人的价值包含自我价值和社会价值两个方面。自我价值是个体的生存和发展得到满足，社会价值是 个体对社会作出的贡献。这是关于人的价值的基本理论。","score":2},{"id":"yc-3-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(三) · 单选","stem":"人生观是人们（ ）","options":["对世界的根本看法","对人生目的的意义和根本看法","对人性的根本看法","对主观领域的根本看法"],"answer":1,"answerLetter":"B","explanation":"人生观主要围绕人生的目的、意义等展开探讨。A选项对世界根本看法是世界观；C选项对人性根本 看法只是人生观一部分；D选项对主观领域根本看法表述不准确。只有B符合人生观定义。","score":2},{"id":"yc-3-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(三) · 单选","stem":"人类历史发展的总趋势是（ ）","options":["由低级到高级的过程","周而复始的循环过程","前进和倒退相互交替的过程","进步与落后相混杂的过程"],"answer":0,"answerLetter":"A","explanation":"人类历史是不断向前发展的，是从低级向高级演进，虽然发展过程会有曲折，但总体趋势是上升进 步的。B选项循环过程不符合人类历史发展有质的飞跃的实际；C选项前进和倒退相互交替不是总趋势；D选项 进步与落后相混杂也不能准确表述总趋势。","score":2},{"id":"yc-3-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(三) · 单选","stem":"马克思主义哲学认为自由是（ ）","options":["人们按照自己的意志创造历史","不受必然性制约的绝对自由","对必然性的认识和对客观世界的改造","按照多数人的意见去行动"],"answer":2,"answerLetter":"C","explanation":"马克思主义哲学认为自由不是随心所欲，A选项按自己意志创造历史忽视社会规律；B选项不受必然 性制约的绝对自由不存在，自由是相对的；D选项按多数人意见行动不一定就代表自由。马克思主义认为自由 是对必然性（规律）的认识和对客观世界的改造。","score":2},{"id":"yc-3-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(三) · 单选","stem":"人类解放就是（ ）","options":["实现绝对自由","不受任何束缚和限制","摆脱盲目必然性和社会关系的奴役","创造有利于全面发展的规律"],"answer":2,"answerLetter":"C","explanation":"人类解放意味着从自然和社会的奴役中摆脱出来。A选项绝对自由不存在；B选项不受任何束缚限制 不现实；D选项规律不能被创造。而C选项摆脱盲目必然性（自然方面）和社会关系的奴役（社会方面）符合 人类解放的内涵。","score":2},{"id":"yc-3-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(三) · 单选","stem":"新民主主义社会的国体是（ ）","options":["无产阶级专政","资产阶级专政","几个革命阶级的联合专政","大地主资产阶级专政"],"answer":2,"answerLetter":"C","explanation":"新民主主义社会是过渡性质社会，其国体既不是无产阶级专政（这是社会主义社会国体），也不是 资产阶级专政或大地主资产阶级专政，而是几个革命阶级的联合专政，这体现了新民主主义革命的各革命阶 级联合的特点。","score":2},{"id":"yc-3-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(三) · 单选","stem":"新民主主义国家的政体是（ ）","options":["民主集中制的人民代表大会制","议会制","委员会制","政治协商制"],"answer":0,"answerLetter":"A","explanation":"新民主主义国家的政体是实行民主集中制的人民代表大会制度。这是符合中国国情的，能体现人民 当家作主。议会制、委员会制不符合新民主主义国家性质，政治协商制是中国政党制度的重要机构形式，并 非政体。","score":2},{"id":"yc-3-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(三) · 单选","stem":"革命统一战线最根本的问题是","options":["革命目标问题","政策和策略问题","领导权问题","工农联盟问题"],"answer":2,"answerLetter":"C","explanation":"领导权问题是革命统一战线最根本的问题，领导权掌握在谁手中决定着统一战线的方向和革命的走 向。没有正确的领导权，统一战线就无法巩固和发展，革命就难以成功。","score":2},{"id":"yc-3-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(三) · 单选","stem":"革命统一战线的基础是（ ）","options":["国共合作","工农联盟","与民族资产阶级合作","反对共同敌人"],"answer":1,"answerLetter":"B","explanation":"革命统一战线中，工人阶级和农民阶级都受压迫最深，有着共同利益和革命诉求，工农联盟是革命 统一战线得以建立和发展的基本力量，是革命统一战线的基础。","score":2},{"id":"yc-3-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(三) · 单选","stem":"中国共产党初步提出统一战线方针的会议是（ ）","options":["中共一大","中共二大","中共三大","中共四大"],"answer":1,"answerLetter":"B","explanation":"中共二大在对中国社会各阶级的状况作了初步分析后，提出组成“民主主义的联合战线”的主张 ，初步提出统一战线方针。中共一大主要是党的创建，中共三大主要是决定与国民党合作，中共四大主要是 提出无产阶级领导权和工农联盟问题 。","score":2},{"id":"yc-3-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(三) · 单选","stem":"标志着人民民主专政理论完全形成的著作是（ ）","options":["《新民主主义论》","《论人民民主专政》","《论联合政府》","《将革命进行到底》"],"answer":1,"answerLetter":"B","explanation":"《论人民民主专政》全面阐述了人民民主专政的性质、领导者、阶级基础、职能等内容，标志着人 民民主专政理论完全形成。而A选项《新民主主义论》主要论述新民主主义革命的基本理论、路线和纲领等 ；C选项《论联合政府》主要阐述党的一般纲领和具体纲领等；D选项《将革命进行到底》主要是号召将革命 进行到底。","score":2},{"id":"yc-3-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(三) · 单选","stem":"人民民主专政政权的组织形式是（ ）","options":["参议会制度","政治协商会议制度","人民代表大会制度","共产党领导的多党合作制度"],"answer":2,"answerLetter":"C","explanation":"人民代表大会制度是我国的根本政治制度，是人民民主专政政权的组织形式。参议会制度是抗战时 期的，与题干不符；政治协商会议制度、共产党领导的多党合作制度是政党制度相关，并非政权组织形式。","score":2},{"id":"yc-3-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(三) · 单选","stem":"1949年10月，中华人民共和国成立，标志着中国从半殖民地半封建社会进入（ ）","options":["资本主义社会","新民主主义社会","社会主义社会形态","共产主义社会形态"],"answer":1,"answerLetter":"B","explanation":"中华人民共和国成立，结束了半殖民地半封建社会，此时中国进入新民主主义社会，因为社会主义 公有制等社会主义经济基础尚未完全建立。1956年底社会主义改造基本完成才标志着进入社会主义社会。资 本主义社会不符合中国发展路径，共产主义社会形态目前远未达到。","score":2},{"id":"yc-3-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(三) · 单选","stem":"新民主主义社会是一种（ ）","options":["独立的社会形态","固定不变的社会形态","过渡性质的社会形态","从属于资本主义的社会形态"],"answer":2,"answerLetter":"C","explanation":"新民主主义社会是近代中国由半殖民地半封建社会走向社会主义社会的中介与桥梁，具有过渡性质 。它不是独立社会形态，也并非固定不变，更不从属于资本主义。","score":2},{"id":"yc-3-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(三) · 单选","stem":"中国共产党七届三中全会确定国民经济恢复时期的中心任务是（ ）","options":["迅速消灭国民党残余势力","统一全国财政经济工作","新解放区土地改革的完成","争取国家财政经济状况的基本好转"],"answer":3,"answerLetter":"D","explanation":"七届三中全会确定，要获得国家财政经济状况的根本好转，要用三年左右的时间，创造三个条件 ，即土地改革的完成、现有工商业的合理调整、国家机构所需经费的大量节减。所以中心任务是争取国家财 政经济状况的基本好转。","score":2},{"id":"yc-3-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(三) · 单选","stem":"党在社会主义初级阶段基本路线的核心和主体是（ ）","options":["经济建设","改革开放","四项基本原则","安定团结的政治局面"],"answer":0,"answerLetter":"A","explanation":"党在社会主义初级阶段基本路线的核心内容是“一个中心，两个基本点”，“一个中心”即以经济 建设为中心，它是核心和主体，其他方面围绕这个中心展开。答案：A。","score":2},{"id":"yc-3-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(三) · 单选","stem":"坚持以经济建设为中心，从根本上说是由（ ）","options":["当前的国情决定的","社会主义初级阶段的主要矛盾决定的","当前的国际环境决定的","党的方针政策决定的"],"answer":1,"answerLetter":"B","explanation":"社会主义初级阶段的主要矛盾是人民日益增长的物质文化需要同落后的社会生产之间的矛盾。解决 这一矛盾的根本途径就是大力发展生产力，而坚持以经济建设为中心，就是为了大力发展生产力，所以坚持 以经济建设为中心从根本上说是由社会主义初级阶段的主要矛盾决定的。 国情范围较宽泛，不是最根本决定 因素；国际环境只是外部影响，不是根本原因；党的方针政策是基于一定情况制定的，不是以经济建设为中 心的根本决定因素。","score":2},{"id":"yc-3-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(三) · 单选","stem":"四项基本原则为经济建设提供了（ ）","options":["政治保证","组织保证","物质保证","发展动力"],"answer":0,"answerLetter":"A","explanation":"四项基本原则规定了我国的社会主义性质、道路、领导核心等根本问题，它能确保经济建设沿着正 确的政治方向前进，为其提供政治保证。","score":2},{"id":"yc-3-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(三) · 单选","stem":"改革开放为经济建设提供了（ ）","options":["政治保证","组织保证","思想保证","发展动力"],"answer":3,"answerLetter":"D","explanation":"改革开放通过变革生产关系、释放市场活力等，为经济建设注入源源不断的活力，推动经济不断向 前发展，所以它为经济建设提供发展动力。而政治保证一般是党的领导等；组织保证多涉及党组织建设等方 面；思想保证通常是先进理论等的指导。","score":2},{"id":"yc-3-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(三) · 单选","stem":"建设中国特色社会主义文化的基本目标是（ ）","options":["以马克思主义为指导，以培育有理想、有道德、有文化、有纪律的公民为目标，发展面向现代化、面向世 界、面向未来的民族的、科学的、大众的社会主义文化","坚持用邓小平理论武装全党，教育人民","努力提高全民族的思想道德素质和教育科学文化水平","坚持为人民服务、为社会主义服务的方向和百花齐放、百家争鸣的方针，重在建设、繁荣学术和文艺"],"answer":0,"answerLetter":"A","explanation":"建设中国特色社会主义文化的基本目标在教材中有明确表述，A选项完整阐述了建设中国特色社会主 义文化在指导思想、培育目标、文化特征等方面的内容，符合基本目标的定义。","score":2},{"id":"yc-3-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(三) · 单选","stem":"市场机制中的核心机制是（ ）","options":["供求机制","激励机制","价格机制","竞争机制"],"answer":2,"answerLetter":"C","explanation":"价格机制影响着供求、竞争等机制的运行，在市场机制中居于核心地位。","score":2},{"id":"yc-3-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(三) · 单选","stem":"社会主义市场经济中的宏观调控是以（ ）","options":["直接调控为主","间接调控为主","结构调控为主","总体调控为主"],"answer":1,"answerLetter":"B","explanation":"在社会主义市场经济体制下，市场在资源配置中起决定性作用，政府宏观调控主要运用经济、法律 手段，通过市场机制间接影响经济主体行为，所以宏观调控以间接调控为主。","score":2},{"id":"yc-3-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(三) · 单选","stem":"转变政府职能的关键是（ ）","options":["中央政府和地方政府合理划分职权","处理好国家和企业的关系","处理好中央和地方的关系","政企职责分开"],"answer":3,"answerLetter":"D","explanation":"政府职能转变的核心是处理好政府与市场、社会的关系，关键在于政企职责分开，只有实现政企分 开，才能真正让政府从微观经济事务中解脱出来，更好地履行宏观调控、市场监管等职能。","score":2},{"id":"yc-3-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(三) · 单选","stem":"社会主义宏观调控的基本目标（ ）","options":["抑制通货膨胀","促进经济结构优化","保持经济增长","保持经济总平衡"],"answer":3,"answerLetter":"D","explanation":"社会主义宏观调控的基本目标是保持经济总量平衡，即保持社会总供给和社会总需求的平衡 ，这是 保证国民经济持续、稳定、协调发展的基础。其他选项如抑制通货膨胀、促进经济结构优化、保持经济增长 都是宏观调控的具体目标。","score":2},{"id":"yc-3-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(三) · 单选","stem":"现代企业制度一般采取公司制，是因为公司制（ ）","options":["适应各种生产关系的要求","具有较强的透明性","比较适应市场经济的要求","是一种最具有经济效益的企业形式"],"answer":2,"answerLetter":"C","explanation":"现代企业制度采取公司制，主要原因是公司制能较好地适应市场经济发展要求，在产权、治理结构 等方面与市场经济契合。A选项“适应各种生产关系”表述太绝对；B选项较强透明性不是公司制成为现代企 业制度主要形式的关键；D选项“最具经济效益”说法不准确，不同企业形式在不同情境下效益不同。答案 ：C","score":2},{"id":"yc-3-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"简述社会存在对社会意识的决定作用。","answer":"（1）社会存在是社会生活的物质方面，是社会物质生活条件的总和。社会意识是社会生活的精神 方面，是社会精神现象的总和。 （2）历史唯物主义认为社会存在决定社会意识，社会意识对社会存在有依赖性。这主要表现在： 第一，社会意识的产生、变化与发展都根源于社会存在的发展变化。 第二，社会意识的内容，无论其具体形式和水平如何，也都是对社会存在的反映。 第三，社会意识中的阶级属性是对社会存在中阶级关系的反映。","explanation":"（1）社会存在是社会生活的物质方面，是社会物质生活条件的总和。社会意识是社会生活的精神 方面，是社会精神现象的总和。 （2）历史唯物主义认为社会存在决定社会意识，社会意识对社会存在有依赖性。这主要表现在： 第一，社会意识的产生、变化与发展都根源于社会存在的发展变化。 第二，社会意识的内容，无论其具体形式和水平如何，也都是对社会存在的反映。 第三，社会意识中的阶级属性是对社会存在中阶级关系的反映。","score":10},{"id":"yc-3-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"简述经济基础与上层建筑的辩证关系。","answer":"（1）在社会形态的矛盾统一体中，经济基础决定上层建筑，上层建筑反作用于经济基础；经济基 础和上层建筑之间存在着自始至终的矛盾运动。 （2）经济基础对上层建筑的决定作用表现在：经济基础决定上层建筑的产生，决定上层建筑的性质，决定上 层建筑的变革。 （3）上层建筑对经济基础的反作用表现为积极地为经济基础服务。 第一，从方式上看，上层建筑是通过对社会生活各个方面和领域的控制与调节来为经济基础服务的。 第二，从内容上看，上层建筑一方面要保护和促进自己的经济基础的形成、巩固与发展，另一方面要消灭和 排斥异己的经济基础与上层建筑。 第三，从性质上看，上层建筑对经济基础的反作用在整个社会发展中所起作用的性质最终取决于其所服务的 经济基础的性质。如果上层建筑维护的是适合生产力发展的先进的经济基础，则该上层建筑反作用的社会性 质是进步的；如果上层建筑维护的是不适合生产力发展的落后的经济基础，则该上层建筑反作用的社会性质 是反动的。 （4）经济基础和上层建筑的相互作用构成了社会形态及其矛盾运动，表现为上层建筑与经济基础之间由基本 适合到基本不适合再到新的基本适合的矛盾运动，如此循环往复，推动社会形态的不断更新。","explanation":"（1）在社会形态的矛盾统一体中，经济基础决定上层建筑，上层建筑反作用于经济基础；经济基 础和上层建筑之间存在着自始至终的矛盾运动。 （2）经济基础对上层建筑的决定作用表现在：经济基础决定上层建筑的产生，决定上层建筑的性质，决定上 层建筑的变革。 （3）上层建筑对经济基础的反作用表现为积极地为经济基础服务。 第一，从方式上看，上层建筑是通过对社会生活各个方面和领域的控制与调节来为经济基础服务的。 第二，从内容上看，上层建筑一方面要保护和促进自己的经济基础的形成、巩固与发展，另一方面要消灭和 排斥异己的经济基础与上层建筑。 第三，从性质上看，上层建筑对经济基础的反作用在整个社会发展中所起作用的性质最终取决于其所服务的 经济基础的性质。如果上层建筑维护的是适合生产力发展的先进的经济基础，则该上层建筑反作用的社会性 质是进步的；如果上层建筑维护的是不适合生产力发展的落后的经济基础，则该上层建筑反作用的社会性质 是反动的。 （4）经济基础和上层建筑的相互作用构成了社会形态及其矛盾运动，表现为上层建筑与经济基础之间由基本 适合到基本不适合再到新的基本适合的矛盾运动，如此循环往复，推动社会形态的不断更新。","score":10},{"id":"yc-3-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"简述宏观经济调控的基本目标。","answer":"保持经济总量平衡，即保持社会总供给和社会总需求的平衡是宏观经济调控的基本目标，主要有 四点：促进经济增长；增加就业；稳定物价；保持国际收支平衡。","explanation":"保持经济总量平衡，即保持社会总供给和社会总需求的平衡是宏观经济调控的基本目标，主要有 四点：促进经济增长；增加就业；稳定物价；保持国际收支平衡。","score":10},{"id":"yc-3-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(三) · 简答题 (10分)","stem":"试述邓小平建设有中国特色社会主义理论首要的基本理论问题及意义。","answer":"（1）什么是社会主义，怎样建设社会主义，是邓小平反复思考和强调的建设有中国特色社会主义 的首要的基本理论。新中国成立以来我们在社会主义建设中所经历的曲折和失误，归根到底，就在于对这个 问题没有完全搞清楚；改革开放过程中遇到的一些疑虑和困扰，归根到底也在于对这个最基本的理论问题没 有完全搞清楚。搞清这一问题，是为了在坚持社会主义基本制度的基础上进一步认清社会主义的本质。 （2）在总结多年来离开生产力抽象谈论社会主义的历史教训的基础上，邓小平在南方谈话中对社会主义本质 作了总结性的理论概括：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终 达到共同富裕。” （3）根据对什么是社会主义和中国国情的思考，邓小平比较系统地初步回答了中国如何建设社会主义的问题 ，形成了我们党在社会主义初级阶段建设有中国特色社会主义的基本路线，即“一个中心，两个基本点”。 （4）邓小平对建设有中国特色社会主义首要的基本理论问题的科学回答，反映了人民的利益和时代的要求 ，廓清了不合乎时代进步和社会主义发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽略社会主义 本质的错误倾向。它对于我们在坚持社会主义制度的基础上推进改革，对于建设有中国特色的社会主义，具 有重大实践意义。","explanation":"（1）什么是社会主义，怎样建设社会主义，是邓小平反复思考和强调的建设有中国特色社会主义 的首要的基本理论。新中国成立以来我们在社会主义建设中所经历的曲折和失误，归根到底，就在于对这个 问题没有完全搞清楚；改革开放过程中遇到的一些疑虑和困扰，归根到底也在于对这个最基本的理论问题没 有完全搞清楚。搞清这一问题，是为了在坚持社会主义基本制度的基础上进一步认清社会主义的本质。 （2）在总结多年来离开生产力抽象谈论社会主义的历史教训的基础上，邓小平在南方谈话中对社会主义本质 作了总结性的理论概括：“社会主义的本质，是解放生产力，发展生产力，消灭剥削，消除两极分化，最终 达到共同富裕。” （3）根据对什么是社会主义和中国国情的思考，邓小平比较系统地初步回答了中国如何建设社会主义的问题 ，形成了我们党在社会主义初级阶段建设有中国特色社会主义的基本路线，即“一个中心，两个基本点”。 （4）邓小平对建设有中国特色社会主义首要的基本理论问题的科学回答，反映了人民的利益和时代的要求 ，廓清了不合乎时代进步和社会主义发展规律的模糊观念，摆脱了长期以来拘泥于具体模式而忽略社会主义 本质的错误倾向。它对于我们在坚持社会主义制度的基础上推进改革，对于建设有中国特色的社会主义，具 有重大实践意义。","score":10},{"id":"yc-3-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(三) · 论述题 (20分)","stem":"为什么说改革是中国的第二次革命？","answer":"（1）改革是为了扫除发展社会生产力的障碍，使中国摆脱贫穷落后的状态。相对于新民主主义革命 而言，改革是中国的第二次革命。 （2）说改革是中国的第二次革命，是从解放生产力，扫除发展生产力的障碍这个意义而言的。 （3）说改革是中国的第二次革命，是从改革的深刻性和广泛性而言的。从1978年以来的30多年间，我国社会 生活最引人注目的变化是经济体制及其他相关体制的改革。这些改革调动了社会各方面的积极性，促进了社 会生产力的发展，引起了整个社会关系和社会生活的深刻变化。","explanation":"（1）改革是为了扫除发展社会生产力的障碍，使中国摆脱贫穷落后的状态。相对于新民主主义革命 而言，改革是中国的第二次革命。 （2）说改革是中国的第二次革命，是从解放生产力，扫除发展生产力的障碍这个意义而言的。 （3）说改革是中国的第二次革命，是从改革的深刻性和广泛性而言的。从1978年以来的30多年间，我国社会 生活最引人注目的变化是经济体制及其他相关体制的改革。这些改革调动了社会各方面的积极性，促进了社 会生产力的发展，引起了整个社会关系和社会生活的深刻变化。","score":20},{"id":"yc-3-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(三) · 论述题 (20分)","stem":"简述人民群众的含义和人民群众在历史发展中的作用。","answer":"（1）人民群众是指推动社会历史发展的绝大多数社会成员的总和，劳动者是人民群众的主体。 （2）人民群众是历史的创造者，是推动社会发展的决定力量。 ①人民群众是社会物质财富的创造者。人民群众创造了社会得以存在和发展的物质资料，并且不断推动生产 力的发展。 ②人民群众是社会精神财富的创造者。人民群众为精神财富的创造提供了物质条件和源泉，还直接参与了精 神财富的创造。 ③人民群众是社会变革的决定力量。生产关系的改变、社会制度的更替，只有通过人民群众的革命实践才能 实现。","explanation":"（1）人民群众是指推动社会历史发展的绝大多数社会成员的总和，劳动者是人民群众的主体。 （2）人民群众是历史的创造者，是推动社会发展的决定力量。 ①人民群众是社会物质财富的创造者。人民群众创造了社会得以存在和发展的物质资料，并且不断推动生产 力的发展。 ②人民群众是社会精神财富的创造者。人民群众为精神财富的创造提供了物质条件和源泉，还直接参与了精 神财富的创造。 ③人民群众是社会变革的决定力量。生产关系的改变、社会制度的更替，只有通过人民群众的革命实践才能 实现。","score":20}]},{"id":"yc-4","title":"2026年成考预测试卷(四)","type":"predict","year":2026,"totalCount":41,"choiceCount":35,"subjectiveCount":6,"questions":[{"id":"yc-4-c-1","isSubjective":false,"num":1,"category":"2026年成考预测试卷(四) · 单选","stem":"“心想事成”这一观点是（ ）","options":["辩证唯物主义观点","唯心主义观点","能动反映论的观点","机械唯物主义观点"],"answer":1,"answerLetter":"B","explanation":"“心想事成”片面夸大了意识的作用，认为只要心里想就能成功，而忽视了客观规律和条件，过分 强调精神的决定作用，这符合唯心主义夸大意识能动性的特点。答案选B。","score":2},{"id":"yc-4-c-2","isSubjective":false,"num":2,"category":"2026年成考预测试卷(四) · 单选","stem":"主观与客观相统一是（ ）","options":["政治工作的基本要求","经济工作的基本要求","一切工作的基本要求","党务工作的基本要求"],"answer":2,"answerLetter":"C","explanation":"主观与客观相统一是马克思主义哲学的重要观点，强调人们在认识世界和改造世界过程中，要使自 己的主观思想符合客观实际情况。这一要求贯穿于人类所有的实践活动，并非局限于政治、经济、党务等某 一类特定工作。所以主观与客观相统一是一切工作的基本要求。","score":2},{"id":"yc-4-c-3","isSubjective":false,"num":3,"category":"2026年成考预测试卷(四) · 单选","stem":"既是发展的主体，也是发展的最大受益者的是（ ）","options":["政府","中国共产党","知识分子","人民群众"],"answer":3,"answerLetter":"D","explanation":"人民群众是历史的创造者，是社会实践的主体，推动社会发展，同时发展成果也由人民共享，所以 人民群众既是发展主体也是最大受益者。政府、中国共产党、知识分子都包含在人民群众范畴中，且都服务 于人民群众这一发展主体。答案：D。","score":2},{"id":"yc-4-c-4","isSubjective":false,"num":4,"category":"2026年成考预测试卷(四) · 单选","stem":"从历史脉络来看，党和人民长期奋斗所创造积累的根本成就和前赴后继的事业是（ ）","options":["改革开放","共同富裕","中华民族的伟大复兴","中国特色社会主义"],"answer":3,"answerLetter":"D","explanation":"中国特色社会主义是党和人民长期奋斗、创造、积累的根本成就，一代又一代中国共产党人前赴后 继推进这一伟大事业。改革开放是中国特色社会主义发展的重要举措；共同富裕是中国特色社会主义的根本 原则和本质要求；中华民族伟大复兴是近代以来中华民族最伟大的梦想。但从题干强调的长期奋斗积累的根 本成就和前赴后继事业角度，中国特色社会主义最符合。","score":2},{"id":"yc-4-c-5","isSubjective":false,"num":5,"category":"2026年成考预测试卷(四) · 单选","stem":"“没有上，就无所谓下；没有先进，就无所谓落后；没有正确，就无所谓错误。”这说明（ ）","options":["矛盾双方相互排斥","矛盾双方相互渗透","矛盾双方相互依存","矛盾双方相互转化"],"answer":2,"answerLetter":"C","explanation":"题干中强调了“没有……就无所谓……”，表明矛盾双方是相互依赖存在的，一方的存在以另一方 的存在为前提。答案：C ，矛盾双方相互依存。","score":2},{"id":"yc-4-c-6","isSubjective":false,"num":6,"category":"2026年成考预测试卷(四) · 单选","stem":"在中国革命进程中，具有新民主主义革命和社会主义革命双重性质的事件是（ ）","options":["没收封建阶级的土地9-3农民所有","没收官僚资本归新民主主义国家所有","接收帝国主义在华企业归新民主主义国家所有","赎买民族工商业归人民民主专政国家所有"],"answer":1,"answerLetter":"B","explanation":"没收官僚资本，一方面，官僚资本是国民党反动统治的经济基础，具有买办性和封建性，没收官僚 资本具有反帝反封建的民主革命性质；另一方面，官僚资本又是中国的垄断资本，没收官僚资本建立起新民 主主义国营经济，又带有社会主义革命的性质。所以没收官僚资本归新民主主义国家所有具有新民主主义革 命和社会主义革命双重性质。","score":2},{"id":"yc-4-c-7","isSubjective":false,"num":7,"category":"2026年成考预测试卷(四) · 单选","stem":"社会主义基本制度初步确立后，科学文化领域实行的方针是（ ）","options":["“统筹兼顾、适当安排”","“团结一批评一团结”","“百花齐放、百家争鸣”","“长期共存、互相监督”"],"answer":2,"answerLetter":"C","explanation":"“百花齐放、百家争鸣”是社会主义基本制度初步确立后，党在科学文化领域实行的方针。A选项 “统筹兼顾、适当安排”是关于正确处理国家、集体和个人三者关系等方面方针；B选项“团结—批评—团结 ”是处理人民内部矛盾在政治思想领域的方针；D选项“长期共存、互相监督”是处理共产党与各民主党派关 系的方针。","score":2},{"id":"yc-4-c-8","isSubjective":false,"num":8,"category":"2026年成考预测试卷(四) · 单选","stem":"感性认识和理性认识的区别在于（ ）","options":["感性认识是对事物现象的认识，理性认识是对事物本质的认识","感性认识来源于实践，理性认识来源于经验","感性认识是直接经验，理性认识是间接经验","感性认识可靠，理性认识不可靠"],"answer":0,"answerLetter":"A","explanation":"感性认识是认识的初级阶段，是对事物现象的认识；理性认识是认识的高级阶段，是对事物本质和 规律的认识，A选项正确阐述了二者区别。B选项中理性认识也来源于实践；C选项混淆概念，感性认识和理性 认识与直接经验、间接经验不是等同关系；D选项说法错误，感性认识和理性认识都有可靠与不可靠的情况。","score":2},{"id":"yc-4-c-9","isSubjective":false,"num":9,"category":"2026年成考预测试卷(四) · 单选","stem":"马克思主义认识论认为，能动的反映是（ ）","options":["摹写和创造的统一","物质和精神的统一","真理性和实践性的统一","可知论和本体论的统一"],"answer":0,"answerLetter":"A","explanation":"马克思主义认识论强调认识是主体对客体的能动反映，这种反映既有对客体的摹写，如实反映客体 的状况，又有主体的创造，在观念中构建出理想客体等。能动的反映体现的是摹写和创造的统一。","score":2},{"id":"yc-4-c-10","isSubjective":false,"num":10,"category":"2026年成考预测试卷(四) · 单选","stem":"掌握意识形态工作领导权的内在要求是（ ）","options":["旗帜鲜明坚持马克思主义指导","坚持正确的舆论方向","构建中国特色哲学社会科学","建设好网络空间"],"answer":2,"answerLetter":"C","explanation":"【标准答案：C】","score":2},{"id":"yc-4-c-11","isSubjective":false,"num":11,"category":"2026年成考预测试卷(四) · 单选","stem":"“近田为农，近山为猎，临路为商，临水为渔”这句话体现的哲学思想是（ ）","options":["人口因素对社会发展具有重要作用","偶然因素对社会发展具有重要作用","地理环境对社会发展起着重要作用","物质资料生产方式对社会发展起决定作用"],"answer":2,"answerLetter":"C","explanation":"“近田为农，近山为猎，临路为商，临水为渔”描述的是人们依据所处的地理环境不同，从事不同 的生产活动，体现了地理环境对人类生产生活方式等社会发展方面有重要影响。","score":2},{"id":"yc-4-c-12","isSubjective":false,"num":12,"category":"2026年成考预测试卷(四) · 单选","stem":"将中国共产党提出的一系列和平解决台湾问题的思想、政策和主张归纳为“一纲四目”的国家领导人是 （ ）","options":["周恩来","刘少奇","邓小平","叶剑英"],"answer":0,"answerLetter":"A","explanation":"“一纲四目”是周恩来根据毛泽东的思想，在 1963 年进一步概括提出。“一纲”即台湾必须统一 于中国；“四目”是具体的操作方案等内容。所以答案是 A 选项周恩来。","score":2},{"id":"yc-4-c-13","isSubjective":false,"num":13,"category":"2026年成考预测试卷(四) · 单选","stem":"在新民主主义社会中存在多种经济成分，其中掌握了国家主要经济命脉的是（ ）","options":["国营经济","合作社经济","个体经济","私人资本主义经济"],"answer":0,"answerLetter":"A","explanation":"新民主主义社会中，国营经济是通过没收官僚资本而形成的，它掌握了国家主要经济命脉，在国民 经济中居于领导地位。","score":2},{"id":"yc-4-c-14","isSubjective":false,"num":14,"category":"2026年成考预测试卷(四) · 单选","stem":"割裂感性认识和理性认识的统一，会导致两种错误理论，一种是唯理论，另一种是（ ）","options":["经验论","循环论","直线论","不可知论"],"answer":0,"answerLetter":"A","explanation":"割裂感性认识和理性认识统一，唯理论片面强调理性认识可靠，忽视感性认识；经验论则片面强调 感性认识可靠，忽视理性认识，二者都走向极端。循环论、直线论与认识过程无关，不可知论探讨的是思维 能否正确认识存在，与题干所讲割裂感性与理性认识关系导致的错误理论不相关。","score":2},{"id":"yc-4-c-15","isSubjective":false,"num":15,"category":"2026年成考预测试卷(四) · 单选","stem":"坚决打好精准脱贫攻坚战，重点解决好（ ），加强东西部扶贫协作和对口支援，做好中央单位定点帮扶 。","options":["贫困问题","山区贫困地区","深度贫困问题","西部贫困地区"],"answer":2,"answerLetter":"C","explanation":"精准脱贫攻坚战重点要攻克深度贫困堡垒，解决深度贫困问题。深度贫困地区脱贫难度大，是脱贫 攻坚的关键。","score":2},{"id":"yc-4-c-16","isSubjective":false,"num":16,"category":"2026年成考预测试卷(四) · 单选","stem":"马克思主义是中国共产党指导思想的理论基础。要解决中国革命所面I临的问题，必须把马克思主义和中 国具体实际相结合。党对这一问题的认识，经历了一个过程。其中党的领导认识到马克思主义与中国实际相 结合的重要性是在（ ）","options":["延安整风运动时期","党的七大","1935年遵义会议后","1938年六届六中全会"],"answer":2,"answerLetter":"C","explanation":"1935 年遵义会议后，党的领导集体才真正认识到马克思主义与中国实际相结合的重要性。遵义会议 事实上确立了以毛泽东为核心的党中央的正确领导，结束了王明“左”倾教条主义在中央的统治，开始把马 克思主义与中国实际结合。延安整风运动使全党对马克思主义中国化的认识达到新高度；党的七大正式将毛 泽东思想确立为党的指导思想，是马克思主义中国化的重大成果；1938 年六届六中全会毛泽东提出“马克思 主义中国化”命题。","score":2},{"id":"yc-4-c-17","isSubjective":false,"num":17,"category":"2026年成考预测试卷(四) · 单选","stem":"（ ）成为衡量国家软实力和竞争力的重要标志。","options":["互联网的飞速发展","信息掌握的多寡","创新能力","人工智能技术"],"answer":1,"answerLetter":"B","explanation":"这道题目考察的是对国家软实力和竞争力衡量标准的理解。首先，我们来了解一下什么是国家软实 力和竞争力。国家软实力是指一个国家通过文化、价值观、制度等非物质性资源来影响他国和国际体系的能 力。而国家竞争力则更侧重于一个国家在全球经济环境中相对于其他国家所表现出来的综合优势。现在，我 们逐一分析每个选项：A. 互联网的飞速发展 - 互联网的发展确实是国家现代化和信息化的重要标志，但它 更多体现的是技术层面的进步，而非直接等同于国家软实力和竞争力的衡量标准。B. 信息掌握的多寡 - 在 信息化时代，信息的掌握对于国家的决策、安全和国际影响力至关重要。一个国家如果能够掌握更多的信息 ，就能更准确地把握国际动态，制定更有效的政策，从而提升其在国际舞台上的竞争力和软实力。因此，这 个选项直接关联到国家软实力和竞争力的核心要素。C. 创新能力 - 创新能力无疑是国家安全和经济发展的 重要动力，但它更多是从经济和科技角度来考量的，并不全面反映国家的软实力和竞争力。D. 人工智能技术 - 人工智能技术是当今科技领域的前沿，但它同样更多体现的是技术层面的进步，并不直接等同于国家软实 力和竞争力的衡量标准。综上所述，信息掌握的多寡最能够全面反映一个国家在软实力和竞争力方面的综合 实力。因此，正确答案应该是B选项：“信息掌握的多寡”。所以，这道题的正确答案是B：“信息掌握的多 寡”。","score":2},{"id":"yc-4-c-18","isSubjective":false,"num":18,"category":"2026年成考预测试卷(四) · 单选","stem":"“物是观念的集合”这一观点是（ ）","options":["辩证唯物主义的观点","唯心主义的观点","能动反映论的观点","机械唯物主义的观点"],"answer":1,"answerLetter":"B","explanation":"“物是观念的集合”强调物质是由观念集合而成，即把观念当作世界的本原，这符合唯心主义认为 意识决定物质的观点。","score":2},{"id":"yc-4-c-19","isSubjective":false,"num":19,"category":"2026年成考预测试卷(四) · 单选","stem":"中华民族伟大复兴的基础工程是建设（ ）","options":["经济强国","教育强国","政治强国","文化强国"],"answer":1,"answerLetter":"B","explanation":"教育是民族振兴、社会进步的重要基石，是功在当代、利在千秋的德政工程，对提高人民综合素质 、促进人的全面发展、增强中华民族创新创造活力、实现中华民族伟大复兴具有决定性意义。建设教育强国 是中华民族伟大复兴的基础工程。","score":2},{"id":"yc-4-c-20","isSubjective":false,"num":20,"category":"2026年成考预测试卷(四) · 单选","stem":"生产关系是人们在生产过程中结成的（ ）","options":["人与自然的关系","人与人的物质利益关系","管理与被管理的关系","分工协作关系"],"answer":1,"answerLetter":"B","explanation":"生产关系是人们在物质资料生产过程中所结成的社会关系，本质上是人与人之间的物质利益关系。 A选项人与自然的关系是生产力范畴；C选项管理与被管理关系只是生产关系中的部分表现，不全面；D选项分 工协作关系也只是生产关系的一方面，不完整。答案选B。","score":2},{"id":"yc-4-c-21","isSubjective":false,"num":21,"category":"2026年成考预测试卷(四) · 单选","stem":"改革开放前和改革开放后两个历史时期是（ ）","options":["党领导人民进行社会主义建设的实践探索","彼此割裂、根本对立","改革开放前的历史时期否定了改革开放后","改革开放后的历史时期否定了改革开放前"],"answer":0,"answerLetter":"A","explanation":"改革开放前和改革开放后两个历史时期本质上都是党领导人民进行社会主义建设的实践探索，不能 将二者割裂、对立，也不存在一方否定另一方的情况。","score":2},{"id":"yc-4-c-22","isSubjective":false,"num":22,"category":"2026年成考预测试卷(四) · 单选","stem":"中国有句古语“塞翁失马，焉知非福”，对我们的哲学启示是（ ）","options":["要透过现象认识事物的本质","事物在一定条件下可以相互转化","看问题要用全面的、长远的眼光","矛盾的主要方面决定事物的性质"],"answer":1,"answerLetter":"B","explanation":"“塞翁失马，焉知非福”意思是坏事在一定条件下可变为好事，好事在一定条件下也可能变为坏事 ，强调事物在一定条件下相互转化。所以答案是B。","score":2},{"id":"yc-4-c-23","isSubjective":false,"num":23,"category":"2026年成考预测试卷(四) · 单选","stem":"从世界物质统一性原理中得出的最重要的结论是（ ）","options":["物质是第一位的，意识是第二位的","世界是普遍联系的","世界是可以被认识和改造的","一切从实际出发、实事求是"],"answer":3,"answerLetter":"D","explanation":"世界物质统一性原理强调世界的本质是物质，这就要求我们在认识和实践中，要尊重客观实际，依 据客观事实来行动。“一切从实际出发、实事求是”正是基于世界物质统一性原理得出的最具实践指导意义 的结论。A选项阐述的是物质和意识的关系；B选项世界普遍联系是辩证法观点；C选项世界可被认识和改造强 调的是人的主观能动性与客观世界的关系，均不如D选项与世界物质统一性原理直接关联紧密。","score":2},{"id":"yc-4-c-24","isSubjective":false,"num":24,"category":"2026年成考预测试卷(四) · 单选","stem":"全面协调可持续是科学发展观的（ ）","options":["根本方法","基本要求","核心立场","第一要义"],"answer":1,"answerLetter":"B","explanation":"科学发展观中，第一要义是发展，核心立场是以人为本，基本要求是全面协调可持续，根本方法是 统筹兼顾。","score":2},{"id":"yc-4-c-25","isSubjective":false,"num":25,"category":"2026年成考预测试卷(四) · 单选","stem":"下列属于民族昌盛和国家富强的重要标志之一是（ ）","options":["食品安全","医疗发达","人民健康","预防控制重大疾病"],"answer":2,"answerLetter":"C","explanation":"人民健康是民族昌盛和国家富强的重要标志，这是在国家对于健康理念及战略高度层面强调的内容 。食品安全、医疗发达、预防控制重大疾病等都围绕人民健康展开，但只有人民健康这一表述最契合作为民 族昌盛和国家富强重要标志这一地位。","score":2},{"id":"yc-4-c-26","isSubjective":false,"num":26,"category":"2026年成考预测试卷(四) · 单选","stem":"毛泽东建军思想的核心是（ ）","options":["全心全意为人民服务","坚持正确的战略战术原则","坚持党对军队的绝对领导","建立一支与广大人民群众血肉相连的新型人民军队"],"answer":2,"answerLetter":"C","explanation":"党对军队的绝对领导是毛泽东建军思想的核心内容。只有坚持党对军队绝对领导，才能保证军队性 质宗旨，实现无产阶级革命目标。A选项全心全意为人民服务是人民军队的唯一宗旨；B选项战略战术原则是 作战指导方面内容；D选项建立新型人民军队是重要方面，但核心是党对军队的绝对领导。","score":2},{"id":"yc-4-c-27","isSubjective":false,"num":27,"category":"2026年成考预测试卷(四) · 单选","stem":"毛泽东曾在不同场合多次谈到，调查研究有两种方法，一种是走马看花，一种是下马看花。走马看花，不 深入，还必须用第二种方法，就是下马看花，过细看花，分析一朵花。毛泽东强调“下马看花”的实际意义 在于（ ）","options":["解决实际问题必须要有先进理论的指导","运用多种综合方法分析调查研究的材料","马克思主义理论必须适合中国革命的具体实际","只有全面深入地了解中国的实际，才能找出规律"],"answer":3,"answerLetter":"D","explanation":"“下马看花”强调过细看花，也就是要全面深入地了解实际情况。只有全面深入了解中国实际，才 能找出其中的规律。A选项强调先进理论指导，与“下马看花”深入了解实际主旨不符；B选项说的是分析材 料方法，不是“下马看花”强调的深入了解实际；C选项说理论要适合实际，重点在理论与实际关系，并非深 入了解实际本身。所以“下马看花”实际意义在于全面深入了解中国实际找规律。","score":2},{"id":"yc-4-c-28","isSubjective":false,"num":28,"category":"2026年成考预测试卷(四) · 单选","stem":"假象同真象一样，也是客观存在的。这是一种（ ）","options":["辩证法的观点","唯物辩证法的观点","形而上学的观点","主观唯心主义的观点"],"answer":1,"answerLetter":"B","explanation":"唯物辩证法认为现象分为真象和假象，真象和假象都是对本质的表现，且都客观存在。强调假象的 客观存在，这体现的是唯物辩证法看待现象与本质关系的观点。","score":2},{"id":"yc-4-c-29","isSubjective":false,"num":29,"category":"2026年成考预测试卷(四) · 单选","stem":"“历史不过是追求自己的目的人的活动而已”，这句话表明（ ）","options":["人是研究社会历史的出发点","人们自己创造自己的历史","历史发展的方向是由自己决定的","人的自我保存和发展是历史的原动力"],"answer":1,"answerLetter":"B","explanation":"题干强调历史是人的活动，这突出了人在创造历史过程中的作用。A选项，研究社会历史出发点应是 社会存在等，而非单纯的人；C选项，历史发展方向受多种因素制约，不是人随意决定；D选项，历史原动力 是生产力与生产关系等矛盾运动，并非人的自我保存和发展。只有B选项“人们自己创造自己的历史”符合题 干表达的人对历史的创造作用。","score":2},{"id":"yc-4-c-30","isSubjective":false,"num":30,"category":"2026年成考预测试卷(四) · 单选","stem":"在我国手工业社会主义改造的过程中，第一步主要是办手工业供销小组，它的性质是（ ）","options":["完全社会主义性质","半社会主义性质","社会主义萌芽性质","新民主主义性质"],"answer":2,"answerLetter":"C","explanation":"手工业供销小组是手工业者通过国营商业、供销合作社与市场建立联系，成员的生产资料仍归个人 所有，具有社会主义萌芽性质。","score":2},{"id":"yc-4-c-31","isSubjective":false,"num":31,"category":"2026年成考预测试卷(四) · 单选","stem":"北京时间2021年10月16日0时23分，搭载（ ）载人飞船（ ）遥十三运载火箭在酒泉卫星发射中心，成 功发射，顺利将翟志刚、王亚平、叶光富3名航天员送入太空，飞行乘组状态良好，发射取得圆满成功。","options":["神州十二号；长征二号F","神州十二号；长征五号","神州十三号；长征二号F","神州十三号；长征五号"],"answer":2,"answerLetter":"C","explanation":"题目中明确提到“搭载（ ）载人飞船（ ）遥十三运载火箭”，说明是神舟十三号飞船，而发射 神舟系列飞船的常用火箭是长征二号F火箭。答案选C。","score":2},{"id":"yc-4-c-32","isSubjective":false,"num":32,"category":"2026年成考预测试卷(四) · 单选","stem":"国家发改委消息，我国已基本形成北斗卫星导航产业体系，产业规模超（ ）元。","options":["4000亿","3000亿","2000亿","3500亿"],"answer":0,"answerLetter":"A","explanation":"需记忆我国基本形成北斗卫星导航产业体系时产业规模超4000亿这一知识点。答案：A 。","score":2},{"id":"yc-4-c-33","isSubjective":false,"num":33,"category":"2026年成考预测试卷(四) · 单选","stem":"2022年政府工作报告指出，落实落细稳就业举措。________执行降低失业和工伤保险费率等阶段性稳就业 政策。今年高校毕业生超过________人，要加强就业创业指导、政策支持和不断线服务。","options":["延续900万","延续1000万","暂缓900万","暂缓1000万"],"answer":1,"answerLetter":"B","explanation":"这是一道关于政府工作报告内容理解的选择题。首先，我们分析题目中提到的两个关键信息点：1. 关于“降低失业和工伤保险费率等阶段性稳就业政策”的执行方式；2. 今年高校毕业生的具体人数。对于第 一点，政府工作报告中提及的相关政策通常是“延续”而非“暂缓”，因为这样的政策旨在持续稳定就业形 势。所以，选项中“延续”更为合理。对于第二点，关于高校毕业生的人数，根据近年来的数据和趋势，高 校毕业生人数持续增长，而1000万这一数字更符合当前的增长趋势，相较于900万更为准确。综上所述，结合 题目描述和实际情况，“延续”执行相关政策以及高校毕业生人数超过“1000万”这两个点均符合题目要求 。因此，正确答案是B：“延续1000万”。","score":2},{"id":"yc-4-c-34","isSubjective":false,"num":34,"category":"2026年成考预测试卷(四) · 单选","stem":"在北京第13届冬残奥会上，中国体育代表团奋勇争先，夺得18枚金牌、20枚银牌、23枚铜牌，在金牌榜、 奖牌榜居（ ），取得了我国参加冬残奥会的历史最好成绩。","options":["第1位","第2位","第3位","第4位"],"answer":0,"answerLetter":"A","explanation":"北京第13届冬残奥会上，中国体育代表团金牌、奖牌总数均位列第一，取得历史最好成绩。所以应 选在金牌榜、奖牌榜居第1位的选项。","score":2},{"id":"yc-4-c-35","isSubjective":false,"num":35,"category":"2026年成考预测试卷(四) · 单选","stem":"下列选项中，与习近平总书记在2021年9月中央人才工作会议上的讲话精神不相符的是：（ ）。","options":["发挥用人主体在人才培养、引进、使用中的积极作用","加快建立以创新价值、能力、贡献为导向的人才评价体系","坚持党对人才工作的全面领导","加快建设我国重要人才中心和创新高地，做好顶层设计和战略谋划"],"answer":3,"answerLetter":"D","explanation":"中央人才工作会议强调了党对人才工作全面领导（C选项）；明确要加快建立以创新价值、能力、贡 献为导向的人才评价体系（B选项）；也提到要发挥用人主体在人才培养、引进、使用中的积极作用（A选项 ）。而“加快建设我国重要人才中心和创新高地，做好顶层设计和战略谋划”表述不准确，会议强调的是进 行战略布局，并非“战略谋划”。","score":2},{"id":"yc-4-s-36","isSubjective":true,"num":36,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"为什么说阶级是特定经济结构中的人群共同体?","answer":"因为阶级首先一个经济范畴。阶级的划分是由人们在特定经济结构中所处的不同地位和结成的不同 关系决定的。划分阶级的根本标准是经济。阶级是基于对生产资料占有关系的不同而形成的利益根本对立的 社会集团和人群共同体。阶级一经形成必然有其相应的政治思想以及其他方面的特征。阶级是特定时代的生 产方式的产物。特定的经济结构产生特定的阶级结构。所以阶级是特定经济结构中的人群共同体。","explanation":"因为阶级首先一个经济范畴。阶级的划分是由人们在特定经济结构中所处的不同地位和结成的不同 关系决定的。划分阶级的根本标准是经济。阶级是基于对生产资料占有关系的不同而形成的利益根本对立的 社会集团和人群共同体。阶级一经形成必然有其相应的政治思想以及其他方面的特征。阶级是特定时代的生 产方式的产物。特定的经济结构产生特定的阶级结构。所以阶级是特定经济结构中的人群共同体。","score":10},{"id":"yc-4-s-37","isSubjective":true,"num":37,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"《历史决议》对毛泽东的历史地位作出了怎样实事求是的评价?","answer":"毛泽东是伟大的马克思主义者、伟大的无产阶级革命家、战略家和理论家。他为中国共产党和中国 人民解放军的创立和发展，为中国各族人民解放事业的胜利，为中华人民共和国的缔造和社会主义事业的发 展，建立了不可磨灭的功勋，为世界被压迫民族的解放和人类进步事业作出了重大贡献。毛泽东的功绩是第 一位的，错误是第二位的。","explanation":"毛泽东是伟大的马克思主义者、伟大的无产阶级革命家、战略家和理论家。他为中国共产党和中国 人民解放军的创立和发展，为中国各族人民解放事业的胜利，为中华人民共和国的缔造和社会主义事业的发 展，建立了不可磨灭的功勋，为世界被压迫民族的解放和人类进步事业作出了重大贡献。毛泽东的功绩是第 一位的，错误是第二位的。","score":10},{"id":"yc-4-s-38","isSubjective":true,"num":38,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"简答推进强军事业、把人民军队全面建成世界一流军队的要求。","answer":"(1)牢固树立战斗力这个唯一的根本的标准。把战斗力作为唯一的根本的标准，是有效履行我军根本 职能的内在要求，也是提高军队建设质量效益的客观需要。 (2)坚持政治建军、改革强军、科技兴军、依法治军。政治建军是人民军队的立军之本，改革是我军发展壮大 、制胜未来的关键一招，科技是现代战争的核心战斗力，依法治军、从严治军是我们党建军治军的基本方略 。 (3)构建中国特色现代军事力量体系。 (4)深入推进练兵备战。","explanation":"(1)牢固树立战斗力这个唯一的根本的标准。把战斗力作为唯一的根本的标准，是有效履行我军根本 职能的内在要求，也是提高军队建设质量效益的客观需要。 (2)坚持政治建军、改革强军、科技兴军、依法治军。政治建军是人民军队的立军之本，改革是我军发展壮大 、制胜未来的关键一招，科技是现代战争的核心战斗力，依法治军、从严治军是我们党建军治军的基本方略 。 (3)构建中国特色现代军事力量体系。 (4)深入推进练兵备战。","score":10},{"id":"yc-4-s-39","isSubjective":true,"num":39,"category":"2026年成考预测试卷(四) · 简答题 (10分)","stem":"简答中国共产党始终代表中国先进文化的前进方向的内容。","answer":"(1)大力发展社会主义先进文化，必须牢牢把握先进文化的前进方向，建设社会主义精神文明，不断 满足人民群众日益增长的精神文化需求，不断丰富人民的精神世界，增强人民的精神力量。 (2)发展社会主义先进文化，就是建设社会主义精神文明。 (3)发展社会主义先进文化，就是发展面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文 化。 (4)发展社会主义先进文化，必须弘扬民族精神。 (5)发展社会主义先进文化，必须加强社会主义思想道德建设，这是发展先进文化的重要内容和中心环节。 (6)发展社会主义先进文化，必须做好思想政治工作。","explanation":"(1)大力发展社会主义先进文化，必须牢牢把握先进文化的前进方向，建设社会主义精神文明，不断 满足人民群众日益增长的精神文化需求，不断丰富人民的精神世界，增强人民的精神力量。 (2)发展社会主义先进文化，就是建设社会主义精神文明。 (3)发展社会主义先进文化，就是发展面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文 化。 (4)发展社会主义先进文化，必须弘扬民族精神。 (5)发展社会主义先进文化，必须加强社会主义思想道德建设，这是发展先进文化的重要内容和中心环节。 (6)发展社会主义先进文化，必须做好思想政治工作。","score":10},{"id":"yc-4-s-40","isSubjective":true,"num":40,"category":"2026年成考预测试卷(四) · 论述题 (20分)","stem":"如何认识具有中国特点的社会主义改造道路。","answer":"(1)社会主义改造取得的成就：①在一个几亿人口的大国比较顺利地实现了如此复杂、困难和深刻的 社会变革，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展。②这样的变革没有引起 巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民基本上普遍拥护的情况下完成的。这说明 ，我国社会主义改造的基本完成的确是一个伟大的历史性胜利。 (2)社会主义改造的失误和偏差：主要是“在一九五五年夏季以后，农业合作化以及对手工业和个体商业的改 造要求过急，工作过粗，改变过快，形式也过于简单划一”。 (3)正确认识：成就第一，失误和偏差第二，不能因为出现一些失误而否定社会主义改造的伟大意义。社会主 义制度的确立是中国历史最深刻最伟大的社会变革，也是20世纪中国又一次划时代的历史巨变。","explanation":"(1)社会主义改造取得的成就：①在一个几亿人口的大国比较顺利地实现了如此复杂、困难和深刻的 社会变革，不仅没有造成生产力的破坏，反而促进了工农业和整个国民经济的发展。②这样的变革没有引起 巨大的社会动荡，反而极大地加强了人民的团结，并且是在人民基本上普遍拥护的情况下完成的。这说明 ，我国社会主义改造的基本完成的确是一个伟大的历史性胜利。 (2)社会主义改造的失误和偏差：主要是“在一九五五年夏季以后，农业合作化以及对手工业和个体商业的改 造要求过急，工作过粗，改变过快，形式也过于简单划一”。 (3)正确认识：成就第一，失误和偏差第二，不能因为出现一些失误而否定社会主义改造的伟大意义。社会主 义制度的确立是中国历史最深刻最伟大的社会变革，也是20世纪中国又一次划时代的历史巨变。","score":20},{"id":"yc-4-s-41","isSubjective":true,"num":41,"category":"2026年成考预测试卷(四) · 论述题 (20分)","stem":"试运用马克思主义认识论的有关原理，说明我们对社会主义本质的认识是一个不断深化的过程。","answer":"(1)认识运动是不断反复的：对一个复杂事物的认识，往往要经过由实践到认识，由认识到实践的多 次反复才能完成。认识运动是无限发展的：认识对象是不断发展的，人们的认识运动也必然随之不断深化和 提高，永无止境。 (2)对社会主义本质的认识正是一个在实践中不断反复和逐渐深化的过程，与认识和实践具体的历史的统一具 有一致性。什么是社会主义是人们一直在探索的问题。马克思、恩格斯使社会主义由空想到科学。列宁领导 十月革命使社会主义由理论到实践。新中国成立后党对社会主义进行了艰难的探索和实践。十一届三中全会 后，邓小平结合中国实际，认为社会主义本质是解放生产力，发展生产力，消灭剥削.消除两极分化，最终达 到共同富裕。随着改革开放的深入推进，邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代 中国特色社会主义思想，形成了中国特色社会主义理论体系，深化了我们对社会主义本质的认识。 (3)社会主义本质的体现是个动态过程，人们对社会主义的认识也将随着实践的推进逐步深入，永无止境。","explanation":"(1)认识运动是不断反复的：对一个复杂事物的认识，往往要经过由实践到认识，由认识到实践的多 次反复才能完成。认识运动是无限发展的：认识对象是不断发展的，人们的认识运动也必然随之不断深化和 提高，永无止境。 (2)对社会主义本质的认识正是一个在实践中不断反复和逐渐深化的过程，与认识和实践具体的历史的统一具 有一致性。什么是社会主义是人们一直在探索的问题。马克思、恩格斯使社会主义由空想到科学。列宁领导 十月革命使社会主义由理论到实践。新中国成立后党对社会主义进行了艰难的探索和实践。十一届三中全会 后，邓小平结合中国实际，认为社会主义本质是解放生产力，发展生产力，消灭剥削.消除两极分化，最终达 到共同富裕。随着改革开放的深入推进，邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代 中国特色社会主义思想，形成了中国特色社会主义理论体系，深化了我们对社会主义本质的认识。 (3)社会主义本质的体现是个动态过程，人们对社会主义的认识也将随着实践的推进逐步深入，永无止境。","score":20}]}]);

